export default function dIconOrImage(badge) {
  const icon = get(badge, "icon");
  const image = get(badge, "image");

  if (!isEmpty(image)) {
    return trustHTML(`<img src='${image}' alt=''>`);
  }

  if (isEmpty(icon)) {
    return "";
  }

  return trustHTML(iconHTML(convertIconClass(icon)));
}
