import { AUTO_GROUPS } from "discourse/lib/constants";

let _autoGroupFlair, _userGroupFlair, _noAutoFlair;

// All automatic groups except "everyone" (which doesn't have flair)
const FLAIR_AUTO_GROUP_IDS = Object.values(AUTO_GROUPS)
  .filter((g) => g.id !== AUTO_GROUPS.everyone.id)
  .map((g) => g.id);

export default function autoGroupFlairForUser(site, user) {
  if (!_userGroupFlair) {
    initializeUserGroupFlair(site);
  }

  if (user.flair_group_id && _userGroupFlair[user.flair_group_id]) {
    return _userGroupFlair[user.flair_group_id];
  }

  if (!_autoGroupFlair) {
    initializeAutoGroupFlair(site);
  }

  if (_noAutoFlair) {
    // No automatic groups have flair.
    return null;
  }

  if (user.admin && _autoGroupFlair[AUTO_GROUPS.admins.id]) {
    return _autoGroupFlair[AUTO_GROUPS.admins.id];
  }

  if (user.moderator && _autoGroupFlair[AUTO_GROUPS.moderators.id]) {
    return _autoGroupFlair[AUTO_GROUPS.moderators.id];
  }

  if ((user.admin || user.moderator) && _autoGroupFlair[AUTO_GROUPS.staff.id]) {
    return _autoGroupFlair[AUTO_GROUPS.staff.id];
  }

  let trustLevel = user.trust_level || user.trustLevel;

  if (trustLevel) {
    for (let i = trustLevel; i >= 0; i--) {
      const group = AUTO_GROUPS[`trust_level_${i}`];
      if (group && _autoGroupFlair[group.id]) {
        return _autoGroupFlair[group.id];
      }
    }
  }
}

export function resetFlair() {
  _autoGroupFlair = null;
  _userGroupFlair = null;
  _noAutoFlair = null;
}

function initializeUserGroupFlair(site) {
  _userGroupFlair = {};

  Object.values(site.groupsById || {}).forEach((group) => {
    if (
      !FLAIR_AUTO_GROUP_IDS.includes(group.id) &&
      (group.flair_url || group.flair_bg_color)
    ) {
      _userGroupFlair[group.id] = {
        flair_name: group.name.replace(/_/g, " "),
        flair_url: group.flair_url,
        flair_bg_color: group.flair_bg_color,
        flair_color: group.flair_color,
      };
    }
  });
}

function initializeAutoGroupFlair(site) {
  _autoGroupFlair = {};
  _noAutoFlair = true;

  FLAIR_AUTO_GROUP_IDS.forEach((groupId) => {
    const group = site.groupsById[groupId];
    if (group?.flair_url) {
      _noAutoFlair = false;
      _autoGroupFlair[groupId] = {
        flair_name: group.name.replace(/_/g, " "),
        flair_url: group.flair_url,
        flair_bg_color: group.flair_bg_color,
        flair_color: group.flair_color,
      };
    }
  });
}
import Component from "@glimmer/component";
import { service } from "@ember/service";
import autoGroupFlairForUser from "discourse/lib/avatar-flair";
import DAvatarFlair from "discourse/ui-kit/d-avatar-flair";
import { i18n } from "discourse-i18n";

export default class DUserAvatarFlair extends Component {
  @service site;

  get flair() {
    const user = this.args.user;

    if (!user || !user.flair_group_id) {
      return;
    }

    if (user.flair_url || user.flair_bg_color) {
      return {
        flairName: user.flair_name,
        flairUrl: user.flair_url,
        flairBgColor: user.flair_bg_color,
        flairColor: user.flair_color,
      };
    }

    const autoFlairAttrs = autoGroupFlairForUser(this.site, user);
    if (autoFlairAttrs) {
      return {
        flairName: autoFlairAttrs.flair_name,
        flairUrl: autoFlairAttrs.flair_url,
        flairBgColor: autoFlairAttrs.flair_bg_color,
        flairColor: autoFlairAttrs.flair_color,
      };
    }
  }

  get isBot() {
    const id = this.args.user?.id;
    return Number.isInteger(id) && id <= 0;
  }

  <template>
    {{#if this.flair}}
      <DAvatarFlair
        @flairBgColor={{this.flair.flairBgColor}}
        @flairColor={{this.flair.flairColor}}
        @flairName={{this.flair.flairName}}
        @flairUrl={{this.flair.flairUrl}}
      />
    {{else if this.isBot}}
      <DAvatarFlair
        aria-label={{i18n "user.bot_account"}}
        class="--bot"
        role="img"
        title={{i18n "user.bot_account"}}
        @flairName="bot"
        @flairUrl="robot"
      />
    {{/if}}
  </template>
}
