 * A depth of 20 is generous for real-world use cases while protecting against
 * malicious or buggy configurations that could cause infinite recursion.
 */
export const MAX_LAYOUT_DEPTH = 20;

/**
 * Maximum allowed length for block names.
 *
 * Prevents potential memory and performance issues from extremely long names.
 * A limit of 100 characters is generous for real-world use cases while
 * protecting against malicious or buggy configurations.
 *
 * This applies to the full namespaced name (e.g., "theme:my-theme:my-block").
 */
export const MAX_BLOCK_NAME_LENGTH = 100;

/**
 * Symbol used to mark a block reference as optional and missing from the registry.
 * When this marker is returned from resolution functions, it signals that the block
 * should be silently skipped rather than throwing an error.
 *
 * Used in layout validation and block registration to identify optional
 * blocks that aren't registered and should be skipped during validation and rendering.
 */
export const OPTIONAL_MISSING = Symbol("optional-missing");

/**
 * Constants for failure type codes used by ghost blocks.
 *
 * These are internal codes for logic comparisons (e.g., determining which
 * section to show in the ghost tooltip). Display messages are generated
 * at render time in ghost-block.gjs based on these types.
 *
 * Custom failure reasons (like "hidden by priority" from the head block)
 * don't need a type constant - they're passed as display strings directly
 * via the `failureReason` field.
 */
export const FAILURE_TYPE = Object.freeze({
  /** Block's conditions evaluated to false. */
  CONDITION_FAILED: "condition-failed",
  /** Container block has no children that passed their conditions. */
  NO_VISIBLE_CHILDREN: "no-visible-children",
  /** Block reference uses `?` suffix but isn't registered. */
  OPTIONAL_MISSING: "optional-missing",
});

/**
 * A resolved-block marker indicating an optional block reference (`name?`)
 * that isn't registered. Returned by resolution functions such as
 * `tryResolveBlock()` in place of a block class.
 */
export interface OptionalMissingMarker {
  optionalMissing: typeof OPTIONAL_MISSING;
  name: string;
}

/**
 * Checks if a resolved block is an optional missing block marker.
 *
 * @param resolvedBlock - The result from tryResolveBlock.
 * @returns True if the block is an optional missing marker.
 */
export function isOptionalMissing(
  resolvedBlock: unknown
): resolvedBlock is OptionalMissingMarker {
  return (
    typeof resolvedBlock === "object" &&
    resolvedBlock !== null &&
    "optionalMissing" in resolvedBlock &&
    resolvedBlock.optionalMissing === OPTIONAL_MISSING
  );
}

/**
 * Valid block name pattern: lowercase letters, numbers, and hyphens.
 * Must start with a letter. Examples: "hero-banner", "sidebar-blocks", "my-block-1"
 *
 * Used for both block names and outlet names since they follow the same format.
 */
export const VALID_BLOCK_NAME_PATTERN = /^[a-z][a-z0-9-]*$/;

/**
 * Valid block ID pattern for the `id` entry property.
 * Same format as block names: lowercase letters, numbers, and hyphens,
 * must start with a letter.
 *
 * Examples: "featured-banner", "sidebar-1", "main-content"
 */
export const VALID_BLOCK_ID_PATTERN = VALID_BLOCK_NAME_PATTERN;

/**
 * Valid namespaced block name pattern. Supports three formats:
 *
 * - **Core blocks**: `block-name` (no prefix)
 * - **Plugin blocks**: `plugin-name:block-name` (where plugin-name is not "theme")
 * - **Theme blocks**: `theme:theme-name:block-name`
 *
 * Each segment must start with a letter and contain only lowercase letters,
 * numbers, and hyphens.
 *
 * @example
 * ```
 * // Valid patterns:
 * "group"                      // Core block
 * "chat:message-widget"        // Plugin block
 * "theme:tactile:hero-banner"  // Theme block
 *
 * // Invalid patterns:
 * "Theme:Name:block"           // Uppercase not allowed
 * "theme:block"                // Theme requires namespace segment
 * "my_block"                   // Underscores not allowed
 * ```
 */
export const VALID_NAMESPACED_BLOCK_PATTERN =
  /^(?:theme:[a-z][a-z0-9-]*:[a-z][a-z0-9-]*|(?!theme:)[a-z][a-z0-9-]*:[a-z][a-z0-9-]*|[a-z][a-z0-9-]*)$/;

/**
 * The parsed components of a block name.
 */
export interface ParsedBlockName {
  type: "core" | "plugin" | "theme";
  namespace: string | null;
  name: string;
}

/**
 * Parses a full block name into its components.
 *
 * @param fullName - The full block name.
 * @returns An object with the parsed components, or `null` if the name is invalid.
 *
 * @example
 * ```
 * parseBlockName("group")
 * // => { type: "core", namespace: null, name: "group" }
 *
 * parseBlockName("chat:message-widget")
 * // => { type: "plugin", namespace: "chat", name: "message-widget" }
 *
 * parseBlockName("theme:tactile:hero-banner")
 * // => { type: "theme", namespace: "theme:tactile", name: "hero-banner" }
 *
 * parseBlockName("Invalid_Name")
 * // => null
 * ```
 */
export function parseBlockName(fullName: string): ParsedBlockName | null {
  // Theme: theme:namespace:name
  const themeMatch = fullName.match(
    /^theme:([a-z][a-z0-9-]*):([a-z][a-z0-9-]*)$/
  );
  if (themeMatch) {
    return {
      type: "theme",
      namespace: `theme:${themeMatch[1]}`,
      name: themeMatch[2],
    };
  }

  // Plugin: namespace:name (where namespace is NOT "theme")
  const pluginMatch = fullName.match(/^([a-z][a-z0-9-]*):([a-z][a-z0-9-]*)$/);
  if (pluginMatch && pluginMatch[1] !== "theme") {
    return { type: "plugin", namespace: pluginMatch[1], name: pluginMatch[2] };
  }

  // Core: just name
  const coreMatch = fullName.match(/^[a-z][a-z0-9-]*$/);
  if (coreMatch) {
    return { type: "core", namespace: null, name: fullName };
  }

  return null;
}

/**
 * The result of parsing a block reference string.
 */
export interface ParsedBlockReference<Name = string | object> {
  name: Name;
  optional: boolean;
}

/**
 * Parses a block reference string to extract the block name and optional flag.
 *
 * Block references can be marked as optional by appending a `?` suffix to the
 * name. Optional blocks that are not registered will be silently skipped
 * instead of throwing an error.
 *
 * Supports all namespaced formats:
 * - Core: `"block-name"` or `"block-name?"`
 * - Plugin: `"plugin:block"` or `"plugin:block?"`
 * - Theme: `"theme:namespace:block"` or `"theme:namespace:block?"`
 *
 * @param blockRef - The block reference. If a string, may have an optional `?`
 *   suffix. Non-string references (e.g., component classes) are returned as-is
 *   in the `name` property with `optional: false`.
 * @returns Parsed result with the clean block name (or original reference) and
 *   whether it's optional.
 *
 * @example
 * ```
 * parseBlockReference("chat:widget?")
 * // => { name: "chat:widget", optional: true }
 *
 * parseBlockReference("hero-banner")
 * // => { name: "hero-banner", optional: false }
 * ```
 */
export function parseBlockReference(
  blockRef: string
): ParsedBlockReference<string>;
export function parseBlockReference<T extends object>(
  blockRef: T
): ParsedBlockReference<T>;
export function parseBlockReference(
  blockRef: string | object
): ParsedBlockReference {
  if (typeof blockRef === "string" && blockRef.endsWith("?")) {
    return { name: blockRef.slice(0, -1), optional: true };
  }
  return { name: blockRef, optional: false };
}
/**
 * Debug hooks for block dev-tools integration.
 *
 * This module provides:
 * - Debug callback hooks for dev-tools integration (visual overlays, logging, outlet boundaries)
 * - Ghost component creation for visualizing hidden blocks
 * - Debug console grouping utilities
 *
 * The debug hooks use TrackedMap for reactivity, enabling Ember's reactivity system
 * to trigger re-renders when callbacks are set/cleared.
 */
import type Component from "@glimmer/component";
import type Owner from "@ember/owner";
import { trackedMap } from "@ember/reactive/collections";
import { FAILURE_TYPE } from "discourse/lib/blocks/-internals/patterns";
import type {
  BlockClass,
  BlockEntry,
  ChildBlockResult,
} from "discourse/lib/blocks/-internals/types";

/**
 * Callback key constants for the debug hooks registry.
 * Use these instead of magic strings when calling debugHooks.getCallback/setCallback.
 */
export const DEBUG_CALLBACK = Object.freeze({
  BLOCK_DEBUG: "blockDebug",
  BLOCK_LOGGING: "blockLogging",
  VISUAL_OVERLAY: "visualOverlay",
  GHOST_BLOCKS: "ghostBlocks",
  OUTLET_INFO_COMPONENT: "outletInfoComponent",
  CONDITION_LOG: "conditionLog",
  COMBINATOR_LOG: "combinatorLog",
  CONDITION_RESULT: "conditionResult",
  PARAM_GROUP_LOG: "paramGroupLog",
  ROUTE_STATE_LOG: "routeStateLog",
  OPTIONAL_MISSING_LOG: "optionalMissingLog",
  START_GROUP: "startGroup",
  END_GROUP: "endGroup",
  LOGGER_INTERFACE: "loggerInterface",
  GHOST_CHILDREN_CREATOR: "ghostChildrenCreator",
});

/**
 * A debug callback registered by dev-tools. Callbacks vary in arity and
 * return shape depending on which `DEBUG_CALLBACK` key they're registered
 * under, so callers narrow the return value at the call site.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type DebugCallback = (...args: any[]) => unknown;

/**
 * The logger interface handed to conditions for logging, as returned by the
 * LOGGER_INTERFACE callback.
 */
export interface DebugLoggerInterface {
  logCondition: DebugCallback;
  updateCombinatorResult: DebugCallback;
  updateConditionResult: DebugCallback;
  logParamGroup: DebugCallback;
  logRouteState: DebugCallback;
}

/**
 * Singleton class that manages debug callback hooks for the block rendering system.
 * Uses TrackedMap for reactivity, so components accessing these values will re-render
 * when callbacks are set or cleared.
 */
class DebugHooks {
  /**
   * Tracked callback registry for debug hooks.
   * Using TrackedMap enables reactivity when callbacks are set/cleared.
   */
  #callbacks: Map<string, DebugCallback | null> = trackedMap<
    string,
    DebugCallback | null
  >(Object.values(DEBUG_CALLBACK).map((key): [string, null] => [key, null]));

  /**
   * Returns whether console logging is enabled.
   * Convenience getter that invokes the blockLogging callback.
   *
   * @returns True if logging is enabled.
   */
  get isBlockLoggingEnabled(): boolean {
    return (
      (this.#callbacks.get(DEBUG_CALLBACK.BLOCK_LOGGING)?.() as
        | boolean
        | undefined) ?? false
    );
  }

  /**
   * Returns the outlet info component if outlet boundaries are enabled.
   * Invokes the OUTLET_INFO_COMPONENT callback which returns the component
   * when enabled, or a nullish value when disabled.
   *
   * @returns The outlet info component, or null.
   */
  get outletInfoComponent(): typeof Component | null | undefined {
    return this.#callbacks.get(DEBUG_CALLBACK.OUTLET_INFO_COMPONENT)?.() as
      | typeof Component
      | null
      | undefined;
  }

  /**
   * Returns whether outlet boundaries should be shown.
   * Derived from whether the outlet info component is available.
   *
   * @returns True if boundaries should be shown.
   */
  get isOutletBoundaryEnabled(): boolean {
    return !!this.outletInfoComponent;
  }

  /**
   * Returns whether visual overlay is enabled.
   *
   * @returns True if visual overlay is enabled.
   */
  get isVisualOverlayEnabled(): boolean {
    return (
      (this.#callbacks.get(DEBUG_CALLBACK.VISUAL_OVERLAY)?.() as
        | boolean
        | undefined) ?? false
    );
  }

  /**
   * Returns whether ghost blocks are enabled.
   *
   * @returns True if ghost blocks are enabled.
   */
  get isGhostBlocksEnabled(): boolean {
    return (
      (this.#callbacks.get(DEBUG_CALLBACK.GHOST_BLOCKS)?.() as
        | boolean
        | undefined) ?? false
    );
  }

  /**
   * Returns the logger interface for conditions to use.
   * Convenience getter that invokes the loggerInterface callback.
   *
   * The interface has methods: logCondition, updateCombinatorResult,
   * updateConditionResult, logParamGroup, logRouteState.
   *
   * @returns The logger interface, or null if not available.
   */
  get loggerInterface(): DebugLoggerInterface | null {
    return (
      (this.#callbacks.get(DEBUG_CALLBACK.LOGGER_INTERFACE)?.() as
        | DebugLoggerInterface
        | null
        | undefined) ?? null
    );
  }

  /**
   * Gets a debug callback from the registry.
   *
   * @param key - The callback key (use DEBUG_CALLBACK constants).
   * @returns The callback function, or null/undefined if not set.
   */
  getCallback(key: string): DebugCallback | null | undefined {
    return this.#callbacks.get(key);
  }

  /**
   * Sets a debug callback in the registry.
   * Used by dev-tools to register debug hooks.
   *
   * @param key - The callback key (use DEBUG_CALLBACK constants).
   * @param value - The callback function, or null to clear.
   * @throws If the key is not a valid callback key.
   */
  setCallback(key: string, value: DebugCallback | null): void {
    if (!this.#callbacks.has(key)) {
      const validKeys = Object.values(DEBUG_CALLBACK).join(", ");
      throw new Error(
        `[Blocks] Unknown debug callback key: "${key}". Valid keys are: ${validKeys}.`
      );
    }
    this.#callbacks.set(key, value);
  }
}

/**
 * Singleton instance of DebugHooks.
 * Import this to access debug callbacks with tracked reactivity.
 */
export const debugHooks = new DebugHooks();

/**
 * Ghost component data produced by the BLOCK_DEBUG dev-tools callback, before
 * the caller attaches a stable rendering `key`.
 */
export type DebugGhostData = Omit<ChildBlockResult, "key">;

/**
 * Data describing a block to ghost, passed to the BLOCK_DEBUG callback.
 */
export interface DebugGhostBlockData {
  /** The block name; absent when the block carries no decorator metadata. */
  name: string | undefined;
  /** The block's unique ID (if set). */
  id?: string;
  /** Block arguments. */
  args?: Record<string, unknown>;
  /** Container arguments. */
  containerArgs?: Record<string, unknown>;
  /** Block conditions. */
  conditions?: BlockEntry["conditions"];
  /** Type of failure (from FAILURE_TYPE). */
  failureType?: string;
  /** Custom failure reason message. */
  failureReason?: string;
  /** Ghost children for containers. */
  children?: ChildBlockResult[] | null;
}

/**
 * Context passed to the BLOCK_DEBUG callback alongside the ghost block data.
 */
export interface DebugGhostContext {
  /** The outlet/hierarchy name for display. */
  outletName: string;
  /** Outlet arguments. */
  outletArgs?: Record<string, unknown>;
}

/**
 * Options for `handleOptionalMissingBlock()`.
 */
export interface HandleOptionalMissingBlockOptions {
  /** The name of the missing block. */
  blockName: string;
  /** The block entry. */
  entry: BlockEntry;
  /** The hierarchy path for logging. */
  hierarchy: string;
  /** Whether debug logging is enabled. */
  isLoggingEnabled: boolean;
  /** Whether to show ghost components. */
  showGhosts: boolean;
  /** Stable unique key for this block. */
  key: string;
}

/**
 * Handles an optional missing block by logging and optionally creating a ghost.
 *
 * When a block reference ends with `?` but the block is not registered, this
 * function handles the logging and ghost component creation.
 *
 * @returns Ghost component data with key if showGhosts is true, null otherwise.
 */
export function handleOptionalMissingBlock({
  blockName,
  entry,
  hierarchy,
  isLoggingEnabled,
  showGhosts,
  key,
}: HandleOptionalMissingBlockOptions): ChildBlockResult | null {
  // Log if debug logging is enabled
  if (isLoggingEnabled) {
    debugHooks.getCallback(DEBUG_CALLBACK.OPTIONAL_MISSING_LOG)?.(
      blockName,
      entry.id,
      hierarchy
    );
  }

  // Show ghost if ghost blocks are enabled
  if (showGhosts) {
    const ghostData = createDebugGhost(
      {
        name: blockName,
        id: entry.id,
        args: entry.args,
        conditions: entry.conditions,
        failureType: FAILURE_TYPE.OPTIONAL_MISSING,
      },
      { outletName: hierarchy }
    );
    return ghostData ? { ...ghostData, key } : null;
  }

  return null;
}

/**
 * Builds a container path for nested containers.
 *
 * Maintains a count map to ensure unique indices for containers of the same type.
 * For example, if there are two "group" containers without ids, they get paths like:
 * - `baseHierarchy/group[0]`
 * - `baseHierarchy/group[1]`
 *
 * If a block has an id, it replaces the index (since the id is unique):
 * - `baseHierarchy/group(#my-id)`
 *
 * @param blockName - The block name.
 * @param blockId - The block's unique id (if set).
 * @param baseHierarchy - The base hierarchy path.
 * @param containerCounts - Map tracking container counts.
 * @returns The full container path.
 */
export function buildContainerPath(
  blockName: string,
  blockId: string | null | undefined,
  baseHierarchy: string,
  containerCounts: Map<string, number>
): string {
  // Always increment the counter for consistent indexing of blocks without ids.
  const count = containerCounts.get(blockName) ?? 0;
  containerCounts.set(blockName, count + 1);

  // Use id if available (unique), otherwise fall back to index.
  const suffix = blockId ? `(#${blockId})` : `[${count}]`;
  return `${baseHierarchy}/${blockName}${suffix}`;
}

/**
 * Invokes the BLOCK_DEBUG callback to create a ghost component.
 *
 * This is the low-level helper that calls the debug callback with block data.
 * Used by both `createGhostBlock` (entry-processing time) and `asGhost`
 * (render time) to avoid duplicating the callback invocation logic.
 *
 * @param blockData - Data describing the block to ghost.
 * @param context - Context for the ghost.
 * @returns Ghost data with Component property, or null if callback
 *   not set or didn't return a component.
 */
export function createDebugGhost(
  blockData: DebugGhostBlockData,
  context: DebugGhostContext
): DebugGhostData | null {
  const ghostData = debugHooks.getCallback(DEBUG_CALLBACK.BLOCK_DEBUG)?.(
    {
      ...blockData,
      Component: null,
      conditionsPassed: false,
    },
    context
  ) as DebugGhostData | undefined;

  return ghostData && ghostData.Component ? ghostData : null;
}

/**
 * A function that resolves a block reference (string name or class) to a
 * block class, an optional-missing marker, or null when unresolved. Used
 * here only as a value relayed to the GHOST_CHILDREN_CREATOR callback, not
 * called directly by this module.
 */
export type ResolveBlockFn = (blockRef: string | BlockClass) => unknown;

/**
 * Options for `createGhostBlock()`.
 */
export interface CreateGhostBlockOptions {
  /** The block name. */
  blockName: string;
  /** The block entry. */
  entry: BlockEntry;
  /** The hierarchy path for display. */
  hierarchy: string;
  /** Container path for child hierarchies. */
  containerPath?: string;
  /** Whether this block is a container. */
  isContainer: boolean;
  /** The application owner. */
  owner: Owner;
  /** Outlet arguments. */
  outletArgs?: Record<string, unknown>;
  /** Whether debug logging is enabled. */
  isLoggingEnabled: boolean;
  /** Function to resolve block references. */
  resolveBlockFn: ResolveBlockFn;
  /** Stable unique key for this block. */
  key: string;
}

/**
 * Creates a ghost component for an invisible block.
 *
 * Ghost components are shown in debug mode to visualize blocks that failed
 * their conditions or have no visible children.
 *
 * @returns Ghost component data with key if successful, null otherwise.
 */
export function createGhostBlock({
  blockName,
  entry,
  hierarchy,
  containerPath,
  isContainer,
  owner,
  outletArgs,
  isLoggingEnabled,
  resolveBlockFn,
  key,
}: CreateGhostBlockOptions): ChildBlockResult | null {
  // For container blocks with children that failed due to no visible children,
  // recursively create ghost children so they appear nested in the debug overlay.
  let ghostChildren: ChildBlockResult[] | null | undefined = null;
  if (
    isContainer &&
    entry.children?.length &&
    entry.__failureType === FAILURE_TYPE.NO_VISIBLE_CHILDREN
  ) {
    ghostChildren = debugHooks.getCallback(
      DEBUG_CALLBACK.GHOST_CHILDREN_CREATOR
    )?.(
      entry.children,
      owner,
      containerPath,
      outletArgs,
      isLoggingEnabled,
      resolveBlockFn
    ) as ChildBlockResult[] | undefined;
  }

  const ghostData = createDebugGhost(
    {
      name: blockName,
      id: entry.id,
      args: entry.args,
      containerArgs: entry.containerArgs,
      conditions: entry.conditions,
      failureType: entry.__failureType,
      failureReason: entry.__failureReason,
      children: ghostChildren,
    },
    { outletName: hierarchy }
  );

  return ghostData ? { ...ghostData, key } : null;
}

/**
 * Executes a function within a debug console group.
 * Ensures START_GROUP and END_GROUP callbacks are always paired.
 *
 * @param blockName - The block name for the group label.
 * @param blockId - The block's unique ID (if set).
 * @param hierarchy - The hierarchy path for context.
 * @param isLoggingEnabled - Whether debug logging is active.
 * @param fn - Function to execute that returns the condition result.
 * @returns The result of the function execution.
 */
export function withDebugGroup(
  blockName: string,
  blockId: string | null,
  hierarchy: string,
  isLoggingEnabled: boolean,
  fn: () => boolean
): boolean {
  if (!isLoggingEnabled) {
    return fn();
  }

  debugHooks.getCallback(DEBUG_CALLBACK.START_GROUP)?.(
    blockName,
    blockId,
    hierarchy
  );
  const result = fn();
  debugHooks.getCallback(DEBUG_CALLBACK.END_GROUP)?.(result);
  return result;
}
/**
 * Block error handling and entry formatting utilities.
 *
 * This module provides error classes, formatting utilities for error display,
 * and helpers for human-readable console output during block validation.
 */
import { DEBUG } from "@glimmer/env";
import { getBlockMetadata } from "discourse/lib/blocks/-internals/decorator";
import type { ValidationContext } from "discourse/lib/blocks/-internals/utils";

/* Value Display Helpers */

/**
 * Formats a simple value (primitive, function, or block reference) for display.
 * Returns null if the value is a complex type (array/object) that needs special handling.
 *
 * @param obj - The value to format.
 * @returns String representation, or null if complex type.
 */
function formatSimpleValue(obj: unknown): string | null {
  if (obj === undefined) {
    return "undefined";
  }
  if (obj === null) {
    return "null";
  }
  if (typeof obj === "function") {
    const blockName = getBlockMetadata(obj)?.blockName;
    return `<${blockName || obj.name || "Function"}>`;
  }
  if (typeof obj !== "object") {
    return JSON.stringify(obj);
  }
  const blockName = getBlockMetadata(obj)?.blockName;
  if (blockName) {
    return `<${blockName}>`;
  }
  return null;
}

/**
 * Formats a value as a truncated string for console display.
 * Returns shallow representations like `{ ... }` or `[ 3 items ]`.
 *
 * Note: This returns STRINGS for console output. For JSON-serializable
 * truncation, use truncateForDisplay() instead.
 *
 * @param obj - The value to format.
 * @returns Truncated string representation.
 */
function formatTruncatedValue(obj: unknown): string {
  const simple = formatSimpleValue(obj);
  if (simple !== null) {
    return simple;
  }

  if (Array.isArray(obj)) {
    return obj.length === 0 ? "[]" : `[ ${obj.length} items ]`;
  }

  // `formatSimpleValue()` only returns `null` for a non-null, non-array
  // object (every other type is handled by it directly), so `obj` is
  // guaranteed to be an object here even though the type-checker can't see
  // through that call.
  const keys = Object.keys(obj as object);
  return keys.length === 0 ? "{}" : "{ ... }";
}

/* Path Parsing */

/**
 * Parses a condition path string into path segments.
 * Handles both dot notation (`.key`) and bracket notation (`[0]`).
 *
 * @param path - The path string (e.g., "conditions.any[0][1].queryParams").
 * @returns Array of path segments.
 *
 * @example
 * ```
 * parseConditionPath("conditions.any[0][1].type")
 * // Returns: ["conditions", "any", 0, 1, "type"]
 * ```
 */
export function parseConditionPath(path: string): (string | number)[] {
  const segments: (string | number)[] = [];
  let current = "";

  for (let i = 0; i < path.length; i++) {
    const char = path[i];

    if (char === ".") {
      if (current) {
        segments.push(current);
        current = "";
      }
    } else if (char === "[") {
      if (current) {
        segments.push(current);
        current = "";
      }
      // Find closing bracket
      let j = i + 1;
      while (j < path.length && path[j] !== "]") {
        j++;
      }
      const index = path.slice(i + 1, j);
      segments.push(parseInt(index, 10));
      i = j; // Skip to after the closing bracket
    } else {
      current += char;
    }
  }

  if (current) {
    segments.push(current);
  }

  return segments;
}

/* Path-Aware Entry Rendering */

/**
 * Formatting options accepted by `formatEntryWithErrorPath()` and, in turn,
 * `PathHighlightRenderer`.
 */
export interface FormatEntryOptions {
  /** Prefix to skip in the path. */
  prefix?: string;
  /** Label to show before the entry. */
  label?: string;
}

/**
 * Renders block entries with error path highlighting.
 * Displays the structure with proper indentation and marks where errors occurred.
 */
class PathHighlightRenderer {
  #errorSegments: (string | number)[];
  #errorKey: string | number | undefined;
  #label: string | undefined;

  /**
   * @param errorPath - Path to the error (e.g., "conditions.any[0].type").
   * @param options - Formatting options.
   */
  constructor(errorPath: string, options: FormatEntryOptions = {}) {
    const { prefix, label } = options;
    const pathSegments = parseConditionPath(errorPath);

    const startIndex = prefix && pathSegments[0] === prefix ? 1 : 0;
    this.#errorSegments = pathSegments.slice(startIndex);
    this.#errorKey = this.#errorSegments.at(-1);
    this.#label = label;
  }

  /**
   * Renders the entry with the error path highlighted.
   *
   * @param entry - The block entry object (or array) to render.
   * @returns Formatted string with error location highlighted.
   */
  render(entry: unknown): string {
    const rendered = this.#renderValue(entry, 0, []);
    return this.#label ? `${this.#label} ${rendered}` : rendered;
  }

  /**
   * Checks if the current path is on the error path.
   *
   * @param currentPath - Current path segments.
   * @returns True if on error path.
   */
  #isOnErrorPath(currentPath: (string | number)[]): boolean {
    return currentPath.every(
      (seg, i) =>
        i >= this.#errorSegments.length || seg === this.#errorSegments[i]
    );
  }

  /**
   * Checks if we've passed the error location in the tree.
   *
   * @param currentPath - Current path segments.
   * @returns True if past error location.
   */
  #isPastErrorLocation(currentPath: (string | number)[]): boolean {
    return currentPath.length > this.#errorSegments.length;
  }

  /**
   * Renders any value, dispatching to the appropriate handler.
   *
   * @param obj - The value to render.
   * @param depth - Current indentation depth.
   * @param currentPath - Path segments to current location.
   * @returns Rendered string.
   */
  #renderValue(
    obj: unknown,
    depth: number,
    currentPath: (string | number)[]
  ): string {
    if (this.#isPastErrorLocation(currentPath)) {
      return formatTruncatedValue(obj);
    }

    const simple = formatSimpleValue(obj);
    if (simple !== null) {
      return simple;
    }

    if (Array.isArray(obj)) {
      return this.#renderArray(obj, depth, currentPath);
    }

    // `formatSimpleValue()` only returns `null` for a non-null, non-array
    // object, so `obj` is guaranteed to be a plain object here.
    return this.#renderObject(
      obj as Record<string, unknown>,
      depth,
      currentPath
    );
  }

  /**
   * Renders an array with path highlighting.
   *
   * @param arr - The array to render.
   * @param depth - Current indentation depth.
   * @param currentPath - Path segments to current location.
   * @returns Rendered string.
   */
  #renderArray(
    arr: unknown[],
    depth: number,
    currentPath: (string | number)[]
  ): string {
    if (arr.length === 0) {
      return "[]";
    }

    const indent = "  ".repeat(depth);
    const itemOnPathIndex = this.#findItemOnPath(arr, currentPath);
    const lines = ["["];

    if (itemOnPathIndex >= 0) {
      this.#renderArrayWithHighlightedItem(
        arr,
        itemOnPathIndex,
        depth,
        currentPath,
        indent,
        lines
      );
    } else {
      this.#renderArrayAllTruncated(arr, indent, lines);
    }

    lines.push(`${indent}]`);
    return lines.join("\n");
  }

  /**
   * Finds which array item (if any) is on the error path.
   *
   * @param arr - The array to search.
   * @param currentPath - Current path segments.
   * @returns Index of item on path, or -1 if none.
   */
  #findItemOnPath(arr: unknown[], currentPath: (string | number)[]): number {
    for (let i = 0; i < arr.length; i++) {
      const itemPath = [...currentPath, i];
      if (this.#isOnErrorPath(itemPath)) {
        return i;
      }
    }
    return -1;
  }

  /**
   * Renders an array with a highlighted item on the error path.
   *
   * @param arr - The array to render.
   * @param itemIndex - Index of the highlighted item.
   * @param depth - Current indentation depth.
   * @param currentPath - Current path segments.
   * @param indent - Current indentation string.
   * @param lines - Output lines array.
   */
  #renderArrayWithHighlightedItem(
    arr: unknown[],
    itemIndex: number,
    depth: number,
    currentPath: (string | number)[],
    indent: string,
    lines: string[]
  ): void {
    if (itemIndex > 0) {
      lines.push(`${indent}  ...`);
    }

    const itemPath = [...currentPath, itemIndex];
    const value = this.#renderValue(arr[itemIndex], depth + 1, itemPath);
    const comma = itemIndex < arr.length - 1 ? "," : "";
    const errorMarker = this.#isExactErrorLocation(itemPath)
      ? " // <-- error here"
      : "";

    lines.push(`${indent}  ${value}${comma}${errorMarker}`);

    if (itemIndex < arr.length - 1) {
      lines.push(`${indent}  ...`);
    }
  }

  /**
   * Renders all array items as truncated values.
   *
   * @param arr - The array to render.
   * @param indent - Current indentation string.
   * @param lines - Output lines array.
   */
  #renderArrayAllTruncated(
    arr: unknown[],
    indent: string,
    lines: string[]
  ): void {
    for (let i = 0; i < arr.length; i++) {
      const value = formatTruncatedValue(arr[i]);
      const comma = i < arr.length - 1 ? "," : "";
      lines.push(`${indent}  ${value}${comma}`);
    }
  }

  /**
   * Checks if a path is the exact error location.
   *
   * @param path - Path to check.
   * @returns True if this is the exact error location.
   */
  #isExactErrorLocation(path: (string | number)[]): boolean {
    return (
      path.length === this.#errorSegments.length &&
      path.every((seg, j) => seg === this.#errorSegments[j])
    );
  }

  /**
   * Renders an object with path highlighting.
   *
   * @param obj - The object to render.
   * @param depth - Current indentation depth.
   * @param currentPath - Path segments to current location.
   * @returns Rendered string.
   */
  #renderObject(
    obj: Record<string, unknown>,
    depth: number,
    currentPath: (string | number)[]
  ): string {
    const indent = "  ".repeat(depth);
    const keys = Object.keys(obj).filter((k) => !k.startsWith("_"));
    const isOnPath = this.#isOnErrorPath(currentPath);
    const nextErrorSegment = this.#errorSegments[currentPath.length];
    const needsSyntheticEntry =
      isOnPath &&
      typeof nextErrorSegment === "string" &&
      !keys.includes(nextErrorSegment);

    if (keys.length === 0 && !needsSyntheticEntry) {
      return "{}";
    }

    const lines = ["{"];
    this.#renderObjectKeys(
      obj,
      keys,
      depth,
      currentPath,
      isOnPath,
      indent,
      lines
    );

    if (needsSyntheticEntry) {
      this.#renderSyntheticEntry(currentPath, indent, lines);
    }

    lines.push(`${indent}}`);
    return lines.join("\n");
  }

  /**
   * Renders all keys of an object.
   *
   * @param obj - The object being rendered.
   * @param keys - Keys to render.
   * @param depth - Current indentation depth.
   * @param currentPath - Current path segments.
   * @param isOnPath - Whether current location is on error path.
   * @param indent - Current indentation string.
   * @param lines - Output lines array.
   */
  #renderObjectKeys(
    obj: Record<string, unknown>,
    keys: string[],
    depth: number,
    currentPath: (string | number)[],
    isOnPath: boolean,
    indent: string,
    lines: string[]
  ): void {
    for (const key of keys) {
      const keyPath = [...currentPath, key];
      const isKeyOnPath = this.#isOnErrorPath(keyPath);
      const isKeyTheError =
        isOnPath &&
        currentPath.length === this.#errorSegments.length - 1 &&
        key === this.#errorKey;

      const value =
        isKeyOnPath || isKeyTheError
          ? this.#renderValue(obj[key], depth + 1, keyPath)
          : formatTruncatedValue(obj[key]);
      const errorMarker = isKeyTheError ? " // <-- error here" : "";

      this.#appendKeyValueLine(key, value, errorMarker, indent, lines);
    }
  }

  /**
   * Appends a key-value line to the output, handling multiline values.
   *
   * @param key - The object key.
   * @param value - The rendered value.
   * @param errorMarker - Error marker string (or empty).
   * @param indent - Current indentation string.
   * @param lines - Output lines array.
   */
  #appendKeyValueLine(
    key: string,
    value: string,
    errorMarker: string,
    indent: string,
    lines: string[]
  ): void {
    if (value.includes("\n")) {
      const [firstLine, ...restLines] = value.split("\n");
      lines.push(`${indent}  ${key}: ${firstLine}${errorMarker}`);
      lines.push(`${restLines.join("\n")},`);
    } else {
      lines.push(`${indent}  ${key}: ${value},${errorMarker}`);
    }
  }

  /**
   * Renders a synthetic entry for missing keys on the error path.
   *
   * @param currentPath - Current path segments.
   * @param indent - Current indentation string.
   * @param lines - Output lines array.
   */
  #renderSyntheticEntry(
    currentPath: (string | number)[],
    indent: string,
    lines: string[]
  ): void {
    const remainingPath = this.#errorSegments.slice(currentPath.length);
    const nextSegment = remainingPath[0];
    const isAtFinalKey = remainingPath.length === 1;

    if (isAtFinalKey) {
      lines.push(`${indent}  ${nextSegment}: <missing>, // <-- error here`);
    } else {
      lines.push(`${indent}  ${nextSegment}: { // <-- missing`);
      lines.push(
        ...this.#renderMissingPath(
          remainingPath.slice(1),
          currentPath.length + 1
        )
      );
      lines.push(`${indent}  },`);
    }
  }

  /**
   * Renders the remaining path segments for a missing key.
   *
   * @param segments - Remaining path segments.
   * @param depth - Current indentation depth.
   * @returns Array of formatted lines.
   */
  #renderMissingPath(segments: (string | number)[], depth: number): string[] {
    const indent = "  ".repeat(depth);
    const lines: string[] = [];

    if (segments.length === 0) {
      return lines;
    }

    const [seg, ...rest] = segments;

    if (rest.length === 0) {
      lines.push(`${indent}  ${seg}: <missing>, // <-- error here`);
    } else {
      lines.push(`${indent}  ${seg}: { // <-- missing`);
      lines.push(...this.#renderMissingPath(rest, depth + 1));
      lines.push(`${indent}  },`);
    }

    return lines;
  }
}

/**
 * Renders a block entry object with the error path highlighted.
 * Shows the structure with proper indentation and adds a comment marker
 * to indicate where the error occurred.
 *
 * @param entry - The block entry object (or array) to render.
 * @param errorPath - The path to the error (e.g., "conditions.any[0][0].queryParams").
 * @param options - Formatting options.
 * @returns Formatted string with the error location highlighted.
 */
export function formatEntryWithErrorPath(
  entry: unknown,
  errorPath: string,
  options: FormatEntryOptions = {}
): string {
  return new PathHighlightRenderer(errorPath, options).render(entry);
}

/**
 * Truncates an object for JSON serialization in error messages.
 * Returns actual objects/arrays with truncated content, not strings.
 *
 * Note: This returns OBJECTS for JSON.stringify(). For string representations
 * in console output, use formatTruncatedValue() instead.
 *
 * Handles special cases like block classes, children arrays, and circular references.
 *
 * @param obj - The object to truncate.
 * @param maxDepth - Maximum nesting depth before truncating.
 * @param maxKeys - Maximum number of keys to show per object.
 * @param _seen - Internal parameter for tracking circular references.
 * @returns Truncated representation of the object.
 */
export function truncateForDisplay(
  obj: unknown,
  maxDepth = 2,
  maxKeys = 5,
  _seen: WeakSet<object> | null = null
): unknown {
  if (obj === null || typeof obj !== "object") {
    return obj;
  }

  // Initialize seen set on first call to track circular references
  const seen = _seen ?? new WeakSet<object>();

  // Handle circular references
  if (seen.has(obj)) {
    return "[Circular]";
  }
  seen.add(obj);

  if (maxDepth <= 0) {
    return Array.isArray(obj) ? "[...]" : "{...}";
  }

  if (Array.isArray(obj)) {
    // `Array.isArray()` narrows to the (necessarily untyped) built-in `any[]`;
    // re-declare it as `unknown[]` so nothing downstream carries an `any`.
    const arr = obj as unknown[];
    if (arr.length > maxKeys) {
      return [
        ...arr
          .slice(0, maxKeys)
          .map((v) => truncateForDisplay(v, maxDepth - 1, maxKeys, seen)),
        "...",
      ];
    }
    return arr.map((v) => truncateForDisplay(v, maxDepth - 1, maxKeys, seen));
  }

  // Filter out private keys (starting with _). `obj` is a non-null,
  // non-array object at this point, so it's safe to treat as a record.
  const record = obj as Record<string, unknown>;
  const keys = Object.keys(record).filter((k) => !k.startsWith("_"));
  const result: Record<string, unknown> = {};
  const displayKeys = keys.slice(0, maxKeys);

  for (const key of displayKeys) {
    // Handle special keys that don't serialize well or are verbose
    if (key === "block") {
      result[key] =
        `<${getBlockMetadata(record[key] as object)?.blockName || "Component"}>`;
    } else if (key === "children") {
      const children = record[key] as unknown[] | undefined;
      result[key] = `[${children?.length || 0} children]`;
    } else {
      result[key] = truncateForDisplay(
        record[key],
        maxDepth - 1,
        maxKeys,
        seen
      );
    }
  }

  if (keys.length > maxKeys) {
    result["..."] = `(${keys.length - maxKeys} more)`;
  }

  return result;
}

/* Error Handling */

/**
 * The V8-specific `Error.captureStackTrace` static, absent from the standard
 * `ErrorConstructor` type declarations. A no-op in non-V8 environments.
 */
interface V8ErrorConstructor {
  captureStackTrace?: (
    targetObject: object,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    constructorOpt?: (...args: any[]) => void
  ) => void;
}

/**
 * Captures the current call site as an Error object, excluding internal frames.
 * Call this at the entry point (e.g., renderBlocks) to capture where
 * the user's code called into the block system.
 *
 * Uses `Error.captureStackTrace` (V8-specific) to exclude the calling function
 * and everything above it from the stack trace. This means the stack will
 * point directly to the user's code, not to internal block system functions.
 *
 * @param callerFn - The function to exclude from the stack trace.
 *   Pass the function that calls `captureCallSite` (e.g., `_renderBlocks`).
 * @returns An Error object with stack trace starting from callerFn's caller.
 */
export function captureCallSite(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  callerFn: (...args: any[]) => void
): Error {
  const error = new Error();

  // V8-specific: exclude callerFn and everything above from the stack trace.
  // In non-V8 browsers, this is a no-op and the full stack is preserved.
  const v8Error: ErrorConstructor & V8ErrorConstructor = Error;
  if (v8Error.captureStackTrace) {
    v8Error.captureStackTrace(error, callerFn);
  }

  return error;
}

/**
 * Builds a tree-style breadcrumb showing the path from root to error.
 * Uses Unicode box-drawing characters for visual hierarchy.
 *
 * @param rootLayout - The root layout (an array of block entries).
 * @param errorPath - The path to the error (e.g., "[4].children[2].args.nme").
 * @returns Tree-style breadcrumb string.
 *
 * @example
 * ```
 * // Returns:
 * // └─ [4] BlockGroup (name: "callouts")
 * //    └─ [2] ChildBlockName
 * //       └─ args.nme  ← error here
 * ```
 */
function buildBreadcrumb(
  rootLayout: Array<Record<string, unknown>>,
  errorPath: string
): string {
  const segments = parseConditionPath(errorPath);
  const lines: string[] = [];
  let current: unknown = rootLayout;
  let indent = "";

  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i];

    if (typeof seg === "number" && Array.isArray(current)) {
      // Array index - show block info
      const block = current[seg] as Record<string, unknown> | undefined;
      const blockClass = block?.block;
      const blockName =
        getBlockMetadata(blockClass as object)?.blockName ||
        (blockClass as { name?: string } | undefined)?.name ||
        "Block";
      const args = block?.args as Record<string, unknown> | undefined;
      const nameArg = args?.name ? ` (name: "${args.name}")` : "";
      lines.push(`${indent}└─ [${seg}] ${blockName}${nameArg}`);
      current = block;
      indent += "   ";
    } else if (
      typeof seg === "string" &&
      current &&
      typeof current === "object"
    ) {
      // Object key - check if this is a terminal segment or intermediate
      const isLastSegment = i === segments.length - 1;
      const nextSeg = segments[i + 1];
      const value = (current as Record<string, unknown>)[seg];

      if (seg === "children" && typeof nextSeg === "number") {
        // "children" followed by index - continue traversal
        current = value;
      } else if (isLastSegment) {
        // Final segment - this is the error location
        lines.push(`${indent}└─ ${seg}  ← error here`);
      } else if (seg === "args" || seg === "conditions") {
        // Show remaining path as the error location
        const remaining = segments.slice(i).join(".");
        lines.push(`${indent}└─ ${remaining}  ← error here`);
        break;
      } else {
        current = value;
      }
    }
  }

  return lines.join("\n");
}

/**
 * Formats the error context into a human-readable string for console output.
 *
 * When an `errorPath` is provided, uses the path-aware formatter to show
 * the error location within the entry with a comment marker.
 *
 * @param context - The error context (see `ValidationContext`).
 * @returns Formatted context string, or empty string if no context.
 */
function formatErrorContext(
  context: Partial<ValidationContext> | null
): string {
  if (!context) {
    return "";
  }

  const parts = [];

  // Use errorPath if available, otherwise fall back to path
  // Many validation calls use "path" for block location in the tree
  const effectivePath = context.errorPath || context.path;

  // Display the error path location - use tree-style breadcrumb when rootLayout is available
  if (effectivePath) {
    if (context.rootLayout) {
      try {
        const breadcrumb = buildBreadcrumb(context.rootLayout, effectivePath);
        parts.push(`Location:\n${breadcrumb}`);
      } catch {
        // Fallback to plain path if breadcrumb fails
        parts.push(`Location: ${effectivePath}`);
      }
    } else {
      parts.push(`Location: ${effectivePath}`);
    }
  }

  // Priority: rootLayout tree > conditions > individual entry
  // Always prefer showing the full tree when rootLayout is available
  if (context.rootLayout && effectivePath) {
    // Root layout available - show full nesting path from root to error
    try {
      const layoutStr = formatEntryWithErrorPath(
        context.rootLayout,
        effectivePath
      );
      parts.push(`\nContext:\n${layoutStr}`);
    } catch {
      parts.push("Context: [unable to format]");
    }
  } else if (context.conditions && context.conditionsPath) {
    // Fallback: conditions with path-aware formatter
    // conditionsPath is relative to conditions object (e.g., "params.categoryId")
    try {
      const conditionsStr = formatEntryWithErrorPath(
        context.conditions,
        context.conditionsPath,
        { label: "conditions:" }
      );
      parts.push(`\nContext:\n${conditionsStr}`);
    } catch {
      parts.push("Context: [unable to format]");
    }
  } else if (context.entry && effectivePath) {
    // Fallback: individual block entry - strip path prefix for relative path
    try {
      let relativePath = effectivePath;
      if (context.path && effectivePath.startsWith(context.path)) {
        relativePath = effectivePath.slice(context.path.length);
        if (relativePath.startsWith(".")) {
          relativePath = relativePath.slice(1);
        }
      }
      const entryStr = formatEntryWithErrorPath(context.entry, relativePath);
      parts.push(`\nContext:\n${entryStr}`);
    } catch {
      parts.push("Context: [unable to format]");
    }
  } else if (context.conditions) {
    // Fallback to simple display without path highlighting
    try {
      const conditionsStr = JSON.stringify(
        truncateForDisplay(context.conditions),
        null,
        2
      );
      parts.push(`Conditions:\n${conditionsStr}`);
    } catch {
      parts.push("Conditions: [unable to serialize]");
    }
  } else if (context.entry) {
    try {
      const entryStr = JSON.stringify(
        truncateForDisplay(context.entry),
        null,
        2
      );
      parts.push(`Block entry:\n${entryStr}`);
    } catch {
      parts.push("Block entry: [unable to serialize]");
    }
  }

  return parts.length > 0 ? `\n\n${parts.join("\n")}` : "";
}

/**
 * Options accepted by `BlockError`'s constructor.
 */
export interface BlockErrorOptions {
  /** The underlying cause of this error, chained via the standard ES2022 `cause` option. */
  cause?: Error;
  /**
   * Path to the error within the layout (e.g., "[0].conditions.any[0].type"
   * or "[0].args.showIcon").
   */
  path?: string;
}

/**
 * Error thrown when block validation fails.
 * Used by block entry and condition validation to report
 * errors at registration time.
 *
 * Supports the standard `cause` option from ES2022 to chain errors together.
 * Note: `raiseBlockError()` uses a different approach - it reuses the
 * `callSiteError` directly (mutating its message and name) rather than
 * passing it as `cause`. This preserves the original stack trace pointing
 * to where `renderBlocks()` was called.
 */
export class BlockError extends Error {
  path?: string;

  /**
   * @param message - The error message.
   * @param options - Error options.
   */
  constructor(message: string, options?: BlockErrorOptions) {
    super(message, options);
    this.name = "BlockError";
    this.path = options?.path;
  }
}

/**
 * Raises a block error by throwing a `BlockError`.
 *
 * If context is provided, the error message will include the block
 * entry for debugging.
 *
 * If a `callSiteError` is present in the context, it is reused with the
 * new message. This preserves the original stack trace pointing to where
 * `renderBlocks()` was called, which is more useful than pointing to this
 * function. Source maps are applied automatically by the browser.
 *
 * @param message - The error message.
 * @param context - Optional error context for better error messages (see
 *   `ValidationContext`).
 * @throws Always throws a `BlockError`.
 */
export function raiseBlockError(
  message: string,
  context: Partial<ValidationContext> | null = null
): never {
  // Warn in DEBUG mode when entry-related errors are missing rootLayout
  // This helps catch future validation code that forgets to pass rootLayout
  if (DEBUG) {
    const hasPath = context?.path || context?.errorPath;
    const isEntryError =
      context?.entry || context?.conditions || context?.outletName;

    if (hasPath && isEntryError && !context?.rootLayout) {
      // eslint-disable-next-line no-console
      console.warn(
        `[Blocks] raiseBlockError called with path but no rootLayout. ` +
          `Add rootLayout to context for better error display. ` +
          `Path: ${context?.path || context?.errorPath}`
      );
    }
  }

  const contextInfo = formatErrorContext(context);
  const fullMessage = `[Blocks] ${message}${contextInfo}`;

  let error: Error & { path?: string };

  // If we have a call site error, reuse it with updated message.
  // This preserves the stack trace pointing to where renderBlocks() was called,
  // which is more useful than pointing to raiseBlockError().
  if (context?.callSiteError) {
    error = context.callSiteError;
    error.name = "BlockError";
    error.message = fullMessage;
    error.path = context.path;
  } else {
    error = new BlockError(fullMessage, { path: context?.path });
  }

  throw error;
}
/**
 * String similarity utilities for fuzzy matching.
 *
 * This module provides functions for computing string similarity using
 * Jaro-Winkler similarity. It is used for typo suggestions in validation
 * error messages throughout Discourse.
 *
 * @module discourse/lib/string-similarity
 */

/**
 * Calculates Jaro-Winkler similarity between two strings.
 *
 * Returns a score from 0 to 1, where 1 is an exact match. This algorithm
 * gives bonus weight to strings that share a common prefix, making it
 * ideal for detecting typos where someone forgets a suffix (e.g., "DISCOVERY"
 * instead of "DISCOVERY_PAGES").
 *
 * The algorithm works in two steps:
 * 1. Jaro similarity: Measures matching characters and transpositions
 * 2. Winkler modification: Adds bonus for matching prefix (up to 4 chars)
 *
 * @param {string} a - First string.
 * @param {string} b - Second string.
 * @returns {number} Similarity score between 0 and 1.
 *
 * @example
 * jaroWinklerSimilarity("DISCOVERY", "DISCOVERY_PAGES") // ~0.88 (prefix match)
 * jaroWinklerSimilarity("condition", "conditions")      // ~0.97 (1 char diff)
 * jaroWinklerSimilarity("foobar", "HOMEPAGE")           // ~0.40 (unrelated)
 */
export function jaroWinklerSimilarity(a, b) {
  if (a === b) {
    return 1;
  }
  if (a.length === 0 || b.length === 0) {
    return 0;
  }

  // Calculate the match window - characters can match if within this distance
  const matchWindow = Math.floor(Math.max(a.length, b.length) / 2) - 1;
  const aMatches = new Array(a.length).fill(false);
  const bMatches = new Array(b.length).fill(false);

  let matches = 0;
  let transpositions = 0;

  // Find matching characters within the match window
  for (let i = 0; i < a.length; i++) {
    const start = Math.max(0, i - matchWindow);
    const end = Math.min(i + matchWindow + 1, b.length);

    for (let j = start; j < end; j++) {
      if (bMatches[j] || a[i] !== b[j]) {
        continue;
      }
      aMatches[i] = true;
      bMatches[j] = true;
      matches++;
      break;
    }
  }

  if (matches === 0) {
    return 0;
  }

  // Count transpositions (matched chars that appear in different order)
  let k = 0;
  for (let i = 0; i < a.length; i++) {
    if (!aMatches[i]) {
      continue;
    }
    while (!bMatches[k]) {
      k++;
    }
    if (a[i] !== b[k]) {
      transpositions++;
    }
    k++;
  }

  // Calculate Jaro similarity
  const jaro =
    (matches / a.length +
      matches / b.length +
      (matches - transpositions / 2) / matches) /
    3;

  // Winkler modification: add bonus for common prefix (up to 4 characters)
  let prefix = 0;
  for (let i = 0; i < Math.min(4, a.length, b.length); i++) {
    if (a[i] === b[i]) {
      prefix++;
    } else {
      break;
    }
  }

  return jaro + prefix * 0.1 * (1 - jaro);
}

/**
 * Finds the closest match for a string from a list of candidates.
 *
 * Uses Jaro-Winkler similarity with a threshold to avoid suggesting
 * completely unrelated strings. The Jaro-Winkler algorithm gives bonus
 * weight to strings with matching prefixes, making it ideal for detecting
 * typos like "DISCOVERY" instead of "DISCOVERY_PAGES".
 *
 * @param {string} input - The string to find a match for.
 * @param {readonly string[]} candidates - List of valid strings to match against.
 * @param {Object} [options] - Options.
 * @param {number} [options.minSimilarity=0.8] - Minimum similarity (0-1) to consider a match.
 * @param {boolean} [options.caseSensitive=false] - Whether to compare case-sensitively.
 * @returns {string|null} The closest matching string, or null if none is similar enough.
 *
 * @example
 * findClosestMatch("conditon", ["block", "args", "conditions"]) // => "conditions"
 * findClosestMatch("DISCOVERY", ["DISCOVERY_PAGES", "HOMEPAGE"]) // => "DISCOVERY_PAGES"
 * findClosestMatch("foo", ["block", "args", "conditions"])      // => null
 */
export function findClosestMatch(input, candidates, options = {}) {
  const { minSimilarity = 0.8, caseSensitive = false } = options;
  let closestMatch = null;
  let highestSimilarity = 0;

  const normalizedInput = caseSensitive ? input : input.toLowerCase();

  for (const candidate of candidates) {
    const normalizedCandidate = caseSensitive
      ? candidate
      : candidate.toLowerCase();
    const similarity = jaroWinklerSimilarity(
      normalizedInput,
      normalizedCandidate
    );

    if (similarity > highestSimilarity && similarity >= minSimilarity) {
      highestSimilarity = similarity;
      closestMatch = candidate;
    }
  }

  return closestMatch;
}

/**
 * Formats an unknown value with a "did you mean?" suggestion if a close match exists.
 *
 * @param {string} value - The unknown/invalid value.
 * @param {readonly string[]} validValues - List of valid values to match against.
 * @param {{ minSimilarity?: number, caseSensitive?: boolean }} [options] - Options passed to findClosestMatch.
 * @returns {string} Formatted string like '"foo" (did you mean "bar"?)' or just '"foo"'.
 *
 * @example
 * formatWithSuggestion("conditon", ["conditions"]) // => '"conditon" (did you mean "conditions"?)'
 * formatWithSuggestion("xyz", ["conditions"])      // => '"xyz"'
 */
export function formatWithSuggestion(value, validValues, options = {}) {
  const suggestion = findClosestMatch(value, validValues, options);
  if (suggestion) {
    return `"${value}" (did you mean "${suggestion}"?)`;
  }
  return `"${value}"`;
}
/**
 * Shared arg validation utilities.
 *
 * This module provides generic validation functions for argument schemas
 * used by both blocks and conditions. Entity-specific validation logic
 * lives in separate modules:
 * - block-args.ts - block-specific validation
 * - condition-args.ts - condition-specific validation
 */
import type { ArgSchema, ArgType } from "discourse/blocks/types";
import {
  BlockError,
  raiseBlockError,
} from "discourse/lib/blocks/-internals/error";
import { formatWithSuggestion } from "discourse/lib/string-similarity";
import RestModel from "discourse/models/rest";

/**
 * A validation error result containing the error message and the path
 * to the argument that failed validation.
 */
export interface ValidationError {
  /** The formatted error message. */
  message: string;
  /** The path to the invalid argument (e.g., "test.name"). */
  path: string;
}

/**
 * Error-message context shared by the arg-value validation functions below.
 */
export interface ArgErrorContext {
  /** Optional entity name for context (e.g., block name). */
  contextName?: string | null;
  /** The entity type for the prefix (e.g., "Block", "Condition"). */
  contextType?: string;
}

/**
 * The minimal owner surface `validateArgValue` needs to resolve a `"model:*"`
 * `instanceOf` reference to its registered class. Modeled as a narrow local
 * shape rather than the full `@ember/owner` `Owner` — whose `factoryFor()` is
 * generic over literal `"type:name"` strings — because the model name here is
 * only known at runtime.
 */
interface ModelRegistryOwner {
  factoryFor?: (fullName: `model:${string}`) => { class?: unknown } | undefined;
}

/** Options accepted by `validateArgValue` and `validateArgsAgainstSchema`. */
export interface ValidateArgValueOptions extends ArgErrorContext {
  /** Ember owner for registry lookups (used for `"model:*"` `instanceOf`). */
  owner?: ModelRegistryOwner | null;
}

/**
 * Valid arg name pattern: must be a valid JavaScript identifier.
 * Starts with a letter, followed by letters, numbers, or underscores.
 * Note: Names starting with underscore are reserved for internal use.
 */
export const VALID_ARG_NAME_PATTERN = /^[a-zA-Z][a-zA-Z0-9_]*$/;

/**
 * Reserved argument names that cannot be used in block/condition arg schemas.
 * These are used internally by the block system and would conflict with
 * user-provided args. Names starting with underscore are also reserved.
 */
export const RESERVED_ARG_NAMES: readonly string[] = Object.freeze([
  "args",
  "block",
  "classNames",
  "containerArgs",
  "id",
  "outletArgs",
  "outletName",
  "children",
  "conditions",
  // Note: Names starting with underscore (e.g., __block$, __visible, __hierarchy)
  // are automatically reserved via the argName.startsWith("_") check in isReservedArgName()
]);

/**
 * Checks if an argument name is reserved for internal use.
 * Reserved names include explicit names in RESERVED_ARG_NAMES and
 * any name starting with underscore (private by convention).
 *
 * @param argName - The argument name to check
 * @returns True if the name is reserved
 */
export function isReservedArgName(argName: string): boolean {
  return RESERVED_ARG_NAMES.includes(argName) || argName.startsWith("_");
}

/**
 * Valid arg types for schema definitions.
 */
export const VALID_ARG_TYPES: readonly ArgType[] = Object.freeze([
  "string",
  "number",
  "boolean",
  "array",
  "object",
  "any",
]);

/** Valid item types for array args. */
type ArgItemType = NonNullable<ArgSchema["itemType"]>;

/**
 * Valid item types for array args.
 */
export const VALID_ITEM_TYPES: readonly ArgItemType[] = Object.freeze([
  "string",
  "number",
  "boolean",
]);

/**
 * Valid properties for arg schema definitions.
 */
export const VALID_ARG_SCHEMA_PROPERTIES: readonly string[] = Object.freeze([
  "type",
  "required",
  "default",
  "itemType",
  "itemEnum",
  "pattern",
  "minLength",
  "maxLength",
  "min",
  "max",
  "integer",
  "enum",
  "properties",
  "instanceOf",
  "instanceOfName",
]);

/**
 * A schema property validation rule, describing which arg types the
 * property is valid for and how to validate its value.
 */
interface SchemaPropertyRule {
  /** Arg types that can use this property. */
  allowedTypes: ArgType[];
  /** Validates the property's value. Omitted when checked elsewhere (e.g. via
   *  `formatWithSuggestion` or recursive schema validation). */
  valueCheck?: (value: unknown) => boolean;
  /** Error message if `valueCheck` fails. */
  valueError?: string;
  /** Text to append for type restriction errors (e.g., "string or array"). */
  typeErrorSuffix: string;
}

/**
 * Schema property rules for declarative validation.
 * Each rule defines:
 * - allowedTypes: arg types that can use this property
 * - valueCheck: function to validate the property value
 * - valueError: error message if value check fails
 * - typeErrorSuffix: text to append for type restriction errors (e.g., "string or array")
 */
export const SCHEMA_PROPERTY_RULES: Readonly<
  Record<string, SchemaPropertyRule>
> = Object.freeze({
  min: {
    allowedTypes: ["number"],
    valueCheck: (v) => typeof v === "number",
    valueError: "Must be a number.",
    typeErrorSuffix: "number",
  },
  max: {
    allowedTypes: ["number"],
    valueCheck: (v) => typeof v === "number",
    valueError: "Must be a number.",
    typeErrorSuffix: "number",
  },
  integer: {
    allowedTypes: ["number"],
    valueCheck: (v) => typeof v === "boolean",
    valueError: "Must be a boolean.",
    typeErrorSuffix: "number",
  },
  minLength: {
    allowedTypes: ["string", "array"],
    valueCheck: (v) => Number.isInteger(v) && (v as number) >= 0,
    valueError: "Must be a non-negative integer.",
    typeErrorSuffix: "string or array",
  },
  maxLength: {
    allowedTypes: ["string", "array"],
    valueCheck: (v) => Number.isInteger(v) && (v as number) >= 0,
    valueError: "Must be a non-negative integer.",
    typeErrorSuffix: "string or array",
  },
  pattern: {
    allowedTypes: ["string"],
    valueCheck: (v) => v instanceof RegExp,
    valueError: "Must be a RegExp.",
    typeErrorSuffix: "string",
  },
  itemType: {
    allowedTypes: ["array"],
    // valueCheck handled separately (uses formatWithSuggestion for better error message)
    typeErrorSuffix: "array",
  },
  enum: {
    allowedTypes: ["string", "number"],
    // valueCheck handled separately (uses validateEnumArray)
    typeErrorSuffix: "string or number",
  },
  itemEnum: {
    allowedTypes: ["array"],
    // valueCheck handled separately (uses validateEnumArray)
    typeErrorSuffix: "array",
  },
  properties: {
    allowedTypes: ["object"],
    // valueCheck handled separately (recursive schema validation)
    typeErrorSuffix: "object",
  },
  instanceOf: {
    allowedTypes: ["object"],
    // valueCheck handled separately (function or "model:*" string)
    typeErrorSuffix: "object",
  },
});

/** Options accepted by the schema-property validation helpers below. */
interface EntityErrorOptions {
  /** The entity name for error messages. */
  entityName?: string | null;
  /** The entity type for error messages. */
  entityType?: string;
}

/**
 * Validates a schema property against its rule.
 *
 * @param argDef - The argument definition.
 * @param argName - The argument name.
 * @param prop - The property name.
 * @param options - Optional configuration.
 */
export function validateSchemaProperty(
  argDef: ArgSchema,
  argName: string,
  prop: keyof ArgSchema,
  options: EntityErrorOptions = {}
): void {
  const { entityName, entityType = "Block" } = options;

  const rule = SCHEMA_PROPERTY_RULES[prop];
  if (!rule || argDef[prop] === undefined) {
    return;
  }

  // Check type restriction
  if (!rule.allowedTypes.includes(argDef.type)) {
    raiseBlockError(
      `${entityType} "${entityName}": arg "${argName}" has "${prop}" but type is "${argDef.type}". ` +
        `"${prop}" is only valid for ${rule.typeErrorSuffix} type.`
    );
  }

  // Check value validity (if valueCheck is defined)
  if (rule.valueCheck && !rule.valueCheck(argDef[prop])) {
    raiseBlockError(
      `${entityType} "${entityName}": arg "${argName}" has invalid "${prop}" value. ${rule.valueError}`
    );
  }
}

/**
 * Validates that at most one of the specified schema properties is defined (mutually exclusive).
 *
 * @param argDef - The argument definition.
 * @param argName - The argument name for error messages.
 * @param properties - Array of property names that are mutually exclusive.
 * @param options - Optional configuration.
 */
export function validateMutuallyExclusive(
  argDef: ArgSchema,
  argName: string,
  properties: readonly (keyof ArgSchema)[],
  options: EntityErrorOptions & {
    /** Label for the argument (e.g., "arg", "childArgs arg"). */
    argLabel?: string;
    /** Custom reason message. */
    reason?: string;
  } = {}
): void {
  const {
    entityName,
    entityType = "Block",
    argLabel = "arg",
    reason = "These are mutually exclusive - use only one.",
  } = options;

  const definedProps = properties.filter((prop) => argDef[prop] !== undefined);

  if (definedProps.length > 1) {
    // Format the list of conflicting properties
    const propList =
      definedProps.length === 2
        ? `"${definedProps[0]}" and "${definedProps[1]}"`
        : definedProps.map((p) => `"${p}"`).join(", ");

    raiseBlockError(
      `${entityType} "${entityName}": ${argLabel} "${argName}" has ${propList}. ${reason}`
    );
  }
}

/** The names of `ArgSchema`'s numeric range-pair properties. */
type NumericRangeProperty = "min" | "max" | "minLength" | "maxLength";

/**
 * Validates a min/max range pair in the schema.
 *
 * @param argDef - The argument definition.
 * @param argName - The argument name.
 * @param minProp - The min property name.
 * @param maxProp - The max property name.
 * @param options - Optional configuration.
 */
export function validateRangePair(
  argDef: ArgSchema,
  argName: string,
  minProp: NumericRangeProperty,
  maxProp: NumericRangeProperty,
  options: EntityErrorOptions = {}
): void {
  const { entityName, entityType = "Block" } = options;

  if (
    argDef[minProp] !== undefined &&
    argDef[maxProp] !== undefined &&
    argDef[minProp] > argDef[maxProp]
  ) {
    raiseBlockError(
      `${entityType} "${entityName}": arg "${argName}" has ${minProp} (${argDef[minProp]}) greater than ${maxProp} (${argDef[maxProp]}).`
    );
  }
}

/** Options accepted by `validateEnumArray`. */
interface ValidateEnumArrayOptions extends EntityErrorOptions {
  /** The enum array value to validate. */
  enumValue: unknown;
  /** Property name ("enum" or "itemEnum"). */
  propName: string;
  /** Expected type for values, or undefined to skip type check. */
  expectedType?: string;
  /** The argument name for error messages. */
  argName: string;
}

/**
 * Validates an enum-like array property (enum or itemEnum).
 * Checks that the value is a non-empty array and all items match the expected type.
 *
 * @param options - Validation options.
 */
function validateEnumArray({
  enumValue,
  propName,
  expectedType,
  argName,
  entityName,
  entityType,
}: ValidateEnumArrayOptions): void {
  if (!Array.isArray(enumValue) || enumValue.length === 0) {
    raiseBlockError(
      `${entityType} "${entityName}": arg "${argName}" has invalid "${propName}" value. Must be an array with at least one element.`
    );
    return;
  }

  if (expectedType !== undefined) {
    for (const value of enumValue) {
      if (typeof value !== expectedType) {
        raiseBlockError(
          `${entityType} "${entityName}": arg "${argName}" ${propName} contains invalid value "${value}". All values must be ${expectedType}s.`
        );
      }
    }
  }
}

/**
 * Validates the common schema properties that are shared between blocks and conditions.
 * This includes itemType, schema property rules, range pairs, enum, itemEnum, and required.
 *
 * Does NOT validate:
 * - "type is required" - blocks require it, conditions allow empty schemas for "any type"
 * - "default" validation - blocks validate default values, conditions reject the property entirely
 * - "required + default contradiction" - only relevant for blocks
 *
 * @param argDef - The argument definition.
 * @param argName - The argument name.
 * @param options - Optional configuration.
 */
export function validateCommonSchemaProperties(
  argDef: ArgSchema,
  argName: string,
  options: EntityErrorOptions = {}
): void {
  const { entityName, entityType = "Block" } = options;
  const context = { entityName, entityType };

  // Validate schema properties using declarative rules (type restrictions + value checks)
  // `Object.keys()` widens to `string[]`; every key of `SCHEMA_PROPERTY_RULES`
  // is a valid `ArgSchema` property name.
  for (const prop of Object.keys(
    SCHEMA_PROPERTY_RULES
  ) as (keyof ArgSchema)[]) {
    validateSchemaProperty(argDef, argName, prop, context);
  }

  // Validate range pairs
  validateRangePair(argDef, argName, "min", "max", context);
  validateRangePair(argDef, argName, "minLength", "maxLength", context);

  // Validate itemType value (uses formatWithSuggestion for better error messages)
  if (argDef.type === "array" && argDef.itemType !== undefined) {
    if (!VALID_ITEM_TYPES.includes(argDef.itemType)) {
      const suggestion = formatWithSuggestion(
        argDef.itemType,
        VALID_ITEM_TYPES
      );
      raiseBlockError(
        `${entityType} "${entityName}": arg "${argName}" has invalid itemType ${suggestion}. ` +
          `Valid item types are: ${VALID_ITEM_TYPES.join(", ")}.`
      );
    }
  }

  // Validate enum array contents
  if (argDef.enum !== undefined) {
    const expectedType = argDef.type === "string" ? "string" : "number";
    validateEnumArray({
      enumValue: argDef.enum,
      propName: "enum",
      expectedType,
      argName,
      entityName,
      entityType,
    });
  }

  // Validate itemEnum array contents
  if (argDef.itemEnum !== undefined) {
    validateEnumArray({
      enumValue: argDef.itemEnum,
      propName: "itemEnum",
      expectedType: argDef.itemType, // undefined skips type check
      argName,
      entityName,
      entityType,
    });
  }

  // Validate properties schema for object types
  if (argDef.type === "object" && argDef.properties !== undefined) {
    if (
      !argDef.properties ||
      typeof argDef.properties !== "object" ||
      Array.isArray(argDef.properties)
    ) {
      raiseBlockError(
        `${entityType} "${entityName}": arg "${argName}" has invalid "properties" value. Must be an object.`
      );
    } else {
      // Recursively validate each property schema
      for (const [propName, propDef] of Object.entries(argDef.properties)) {
        validateArgName(propName, {
          ...context,
          argLabel: `arg "${argName}" property`,
        });

        // Validate the property definition recursively
        const nestedArgName = `${argName}.properties.${propName}`;
        validateArgSchemaEntry(propDef, nestedArgName, {
          ...context,
          validProperties: VALID_ARG_SCHEMA_PROPERTIES,
          allowAnyType: false,
          argLabel: "property",
        });
      }
    }
  }

  // Validate instanceOf for object types
  if (argDef.type === "object" && argDef.instanceOf !== undefined) {
    // Check mutual exclusivity with properties
    validateMutuallyExclusive(
      argDef,
      argName,
      ["instanceOf", "properties"],
      context
    );

    // Validate instanceOf value: must be a function (constructor) or "model:*" string
    const isFunction = typeof argDef.instanceOf === "function";
    const isModelString =
      typeof argDef.instanceOf === "string" &&
      argDef.instanceOf.startsWith("model:");

    if (!isFunction && !isModelString) {
      raiseBlockError(
        `${entityType} "${entityName}": arg "${argName}" has invalid "instanceOf" value. ` +
          `Must be a class constructor or a "model:*" string (e.g., "model:user").`
      );
    }
  }

  // Validate instanceOfName for object types (only valid when instanceOf is a class reference)
  if (argDef.instanceOfName !== undefined) {
    if (argDef.instanceOf === undefined) {
      raiseBlockError(
        `${entityType} "${entityName}": arg "${argName}" has "instanceOfName" but no "instanceOf". ` +
          `"instanceOfName" is only valid when "instanceOf" is also specified.`
      );
    }
    if (typeof argDef.instanceOf === "string") {
      raiseBlockError(
        `${entityType} "${entityName}": arg "${argName}" has "instanceOfName" with a "model:*" instanceOf. ` +
          `"instanceOfName" is only valid for class references, not model strings.`
      );
    }
    if (typeof argDef.instanceOfName !== "string") {
      raiseBlockError(
        `${entityType} "${entityName}": arg "${argName}" has invalid "instanceOfName" value. ` +
          `Must be a string.`
      );
    }
  }

  // Validate required is boolean
  if (argDef.required !== undefined && typeof argDef.required !== "boolean") {
    raiseBlockError(
      `${entityType} "${entityName}": arg "${argName}" has invalid "required" value. Must be a boolean.`
    );
  }
}

/* Arg Schema Entry Validation Helpers */

/** Options accepted by `validateArgName`. */
interface ValidateArgNameOptions extends EntityErrorOptions {
  /** Label for error messages (e.g., "childArgs arg"). */
  argLabel?: string;
}

/**
 * Validates an argument name format.
 *
 * @param argName - The argument name to validate.
 * @param options - Optional configuration.
 * @returns True if valid, false if invalid (and error raised).
 */
export function validateArgName(
  argName: string,
  options: ValidateArgNameOptions = {}
): boolean {
  const { entityName, entityType = "Block", argLabel = "arg" } = options;

  if (!VALID_ARG_NAME_PATTERN.test(argName)) {
    raiseBlockError(
      `${entityType} "${entityName}": ${argLabel} name "${argName}" is invalid. ` +
        `Arg names must start with a letter and contain only letters, numbers, and underscores.`
    );
    return false;
  }

  // Check for reserved names (entry-level properties and underscore-prefixed names)
  if (isReservedArgName(argName)) {
    raiseBlockError(
      `${entityType} "${entityName}": ${argLabel} name "${argName}" is reserved. ` +
        `Reserved names are used as entry-level properties (id, children, conditions, etc.) or for internal use.`
    );
    return false;
  }

  return true;
}

/** Options accepted by `validateArgSchemaEntry`. */
export interface ValidateArgSchemaEntryOptions extends EntityErrorOptions {
  /** List of valid schema properties. */
  validProperties: readonly string[];
  /** Map of property names to their specific error messages. Properties in
   *  this map trigger a "disallowed" error instead of "unknown". */
  disallowedProperties?: Record<string, string>;
  /** If true, allow type: "any" (for conditions only). */
  allowAnyType?: boolean;
  /** Label for error messages (e.g., "childArgs arg"). */
  argLabel?: string;
}

/**
 * Validates a single arg schema entry (argDef).
 * Shared logic between block args, childArgs, and condition args validation.
 *
 * @param argDef - The argument definition.
 * @param argName - The argument name.
 * @param options - Configuration options.
 * @returns True if validation should continue with caller-specific logic, false if
 *   validation should stop (e.g., missing type, type: "any" with allowAnyType).
 */
export function validateArgSchemaEntry(
  argDef: ArgSchema,
  argName: string,
  options: ValidateArgSchemaEntryOptions
): boolean {
  const {
    entityName,
    entityType = "Block",
    validProperties,
    disallowedProperties = {},
    allowAnyType = false,
    argLabel = "arg",
  } = options;

  // Check argDef is object
  if (!argDef || typeof argDef !== "object") {
    raiseBlockError(
      `${entityType} "${entityName}": ${argLabel} "${argName}" must be an object with a "type" property.`
    );
    return false;
  }

  // Check for unknown/disallowed properties
  const disallowedPropNames = Object.keys(disallowedProperties);
  const unknownProps = Object.keys(argDef).filter(
    (prop) => !validProperties.includes(prop)
  );
  if (unknownProps.length > 0) {
    const disallowed = unknownProps.filter((p) =>
      disallowedPropNames.includes(p)
    );
    if (disallowed.length > 0) {
      const prop = disallowed[0]!;
      raiseBlockError(
        `${entityType} "${entityName}": ${argLabel} "${argName}" has disallowed property "${prop}". ` +
          disallowedProperties[prop]
      );
    } else {
      const suggestions = unknownProps.map((prop) =>
        formatWithSuggestion(prop, validProperties)
      );
      raiseBlockError(
        `${entityType} "${entityName}": ${argLabel} "${argName}" has unknown properties: ${suggestions.join(", ")}. ` +
          `Valid properties are: ${validProperties.join(", ")}.`
      );
    }
  }

  // Type is required
  if (!argDef.type) {
    raiseBlockError(
      `${entityType} "${entityName}": ${argLabel} "${argName}" is missing required "type" property.`
    );
    return false;
  }

  // Build valid types list based on whether "any" is allowed
  const validTypes = allowAnyType
    ? VALID_ARG_TYPES
    : VALID_ARG_TYPES.filter((t) => t !== "any");

  // Validate type
  if (!validTypes.includes(argDef.type)) {
    const suggestion = formatWithSuggestion(argDef.type, validTypes);
    raiseBlockError(
      `${entityType} "${entityName}": ${argLabel} "${argName}" has invalid type ${suggestion}. ` +
        `Valid types are: ${validTypes.join(", ")}.`
    );
  }

  // "any" type skips further validation (enum, itemType checks don't apply)
  if (argDef.type === "any") {
    return false;
  }

  // Validate common schema properties
  validateCommonSchemaProperties(argDef, argName, { entityName, entityType });

  return true;
}

