 * @param argNames - The arg names to check.
 * @param args - The resolved args.
 * @param blockName - The block name for error messages.
 * @returns Error message if validation fails, null otherwise.
 */
function validateAtLeastOne(
  argNames: string[],
  args: Record<string, unknown>,
  blockName: string
): string | null {
  const providedCount = argNames.filter(
    (name) => args[name] !== undefined
  ).length;

  if (providedCount === 0) {
    const argList = formatArgList(argNames);
    return `Block "${blockName}": at least one of ${argList} must be provided.`;
  }

  return null;
}

/**
 * Validates that exactly one of the specified args is provided.
 *
 * @param argNames - The arg names to check.
 * @param args - The resolved args.
 * @param blockName - The block name for error messages.
 * @returns Error message if validation fails, null otherwise.
 */
function validateExactlyOne(
  argNames: string[],
  args: Record<string, unknown>,
  blockName: string
): string | null {
  const providedArgs = argNames.filter((name) => args[name] !== undefined);
  const argList = formatArgList(argNames);

  if (providedArgs.length === 0) {
    return `Block "${blockName}": exactly one of ${argList} must be provided, but got none.`;
  }

  if (providedArgs.length > 1) {
    const providedList = formatArgList(providedArgs);
    return `Block "${blockName}": exactly one of ${argList} must be provided, but got ${providedArgs.length}: ${providedList}.`;
  }

  return null;
}

/**
 * Validates that either all or none of the specified args are provided.
 *
 * @param argNames - The arg names to check.
 * @param args - The resolved args.
 * @param blockName - The block name for error messages.
 * @returns Error message if validation fails, null otherwise.
 */
function validateAllOrNone(
  argNames: string[],
  args: Record<string, unknown>,
  blockName: string
): string | null {
  const providedCount = argNames.filter(
    (name) => args[name] !== undefined
  ).length;

  // Valid: all provided or none provided
  if (providedCount === 0 || providedCount === argNames.length) {
    return null;
  }

  // Invalid: some but not all
  const providedArgs = argNames.filter((name) => args[name] !== undefined);
  const missingArgs = argNames.filter((name) => args[name] === undefined);
  const argList = formatArgList(argNames);

  return (
    `Block "${blockName}": args ${argList} must be provided together or not at all. ` +
    `Got ${formatArgList(providedArgs)} but missing ${formatArgList(missingArgs)}.`
  );
}

/**
 * Validates that at most one of the specified args is provided (0 or 1).
 *
 * @param argNames - The arg names to check.
 * @param args - The resolved args.
 * @param blockName - The block name for error messages.
 * @returns Error message if validation fails, null otherwise.
 */
function validateAtMostOne(
  argNames: string[],
  args: Record<string, unknown>,
  blockName: string
): string | null {
  const providedArgs = argNames.filter((name) => args[name] !== undefined);

  if (providedArgs.length > 1) {
    const providedList = formatArgList(providedArgs);
    const argList = formatArgList(argNames);
    return `Block "${blockName}": at most one of ${argList} may be provided, but got ${providedArgs.length}: ${providedList}.`;
  }

  return null;
}

/**
 * Validates that if a dependent arg is provided, its required arg must also be provided.
 *
 * @param requiresMap - Object mapping dependent args to required args.
 * @param args - The resolved args.
 * @param blockName - The block name for error messages.
 * @returns Error message if validation fails, null otherwise.
 */
function validateRequires(
  requiresMap: Record<string, string>,
  args: Record<string, unknown>,
  blockName: string
): string | null {
  for (const [dependentArg, requiredArg] of Object.entries(requiresMap)) {
    if (args[dependentArg] !== undefined && args[requiredArg] === undefined) {
      return `Block "${blockName}": "${dependentArg}" requires "${requiredArg}" to be specified.`;
    }
  }
  return null;
}

/**
 * Runs a custom validation function if provided.
 *
 * @param validateFn - The custom validate function.
 * @param args - The resolved args (with defaults applied).
 * @returns Array of error messages if validation fails, null otherwise.
 */
export function runCustomValidation(
  validateFn: BlockValidateFn | null | undefined,
  args: Record<string, unknown>
): string[] | null {
  if (typeof validateFn !== "function") {
    return null;
  }

  const result = validateFn(args);

  if (result == null) {
    return null;
  }

  // Normalize to array
  if (typeof result === "string") {
    return [result];
  }

  if (Array.isArray(result)) {
    // `Array.isArray()` narrows to the (necessarily untyped) built-in `any[]`;
    // re-declare it as `unknown[]` so nothing downstream carries an `any`.
    const resultArray = result as unknown[];
    // Filter out non-string values and empty strings
    const errors = resultArray.filter(
      (e): e is string => typeof e === "string" && e.length > 0
    );
    return errors.length > 0 ? errors : null;
  }

  // Invalid return type - ignore
  return null;
}
import { findClosestMatch } from "discourse/lib/string-similarity";

/**
 * Page type definitions for the route condition.
 *
 * This is a pure data structure that defines the available page types
 * and their parameters. The evaluation logic is in route.js.
 */

/**
 * Definition of a single parameter accepted by a page type.
 */
export interface ParamDefinition {
  /** The expected type of the parameter. */
  type: "string" | "number";
  /** A description of the parameter. */
  description: string;
}

/**
 * Definition of a page type: its description and the parameters it exposes.
 */
export interface PageDefinition {
  /** A description of the page type. */
  description: string;
  /** The parameters for this page type. */
  params: Record<string, ParamDefinition>;
}

/**
 * The router service shape used by `getPageContext()`/`getCurrentPageType()`
 * to read the current route. Callers pass Ember's injected `router` service,
 * which is untyped at the call sites today.
 */
export interface PageContextRouter {
  currentRouteName?: string | null;
  currentRoute?: { params?: Record<string, unknown> } | null;
}

/**
 * The discovery service shape used by `getPageContext()`/`getCurrentPageType()`
 * to read the current discovery route state. Callers pass Discourse's injected
 * `discovery` service, which is untyped at the call sites today.
 */
export interface PageContextDiscovery {
  category?: {
    id?: number;
    slug?: string;
    parent_category_id?: number;
  } | null;
  tag?: { name?: string } | null;
  custom?: boolean;
  onDiscoveryRoute?: boolean;
}

/**
 * Injected services needed to extract page context.
