 *
 * The authorization model works as follows:
 * 1. AUTH_TOKEN is a secret symbol known only to this module.
 * 2. blockMetadataMap tracks which classes are decorated with @block.
 * 3. rootBlockClass holds the single block that can be rendered directly (set via registerRootBlock).
 * 4. Child blocks receive AUTH_TOKEN via the __block$ arg from their parent.
 * 5. BlockComponentManager verifies authorization before instantiation.
 *
 * This prevents:
 * - Using blocks directly in templates (bypassing BlockOutlet).
 * - Spoofing block authorization by setting properties on classes.
 * - Accessing authorization state from external code.
 */

/**
 * Secret token used to authorize block rendering. Passed via the `__block$` arg
 * from parent containers to child blocks.
 */
const AUTH_TOKEN = Symbol("block-auth-token");

/**
 * The minimal surface of Glimmer's internal component manager that this module
 * relies on. Wrapped in a Proxy to enforce block authorization on `create`.
 */
interface InternalManager {
  create(...args: unknown[]): unknown;
}

/**
 * The captured named-args reference Glimmer passes to `create`. Only the members
 * needed to read the `__block$` authorization token are described.
 */
interface CapturedArgs {
  named?: {
    names: string[];
    get(name: string): { compute(): unknown };
  };
}

/**
 * Maps block classes to their metadata. A WeakMap ensures classes are garbage
 * collected when no longer referenced and that authorization state cannot be
 * discovered via `Object.getOwnPropertySymbols()`. The key is widened to
 * `object` (rather than a block-class type) because the registry probes it with
 * lazy block factory functions too, and both classes and factories are objects.
 */
const blockMetadataMap = new WeakMap<object, BlockMetadata>();

/**
 * The single root block class (BlockOutlet). Only one block can be the root;
 * once set it cannot be changed, which prevents any other block from claiming
 * root status.
 */
let rootBlockClass: BlockClass | null = null;

/**
 * Registers a block class as the root block that can be rendered directly
 * without authorization. Only one root block can be registered.
 *
 * @param klass - The block class to register as the root.
 */
export function registerRootBlock(klass: BlockClass): void {
  if (rootBlockClass !== null) {
    // `BlockClass` is a construct signature, so `.name` (a runtime Function
    // static) is read through a cast.
    const existingName = (rootBlockClass as { name: string }).name;
    raiseBlockError(
      `Only one root block is allowed. ` +
        `"${existingName}" is already registered as the root block.`
    );
  }
  rootBlockClass = klass;
}

/**
 * Custom component-manager proxy that enforces block authorization. Blocks can
 * only be instantiated in two authorized scenarios:
 * 1. As the root block (the class is `rootBlockClass`, set via `registerRootBlock`).
 * 2. As a child of a container (the parent passes the `__block$` arg with `AUTH_TOKEN`).
 *
 * This prevents blocks from being used directly in templates, ensuring they can
 * only be rendered through the BlockOutlet system.
 */
const baseManager = getInternalComponentManager(Component) as InternalManager;

const BlockComponentManager = new Proxy(baseManager, {
  get(target, prop) {
    if (prop === "create") {
      // Glimmer calls `create` with more positional args than the three we
      // inspect (env, dynamic scope, caller, ...). Capture them all with a rest
      // param and forward the full list so no rendering context is dropped.
      return function (...createArgs: unknown[]): unknown {
        const klass = createArgs[1] as BlockClass;
        const args = createArgs[2] as CapturedArgs;

        // Check if this is the root block (BlockOutlet).
        const isRootBlock = klass === rootBlockClass;

        // Check if this is an authorized child (parent passes __block$ secret token).
        let isAuthorizedChild = false;
        const named = args?.named;
        if (named?.names?.includes("__block$")) {
          const ref = named.get("__block$");
          isAuthorizedChild = ref.compute() === AUTH_TOKEN;
        }

        if (!isRootBlock && !isAuthorizedChild) {
          const blockName =
            blockMetadataMap.get(klass)?.blockName ||
            (klass as { name: string }).name;
          throw new Error(
            `Block "${blockName}" cannot be used directly in templates. ` +
              `Blocks can only be rendered inside BlockOutlets or container blocks.`
          );
        }

        return target.create(...createArgs);
      };
    }
    return Reflect.get(target, prop);
  },
});

/**
 * Decorator that transforms a Glimmer component into a block component.
 *
 * Block components have special authorization constraints:
 * - They can only be rendered inside BlockOutlets or container blocks.
 * - They cannot be used directly in templates.
 * - They receive special args for authorization and hierarchy management.
 *
 * @experimental This API is under active development and may change or be
 * removed in future releases without prior notice.
 *
 * @param name - Unique identifier for the block. Supports three namespacing
 *   formats: core blocks `"block-name"`, plugin blocks `"plugin-name:block-name"`,
 *   and theme blocks `"theme:theme-name:block-name"`. Names must use lowercase
 *   letters, numbers, and hyphens only.
 * @param options - Configuration options for the block (see `BlockOptions`).
 * @returns A decorator that returns the decorated class.
 *
 * @example
 * ```js
 * @block("my-card")
 * class MyCard extends Component {}
 *
 * @block("my-section", { container: true })
 * class MySection extends Component {}
 * ```
 */
export function block(
  name: string,
  options: BlockOptions = {}
): <T extends BlockClass & { prototype: unknown }>(target: T) => T {
  // Decoration-time validation.
  validateBlockOptions(name, options);
  const parsed = validateAndParseBlockName(name);

  const {
    container: isContainer = false,
    classNames: decoratorClassNames = null,
    description = "",
    args: argsSchema = null,
    childArgs: childArgsSchema = null,
    constraints = null,
    validate: validateFn = null,
    allowedOutlets = null,
    deniedOutlets = null,
  } = options;

  // Validate arg schema structure and types.
  validateArgsSchema(argsSchema, name);

  // childArgs is only allowed on container blocks.
  if (childArgsSchema && !isContainer) {
    raiseBlockError(
      `Block "${name}": "childArgs" is only valid for container blocks (container: true).`
    );
  }

  // classNames must be a string, array, or function.
  if (
    decoratorClassNames != null &&
    typeof decoratorClassNames !== "string" &&
    typeof decoratorClassNames !== "function" &&
    !Array.isArray(decoratorClassNames)
  ) {
    raiseBlockError(
      `Block "${name}": "classNames" must be a string, array, or function.`
    );
  }

  // Validate childArgs schema structure and types.
  validateChildArgsSchema(childArgsSchema, name);

  // Validate constraints schema.
  validateConstraintsSchema(constraints, argsSchema, name);

  // validate must be a function if provided.
  if (validateFn !== null && typeof validateFn !== "function") {
    raiseBlockError(
      `Block "${name}": "validate" must be a function, got ${typeof validateFn}.`
    );
  }

  // Validate outlet restriction patterns.
  validateOutletRestrictions(name, allowedOutlets, deniedOutlets);

  return (target) => {
    setInternalComponentManager(BlockComponentManager, target);

    if (!(target.prototype instanceof Component)) {
      raiseBlockError("@block target must be a Glimmer component class");
    }

    // Create and register the frozen metadata object with all block information.
    const metadata: BlockMetadata = Object.freeze({
      allowedOutlets: allowedOutlets
        ? Object.freeze([...allowedOutlets])
        : null,
      args: argsSchema ? Object.freeze(argsSchema) : null,
      blockName: name,
      childArgs: childArgsSchema ? Object.freeze(childArgsSchema) : null,
      constraints: constraints ? Object.freeze(constraints) : null,
      decoratorClassNames,
      deniedOutlets: deniedOutlets ? Object.freeze([...deniedOutlets]) : null,
      description,
      isContainer,
      namespace: parsed.namespace,
      namespaceType: parsed.type,
      shortName: parsed.name,
      validate: validateFn,
    });

    blockMetadataMap.set(target, metadata);

    return target;
  };
}

/**
 * Creates the args object for a child block with reactive getters for context
 * args.
 *
 * This embeds the `AUTH_TOKEN` in the `__block$` property, which is how child
 * blocks are authorized to render. Context args are defined as getters rather
 * than direct properties so `curryComponent` can maintain a stable component
 * identity while still updating reactively when the getter values change.
 * Without getters, changing any arg would require a new curried component,
 * breaking Ember's identity-based rendering.
 *
 * @param entryArgs - User-provided args from the layout entry.
 * @param contextArgs - Rendering context to define as reactive getters.
 * @returns The merged args object ready for `curryComponent`.
 */
export function createBlockArgsWithReactiveGetters(
  entryArgs: Record<string, unknown>,
  contextArgs: Record<string, unknown>
): Record<string, unknown> {
  const blockArgs: Record<string, unknown> = {
    ...entryArgs,
    __block$: AUTH_TOKEN,
  };

  // Dynamically define reactive getters for each context arg.
  const propertyDescriptors: PropertyDescriptorMap = {};
  for (const [key, value] of Object.entries(contextArgs)) {
    propertyDescriptors[key] = {
      get() {
        return value;
      },
      enumerable: true,
    };
  }
  Object.defineProperties(blockArgs, propertyDescriptors);

  return blockArgs;
}

/**
 * Gets all metadata for a component registered with `@block`.
 *
 * @experimental This API is under active development and may change or be
 * removed in future releases without prior notice.
 *
 * @param component - The component (or factory) to get metadata for. Accepts
 *   nullish values so untyped registration paths can probe safely.
 * @returns The block metadata object, or `null` if not a block.
 */
export function getBlockMetadata(
  component: object | null | undefined
): BlockMetadata | null {
  return component ? (blockMetadataMap.get(component) ?? null) : null;
}
import { DEBUG } from "@glimmer/env";
import { trackedMap } from "@ember/reactive/collections";
import type { BlockMetadata } from "discourse/blocks/types";
import { getBlockMetadata } from "discourse/lib/blocks/-internals/decorator";
import { raiseBlockError } from "discourse/lib/blocks/-internals/error";
import {
  OPTIONAL_MISSING,
  type OptionalMissingMarker,
  parseBlockReference,
} from "discourse/lib/blocks/-internals/patterns";
import type {
  BlockClass,
  BlockFactory,
  BlockRegistryEntry,
} from "discourse/lib/blocks/-internals/types";
import type { CustomizationSource } from "discourse/lib/customization-source";
import { isTesting } from "discourse/lib/environment";
import {
  assertNotDuplicate,
  assertRegistryNotFrozen,
  createTestRegistrationWrapper,
  validateNamePattern,
  validateSourceNamespace,
} from "./helpers.ts";

/*
 * Registry State
 */

/**
 * Registry of block components registered via `api.registerBlock()`.
 * Maps block names to their component classes or factory functions.
 */
const blockRegistry = new Map<string, BlockRegistryEntry>();

/**
 * Cache for resolved factory functions.
 * Once a factory is resolved, the result is stored here to avoid re-resolving.
 *
 * This is a tracked map so that components calling `tryResolveBlock()` will
 * automatically re-render when a factory they depend on finishes resolving.
 * The tracked map tracks per-key, so only components waiting on specific blocks
 * are invalidated.
 */
const resolvedFactoryCache = trackedMap<string, BlockClass>();

/** Tracks in-flight resolution promises to prevent duplicate concurrent attempts. */
const pendingResolutions = new Map<string, Promise<BlockClass | undefined>>();

/** Caches failed resolution attempts to prevent infinite retry loops. */
const failedResolutions = new Set<string>();

/** Whether the block registry is frozen (no new registrations allowed). */
let registryFrozen = false;

/** Stores the initial frozen state to allow correct reset after tests. */
let testRegistryFrozenState: boolean | null = null;

/*
 * Public Functions
 */

/** Returns whether the block registry is frozen. */
export function isBlockRegistryFrozen(): boolean {
  return registryFrozen;
}

/**
 * Checks if a block is registered (by name or class reference).
 *
 * This is a synchronous check that does not resolve factory functions.
 * Use this to verify a block exists before attempting resolution.
 *
 * @param nameOrClass - Block name string or BlockClass.
 * @returns True if the block is registered.
 */
export function hasBlock(nameOrClass: string | BlockClass): boolean {
  if (typeof nameOrClass === "string") {
    return blockRegistry.has(nameOrClass);
  }
  const metadata: BlockMetadata | null = getBlockMetadata(nameOrClass);
  const blockName = metadata?.blockName;
  return blockName !== undefined && blockRegistry.has(blockName);
}

/**
 * Returns the registry entry for a block (class or factory).
 *
 * @param name - The block name.
 * @returns The registry entry, or undefined if not found.
 */
export function getBlockEntry(name: string): BlockRegistryEntry | undefined {
  return blockRegistry.get(name);
}

/**
 * Returns all block entries with their names as [name, entry] pairs.
 * Used by Blocks service for listing and introspection.
 *
 * @returns Array of [name, entry] pairs.
 */
export function getAllBlockEntries(): Array<[string, BlockRegistryEntry]> {
  return Array.from(blockRegistry.entries());
}

/**
 * Checks if a block is registered and fully resolved (not a pending factory).
 *
 * @param name - The block name to check.
 * @returns True if registered and resolved.
 */
export function isBlockResolved(name: string): boolean {
  if (!blockRegistry.has(name)) {
    return false;
  }
  const entry = blockRegistry.get(name);
  return !isBlockFactory(entry);
}

/**
 * Checks if a registry entry is a factory function (not a resolved class).
 *
 * Factory functions are plain functions not registered in the block metadata WeakMap.
 * BlockClasses are tracked by the `@block` decorator.
 *
 * @param entry - The registry entry to check.
 * @returns True if the entry is a factory function.
 */
export function isBlockFactory(
  entry: BlockRegistryEntry | undefined
): entry is BlockFactory {
  return typeof entry === "function" && !getBlockMetadata(entry);
}

/**
 * Resolves a block reference (string name or class) to a BlockClass.
 *
 * - If given a BlockClass, returns it directly.
 * - If given a string, looks up in registry and resolves factory if needed.
 * - Caches resolved factories to avoid re-resolving.
 *
 * @param nameOrClass - Block name string or BlockClass.
 * @returns The resolved block class, or undefined if resolution previously failed.
 * @throws If block not registered or factory resolution fails on first attempt.
 *
 * @example
 * ```javascript
 * const BlockClass = await resolveBlock("hero-banner");
 * const BlockClass = await resolveBlock(HeroBanner); // Returns directly
 * ```
 */
export async function resolveBlock(
  nameOrClass: string | BlockClass
): Promise<BlockClass | undefined> {
  if (typeof nameOrClass !== "string") {
    if (!getBlockMetadata(nameOrClass)) {
      raiseBlockError(
        `Invalid block reference: expected string name or @block-decorated class, ` +
          `got ${typeof nameOrClass}.`
      );
    }
    return nameOrClass;
  }

  const name = nameOrClass;

  if (resolvedFactoryCache.has(name)) {
    return resolvedFactoryCache.get(name);
  }

  if (failedResolutions.has(name)) {
    return undefined;
  }

  if (pendingResolutions.has(name)) {
    return pendingResolutions.get(name);
  }

  if (!blockRegistry.has(name)) {
    raiseBlockError(
      `Block "${name}" is not registered. ` +
        `Use api.registerBlock() in a pre-initializer before any renderBlocks() configuration.`
    );
  }

  // Guaranteed to be set by the `.has()` check above.
  const entry = blockRegistry.get(name)!;

  if (!isBlockFactory(entry)) {
    return entry;
  }

  const resolutionPromise = resolveFactory(name, entry);
  pendingResolutions.set(name, resolutionPromise);
  return resolutionPromise;
}

/**
 * Attempts to resolve a block reference to a BlockClass synchronously.
 *
 * If the block is already resolved, returns the BlockClass immediately.
 * If the block is a factory that hasn't resolved yet, triggers async resolution
 * and returns null. The calling component will automatically re-render when the
 * factory resolves.
 *
 * @param blockRef - Block reference (string name or class). String names may
 *   include a trailing "?" to mark the block as optional.
 * @returns The BlockClass if found and resolved; an optional-missing marker if
 *   the block is optional and not registered; or `null` if the block is not
 *   registered (non-optional) or is a factory awaiting resolution.
 */
export function tryResolveBlock(
  blockRef: string | BlockClass
): BlockClass | OptionalMissingMarker | null {
  if (typeof blockRef !== "string") {
    return blockRef;
  }

  const { name: blockName, optional } = parseBlockReference(blockRef);

  // Check cache first - ALWAYS call .get() to establish tracking dependency.
  // TrackedMap establishes tracking even when key doesn't exist (returns undefined).
  // This ensures component re-renders when factory resolves and calls .set().
  const cachedClass = resolvedFactoryCache.get(blockName);
  if (cachedClass) {
    return cachedClass;
  }

  if (!blockRegistry.has(blockName)) {
    if (optional) {
      return { optionalMissing: OPTIONAL_MISSING, name: blockName };
    }
    // eslint-disable-next-line no-console
    console.error(`[Blocks] Block "${blockName}" is not registered.`);
    return null;
  }

  // Guaranteed to be set by the `.has()` check above.
  const entry = blockRegistry.get(blockName)!;

  if (!isBlockFactory(entry)) {
    return entry;
  }

  // Trigger async resolution. Returns null for this render cycle - the component
  // will re-render automatically when the factory resolves (tracked via TrackedMap).
  resolveBlock(blockName).catch((error: unknown) => {
    // TODO (blocks-api) Consider returning an error marker and rendering an error
    // placeholder component for admin visibility, rather than silently returning null.
    document.dispatchEvent(
      new CustomEvent("discourse-error", {
        detail: { messageKey: "broken_block_factory_alert", error },
      })
    );
  });

  return null;
}

/*
 * Internal Functions
 */

/**
 * Freezes the registry, preventing further registrations.
 * Called by the "freeze-block-registry" initializer during app boot.
 *
 * @internal
 */
export function _freezeBlockRegistry(): void {
  registryFrozen = true;
}

/**
 * Registers a block component in the registry.
 * Must be called before any renderBlocks() configuration is registered.
 *
 * The block component must be decorated with `@block`. Block metadata
 * (including `blockName`) is stored in an internal WeakMap and accessed
 * via `getBlockMetadata()`.
 *
 * @param klass - The block component class. Typed nullable because untyped
 *   callers reach this through `api.registerBlock()`, where a bad or circular
 *   import hands it `undefined`; that call must report the decorator error
 *   rather than fail on a property read.
 * @param source - The plugin or theme the call came from.
 * @throws If called after registry is locked, or if block is invalid
 *
 * @example
 * ```javascript
 * // In a plugin's pre-initializer (plugins/my-plugin/assets/javascripts/pre-initializers/...)
 * import { withPluginApi } from "discourse/lib/plugin-api";
 * import MyBlock from "../blocks/my-block";
 *
 * export default {
 *   initialize() {
 *     withPluginApi("1.0", (api) => {
 *       api.registerBlock(MyBlock);
 *     });
 *   },
 * };
 * ```
 */
export function _registerBlock(
  klass: BlockClass | null | undefined,
  source?: CustomizationSource
): void {
  const metadata: BlockMetadata | null = getBlockMetadata(klass);
  const blockName = metadata?.blockName;

  if (
    !assertRegistryNotFrozen({
      frozen: registryFrozen,
      apiMethod: "api.registerBlock()",
      entityType: "Block",
      entityName: blockName || klass?.name,
    })
  ) {
    return;
  }

  if (!klass || !blockName) {
    raiseBlockError(
      `Block class "${klass?.name}" must be decorated with @block to be registered.`
    );
    return;
  }

  if (!validateNamePattern(blockName, "Block")) {
    return;
  }

  if (
    !validateSourceNamespace({ name: blockName, entityType: "block", source })
  ) {
    return;
  }

  if (!assertNotDuplicate(blockRegistry, blockName, "Block")) {
    return;
  }

  blockRegistry.set(blockName, klass);
}

/**
 * Registers a factory function for lazy loading a block.
 *
 * The factory will be called when the block is first needed. It must return
 * a Promise that resolves to a BlockClass (or a module with a default export).
 *
 * @param name - The name to register the block under.
 * @param factory - Factory function returning Promise<BlockClass>.
 * @param source - The plugin or theme the call came from.
 * @throws If registry is locked, name is invalid, or factory is not a function.
 *
 * @example
 * ```javascript
 * api.registerBlock("hero-banner", () => import("../blocks/hero-banner"));
 * ```
 *
 * @internal
 */
export function _registerBlockFactory(
  name: string,
  factory: BlockFactory,
  source?: CustomizationSource
): void {
  if (
    !assertRegistryNotFrozen({
      frozen: registryFrozen,
      apiMethod: "api.registerBlock()",
      entityType: "Block",
      entityName: name,
    })
  ) {
    return;
  }

  if (!validateNamePattern(name, "Block")) {
    return;
  }

  if (typeof factory !== "function") {
    raiseBlockError(
      `Block factory for "${name}" must be a function that returns a Promise<BlockClass>.`
    );
    return;
  }

  if (!validateSourceNamespace({ name, entityType: "block", source })) {
    return;
  }

  if (!assertNotDuplicate(blockRegistry, name, "Block")) {
    return;
  }

  blockRegistry.set(name, factory);
}

/**
 * Resolves a factory function and caches the result.
 *
 * @param name - The block name.
 * @param factory - The factory function to resolve.
 * @returns The resolved block class.
 * @throws If the factory returns an invalid class or the resolved name doesn't match.
 */
async function resolveFactory(
  name: string,
  factory: BlockFactory
): Promise<BlockClass | undefined> {
  try {
    const result = await factory();

    // A factory resolves to the class itself or to a module namespace, and to
    // nothing at all when an author forgets to return. Unwrap without assuming
    // a value is present so an absent result reaches the error below.
    const resolvedClass = ((result as { default?: BlockClass } | null)
      ?.default ?? result) as BlockClass;
    const resolvedBlockName = getBlockMetadata(resolvedClass)?.blockName;

    if (!resolvedBlockName) {
      raiseBlockError(
        `Block factory for "${name}" did not return a valid @block-decorated class.`
      );
    }

    if (resolvedBlockName !== name) {
      raiseBlockError(
        `Block factory registered as "${name}" resolved to a block with ` +
          `blockName "${resolvedBlockName}". The registered name must match ` +
          `the block's @block decorator name.`
      );
    }

    resolvedFactoryCache.set(name, resolvedClass);
    blockRegistry.set(name, resolvedClass);

    return resolvedClass;
  } catch (error: unknown) {
    failedResolutions.add(name);

    // Thrown errors are always `Error`-like: either a rethrown `BlockError` or
    // a factory/import failure. Cast to read `.name`/`.message` without
    // widening the catch signature to `any`.
    const err = error as Error;

    if (err.name === "BlockError") {
      throw err;
    }
    raiseBlockError(
      `Failed to resolve block factory for "${name}": ${err.message}`
    );
    return undefined;
  } finally {
    pendingResolutions.delete(name);
  }
}

/*
 * Test Utilities
 */

/**
 * Temporarily unfreezes the block registry for testing.
 *
 * USE ONLY FOR TESTING PURPOSES.
 */
export const withTestBlockRegistration = createTestRegistrationWrapper({
  getFrozen: () => registryFrozen,
  setFrozen: (value) => {
    registryFrozen = value;
  },
  getSavedState: () => testRegistryFrozenState,
  setSavedState: (value) => {
    testRegistryFrozenState = value;
  },
  name: "withTestBlockRegistration",
});

/**
 * Resets the block registry state for testing.
 *
 * USE ONLY FOR TESTING PURPOSES.
 *
 * @internal Called by `resetBlockRegistryForTesting`, not meant for direct use.
 */
export function _resetBlockRegistryState(): void {
  // allows tree-shaking in production builds
  if (!DEBUG) {
    return;
  }
  if (!isTesting()) {
    throw new Error("_resetBlockRegistryState can only be used in tests.");
  }
  blockRegistry.clear();
  resolvedFactoryCache.clear();
  pendingResolutions.clear();
  failedResolutions.clear();
  registryFrozen = false;
  testRegistryFrozenState = null;
}
