interface BlockOutletRootContainerSignature {
  Args: {
    outletName: string;
    outletArgs: Record<string, unknown>;
    rawChildren: BlockEntry[];
    showGhosts: boolean;
    showVisualOverlay: boolean;
    isLoggingEnabled: boolean;
    createChildBlockFn: CreateChildBlockFn;
  };
