    const confirmed = await this.dialog.yesNoConfirm({
      message: i18n(
        "nested_replies.category_settings.convert_existing_confirm"
      ),
    });

    if (!confirmed) {
      return;
    }

    this.converting = true;

    try {
      const result = await ajax(
        `/categories/${this.category.id}/convert_nested_replies`,
        { type: "POST" }
