} from "discourse/routes/build-topic-route";
import DiscourseRoute from "discourse/routes/discourse";
import { i18n } from "discourse-i18n";

const NONE = "none";
const ALL = "all";

@disableImplicitInjections
export default class TagShowRoute extends DiscourseRoute {
  @service router;
  @service currentUser;
  @service store;
  @service topicTrackingState;
  @service("search") searchService;
  @service historyStore;

  queryParams = queryParams;
  templateName = "discovery/list";
  routeConfig = {};

  get navMode() {
    return this.routeConfig.navMode || "latest";
  }

  get noSubcategories() {
    return this.routeConfig.noSubcategories;
  }

  async model(params, transition) {
    // support both canonical (tag_slug/tag_id) and legacy (tag_name) params
    let slug = params.tag_slug || params.tag_name;
    let id = parseInt(params.tag_id, 10);

    if (params.tag_id && isNaN(id) && params.category_slug_path_with_id) {
      params.category_slug_path_with_id = `${params.category_slug_path_with_id}/${slug}`;
      slug = params.tag_id;
      id = null;
    }

    if (!slug) {
      slug = NONE;
      id = null;
    }

    // handle legacy URLs without tag_id - fetch tag info to get the ID
    // e.g., /tags/c/category/1/my-tag -> need to lookup my-tag to get its ID
    // skip redirect for intersection routes (they use tag_name, not tag_slug/tag_id)
    const isIntersectionRoute = params.additional_tags !== undefined;
    if (slug && slug !== NONE && !id && !isIntersectionRoute) {
      try {
        const result = await ajax(`/tag/${slug}/info.json`);
        if (result.tag_info) {
          id = result.tag_info.id;
          // redirect to canonical URL with ID
          const routeName = transition.to.name;
          const transitionQueryParams = transition.to.queryParams;
          if (params.category_slug_path_with_id) {
            return this.router.replaceWith(
              routeName,
              params.category_slug_path_with_id,
              result.tag_info.slug,
              id,
              { queryParams: transitionQueryParams }
            );
          }
          return this.router.replaceWith(routeName, result.tag_info.slug, id, {
            queryParams: transitionQueryParams,
          });
        }
      } catch {
        // tag not found, continue with slug only
      }
    }

    // use slug as initial name until API returns actual name
    const tag = this.store.createRecord("tag", {
      id,
      name: slug,
      slug,
    });

    let additionalTags;

    if (params.additional_tags) {
      additionalTags = params.additional_tags
        .split("/")
        .filter(Boolean)
        .map((t) => {
          return this.store.createRecord("tag", {
            name: escapeExpression(t),
          }).name;
        });
    }

    const filterType = filterTypeForMode(this.navMode);

    let tagNotification;
    if (tag && slug !== NONE && this.currentUser && !additionalTags) {
      tagNotification = await this.store.find("tagNotification", id);
    }

    let category = params.category_slug_path_with_id
      ? Category.findBySlugPathWithID(params.category_slug_path_with_id)
      : null;
    const filteredQueryParams = filterQueryParams(
      transition.to.queryParams,
      {}
    );
    const topicFilter = this.navMode;
    let filter;

    if (category) {
      category.setupGroupsAndPermissions();
      filter = `tags/c/${Category.slugFor(category)}/${category.id}`;

      if (this.noSubcategories !== undefined) {
        filter += this.noSubcategories ? `/${NONE}` : `/${ALL}`;
      }

      if (slug === NONE) {
        // untagged category route - use "none" without ID
        filter += `/${NONE}/l/${topicFilter}`;
      } else {
        // category+tag routes still use slug/id format
        filter += `/${slug}/${id}/l/${topicFilter}`;
      }
    } else if (additionalTags) {
      filter = `tags/intersection/${slug}/${additionalTags.join("/")}`;

      if (transition.to.queryParams["category"]) {
        filteredQueryParams["category"] = transition.to.queryParams["category"];
        category = Category.findBySlugPathWithID(
          transition.to.queryParams["category"]
        );
      }
    } else if (slug === NONE) {
      filter = `tag/${NONE}/l/${topicFilter}`;
    } else {
      // use ID-only format for API calls
      filter = `tag/${id}/l/${topicFilter}`;
    }

    if (
      this.noSubcategories === undefined &&
      category?.default_list_filter === "none" &&
      topicFilter === "latest"
    ) {
      // TODO: avoid throwing away preload data by redirecting on the server
      PreloadStore.getAndRemove("topic_list");
      return this.router.replaceWith(
        "tags.showCategoryNone",
        params.category_slug_path_with_id,
        slug,
        id
      );
    }

    const list = await findTopicList(
      this.store,
      this.topicTrackingState,
      filter,
      filteredQueryParams,
      {
        cached: this.historyStore.isPoppedState,
      }
    );

    if (list.topic_list.tags && list.topic_list.tags.length >= 1) {
      const mainTagData = list.topic_list.tags.find(
        (t) =>
          t.id === id ||
          (!id &&
            (t.name.toLowerCase() === slug.toLowerCase() || t.slug === slug))
      );
      if (mainTagData) {
        tag.setProperties({
          id: mainTagData.id,
          name: mainTagData.name,
          slug: mainTagData.slug,
          staff: mainTagData.staff,
          description: mainTagData.description,
          topic_count: mainTagData.topic_count,
        });
      } else if (!additionalTags) {
        // tag was a synonym, redirect to canonical tag URL
        const canonicalTag = list.topic_list.tags[0];
        const routeName = transition.to.name;
        if (params.category_slug_path_with_id) {
          return this.router.replaceWith(
            routeName,
            params.category_slug_path_with_id,
            canonicalTag.slug,
            canonicalTag.id
          );
        } else {
          return this.router.replaceWith(
            routeName,
            canonicalTag.slug,
            canonicalTag.id
          );
        }
      }

      if (additionalTags) {
        additionalTags = additionalTags.map((additionalSlug) => {
          const tagData = list.topic_list.tags.find(
            (t) =>
              t.name.toLowerCase() === additionalSlug.toLowerCase() ||
              t.slug === additionalSlug
          );
          return tagData ? tagData.name : additionalSlug;
        });
      }
    }

    return {
      tag,
      category,
      list,
      additionalTags,
      filterType,
      tagNotification,
      canCreateTopic: list.can_create_topic,
      canCreateTopicOnCategory: category?.permission === PermissionType.FULL,
      canCreateTopicOnTag: !tag.staff || this.currentUser?.staff,
      noSubcategories: this.noSubcategories,
    };
  }

  setupController(controller, model) {
    super.setupController(...arguments);
    controller.bulkSelectHelper.clear();
    controller.syncTagInfo();
    setTopicList(model.list);

    if (model.category || model.additionalTags) {
      const tagIntersectionSearchContext = {
        type: "tagIntersection",
        tagId: model.tag.name,
        tag: model.tag,
        additionalTags: model.additionalTags || null,
        categoryId: model.category?.id || null,
        category: model.category || null,
      };

      this.searchService.searchContext = tagIntersectionSearchContext;
    } else {
      this.searchService.searchContext = model.tag.searchContext;
    }
  }

  titleToken() {
    const filterText = i18n(`filters.${this.navMode.replace("/", ".")}.title`);
    const model = this.currentModel;

    const tag = model?.tag?.name;
    if (tag && tag !== NONE) {
      if (model.category) {
        return i18n("tagging.filters.with_category", {
          filter: filterText,
          tag: model.tag.name,
          category: model.category.displayName,
        });
      } else {
        return i18n("tagging.filters.without_category", {
          filter: filterText,
          tag: model.tag.name,
        });
      }
    } else {
      if (model.category) {
        return i18n("tagging.filters.untagged_with_category", {
          filter: filterText,
          category: model.category.displayName,
        });
      } else {
        return i18n("tagging.filters.untagged_without_category", {
          filter: filterText,
        });
      }
    }
  }

  deactivate() {
    super.deactivate(...arguments);
    this.searchService.searchContext = null;
  }

  @action
  resetParams(skipParams = []) {
    resetParams.call(this, skipParams);
  }
}

/** @returns {any} */
export function buildTagRoute(routeConfig = {}) {
  return class extends TagShowRoute {
    routeConfig = routeConfig;
  };
}
import { dasherize } from "@ember/string";
import DiscoveryListController from "discourse/controllers/discovery/list";
import Site from "discourse/models/site";
import buildCategoryRoute from "discourse/routes/build-category-route";
import buildTopicRoute from "discourse/routes/build-topic-route";
import { buildTagRoute } from "discourse/routes/tag/show";

export default {
  after: "inject-discourse-objects",

  initialize(app) {
    app.register(
      "route:discovery.category",
      buildCategoryRoute({ filter: "default" })
    );
    app.register("controller:discovery.category", DiscoveryListController);
    app.register(
      "route:discovery.category-none",
      buildCategoryRoute({ filter: "default", no_subcategories: true })
    );
    app.register("controller:discovery.category-none", DiscoveryListController);
    app.register(
      "route:discovery.category-all",
      buildCategoryRoute({ filter: "default", no_subcategories: false })
    );
    app.register("controller:discovery.category-all", DiscoveryListController);

    const site = Site.current();
    site.get("filters").forEach((filter) => {
      const filterDasherized = dasherize(filter);

      app.register(
        `route:discovery.${filterDasherized}`,
        buildTopicRoute(filter)
      );
      app.register(
        `controller:discovery.${filterDasherized}`,
        DiscoveryListController
      );

      app.register(
        `route:discovery.${filterDasherized}-category`,
        buildCategoryRoute({ filter })
      );
      app.register(
        `controller:discovery.${filterDasherized}-category`,
        DiscoveryListController
      );
      app.register(
        `route:discovery.${filterDasherized}-category-none`,
        buildCategoryRoute({ filter, no_subcategories: true })
      );
      app.register(
        `controller:discovery.${filterDasherized}-category-none`,
        DiscoveryListController
      );
    });

    app.register("route:tags.show-category", buildTagRoute());
    app.register("controller:tags.show-category", DiscoveryListController);
    app.register(
      "route:tags.show-category-none",
      buildTagRoute({
        noSubcategories: true,
      })
    );
    app.register("controller:tags.show-category-none", DiscoveryListController);
    app.register(
      "route:tags.show-category-all",
      buildTagRoute({
        noSubcategories: false,
      })
    );
    app.register("controller:tags.show-category-all", DiscoveryListController);

    // untagged category routes (no tag selected, shows category with tag=none)
    app.register("route:tags.untagged-category", buildTagRoute());
    app.register("controller:tags.untagged-category", DiscoveryListController);
    app.register(
      "route:tags.untagged-category-all",
      buildTagRoute({ noSubcategories: false })
    );
    app.register(
      "controller:tags.untagged-category-all",
      DiscoveryListController
    );

    site.get("filters").forEach(function (filter) {
      const filterDasherized = dasherize(filter);

      app.register(
        `route:tag.show-${filterDasherized}`,
        buildTagRoute({
          navMode: filter,
        })
      );
      app.register(
        `controller:tag.show-${filterDasherized}`,
        DiscoveryListController
      );
      app.register(
        `route:tags.show-category-${filterDasherized}`,
        buildTagRoute({ navMode: filter })
      );
      app.register(
        `controller:tags.show-category-${filterDasherized}`,
        DiscoveryListController
      );
      app.register(
        `route:tags.show-category-none-${filterDasherized}`,
        buildTagRoute({ navMode: filter, noSubcategories: true })
      );
      app.register(
        `controller:tags.show-category-none-${filterDasherized}`,
        DiscoveryListController
      );
      app.register(
        `route:tags.show-category-all-${filterDasherized}`,
        buildTagRoute({ navMode: filter, noSubcategories: false })
      );
      app.register(
        `controller:tags.show-category-all-${filterDasherized}`,
        DiscoveryListController
      );

      // category filter routes with no tag selected (tag=none)
      app.register(
        `route:tags.untagged-category-${filterDasherized}`,
        buildTagRoute({ navMode: filter })
      );
      app.register(
        `controller:tags.untagged-category-${filterDasherized}`,
        DiscoveryListController
      );
      app.register(
        `route:tags.untagged-category-all-${filterDasherized}`,
        buildTagRoute({ navMode: filter, noSubcategories: false })
      );
      app.register(
        `controller:tags.untagged-category-all-${filterDasherized}`,
        DiscoveryListController
      );
    });
  },
};
import { DEBUG } from "@glimmer/env";
import type { BlockCondition } from "discourse/blocks/conditions";
import { isDecoratedCondition } from "discourse/blocks/conditions/decorator";
import { raiseBlockError } from "discourse/lib/blocks/-internals/error";
import type { CustomizationSource } from "discourse/lib/customization-source";
import { isTesting } from "discourse/lib/environment";
import {
  assertRegistryNotFrozen,
  createTestRegistrationWrapper,
  validateNamePattern,
  validateSourceNamespace,
} from "./helpers.ts";

/*
 * Registry State
 */

/**
 * Registry of condition type classes registered by core, plugins, and themes.
 * Maps condition type names to their class constructors.
 *
 * Unlike blocks which store component classes, conditions are stored as classes
 * and instantiated by the Blocks service when first needed. This allows the
 * service to set the owner for dependency injection.
 */
const conditionTypeRegistry = new Map<string, typeof BlockCondition>();

/** Whether the condition type registry is frozen (no new registrations allowed). */
let conditionTypeRegistryFrozen = false;

/**
 * Stores the initial frozen state for condition registry to allow correct reset after tests.
 */
let testConditionRegistryFrozenState: boolean | null = null;

/*
 * Public Functions
 */

/** Returns whether the condition type registry is frozen. */
export function isConditionTypeRegistryFrozen(): boolean {
  return conditionTypeRegistryFrozen;
}

/**
 * Checks if a condition type is registered.
 *
 * @param type - The condition type name.
 */
export function hasConditionType(type: string): boolean {
  return conditionTypeRegistry.has(type);
}

/**
 * Returns all condition type entries as [type, ConditionClass] pairs.
 * Used by Blocks service for lazy initialization.
 */
export function getAllConditionTypeEntries(): Array<
  [string, typeof BlockCondition]
> {
  return Array.from(conditionTypeRegistry.entries());
}

/*
 * Internal Functions
 */

/**
 * Freezes the condition type registry, preventing further registrations.
 * Called by the "freeze-block-registry" initializer during app boot.
 *
 * @internal
 */
export function _freezeConditionTypeRegistry(): void {
  conditionTypeRegistryFrozen = true;
}

/**
 * Registers a condition type class in the registry.
 * Must be called before the registry is frozen by the "freeze-block-registry" initializer.
 *
 * The condition class must be decorated with `@blockCondition`
 *
 * @param ConditionClass - The condition class to register. Typed nullable
 *   because untyped callers can hand `api.registerBlockConditionType()` a bad
 *   import; that call must report the decorator error, not a property-read
 *   failure.
 * @param source - The plugin or theme the call came from.
 *
 * @example
 * ```javascript
 * import { withPluginApi } from "discourse/lib/plugin-api";
 * import MyCondition from "../conditions/my-condition";
 *
 * export default {
 *   initialize() {
 *     withPluginApi((api) => {
 *       api.registerBlockConditionType(MyCondition);
 *     });
 *   },
 * };
 * ```
 *
 * @internal
 */
export function _registerConditionType(
  ConditionClass: typeof BlockCondition | null | undefined,
  source?: CustomizationSource
): void {
  if (
    !assertRegistryNotFrozen({
      frozen: conditionTypeRegistryFrozen,
      apiMethod: "api.registerBlockConditionType()",
      entityType: "Condition",
      entityName: ConditionClass?.type || ConditionClass?.name,
    })
  ) {
    return;
  }

  // Ensure the class was created by the @blockCondition decorator
  if (!ConditionClass || !isDecoratedCondition(ConditionClass)) {
    raiseBlockError(
      `${ConditionClass?.name} must use the @blockCondition decorator. ` +
        `Manual inheritance from BlockCondition is not allowed.`
    );
    return;
  }

  const type = ConditionClass.type;

  // Validate condition type follows the namespaced pattern
  if (!validateNamePattern(type, "Condition")) {
    return;
  }

  // Validate namespace requirements for plugins/themes and enforce consistency
  if (
    !validateSourceNamespace({ name: type, entityType: "condition", source })
  ) {
    return;
  }

  if (conditionTypeRegistry.has(type)) {
    raiseBlockError(`Condition type "${type}" is already registered`);
    return;
  }

  conditionTypeRegistry.set(type, ConditionClass);
}

/*
 * Test Utilities
 */

/**
 * Temporarily unfreezes the condition type registry for testing purposes.
 * Call this before registering condition types in tests.
 *
 * USE ONLY FOR TESTING PURPOSES.
 *
 * @example
 * ```javascript
 * withTestConditionRegistration(() => {
 *   _registerConditionType(MyTestCondition);
 * });
 * ```
 */
export const withTestConditionRegistration = createTestRegistrationWrapper({
  getFrozen: () => conditionTypeRegistryFrozen,
  setFrozen: (value) => {
    conditionTypeRegistryFrozen = value;
  },
  getSavedState: () => testConditionRegistryFrozenState,
  setSavedState: (value) => {
    testConditionRegistryFrozenState = value;
  },
  name: "withTestConditionRegistration",
});

/**
 * Resets the condition registry state for testing.
 *
 * USE ONLY FOR TESTING PURPOSES.
 *
 * @internal Called by `resetBlockRegistryForTesting`, not meant for direct use.
 */
export function _resetConditionRegistryState(): void {
  // allows tree-shaking in production builds
  if (!DEBUG) {
    return;
  }
  if (!isTesting()) {
    throw new Error("_resetConditionRegistryState can only be used in tests.");
  }
  conditionTypeRegistry.clear();
  conditionTypeRegistryFrozen = false;
  testConditionRegistryFrozenState = null;
}
