      @change={{this.handleInput}}
      @composerEvents={{true}}
      @disabled={{this.composer.disableTextarea}}
      @disableSubmit={{this.composer.disableSubmit}}
      @extraButtons={{@extraButtons}}
      @forcePreview={{true}}
