  }

  #findMatchingUploadHandler(fileName) {
    return this.uploadHandlers.find((handler) => {
      const ext = handler.extensions.join("|");
      const regex = new RegExp(`\\.(${ext})$`, "i");
      return regex.test(fileName);
    });
  }

  @bind
  _cancelUpload(data) {
    if (data) {
      // Single file
      const file = this.uppyWrapper.uppyInstance.getFile(data.fileId);
      if (!file) {
        return;
      }

      file.meta.cancelled = true;
      this.uppyWrapper.uppyInstance.removeFile(file.id);
      this.appEvents.trigger(
        `${this.composerEventPrefix}:upload-cancelled`,
        file.id
      );
      this.#removeInProgressUpload(file.id);
      this.#resetUpload(file);
      if (this.#inProgressUploads.length === 0) {
        this.#userCancelled = true;
        this.uppyWrapper.uppyInstance.cancelAll();
      }
    } else {
      // All files
      this.#userCancelled = true;
      this.uppyWrapper.uppyInstance.cancelAll();
    }
  }

  @bind
  _handleUploadError(file, error, response) {
    this.#removeInProgressUpload(file.id);
    this.#resetUpload(file);

    file.meta.error = error;

    if (!this.#userCancelled) {
      this.#bufferUploadError(response || error, file.name);
      this.appEvents.trigger(`${this.composerEventPrefix}:upload-error`, file);
    }
    if (this.#inProgressUploads.length === 0) {
      displayUploadErrors(this.#bufferedUploadErrors, this.siteSettings);
      this.#reset();
    }
  }

  @bind
  _pasteEventListener(event) {
    if (!event.target.closest(this.editorInputClass)) {
      return;
    }

    const { canUpload, canPasteHtml, types } = clipboardHelpers(event, {
      siteSettings: this.siteSettings,
      canUpload: true,
    });

    if (!canUpload || canPasteHtml || types.includes("text/plain")) {
      return;
    }

    if (event && event.clipboardData && event.clipboardData.files) {
      event.preventDefault();
      this._addFiles([...event.clipboardData.files], { pasted: true });
    }
  }

  @bind
  async _addFiles(files, opts = {}) {
    if (!this.session.csrfToken) {
      await updateCsrfToken();
    }

    files = Array.isArray(files) ? files : [files];

    try {
      this.uppyWrapper.uppyInstance.addFiles(
        files.map((file) => {
          return {
            source: this.uppyId,
            name: file.name,
            type: file.type,
            data: file,
            meta: {
              pasted: opts.pasted,
              skipPlaceholder: opts.skipPlaceholder,
            },
          };
        })
      );
    } catch (err) {
      warn(`error adding files to uppy: ${err}`, {
        id: "discourse.upload.uppy-add-files-error",
      });
    }
  }

  @bind
  _mobileUploadButtonEventListener() {
    this.#fileInputEl.click();
  }
}
/* eslint-disable ember/no-classic-components, ember/no-observers, ember/require-tagless-components */
import { tracked } from "@glimmer/tracking";
import Component from "@ember/component";
import { hash } from "@ember/helper";
import EmberObject, { action, computed } from "@ember/object";
import didInsert from "@ember/render-modifiers/modifiers/did-insert";
import willDestroy from "@ember/render-modifiers/modifiers/will-destroy";
import { schedule, throttle } from "@ember/runloop";
import { service } from "@ember/service";
import { classNameBindings } from "@ember-decorators/component";
import { observes, on } from "@ember-decorators/object";
import { BasePlugin } from "@uppy/core";
import { resolveAllShortUrls } from "pretty-text/upload-short-url";
import DEditorPreview from "discourse/components/d-editor-preview";
import Wrapper from "discourse/components/form-template-field/wrapper";
import PostTranslationEditor from "discourse/components/post-translation-editor";
import lazyHash from "discourse/helpers/lazy-hash";
import { ajax } from "discourse/lib/ajax";
import { tinyAvatar } from "discourse/lib/avatar-utils";
import { setupComposerPosition } from "discourse/lib/composer/composer-position";
import { decorateImageControls } from "discourse/lib/composer/image-controls";
import { bind, debounce } from "discourse/lib/decorators";
import prepareFormTemplateData from "discourse/lib/form-template-validation";
import {
  fetchUnseenHashtagsInContext,
  linkSeenHashtagsInContext,
} from "discourse/lib/hashtag-decorator";
import { iconHTML } from "discourse/lib/icon-library";
import discourseLater from "discourse/lib/later";
import {
  fetchUnseenMentions,
  linkSeenMentions,
} from "discourse/lib/link-mentions";
import { loadOneboxes } from "discourse/lib/load-oneboxes";
import { generateCookFunction } from "discourse/lib/text";
import { applyValueTransformer } from "discourse/lib/transformer";
import {
  authorizesOneOrMoreImageExtensions,
  IMAGE_MARKDOWN_REGEX,
} from "discourse/lib/uploads";
import UppyComposerUpload from "discourse/lib/uppy/composer-upload";
import { formatUsername } from "discourse/lib/utilities";
import Composer from "discourse/models/composer";
import FormTemplateChooser from "discourse/select-kit/components/form-template-chooser";
import { applyHtmlDecorators } from "discourse/ui-kit/d-decorated-html";
import DEditor from "discourse/ui-kit/d-editor";
import DPickFilesButton from "discourse/ui-kit/d-pick-files-button";
import { i18n } from "discourse-i18n";

let uploadHandlers = [];
export function addComposerUploadHandler(extensions, method) {
  uploadHandlers.push({
    extensions,
    method,
  });
}
export function cleanUpComposerUploadHandler() {
  // we cannot set this to uploadHandlers = [] because that messes with
  // the references to the original array that the component has. this only
  // really affects tests, but without doing this you could addComposerUploadHandler
  // in a beforeEach function in a test but then it's not adding to the
  // existing reference that the component has, because an earlier test ran
  // cleanUpComposerUploadHandler and lost it. setting the length to 0 empties
  // the array but keeps the reference
  uploadHandlers.length = 0;
}

let uploadPreProcessors = [];
export function addComposerUploadPreProcessor(pluginClass, optionsResolverFn) {
  if (!(pluginClass.prototype instanceof BasePlugin)) {
    throw new Error(
      "Composer upload preprocessors must inherit from the Uppy BasePlugin class."
    );
  }

  uploadPreProcessors.push({
    pluginClass,
    optionsResolverFn,
  });
}
export function cleanUpComposerUploadPreProcessor() {
  uploadPreProcessors = [];
}

let uploadMarkdownResolvers = [];
export function addComposerUploadMarkdownResolver(resolver) {
  uploadMarkdownResolvers.push(resolver);
}
export function cleanUpComposerUploadMarkdownResolver() {
  uploadMarkdownResolvers = [];
}

let apiImageWrapperBtnEvents = [];
export function addApiImageWrapperButtonClickEvent(fn) {
  apiImageWrapperBtnEvents.push(fn);
}

const DEBOUNCE_FETCH_MS = 450;
const DEBOUNCE_JIT_MS = 2000;

@classNameBindings("composer.showToolbar:toolbar-visible", ":wmd-controls")
export default class ComposerEditor extends Component {
  @service composer;
  @service siteSettings;
  @service currentUser;

  @tracked preview;

  composerEventPrefix = "composer";

  fileUploadElementId = "file-uploader";

  init() {
    super.init(...arguments);
    this.warnedCannotSeeMentions = [];
    this.warnedGroupMentions = [];

    this.uppyComposerUpload = new UppyComposerUpload(this, {
      composerEventPrefix: this.composerEventPrefix,
      composerModel: this.composer.model,
      uploadMarkdownResolvers,
      uploadPreProcessors,
      uploadHandlers,
      fileUploadElementId: this.fileUploadElementId,
    });
  }

  @computed("composer.formTemplateIds")
  get selectedFormTemplateId() {
    if (this._selectedFormTemplateId) {
      return this._selectedFormTemplateId;
    }

    return (
      this.composer.model.formTemplateId || this.composer.formTemplateIds?.[0]
    );
  }

  set selectedFormTemplateId(value) {
    this._selectedFormTemplateId = value;
  }

  get composerRedesign() {
    return this.siteSettings.enable_composer_redesign;
  }

  get topic() {
    return this.composer.get("model.topic");
  }

  @computed(
    "composer.model.requiredCategoryMissing",
    "currentUser.useRichEditor"
  )
  get replyPlaceholder() {
    let placeholder = "composer.reply_placeholder_choose_category";

    if (!this.composer?.model?.requiredCategoryMissing) {
      const allowImages = authorizesOneOrMoreImageExtensions(
        this.currentUser.staff,
        this.siteSettings
      );

      let key;
      if (this.currentUser.useRichEditor) {
        key = allowImages
          ? "reply_placeholder_rte"
          : "reply_placeholder_rte_no_images";
      } else {
        key = allowImages ? "reply_placeholder" : "reply_placeholder_no_images";
      }

      placeholder = `composer.${key}`;
    }

    return i18n(
      applyValueTransformer("composer-editor-reply-placeholder", placeholder, {
        model: this.composer,
      })
    );
  }

  @computed
  get showLink() {
    return this.currentUser && this.currentUser.link_posting_access !== "none";
  }

  @computed
  get markdownOptions() {
    return {
      previewing: true,

      formatUsername,

      lookupAvatarByPostNumber: (postNumber, topicId) => {
        const avatarTemplate = this.lookupAvatarTemplateByPostNumber(
          postNumber,
          topicId
        );

        return avatarTemplate ? tinyAvatar(avatarTemplate) : undefined;
      },

      lookupAvatarTemplateByPostNumber: this.lookupAvatarTemplateByPostNumber,

      lookupPrimaryUserGroupByPostNumber: (postNumber, topicId) => {
        const topic = this.topic;
        if (!topic) {
          return;
        }

        const posts = topic.get("postStream.posts");
        if (posts && topicId === topic.get("id")) {
          const quotedPost = posts.find((p) => p.post_number === postNumber);
          if (quotedPost) {
            return quotedPost.primary_group_name;
          }
        }
      },

      hashtagTypesInPriorityOrder:
        this.site.hashtag_configurations["topic-composer"],
      hashtagIcons: this.site.hashtag_icons,
    };
  }

  @computed(
    "composer.model.reply",
    "composer.model.replyLength",
    "composer.model.missingReplyCharacters",
    "composer.model.minimumPostLength",
    "composer.lastValidatedAt"
  )
  get validation() {
    const postType = this.get("composer.post.post_type");
    if (postType === this.site.get("post_types.small_action")) {
      return;
    }

    let reason;
    if (this.composer?.model?.missingReplyCharacters > 0) {
      if (this.composer?.model?.replyLength < 1) {
        reason = i18n("composer.error.post_missing");
      } else {
        reason = i18n("composer.error.post_length", {
          count: this.composer?.model?.minimumPostLength,
        });
        const tl = this.get("currentUser.trust_level");
        if ((tl === 0 || tl === 1) && !this._isNewTopic) {
          reason +=
            "<br/>" +
            i18n("composer.error.try_like", {
              heart: iconHTML("heart", {
                label: i18n("likes_lowercase", { count: 1 }),
              }),
            });
        }
      }
    }

    if (reason) {
      return EmberObject.create({
        failed: true,
        reason,
        lastShownAt: this.composer?.lastValidatedAt,
      });
    }
  }

  @computed("composer.{creatingTopic,editingFirstPost,creatingSharedDraft}")
  get _isNewTopic() {
    return (
      this.composer.model.creatingTopic ||
      this.composer.model.editingFirstPost ||
      this.composer.model.creatingSharedDraft
    );
  }

  get showTranslationEditor() {
    const post = this.get("composer.model.post");
    if (!post?.can_localize_post) {
      return false;
    }

    if (this.composer.model?.action === Composer.ADD_TRANSLATION) {
      return true;
    }

    return false;
  }

  @computed(
    "composer.formTemplateIds",
    "composer.model.replyingToTopic",
    "composer.model.editingPost"
  )
  get showFormTemplateForm() {
    return (
      this.composer?.formTemplateIds?.length > 0 &&
      !this.composer?.model?.replyingToTopic &&
      !this.composer?.model?.editingPost
    );
  }

  @computed("composer.model")
  get forceEditorMode() {
    return applyValueTransformer("composer-force-editor-mode", null, {
      model: this.composer.model,
    });
  }

  @observes("composer.focusTarget")
  setFocus() {
    if (this.composer.focusTarget === "editor") {
      this.textManipulation.putCursorAtEnd();
    }
  }

  @bind
  lookupAvatarTemplateByPostNumber(postNumber, topicId) {
    const topic = this.topic;
    if (!topic || topicId !== topic.get("id")) {
      return;
    }

    const quotedPost = topic
      .get("postStream.posts")
      ?.find((p) => p.post_number === postNumber);

    if (!quotedPost) {
      return;
    }

    return applyValueTransformer(
      "composer-editor-quoted-post-avatar-template",
      quotedPost.get("avatar_template"),
      { post: quotedPost }
    );
  }

  /**
   * Sets up the editor with the given text manipulation instance
   *
   * @param {TextManipulation} textManipulation The text manipulation instance
   * @returns {(() => void)} destructor function
   */
  @bind
  setupEditor(textManipulation) {
    this.textManipulation = textManipulation;
    this.uppyComposerUpload.textManipulation = textManipulation;

    const input = this.element.querySelector(".d-editor-input");

    input.addEventListener("scroll", this._throttledSyncEditorAndPreviewScroll);

    this.composer.set("allowPreview", this.textManipulation.allowPreview);

    if (
      // Focus on the editor unless we have a title
      !this.get("composer.model.canEditTitle") ||
      // Or focus is in the body (e.g. when the editor is destroyed)
      document.activeElement.tagName === "BODY"
    ) {
      this.textManipulation.putCursorAtEnd();
    }

    const destroyComposerPosition = setupComposerPosition(input, {
      swipeToCollapse: this.siteSettings.enable_composer_redesign,
    });

    return () => {
      destroyComposerPosition();

      input.removeEventListener(
        "scroll",
        this._throttledSyncEditorAndPreviewScroll
      );
    };
  }

  resetImageControls(buttonWrapper) {
    const imageResize = buttonWrapper.querySelector(".scale-btn-container");
    const imageDelete = buttonWrapper.querySelector(".delete-image-button");

    const readonlyContainer = buttonWrapper.querySelector(
      ".alt-text-readonly-container"
    );
    const editContainer = buttonWrapper.querySelector(
      ".alt-text-edit-container"
    );

    imageResize.removeAttribute("hidden");
    imageDelete.removeAttribute("hidden");

    readonlyContainer.removeAttribute("hidden");
    buttonWrapper.removeAttribute("editing");
    editContainer.setAttribute("hidden", "true");
  }

  commitAltText(buttonWrapper) {
    const index = parseInt(buttonWrapper.getAttribute("data-image-index"), 10);
    const matchingPlaceholder = this.get("composer.model.reply").match(
      IMAGE_MARKDOWN_REGEX
    );
    const match = matchingPlaceholder?.[index];

    if (!match) {
      this.resetImageControls(buttonWrapper);
      return;
    }

    const input = buttonWrapper.querySelector("input.alt-text-input");
    const replacement = match.replace(
      IMAGE_MARKDOWN_REGEX,
      `![${input.value}|$2$3$4]($5)`
    );

    this.appEvents.trigger(
      `${this.composerEventPrefix}:replace-text`,
      match,
      replacement
    );

    this.resetImageControls(buttonWrapper);
  }

  @action
  onExpandPopupMenuOptions(toolbarEvent) {
    const selected = toolbarEvent.selected;
    toolbarEvent.selectText(selected.start, selected.end - selected.start);
    this.composer.storeToolbarState(toolbarEvent);

    window.getSelection().removeAllRanges();
  }

  showPreview() {
    this.composer.togglePreview();
  }

  @action
  extraButtons(toolbar) {
    const composerRedesign = this.siteSettings.enable_composer_redesign;

    if (
      this.composer.allowUpload &&
      this.composer.uploadIcon &&
      (composerRedesign || this.site.desktopView)
    ) {
      toolbar.addButton({
        id: "upload",
        group: "insertions",
        icon: this.composer.uploadIcon,
        title: "upload",
        sendAction: this.showUploadModal,
      });
    }

    toolbar.addButton({
      id: "options",
      group: "extras",
      icon: composerRedesign ? "discourse-circle-plus" : "circle-plus",
      title: "composer.options",
      sendAction: this.onExpandPopupMenuOptions.bind(this),
      popupMenu: {
        options: () => this.composer.popupMenuOptions,
        action: this.composer.onPopupMenuAction,
      },
    });
  }

  @action
  replyChanged() {
    this.appEvents.trigger("composer:reply-changed", this.composer.model);
  }

  @action
  previewUpdated(preview, helper) {
    decorateImageControls(preview);

    this._renderMentions(preview);
    this._renderHashtags(preview);
    this._refreshOneboxes(preview);
    this._expandShortUrls(preview);

    this._decorateCookedElement(preview, helper);

    this.composer.afterRefresh(preview);
  }

  @action
  async updateFormPreview() {
    const formTemplateData = prepareFormTemplateData(
      document.querySelector("#form-template-form"),
      this.composer.selectedFormTemplate,
      false
    );

    this.composer.model.set("reply", formTemplateData);

    this.preview = await this.cachedCookAsync(
      formTemplateData,
      this.markdownOptions
    );
  }

  async cachedCookAsync(text, options) {
    this._cachedCookFunction ||= await generateCookFunction(options || {});
    return await this._cachedCookFunction(text);
  }

  @action
  updateSelectedFormTemplateId(formTemplateId) {
    this.selectedFormTemplateId = formTemplateId;
  }

  @action
  showUploadModal() {
    document.getElementById(this.fileUploadElementId).click();
  }

  @on("didInsertElement")
  _composerEditorInit() {
    this.appEvents.trigger(`${this.composerEventPrefix}:will-open`);
  }

  @on("willDestroyElement")
  _composerClosed() {
    this.appEvents.trigger(`${this.composerEventPrefix}:will-close`);

    // need to wait a bit for the "slide down" transition of the composer
    discourseLater(
      () => this.appEvents.trigger(`${this.composerEventPrefix}:closed`),
      400
    );
  }

  @action
  _composerEditorInitPreview(elem) {
    const preview = elem.classList.contains("d-editor-preview-wrapper")
      ? elem
      : elem.querySelector(".d-editor-preview-wrapper");
    this._registerImageAltTextButtonClick(preview);
    this._editorInitPreview = true;
  }

  @action
  _composerEditorDestroyPreview(elem) {
    const preview = elem.classList.contains("d-editor-preview-wrapper")
      ? elem
      : elem.querySelector(".d-editor-preview-wrapper");

    if (preview) {
      preview.removeEventListener(
        "click",
        this._handleAltTextCancelButtonClick
      );
      preview.removeEventListener("click", this._handleAltTextEditButtonClick);
      preview.removeEventListener("click", this._handleAltTextOkButtonClick);
      preview.removeEventListener("click", this._handleImageDeleteButtonClick);
      preview.removeEventListener("click", this._handleImageGridButtonClick);
      preview.removeEventListener("click", this._handleImageScaleButtonClick);
      preview.removeEventListener("keypress", this._handleAltTextInputKeypress);

      apiImageWrapperBtnEvents.forEach((fn) =>
        preview.removeEventListener("click", fn)
      );
    }
  }

  @action
  _composerEditorInitEditor(elem) {
    if (this.composer.allowUpload) {
      this.uppyComposerUpload.setup(elem);
    }
  }

  @action
  _composerEditorDestroyEditor(elem) {
    if (this.composer.allowUpload && this._cleanupComposerUploadElement) {
      this.uppyComposerUpload.teardown(elem);
    }
  }

  @action
  _composerEditorInitFormTemplate(formEl) {
    if (this.composer.allowUpload) {
      this.uppyComposerUpload.setup(formEl);
    }
  }

  @bind
  _throttledSyncEditorAndPreviewScroll(event) {
    const preview = this.element.querySelector(".d-editor-preview-wrapper");
    throttle(this, this._syncEditorAndPreviewScroll, event.target, preview, 20);
  }

  _syncEditorAndPreviewScroll(input, preview) {
    if (!input || !preview) {
      return;
    }

    if (input.scrollTop === 0) {
      preview.scrollTop = 0;
      return;
    }

    const inputHeight = input.scrollHeight;
    const previewHeight = preview.scrollHeight;

    if (input.clientHeight + input.scrollTop + 100 > inputHeight) {
      // cheat, special case for bottom
      preview.scrollTop = previewHeight;
      return;
    }

    const factor = previewHeight / inputHeight;
    preview.scrollTop = input.scrollTop * factor + 50;
  }

  _renderMentions(preview) {
    const unseen = linkSeenMentions(preview, this.siteSettings);
    if (unseen.length > 0) {
      this._renderUnseenMentions(preview, unseen);
    } else {
      this._warnMentionedGroups(preview);
      this._warnCannotSeeMention(preview);
    }
  }

  @debounce(DEBOUNCE_FETCH_MS)
  _renderUnseenMentions(preview, unseen) {
    fetchUnseenMentions({
      names: unseen,
      topicId: this.get("composer.model.topic.id"),
      allowedNames: this.get("composer.model.targetRecipients")?.split(","),
    }).then((response) => {
      linkSeenMentions(preview, this.siteSettings);
      this._warnMentionedGroups(preview);
      this._warnCannotSeeMention(preview);
      this._warnHereMention(response.here_count);
    });
  }

  _renderHashtags(preview) {
    const context = this.site.hashtag_configurations["topic-composer"];
    const unseen = linkSeenHashtagsInContext(context, preview);
    if (unseen.length > 0) {
      this._renderUnseenHashtags(preview, unseen, context);
    }
  }

  @debounce(DEBOUNCE_FETCH_MS)
  _renderUnseenHashtags(preview, unseen, context) {
    fetchUnseenHashtagsInContext(context, unseen).then(() =>
      linkSeenHashtagsInContext(context, preview)
    );
  }

  @debounce(DEBOUNCE_FETCH_MS)
  _refreshOneboxes(preview) {
    const post = this.get("composer.post");
    // If we are editing a post, we'll refresh its contents once.
    const refresh = post && !post.get("refreshedPost");

    const loaded = loadOneboxes(
      preview,
      ajax,
      this.get("composer.model.topic.id"),
      this.get("composer.model.category.id"),
      this.siteSettings.max_oneboxes_per_post,
      refresh,
      false,
      (onebox) => onebox && this.appEvents.trigger("composer:refresh-preview")
    );

    if (refresh && loaded > 0) {
      post.set("refreshedPost", true);
    }
  }

  _expandShortUrls(preview) {
    resolveAllShortUrls(ajax, this.siteSettings, preview);
  }

  _decorateCookedElement(preview, helper) {
    applyHtmlDecorators(preview, helper);
  }

  @debounce(DEBOUNCE_JIT_MS)
  _warnMentionedGroups(preview) {
    schedule("afterRender", () => {
      preview
        .querySelectorAll(".mention-group[data-mentionable-user-count]")
        .forEach((mention) => {
          const { name } = mention.dataset;
          if (
            this.warnedGroupMentions.includes(name) ||
            this._isInQuote(mention)
          ) {
            return;
          }

          this.warnedGroupMentions.push(name);
          this.composer.groupsMentioned({
            name,
            userCount: mention.dataset.mentionableUserCount,
            maxMentions: mention.dataset.maxMentions,
          });
        });
    });
  }

  // add a delay to allow for typing, so you don't open the warning right away
  // previously we would warn after @bob even if you were about to mention @bob2
  @debounce(DEBOUNCE_JIT_MS)
  _warnCannotSeeMention(preview) {
    if (this.composer.model?.draftKey === Composer.NEW_PRIVATE_MESSAGE_KEY) {
      return;
    }

    preview.querySelectorAll(".mention[data-reason]").forEach((mention) => {
      const { name } = mention.dataset;
      if (this.warnedCannotSeeMentions.includes(name)) {
        return;
      }

      this.warnedCannotSeeMentions.push(name);
      this.composer.cannotSeeMention({
        name,
        reason: mention.dataset.reason,
      });
    });

    preview
      .querySelectorAll(".mention-group[data-reason]")
      .forEach((mention) => {
        const { name } = mention.dataset;
        if (this.warnedCannotSeeMentions.includes(name)) {
          return;
        }

        this.warnedCannotSeeMentions.push(name);
        this.composer.cannotSeeMention({
          name,
          reason: mention.dataset.reason,
          notifiedCount: mention.dataset.notifiedUserCount,
          isGroup: true,
        });
      });
  }

  _warnHereMention(hereCount) {
    if (!hereCount || hereCount === 0) {
      return;
    }

    this.composer.hereMention(hereCount);
  }

  @bind
  _handleImageScaleButtonClick(event) {
    if (!event.target.classList.contains("scale-btn")) {
      return;
    }

    const index = parseInt(
      event.target.closest(".button-wrapper").dataset.imageIndex,
      10
    );

    const scale = event.target.dataset.scale;
    const matchingPlaceholder = this.get("composer.model.reply").match(
      IMAGE_MARKDOWN_REGEX
    );

    if (matchingPlaceholder) {
      const match = matchingPlaceholder[index];

      if (match) {
        const replacement = match.replace(
          IMAGE_MARKDOWN_REGEX,
          `![$1|$2, ${scale}%$4]($5)`
        );

        this.appEvents.trigger(
          `${this.composerEventPrefix}:replace-text`,
          matchingPlaceholder[index],
          replacement,
          { regex: IMAGE_MARKDOWN_REGEX, index }
        );
      }
    }

    event.preventDefault();
    return;
  }

  @bind
  _handleAltTextInputKeypress(event) {
    if (!event.target.classList.contains("alt-text-input")) {
      return;
    }

    if (event.key === "[" || event.key === "]") {
      event.preventDefault();
    }

    if (event.key === "Enter") {
      const buttonWrapper = event.target.closest(".button-wrapper");
      this.commitAltText(buttonWrapper);
    }
  }

  @bind
  _handleAltTextEditButtonClick(event) {
    if (!event.target.classList.contains("alt-text-edit-btn")) {
      return;
    }

    const buttonWrapper = event.target.closest(".button-wrapper");
    const imageResize = buttonWrapper.querySelector(".scale-btn-container");
    const imageDelete = buttonWrapper.querySelector(".delete-image-button");

    const readonlyContainer = buttonWrapper.querySelector(
      ".alt-text-readonly-container"
    );
    const altText = readonlyContainer.querySelector(".alt-text");

    const editContainer = buttonWrapper.querySelector(
      ".alt-text-edit-container"
    );
    const editContainerInput = editContainer.querySelector(".alt-text-input");

    buttonWrapper.setAttribute("editing", "true");
    imageResize.setAttribute("hidden", "true");
    imageDelete.setAttribute("hidden", "true");
    readonlyContainer.setAttribute("hidden", "true");
    editContainerInput.value = altText.textContent;
    editContainer.removeAttribute("hidden");
    editContainerInput.focus();
    event.preventDefault();
  }

  @bind
  _handleAltTextOkButtonClick(event) {
    if (!event.target.classList.contains("alt-text-edit-ok")) {
      return;
    }

    const buttonWrapper = event.target.closest(".button-wrapper");
    this.commitAltText(buttonWrapper);
  }

  @bind
  _handleAltTextCancelButtonClick(event) {
    if (!event.target.classList.contains("alt-text-edit-cancel")) {
      return;
    }

    const buttonWrapper = event.target.closest(".button-wrapper");
    this.resetImageControls(buttonWrapper);
  }

  @bind
  _handleImageDeleteButtonClick(event) {
    if (!event.target.classList.contains("delete-image-button")) {
      return;
    }
    const index = parseInt(
      event.target.closest(".button-wrapper").dataset.imageIndex,
      10
    );
    const matchingPlaceholder = this.get("composer.model.reply").match(
      IMAGE_MARKDOWN_REGEX
    );

    if (!matchingPlaceholder?.[index]) {
      return;
    }

    this.appEvents.trigger(
      `${this.composerEventPrefix}:replace-text`,
      matchingPlaceholder[index],
      "",
      { regex: IMAGE_MARKDOWN_REGEX, index }
    );
  }

  @bind
  _handleImageGridButtonClick(event) {
    if (!event.target.classList.contains("wrap-image-grid-button")) {
      return;
    }

    const index = parseInt(
      event.target.closest(".button-wrapper").dataset.imageIndex,
      10
    );
    const reply = this.get("composer.model.reply");
    const matches = reply.match(IMAGE_MARKDOWN_REGEX);
    const closingIndex =
      index + parseInt(event.target.dataset.imageCount, 10) - 1;

    if (!matches?.[index] || !matches[closingIndex]) {
      return;
    }

    const textArea = this.element.querySelector(".d-editor-input");
    textArea.selectionStart = reply.indexOf(matches[index]);
    textArea.selectionEnd =
      reply.indexOf(matches[closingIndex]) + matches[closingIndex].length;

    this.appEvents.trigger(
      `${this.composerEventPrefix}:apply-surround`,
      "[grid]",
      "[/grid]",
      "grid_surround",
      { useBlockMode: true }
    );
  }

  _registerImageAltTextButtonClick(preview) {
    if (!preview) {
      return;
    }

    preview.addEventListener("click", this._handleAltTextCancelButtonClick);
    preview.addEventListener("click", this._handleAltTextEditButtonClick);
    preview.addEventListener("click", this._handleAltTextOkButtonClick);
    preview.addEventListener("click", this._handleImageDeleteButtonClick);
    preview.addEventListener("click", this._handleImageGridButtonClick);
    preview.addEventListener("click", this._handleImageScaleButtonClick);
    preview.addEventListener("keypress", this._handleAltTextInputKeypress);

    apiImageWrapperBtnEvents.forEach((fn) =>
      preview.addEventListener("click", fn)
    );
  }

  _isInQuote(element) {
    let parent = element.parentElement;
    while (parent && !this._isPreviewRoot(parent)) {
      if (this._isQuote(parent)) {
        return true;
      }

      parent = parent.parentElement;
    }

    return false;
  }

  _isPreviewRoot(element) {
    return (
      element.tagName === "DIV" &&
      element.classList.contains("d-editor-preview")
    );
  }

  _isQuote(element) {
    return element.tagName === "ASIDE" && element.classList.contains("quote");
  }

  <template>
    {{#if this.showFormTemplateForm}}
      <div class="d-editor">
        <div class="d-editor-textarea-column">
          {{yield}}

          {{#if (gt this.composer.formTemplateIds.length 1)}}
            <FormTemplateChooser
              class="composer-select-form-template"
              @filteredIds={{this.composer.formTemplateIds}}
              @onChange={{this.updateSelectedFormTemplateId}}
              @options={{hash maximum=1}}
              @value={{this.selectedFormTemplateId}}
            />
          {{/if}}
          <form
            id="form-template-form"
            {{didInsert this._composerEditorInitFormTemplate}}
          >
            <Wrapper
              @id={{this.selectedFormTemplateId}}
              @initialValues={{this.composer.formTemplateInitialValues}}
              @onChange={{this.updateFormPreview}}
              @onSelectFormTemplate={{this.composer.onSelectFormTemplate}}
              @uppyComposerUpload={{this.uppyComposerUpload}}
            />
          </form>
        </div>
        {{#if this.siteSettings.show_preview_for_form_templates}}
          <DEditorPreview
            @forcePreview={{this.forcePreview}}
            @onPreviewUpdated={{this.previewUpdated}}
            @outletArgs={{this.outletArgs}}
            @preview={{this.preview}}
            {{didInsert this._composerEditorInitPreview}}
            {{willDestroy this._composerEditorDestroyPreview}}
          />
        {{/if}}
      </div>
    {{else if this.showTranslationEditor}}
      <PostTranslationEditor
        @extraButtons={{this.extraButtons}}
        @setupEditor={{this.setupEditor}}
        @showLink={{this.showLink}}
        @uppyComposerUpload={{this.uppyComposerUpload}}
        {{didInsert this._composerEditorInitPreview}}
        {{willDestroy this._composerEditorDestroyPreview}}
      />
    {{else}}
      <DEditor
        @categoryId={{this.composer.model.category.id}}
        @change={{this.replyChanged}}
        @composerEvents={{true}}
        @disabled={{this.composer.disableTextarea}}
        @disableSubmit={{this.composer.disableSubmit}}
        @extraButtons={{this.extraButtons}}
        @forceEditorMode={{this.forceEditorMode}}
        @forcePreview={{this.forcePreview}}
        @loading={{this.composer.loading}}
        @markdownOptions={{this.markdownOptions}}
        @onPopupMenuAction={{this.composer.onPopupMenuAction}}
        @onSetup={{this.setupEditor}}
        @outletArgs={{lazyHash
          composer=this.composer.model
          editorType="composer"
        }}
        @placeholder={{this.replyPlaceholder}}
        @popupMenuOptions={{this.composer.popupMenuOptions}}
        @previewUpdated={{this.previewUpdated}}
        @processPreview={{this.composer.isPreviewVisible}}
        @renderYieldAboveContainer={{this.composerRedesign}}
        @replyingToUserId={{this.composer.replyingToUserId}}
        @showLink={{this.showLink}}
        @toolbarPortalTarget={{this.toolbarPortalTarget}}
        @topicId={{this.composer.model.topic.id}}
        @userToolbarPreferences={{true}}
        @validation={{this.validation}}
        @value={{this.composer.model.reply}}
        {{didInsert this._composerEditorInitEditor}}
        {{willDestroy this._composerEditorDestroyEditor}}
        {{didInsert this._composerEditorInitPreview}}
        {{willDestroy this._composerEditorDestroyPreview}}
      >
        {{yield}}
      </DEditor>
    {{/if}}

    {{#if this.composer.allowUpload}}
      <DPickFilesButton
        name="file-uploader"
        @allowMultiple={{true}}
        @fileInputId={{this.fileUploadElementId}}
      />
    {{/if}}
  </template>
}
import { isEmpty } from "@ember/utils";
import { isTesting } from "discourse/lib/environment";
import getURL from "discourse/lib/get-url";
import { helperContext } from "discourse/lib/helpers";

export default function logout({ redirect } = {}) {
  if (isTesting()) {
    return;
  }

  const { keyValueStore, siteSettings } = helperContext();

  keyValueStore.abandonLocal();

  window.location = isEmpty(redirect)
    ? getURL(siteSettings.login_required ? "/login" : "/")
    : redirect;
}
import Component from "@glimmer/component";
import { service } from "@ember/service";
import { setLogoffCallback } from "discourse/lib/ajax";
import { clearBodyLocks } from "discourse/lib/body-scroll-lock";
import { bind } from "discourse/lib/decorators";
import logout from "discourse/lib/logout";
import { i18n } from "discourse-i18n";

let pluginCounterFunctions = [];
export function addPluginDocumentTitleCounter(counterFunction) {
  pluginCounterFunctions.push(counterFunction);
}

export function clearPluginDocumentTitleCounters() {
  pluginCounterFunctions.length = 0;
}

export default class DDocument extends Component {
  @service appEvents;
  @service currentUser;
  @service dialog;
  @service documentTitle;
  @service messageBus;
  @service session;

  #showingLogout = false;

  constructor() {
    super(...arguments);

    this.documentTitle.setTitle(document.title);
    document.addEventListener("visibilitychange", this._focusChanged);
    document.addEventListener("resume", this._focusChanged);
    document.addEventListener("freeze", this._focusChanged);
    this.session.hasFocus = true;

    this.appEvents.on("notifications:changed", this, this._updateNotifications);
    setLogoffCallback(() => this.displayLogoff());
  }

  willDestroy() {
    super.willDestroy(...arguments);

    setLogoffCallback(null);
    document.removeEventListener("visibilitychange", this._focusChanged);
    document.removeEventListener("resume", this._focusChanged);
    document.removeEventListener("freeze", this._focusChanged);

    this.appEvents.off(
      "notifications:changed",
      this,
      this._updateNotifications
    );
  }

  displayLogoff() {
    if (this.#showingLogout) {
      return;
    }

    this.#showingLogout = true;
    this.messageBus.stop();

    this.dialog.alert({
      message: i18n("logout"),
      confirmButtonLabel: "refresh",
      didConfirm: () => logout(),
      didCancel: () => logout(),
      class: "dialog-container__logout-refresh",
    });
  }

  _updateNotifications(opts) {
    if (!this.currentUser) {
      return;
    }

    let count = pluginCounterFunctions.reduce((sum, fn) => sum + fn(), 0);
    count += this.currentUser.all_unread_notifications_count;
    if (this.currentUser.unseen_reviewable_count) {
      count += this.currentUser.unseen_reviewable_count;
    }
    this.documentTitle.updateNotificationCount(count, { forced: opts?.forced });
  }

  @bind
  _focusChanged() {
    // changing app while keyboard is up could cause the keyboard to not collapse and not release lock
    clearBodyLocks();

    if (document.visibilityState === "hidden") {
      if (this.session.hasFocus) {
        this.documentTitle.setFocus(false);
      }
    } else if (!this.session.hasFocus) {
      this.documentTitle.setFocus(true);
    }
  }
}
import { assert } from "@ember/debug";
import { bind } from "discourse/lib/decorators";
import { makeArray } from "discourse/lib/helpers";

/**
 * A key or array of keys used to position an item relative to others.
 */
export interface DAGPosition {
  /** A key or array of keys of items which should appear before this one. */
  before?: string | string[];
  /** A key or array of keys of items which should appear after this one. */
  after?: string | string[];
}

export interface DAGOptions<T = unknown> {
  /** Default positioning rules for new items. */
  defaultPosition?: DAGPosition;
  /**
   * Whether to throw an error when a cycle is detected. When false, the
   * default position will be used instead.
   */
  throwErrorOnCycle?: boolean;
  /** Called when an item is added. */
  onAddItem?: (key: string, value: T, position: DAGPosition) => void;
  /** Called when an item is removed. */
  onDeleteItem?: (key: string) => void;
  /** Called when an item is replaced. */
  onReplaceItem?: (
    key: string,
    newValue: T,
    oldValue: T,
    newPosition: DAGPosition | undefined,
    oldPosition: DAGPosition
  ) => void;
  /** Called when an item is repositioned. */
  onRepositionItem?: (
    key: string,
    newPosition: DAGPosition,
    oldPosition: DAGPosition
  ) => void;
}

/**
 * A resolved key/value pair together with its positioning rules, as
 * returned by {@link DAG#resolve}.
 */
export interface DAGResolvedEntry<T = unknown> {
  key: string;
  value: T;
  position: DAGPosition;
}

interface DAGItem<T> {
  value: T;
  before?: string | string[];
  after?: string | string[];
}

interface DAGVertex<T> {
  key: string;
  val: T | undefined;
  inEdges: Set<string>;
  outEdges: Set<string>;
  insertionIdx: number;

  /**
   * The before/after constraints actually applied to the graph for this
   * vertex. They can differ from the item's declared position when a
   * cycle forced a fallback to the default position, and they drive the
   * placement ranks computed by the sort.
   */
  appliedBefore?: string | string[];
  appliedAfter?: string | string[];
}

/* Placement-rank slots: a rank extended with BEFORE_ANCHOR sorts just
   before its anchor, with AFTER_ANCHOR just after it. The anchor itself
   compares as 0 (the implicit padding value in compareRanks). */
const BEFORE_ANCHOR = -1;
const AFTER_ANCHOR = 1;

/**
 * Lexicographic comparison of placement ranks. A rank that runs out of
 * elements compares as 0 from then on, ordering an anchor between its
 * before-extensions (-1, ...) and its after-extensions (1, ...).
 */
function compareRanks(a: number[], b: number[]): number {
  const len = Math.max(a.length, b.length);
  for (let i = 0; i < len; i++) {
    const av = i < a.length ? a[i] : 0;
    const bv = i < b.length ? b[i] : 0;
    if (av !== bv) {
      return av < bv ? -1 : 1;
    }
  }
  return 0;
}

/** Binary min-heap over numbers, used to pop the lowest rank ordinal. */
class MinHeap {
  #heap: number[] = [];

  get size(): number {
    return this.#heap.length;
  }

  push(value: number): void {
    const heap = this.#heap;
    heap.push(value);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (heap[parent] <= heap[i]) {
        break;
      }
      [heap[parent], heap[i]] = [heap[i], heap[parent]];
      i = parent;
    }
  }

  pop(): number {
    const heap = this.#heap;
    const top = heap[0];
    const last = heap.pop();
    if (last !== undefined && heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const left = 2 * i + 1;
        const right = left + 1;
        let min = i;
        if (left < heap.length && heap[left] < heap[min]) {
          min = left;
        }
        if (right < heap.length && heap[right] < heap[min]) {
          min = right;
        }
        if (min === i) {
          break;
        }
        [heap[min], heap[i]] = [heap[i], heap[min]];
        i = min;
      }
    }
    return top;
  }
}

class DAGCycleError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "DAGCycleError";
  }
}

export default class DAG<T = unknown> {
  /**
   * Creates a new DAG instance from an iterable of entries.
   *
   * @param entriesLike - An iterable of key-value-position tuples to initialize the DAG.
   * @param opts - Optional configuration object.
   * @returns A new DAG instance.
   */
  static from<T = unknown>(
    entriesLike: Iterable<[string, T, DAGPosition?]>,
    opts?: DAGOptions<T>
  ): DAG<T> {
    const dag = new this(opts) as DAG<T>;

    for (const [key, value, position] of entriesLike) {
      dag.add(key, value, position);
    }

    return dag;
  }

  #defaultPosition: DAGPosition;
  #onAddItem?: DAGOptions<T>["onAddItem"];
  #onDeleteItem?: DAGOptions<T>["onDeleteItem"];
  #onReplaceItem?: DAGOptions<T>["onReplaceItem"];
  #onRepositionItem?: DAGOptions<T>["onRepositionItem"];
  #throwErrorOnCycle: boolean;

  #items = new Map<string, DAGItem<T>>();
  #vertices = new Map<string, DAGVertex<T>>();
  #insertionCounter = 0;
  #dirty = true;
  #cachedResolve: DAGResolvedEntry<T>[] | null = null;

  /**
   * Creates a new Directed Acyclic Graph (DAG) instance.
   *
   * @param opts - Optional configuration object.
   */
  constructor(opts?: DAGOptions<T>) {
    this.#defaultPosition = opts?.defaultPosition || {};
    this.#throwErrorOnCycle = opts?.throwErrorOnCycle ?? true;

    this.#onAddItem = opts?.onAddItem;
    this.#onDeleteItem = opts?.onDeleteItem;
    this.#onReplaceItem = opts?.onReplaceItem;
    this.#onRepositionItem = opts?.onRepositionItem;
  }

  /**
   * Adds a key/value pair to the DAG. Can optionally specify before/after position requirements.
   *
   * @param key - The key of the item to be added. Can be referenced by other member's position parameters.
   * @param value - The value of the item to be added.
   * @param position - The position object specifying before/after requirements.
   * @returns True if the item was added, false if the key already exists.
   */
  add(key: string, value: T, position?: DAGPosition): boolean {
    if (this.has(key)) {
      return false;
    }

    position ||= this.#defaultPositionForKey(key);
    const { before, after } = position;

    try {
      this.#addToGraph(key, value, before, after);
    } catch (e) {
      // Roll the graph back to the current items so a failed add leaves nothing behind.
      this.#rebuildGraph();
      throw e;
    }

    this.#items.set(key, { value, before, after });
    this.#dirty = true;
    this.#onAddItem?.(key, value, position);

    return true;
  }

  /**
   * Remove an item from the map by key.
   *
   * @param key - The key of the item to be removed.
   * @returns True if the item was deleted, false otherwise.
   */
  delete(key: string): boolean {
    const deleted = this.#items.delete(key);
    if (deleted) {
      this.#dirty = true;
      this.#rebuildGraph();
      this.#onDeleteItem?.(key);
    }

    return deleted;
  }

  /**
   * Replace an existing item in the map.
   *
   * @param key - The key of the item to be replaced.
   * @param value - The new value of the item.
   * @param position - The new position constraints. If omitted, the existing position is preserved.
   * @returns True if the item was replaced, false otherwise.
   */
  replace(key: string, value: T, position?: DAGPosition): boolean {
    return this.#replace(key, value, position);
  }

  /**
   * Change the positioning rules of an existing item in the map. Will replace all existing rules.
   *
   * @param key - The key of the item to reposition.
   * @param position - The new position constraints. Replaces all existing rules.
   * @returns True if the item was repositioned, false otherwise.
   */
  reposition(key: string, position: DAGPosition): boolean {
    const item = this.#items.get(key);
    if (!item || !position) {
      return false;
    }

    const { value } = item;

    return this.#replace(key, value, position, { repositionOnly: true });
  }

  /**
   * Check whether an item exists in the map.
   *
   * @param key - The key to check for existence.
   * @returns True if the item exists, false otherwise.
   */
  has(key: string): boolean {
    return this.#items.has(key);
  }

  /**
   * Returns an array of entries in the DAG. Each entry is a tuple containing the key, value, and position object.
   *
   * @returns An array of key-value-position tuples.
   */
  entries(): Array<[string, T, DAGPosition]> {
    return Array.from(this.#items.entries()).map(
      ([key, { value, before, after }]) => [key, value, { before, after }]
    );
  }

  /**
   * Return the resolved key/value pairs in the map. The order of the
   * pairs is determined by the before/after rules using a
   * locality-preserving topological sort.
   *
   * The result is memoized per instance: repeated resolve() calls on an
   * unmutated DAG return the same array (helps the header icon/button
   * singletons that re-resolve on every render).
   *
   * @returns An array of key/value/position objects.
   */
  @bind
  resolve(): DAGResolvedEntry<T>[] {
    if (!this.#dirty && this.#cachedResolve) {
      return this.#cachedResolve;
    }

    const sortedKeys = this.#sort();
    const result: DAGResolvedEntry<T>[] = [];

    for (let i = 0; i < sortedKeys.length; i++) {
      const key = sortedKeys[i];
      const item = this.#items.get(key);
      if (item) {
        const { value, before, after } = item;
        result.push({ key, value, position: { before, after } });
      }
    }

    this.#dirty = false;
    // Frozen so callers can't mutate the shared cached array in place.
    Object.freeze(result);
    this.#cachedResolve = result;
    return result;
  }

  /* Graph management */

  /**
   * Returns the default position for a given key, excluding any
   * constraints that reference the key itself. This prevents
   * self-loops when the default position happens to mention the
   * same key being added (e.g., adding "search" with a default
   * of `{ before: "search" }` would otherwise create a self-edge).
   *
   * @param key - The key to compute the default position for.
   * @returns The default position with self-references stripped.
   */
  #defaultPositionForKey(key: string): DAGPosition {
    const pos = { ...this.#defaultPosition };
    if (makeArray(pos.before).includes(key)) {
      delete pos.before;
    }
    if (makeArray(pos.after).includes(key)) {
      delete pos.after;
    }
    return pos;
  }

  /**
   * Returns the vertex for the given key, creating a placeholder
   * vertex if one does not exist yet. Placeholder vertices support
   * forward references: a key can appear in a before/after constraint
   * before it is explicitly added via `add()`.
   *
   * @param key - The vertex key.
   * @returns The vertex object.
   */
  #getOrCreateVertex(key: string): DAGVertex<T> {
    let v = this.#vertices.get(key);
    if (v === undefined) {
      v = {
        key,
        val: undefined,
        inEdges: new Set(),
        outEdges: new Set(),
        insertionIdx: -1,
      };
      this.#vertices.set(key, v);
    }
    return v;
  }

  /**
   * Adds a vertex and its edges to the internal graph. When
   * `throwErrorOnCycle` is false, a cycle caused by the requested
   * position will be caught and the item will be re-added using
   * the default position instead.
   *
   * @param key - The vertex key.
   * @param value - The vertex value.
   * @param before - Key(s) this vertex must appear before.
   * @param after - Key(s) this vertex must appear after.
   */
  #addToGraph(
    key: string,
    value: T,
    before?: string | string[],
    after?: string | string[]
  ): void {
    if (this.#throwErrorOnCycle) {
      this.#addVertexAndEdges(key, value, before, after);
    } else {
      try {
        this.#addVertexAndEdges(key, value, before, after);
      } catch (e) {
        if (!(e instanceof DAGCycleError)) {
          throw e;
        }
        const { before: newBefore, after: newAfter } =
          this.#defaultPositionForKey(key);
        try {
          this.#addVertexAndEdges(key, value, newBefore, newAfter);
        } catch (e2) {
          if (!(e2 instanceof DAGCycleError)) {
            throw e2;
          }
          // Both the requested and default positions create a cycle.
          // The vertex exists but has no constraint edges.
        }
      }
    }
  }

  #addVertexAndEdges(
    key: string,
    value: T,
    before?: string | string[],
    after?: string | string[]
  ): void {
    const v = this.#getOrCreateVertex(key);
    v.val = value;
    if (v.insertionIdx === -1) {
      v.insertionIdx = this.#insertionCounter++;
    }

    // Track edges added during this call as [fromKey, toKey] pairs
    // so they can be rolled back if a later constraint creates a cycle.
    const added: string[] = [];

    try {
      if (before) {
        if (typeof before === "string") {
          if (this.#addEdge(v, this.#getOrCreateVertex(before))) {
            added.push(v.key, before);
          }
        } else {
          for (let i = 0; i < before.length; i++) {
            if (this.#addEdge(v, this.#getOrCreateVertex(before[i]))) {
              added.push(v.key, before[i]);
            }
          }
        }
      }

      if (after) {
        if (typeof after === "string") {
          if (this.#addEdge(this.#getOrCreateVertex(after), v)) {
            added.push(after, v.key);
          }
        } else {
          for (let i = 0; i < after.length; i++) {
            if (this.#addEdge(this.#getOrCreateVertex(after[i]), v)) {
              added.push(after[i], v.key);
            }
          }
        }
      }
    } catch (e) {
      for (let i = 0; i < added.length; i += 2) {
        // Both ends were created by #getOrCreateVertex before being recorded.
        const from = this.#vertices.get(added[i]);
        const to = this.#vertices.get(added[i + 1]);
        assert("A recorded edge has both vertices", from && to);
        from.outEdges.delete(added[i + 1]);
        to.inEdges.delete(added[i]);
      }
      throw e;
    }

    // Recorded only on success so a cycle fallback re-records the
    // constraints that actually made it into the graph.
    v.appliedBefore = before;
    v.appliedAfter = after;
  }

  #addEdge(from: DAGVertex<T>, to: DAGVertex<T>): boolean {
    if (from.key === to.key) {
      throw new DAGCycleError("cycle detected: " + to.key + " <- " + to.key);
    }

    if (from.outEdges.has(to.key)) {
      return false;
    }

    if (to.outEdges.size > 0) {
      const path = this.#findCyclePath(to, from.key);
      if (path !== null) {
        throw new DAGCycleError("cycle detected: " + path);
      }
    }

    from.outEdges.add(to.key);
    to.inEdges.add(from.key);
    return true;
  }

  #findCyclePath(start: DAGVertex<T>, targetKey: string): string | null {
    if (start.outEdges.has(targetKey)) {
      return targetKey + " <- " + start.key + " <- " + targetKey;
    }

    const visited = new Set([start.key]);
    const parent = new Map<string, string>();
    const frontier: string[] = [];

    for (const next of start.outEdges) {
      if (!visited.has(next)) {
        visited.add(next);
        parent.set(next, start.key);
        frontier.push(next);
      }
    }

    for (let head = 0; head < frontier.length; head++) {
      const key = frontier[head];

      if (key === targetKey) {
        let msg = targetKey;
        let cur: string | undefined = targetKey;
        while (cur !== undefined) {
          msg += " <- " + (parent.get(cur) ?? start.key);
          cur = parent.get(cur);
          if (cur === start.key) {
            break;
          }
        }
        msg += " <- " + targetKey;
        return msg;
      }

      const vertex = this.#vertices.get(key);
      if (vertex) {
        for (const next of vertex.outEdges) {
          if (!visited.has(next)) {
            visited.add(next);
            parent.set(next, key);
            frontier.push(next);
          }
        }
      }
    }

    return null;
  }

  #rebuildGraph(): void {
    this.#vertices = new Map();
    this.#insertionCounter = 0;
    for (const [key, { value, before, after }] of this.#items) {
      this.#addToGraph(key, value, before, after);
    }
  }

  #replace(
    key: string,
    value: T,
    position?: DAGPosition,
    { repositionOnly }: { repositionOnly: boolean } = { repositionOnly: false }
  ): boolean {
    const existingItem = this.#items.get(key);
    if (!existingItem) {
      return false;
    }

    const oldValue = existingItem.value;
    const oldPosition = {
      before: existingItem.before,
      after: existingItem.after,
    };

    existingItem.value = value;

    if (position) {
      existingItem.before = position.before;
      existingItem.after = position.after;
    }

    this.#dirty = true;

    try {
      this.#rebuildGraph();
    } catch (e) {
      existingItem.value = oldValue;
      existingItem.before = oldPosition.before;
      existingItem.after = oldPosition.after;
      this.#rebuildGraph();
      throw e;
    }

    if (repositionOnly) {
      assert("A reposition carries a position", position);
      this.#onRepositionItem?.(key, position, oldPosition);
    } else {
      this.#onReplaceItem?.(key, value, oldValue, position, oldPosition);
    }

    return true;
  }

  /* Sorting */

  /**
   * Locality-preserving topological sort.
   *
   * Every vertex gets a placement rank, and the output is the topological
   * order closest to rank order: Kahn's algorithm always emits the
   * lowest-ranked ready vertex, so the result deviates from rank order
   * only where an edge contradicts it, and only for the vertices that
   * edge touches. The output is always a valid topological order.
   *
   * A rank is a path of `(side, insertionIdx)` steps rooted at an
   * unanchored vertex. Each vertex anchors to at most ONE key from its
   * applied position — the anchor decides where the vertex prefers to
   * sit, while every declared key remains a hard ordering edge:
   *
   * - `after: X` extends X's rank on the after side: the item sorts
   *   immediately after X (and after X's whole after-group, in insertion
   *   order), before anything unrelated to X.
   * - `before: X` extends X's rank on the before side: the item sorts
   *   immediately before X, again in insertion order within the group.
   * - With both `before` and `after`, the `after` anchor wins: the item
   *   hugs the item it follows.
   * - With multiple keys on one side, `after` anchors to the
   *   highest-ranked key and `before` to the lowest-ranked one — the
   *   nearest end of the window the constraints allow.
   * - Anchors never added to the DAG are ignored (an item constrained
   *   only relative to absent keys ranks by its own insertion index, and
   *   an absent key itself sorts past every real item, so anything
   *   `after` it lands at the end). Mutually recursive anchor references
   *   (e.g. `x after a` + `a before x`) break the loop at the vertex
   *   reached last, which then ranks by insertion index.
   */
  #sort(): string[] {
    const vertices = this.#vertices;
    const size = vertices.size;
    if (size === 0) {
      return [];
    }

    const sortedKeys = this.#keysInRankOrder();
    const ordinals = new Map<string, number>();
    for (let i = 0; i < sortedKeys.length; i++) {
      ordinals.set(sortedKeys[i], i);
    }

    // `ordinals` and `inDegree` hold every vertex key, and edges only join
    // vertices, so the lookups below are always defined.
    const inDegree = new Map<string, number>();
    const ready = new MinHeap();
    for (const [key, v] of vertices) {
      inDegree.set(key, v.inEdges.size);
      if (v.inEdges.size === 0) {
        const ordinal = ordinals.get(key);
        assert("Every vertex has an ordinal", ordinal !== undefined);
        ready.push(ordinal);
      }
    }

    const result: string[] = [];
    while (ready.size > 0) {
      const key = sortedKeys[ready.pop()];
      result.push(key);

      const vertex = vertices.get(key);
      assert("A ready key is a vertex", vertex);
      for (const succKey of vertex.outEdges) {
        const degree = inDegree.get(succKey);
        assert("Every successor has an in-degree", degree !== undefined);
        const d = degree - 1;
        inDegree.set(succKey, d);
        if (d === 0) {
          const ordinal = ordinals.get(succKey);
          assert("Every vertex has an ordinal", ordinal !== undefined);
          ready.push(ordinal);
        }
      }
    }

    if (result.length !== size) {
      const remaining: string[] = [];
      for (const [key, deg] of inDegree) {
        if (deg > 0) {
          remaining.push(key);
        }
      }
      throw new DAGCycleError(
        "cycle detected among: " + JSON.stringify(remaining)
      );
    }

    return result;
  }

  #keysInRankOrder(): string[] {
    const ranks = this.#computeRanks();
    const keys = [...this.#vertices.keys()];
    keys.sort((a, b) => {
      const rankA = ranks.get(a);
      const rankB = ranks.get(b);
      assert("Every vertex has a rank", rankA && rankB);
      return compareRanks(rankA, rankB);
    });
    return keys;
  }

  /**
   * Computes the placement rank of every vertex (see the sort method's
   * doc for the rank semantics).
   * Memoized per call; anchor chains are followed recursively with an
   * in-progress guard so mutually recursive anchor references terminate.
   */
  #computeRanks(): Map<string, number[]> {
    const ranks = new Map<string, number[]>();
    const inProgress = new Set<string>();

    const selectAnchor = (
      refs: string | string[] | undefined,
      latest: boolean
    ): string | null => {
      if (!refs) {
        return null;
      }

      let best: string | null = null;
      let bestRank: number[] | null = null;

      for (const ref of makeArray(refs)) {
        const anchor = this.#vertices.get(ref);
        if (!anchor || anchor.insertionIdx === -1 || inProgress.has(ref)) {
          continue;
        }

        const anchorRank = rankOf(ref);
        if (
          bestRank === null ||
          (latest
            ? compareRanks(anchorRank, bestRank) > 0
            : compareRanks(anchorRank, bestRank) < 0)
        ) {
          best = ref;
          bestRank = anchorRank;
        }
      }

      return best;
    };

    const rankOf = (key: string): number[] => {
      let rank = ranks.get(key);
      if (rank !== undefined) {
        return rank;
      }

      const v = this.#vertices.get(key);
      assert("A ranked key is a vertex", v);
      // Placeholder vertices (referenced but never added) sort past every
      // real insertion index.
      const idx = v.insertionIdx === -1 ? Infinity : v.insertionIdx;

      inProgress.add(key);

      const afterAnchor = selectAnchor(v.appliedAfter, true);
      if (afterAnchor !== null) {
        rank = [...rankOf(afterAnchor), AFTER_ANCHOR, idx];
      } else {
        const beforeAnchor = selectAnchor(v.appliedBefore, false);
        rank =
          beforeAnchor !== null
            ? [...rankOf(beforeAnchor), BEFORE_ANCHOR, idx]
            : [idx];
      }

      inProgress.delete(key);
      ranks.set(key, rank);
      return rank;
    };

    for (const key of this.#vertices.keys()) {
      rankOf(key);
    }

    return ranks;
  }
}
