    clickable: true,
  },
  {
    shortcut: "mod+enter",
    description: i18n("search.tips.full_search"),
  },
  {
    label: "@me",
    description: i18n("search.tips.me"),
  },
];

let QUICK_TIPS = [];

export function addQuickSearchRandomTip(tip) {
  if (!QUICK_TIPS.includes(tip)) {
    QUICK_TIPS.push(tip);
  }
}

export function resetQuickSearchRandomTips() {
  QUICK_TIPS = [].concat(DEFAULT_QUICK_TIPS);
}

export function removeDefaultQuickSearchRandomTips() {
  QUICK_TIPS = QUICK_TIPS.filter((tip) => !DEFAULT_QUICK_TIPS.includes(tip));
}

resetQuickSearchRandomTips();

export default class RandomQuickTip extends Component {
  @service capabilities;
  @service search;

  constructor() {
    super(...arguments);
    // A tip about a key combination is no help without a keyboard to press
    // it. The pick is made once per instance, so a keyboard noticed later
    // shows up on the next open.
    const tips = QUICK_TIPS.filter(
      (tip) => !tip.shortcut || this.capabilities.hasKeyboard
    );
    this.randomTip = tips[Math.floor(Math.random() * tips.length)];
  }

  @action
  tipSelected(e) {
    if (e.target.classList.contains("tip-clickable")) {
      this.args.searchTermChanged(this.randomTip.label);
      this.search.focusSearchInput();

      e.stopPropagation();
      e.preventDefault();
    }
  }

  <template>
    <li class="search-random-quick-tip">
      <button
        aria-describedby="tip-description"
        class={{dConcatClass
          "tip-label"
          (if this.randomTip.clickable "tip-clickable")
        }}
        {{on "click" this.tipSelected}}
      >
        {{#if this.randomTip.shortcut}}
          <DShortcut @keys={{this.randomTip.shortcut}} />
        {{else}}
          {{this.randomTip.label}}
        {{/if}}
      </button>

      <span id="tip-description">
        {{this.randomTip.description}}
      </span>
    </li>
  </template>
}
import Component from "@glimmer/component";
import { action, get } from "@ember/object";
import { service } from "@ember/service";
import AssistantItem from "discourse/components/search-menu/results/assistant-item";
import { MAX_RECENT_SEARCHES } from "discourse/lib/search";
import {
  applyBehaviorTransformer,
  applyValueTransformer,
} from "discourse/lib/transformer";
import User from "discourse/models/user";
import DButton from "discourse/ui-kit/d-button";

export default class RecentSearches extends Component {
  @service currentUser;
  @service siteSettings;

  constructor() {
    super(...arguments);

    if (
      this.currentUser &&
      this.siteSettings.log_search_queries &&
      !this.currentUser.recent_searches?.length
    ) {
      this.loadRecentSearches();
    }
  }

  // Entries rather than bare terms so a consumer can merge in history of its
  // own, and each row can say which kind of search it repeats.
  get entries() {
    // `get` rather than a native read: recent searches are set on the classic
    // user object, and a native read would not re-render when they arrive.
    const detailed = get(this.currentUser, "recent_searches_detailed");
    const terms = get(this.currentUser, "recent_searches") || [];
    const searches = (detailed || terms.map((term) => ({ term }))).map(
      (entry) => ({ ...entry, icon: "magnifying-glass" })
    );

    const merged = applyValueTransformer(
      "search-menu-recent-searches",
      searches,
      { location: this.args.location }
    );

    const at = (entry) => {
      const parsed = entry.at ? Date.parse(entry.at) : NaN;
      return isNaN(parsed) ? -Infinity : parsed;
    };

    return [...merged]
      .sort((first, second) => at(second) - at(first))
      .slice(0, MAX_RECENT_SEARCHES);
  }

  @action
  async clearRecent() {
    await applyBehaviorTransformer(
      "search-menu-clear-recent-searches",
      async () => {
        const result = await User.resetRecentSearches();
        if (result.success) {
          this.currentUser.set("recent_searches", []);
          this.currentUser.set("recent_searches_detailed", []);
        }
      },
      { location: this.args.location }
    );
  }

  @action
  onKeyup(e) {
    if (e.key === "Escape") {
      this.args.closeSearchMenu();
      e.preventDefault();
      return false;
    }

    this.search.handleArrowUpOrDown(e);
  }

  async loadRecentSearches() {
    const result = await User.loadRecentSearches();
    if (result.success && result.recent_searches?.length) {
      this.currentUser.set("recent_searches", result.recent_searches);
      this.currentUser.set(
        "recent_searches_detailed",
        result.recent_searches_detailed
      );
    }
  }

  <template>
    {{#if this.entries}}
      <div class="search-menu-recent">
        {{#each this.entries as |entry|}}
          <AssistantItem
            @closeSearchMenu={{@closeSearchMenu}}
            @concatSlug={{true}}
            @icon={{entry.icon}}
            @label={{entry.term}}
            @searchTermChanged={{@searchTermChanged}}
            @slug={{entry.term}}
            @usage={{if entry.usage entry.usage "recent-search"}}
          />
        {{/each}}

        <DButton
          class="btn-transparent btn-small clear-recent-searches"
          @action={{this.clearRecent}}
          @label="search.clear_recent"
        />
      </div>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import { service } from "@ember/service";
import PluginOutlet from "discourse/components/plugin-outlet";
import { MODIFIER_REGEXP } from "discourse/components/search-menu";
import AssistantItem from "discourse/components/search-menu/results/assistant-item";
import RandomQuickTip from "discourse/components/search-menu/results/random-quick-tip";
import RecentSearches from "discourse/components/search-menu/results/recent-searches";
import lazyHash from "discourse/helpers/lazy-hash";
import { applyValueTransformer } from "discourse/lib/transformer";
import { i18n } from "discourse-i18n";
import Assistant from "./assistant.gjs";

const SEARCH_CONTEXT_TYPE_COMPONENTS = {
  topic: AssistantItem,
  private_messages: AssistantItem,
  category: Assistant,
  tag: Assistant,
  tagIntersection: Assistant,
  user: AssistantItem,
};

const DISPLAY_INITIAL_OPTIONS_FOR_CONTEXT_TYPES = [
  "topic",
  "category",
  "tag",
  "tagIntersection",
  "user",
];

export default class InitialOptions extends Component {
  @service search;
  @service siteSettings;
  @service currentUser;

  constructor() {
    super(...arguments);

    if (this.search.activeGlobalSearchTerm || this.search.searchContext) {
      if (this.search.searchContext) {
        // set the component we will be using to display results
        this.contextTypeComponent =
          SEARCH_CONTEXT_TYPE_COMPONENTS[this.search.searchContext.type];
        // set attributes for the component
        this.setAttributesForSearchContextType(this.search.searchContext.type);
      }
    }
  }

  // These shortcuts promise the term will be run against the index, scoped or
  // not, so a consumer that offers those choices itself can drop them.
  get showSearchShortcuts() {
    return applyValueTransformer("search-menu-search-shortcuts-enabled", true, {
      location: this.args.location,
    });
  }

  get termMatchesContextTypeKeyword() {
    return this.search.activeGlobalSearchTerm?.match(MODIFIER_REGEXP);
  }

  get displayInitialOptions() {
    if (this.search.activeGlobalSearchTerm) {
      return false;
    }
    return DISPLAY_INITIAL_OPTIONS_FOR_CONTEXT_TYPES.includes(
      this.search.searchContext?.type
    );
  }

  setAttributesForSearchContextType(type) {
    switch (type) {
      case "topic":
        this.topicContextType();
        break;
      case "private_messages":
        this.privateMessageContextType();
        break;
      case "category":
        this.categoryContextType();
        break;
      case "tag":
        this.tagContextType();
        break;
      case "tagIntersection":
        this.tagIntersectionContextType();
        break;
      case "user":
        this.userContextType();
        break;
    }
  }

  topicContextType() {
    this.suffix = i18n("search.in_this_topic");
  }

  privateMessageContextType() {
    this.slug = "in:messages";
    this.label = "in:messages";
  }

  categoryContextType() {
    const searchContextCategory = this.search.searchContext.category;
    const fullSlug = searchContextCategory.parentCategory
      ? `#${searchContextCategory.parentCategory.slug}:${searchContextCategory.slug}`
      : `#${searchContextCategory.slug}`;

    this.slug = fullSlug;
    this.contextTypeKeyword = "#";
    this.initialResults = [{ model: this.search.searchContext.category }];
    this.withInLabel = true;
  }

  tagContextType() {
    this.slug = `#${this.search.searchContext.name}`;
    this.contextTypeKeyword = "#";
    this.initialResults = [{ name: this.search.searchContext.name }];
    this.withInLabel = true;
  }

  tagIntersectionContextType() {
    const searchContext = this.search.searchContext;

    let tagTerm;
    if (searchContext.additionalTags) {
      const tags = [searchContext.tagId, ...searchContext.additionalTags];
      tagTerm = `tags:${tags.join("+")}`;
    } else {
      tagTerm = `#${searchContext.tagId}`;
    }
    let suggestionOptions = {
      tagName: searchContext.tagId,
      additionalTags: searchContext.additionalTags,
    };
    if (searchContext.category) {
      const categorySlug = searchContext.category.parentCategory
        ? `#${searchContext.category.parentCategory.slug}:${searchContext.category.slug}`
        : `#${searchContext.category.slug}`;
      suggestionOptions.categoryName = categorySlug;
      suggestionOptions.category = searchContext.category;
      tagTerm = tagTerm + ` ${categorySlug}`;
    }

    this.slug = tagTerm;
    this.contextTypeKeyword = "+";
    this.initialResults = [suggestionOptions];
    this.withInLabel = true;
  }

  userContextType() {
    this.contextTypeKeyword = "@";
    this.slug = `@${this.search.searchContext.user.username}`;
    this.suffix = i18n("search.in_posts_by", {
      username: this.search.searchContext.user.username,
    });
  }

  <template>
    <ul class="search-menu-initial-options">
      <PluginOutlet
        @name="search-menu-initial-options"
        @outletArgs={{lazyHash
          termMatchesContextTypeKeyword=this.termMatchesContextTypeKeyword
          contextTypeComponent=this.contextTypeComponent
          slug=this.slug
          suggestionKeyword=this.contextTypeKeyword
          results=this.initialResults
          withInLabel=this.withInLabel
          suffix=this.suffix
          label=this.label
          closeSearchMenu=@closeSearchMenu
          searchTermChanged=@searchTermChanged
        }}
      >
        {{#if this.termMatchesContextTypeKeyword}}
          {{#if this.showSearchShortcuts}}
            <AssistantItem
              @closeSearchMenu={{@closeSearchMenu}}
              @extraHint={{true}}
              @searchTermChanged={{@searchTermChanged}}
              @slug={{this.slug}}
              @suggestionKeyword={{this.contextTypeKeyword}}
            />
          {{/if}}
        {{else}}
          {{#if
            (or this.search.activeGlobalSearchTerm this.search.searchContext)
          }}
            {{#if
              (and this.search.activeGlobalSearchTerm this.showSearchShortcuts)
            }}
              <AssistantItem
                @closeSearchMenu={{@closeSearchMenu}}
                @extraHint={{true}}
                @searchAllTopics={{true}}
                @searchTermChanged={{@searchTermChanged}}
                @suffix={{i18n "search.in_topics_posts"}}
                @suggestionKeyword={{this.contextTypeKeyword}}
              />
            {{/if}}

            {{#if (and this.search.searchContext this.showSearchShortcuts)}}
              <this.contextTypeComponent
                @closeSearchMenu={{@closeSearchMenu}}
                @label={{this.label}}
                @results={{this.initialResults}}
                @searchTermChanged={{@searchTermChanged}}
                @slug={{this.slug}}
                @suffix={{this.suffix}}
                @suggestionKeyword={{this.contextTypeKeyword}}
                @withInLabel={{this.withInLabel}}
              />

              {{#if
                (and
                  this.currentUser
                  this.siteSettings.log_search_queries
                  this.displayInitialOptions
                )
              }}
                <RecentSearches
                  @closeSearchMenu={{@closeSearchMenu}}
                  @location={{@location}}
                  @searchTermChanged={{@searchTermChanged}}
                />
              {{/if}}
            {{/if}}
          {{else}}
            <RandomQuickTip
              @searchInputId={{@searchInputId}}
              @searchTermChanged={{@searchTermChanged}}
            />
            {{#if (and this.currentUser this.siteSettings.log_search_queries)}}
              <RecentSearches
                @closeSearchMenu={{@closeSearchMenu}}
                @location={{@location}}
                @searchTermChanged={{@searchTermChanged}}
              />
            {{/if}}
          {{/if}}
        {{/if}}
      </PluginOutlet>

    </ul>
  </template>
}
