          alt={{@title}}
          class={{@key}}
          id="site-logo"
          src={{getURL @url}}
          width={{if (eq @key "logo-small") "36"}}
        />
      </picture>
    {{else}}
      <img
        alt={{@title}}
        class={{@key}}
        id="site-logo"
        src={{getURL @url}}
        width={{if (eq @key "logo-small") "36"}}
      />
    {{/if}}
  </template>
}
