              class="sidebar__edit-navigation-menu__filter-input-field"
              placeholder={{@inputFilterPlaceholder}}
              type="text"
              value={{this.filter}}
              {{on "input" (withEventValue (fn (mut this.filter)))}}
              {{on "input" (withEventValue @onFilterInput)}}
