export default class UserMenuBaseItem {
  constructor({ siteSettings, site }) {
    this.site = site;
    this.siteSettings = siteSettings;
  }

  get className() {}

  get linkHref() {
    throw new Error("not implemented");
  }

  get linkTitle() {
    throw new Error("not implemented");
  }

  get icon() {
    throw new Error("not implemented");
  }

  get label() {
    throw new Error("not implemented");
  }

  get labelClass() {}

  get description() {
    throw new Error("not implemented");
  }

  get descriptionClass() {}

  get topicId() {}

  get avatarTemplate() {}

  get iconComponent() {
    return this.siteSettings.show_user_menu_avatars ? UserMenuIconAvatar : null;
  }

  get iconComponentArgs() {
    // Use endsWith to determine if the avatarTemplate is the system avatar, because locally the
    // system avatar is a relative path and doesn't contain hostname. Exact matches will also
    // evaluate to true.
    const usingSystemAvatar =
      !this.avatarTemplate ||
      this.avatarTemplate.endsWith(this.site.system_user_avatar_template);

    return {
      avatarTemplate:
        this.avatarTemplate || this.site.system_user_avatar_template,
      icon: this.icon,
      classNames: usingSystemAvatar ? "system-avatar" : "user-avatar",
    };
  }

  onClick({ event, closeUserMenu }) {
    if (wantsNewWindow(event)) {
      return;
    }

    event.preventDefault();
    closeUserMenu?.();

    if (this.linkHref) {
      DiscourseURL.routeTo(this.linkHref);
    }
  }
}
import { setTransientHeader } from "discourse/lib/ajax";
import cookie from "discourse/lib/cookie";
import getURL from "discourse/lib/get-url";
import { getRenderDirector } from "discourse/lib/notification-types-manager";
import { applyValueTransformer } from "discourse/lib/transformer";
import UserMenuBaseItem from "discourse/lib/user-menu/base-item";

export default class UserMenuNotificationItem extends UserMenuBaseItem {
  constructor({
    notification,
    endComponent,
    appEvents,
    currentUser,
    siteSettings,
    site,
  }) {
    super(...arguments);
    this.appEvents = appEvents;
    this.currentUser = currentUser;
    this.endComponent = endComponent;
    this.notification = notification;
    this.siteSettings = siteSettings;
    this.site = site;

    this.renderDirector = getRenderDirector(
      this.#notificationName,
      notification,
      currentUser,
      siteSettings,
      site
    );
  }

  get className() {
    return this.renderDirector.classNames?.join(" ") || "";
  }

  get linkHref() {
    return this.renderDirector.linkHref;
  }

  get linkTitle() {
    return this.renderDirector.linkTitle;
  }

  get icon() {
    return this.renderDirector.icon;
  }

  get label() {
    return this.renderDirector.label;
  }

  get labelClass() {
    return this.renderDirector.labelClasses?.join(" ") || "";
  }

  get description() {
    return this.renderDirector.description;
  }

  get descriptionClass() {
    return this.renderDirector.descriptionClasses?.join(" ") || "";
  }

  get topicId() {
    return this.notification.topic_id;
  }

  get avatarTemplate() {
    const acting_user_avatar = this.notification.acting_user_avatar_template;
    return applyValueTransformer(
      "user-menu-notification-item-acting-user-avatar",
      acting_user_avatar,
      { notification: this.notification }
    );
  }

  get endOutletArgs() {
    return {
      notification: this.notification,
    };
  }

  get #notificationName() {
    return this.site.notificationLookup[this.notification.notification_type];
  }

  onClick() {
    this.renderDirector.onClick?.();
    this.appEvents.trigger("user-menu:notification-click", {
      notification: this.notification,
      href: this.linkHref,
    });

    if (!this.notification.read) {
      this.notification.set("read", true);

      const groupedUnreadNotifications = {
        ...this.currentUser.grouped_unread_notifications,
      };
      const unreadCount =
        groupedUnreadNotifications &&
        groupedUnreadNotifications[this.notification.notification_type];
      if (unreadCount > 0) {
        groupedUnreadNotifications[this.notification.notification_type] =
          unreadCount - 1;
        this.currentUser.set(
          "grouped_unread_notifications",
          groupedUnreadNotifications
        );
      }

      setTransientHeader("Discourse-Clear-Notifications", this.notification.id);
      cookie("cn", this.notification.id, { path: getURL("/") });
    }
    super.onClick(...arguments);
  }
}
