import { i18n } from "discourse-i18n";

export default function (element, context) {
  const { post } = context;

  const linkCounts = post.link_counts;
  if (!linkCounts?.length) {
    return;
  }

  // find the best <a> element in each onebox and display link counts only
  // for that one (the best element is the most significant one to the
  // viewer)
  const bestElements = new Map();
  element.querySelectorAll("aside.onebox").forEach((onebox) => {
    // look in headings first
    for (let i = 1; i <= 6; ++i) {
      const hLinks = onebox.querySelectorAll(`h${i} a[href]`);
      if (hLinks.length > 0) {
        bestElements.set(onebox, hLinks[0]);
        return;
      }
    }

    // use the header otherwise
    const hLinks = onebox.querySelectorAll("header a[href]");
    if (hLinks.length > 0) {
      bestElements.set(onebox, hLinks[0]);
    }
  });

  linkCounts.forEach((lc) => {
    if (!lc.clicks || lc.clicks < 1) {
      return;
    }

    element.querySelectorAll("a[href]").forEach((link) => {
      const href = link.getAttribute("href");
      let valid = href === lc.url;

      // this might be an attachment
      if (lc.internal && /^\/uploads\//.test(lc.url)) {
        valid = href.includes(lc.url);
      }

      // match server-side behavior for internal links with query params
      if (lc.internal && /\?/.test(href)) {
        valid = href.split("?")[0] === lc.url;
      }

      // don't display badge counts on category badge & oneboxes (unless when explicitly stated)
      if (valid && isValidLink(link)) {
        const onebox = link.closest(".onebox");

        if (
          !onebox ||
          !bestElements.has(onebox) ||
          bestElements.get(onebox) === link
        ) {
          link.setAttribute("data-clicks", number(lc.clicks));

          const countText = i18n("post.link_clicked", {
            count: lc.clicks,
          });
          const ariaLabel = `${link.textContent.trim()} ${countText}`;
          link.setAttribute("aria-label", ariaLabel);
        }
      }
    });
  });
}
// Swaps the title and preview of internal topic onebox cards with the reader's
// language when the post is shown in its original form (see PostSerializer
// #localized_oneboxes). Same-topic inline quotes carry a data-username and are
// left untouched. Runs before quote-controls so the rendered quote component
// picks up the already-localized text.
//
// title and excerpt are server-rendered, sanitized HTML (HTML-escaped text with
// emoji <img> tags), matching the baked onebox card, so both are assigned via
// innerHTML — textContent would show emoji markup as literal text.
export default function decorateLocalizedOneboxes(element, context) {
  const { post } = context;

  const localized = post.localized_oneboxes;
  if (!localized?.length) {
    return;
  }

  for (const { topic_id, post_number, title, excerpt } of localized) {
    const selector = `aside.quote[data-topic="${topic_id}"][data-post="${post_number}"]:not([data-username])`;

    element.querySelectorAll(selector).forEach((aside) => {
      if (title) {
        // the title link, not the category badge that also lives in .title
        const titleLink =
          aside.querySelector(".quote-title__text-content a[href]") ??
          aside.querySelector(".title a[href]");
        if (titleLink) {
          titleLink.innerHTML = title;
        }
      }

      if (excerpt) {
        const blockquote = aside.querySelector("blockquote");
        if (blockquote) {
          blockquote.innerHTML = excerpt;
        }
      }
    });
  }
}
import getURL from "discourse/lib/get-url";
import { applyValueTransformer } from "discourse/lib/transformer";
import DUserStatusMessage from "discourse/ui-kit/d-user-status-message";

const CookedUserStatusMessage = <template>
  {{#in-element @data.wrapper}}
    <DUserStatusMessage @status={{@data.status}} />
  {{/in-element}}
</template>;

export default function (element, context) {
  const { post, owner, helper } = context;

  const extractedMentions = extractMentions(element, post);
  const userStatusService = owner.lookup("service:user-status");

  const updateUserStatus = (updatedUser) => {
    extractedMentions
      .filter(({ user }) => updatedUser.id === user?.id)
      .forEach(({ mentions, user }) => {
        renderUserStatusOnMentions(mentions, user, helper);
      });
  };

  extractedMentions.forEach(({ mentions, user }) => {
    if (userStatusService.isEnabled) {
      user.statusManager?.trackStatus?.();
      user.on?.("status-changed", element, updateUserStatus);

      renderUserStatusOnMentions(mentions, user, helper);
    }

    const classes = applyValueTransformer("mentions-class", [], {
      user,
    });

    mentions.forEach((mention) => {
      mention.classList.add(...classes);
    });
  });

  // cleanup code
  return () => {
    if (userStatusService.isEnabled) {
      extractedMentions.forEach(({ user }) => {
        user.statusManager?.stopTrackingStatus?.();
        user.off?.("status-changed", element, updateUserStatus);
      });
    }
  };
}

function renderUserStatusOnMentions(mentions, user, helper) {
  mentions.forEach((mention) => {
    let wrapper = mention.querySelector(".user-status-message-wrapper");

    if (user.status) {
      if (!wrapper) {
        wrapper = document.createElement("span");
        wrapper.classList.add("user-status-message-wrapper");
        mention.appendChild(wrapper);
      }

      helper.renderGlimmer(mention, CookedUserStatusMessage, {
        wrapper,
        status: user.status,
      });
    } else {
      wrapper?.remove?.();
    }
  });
}

function extractMentions(element, post) {
  return (
    post?.mentioned_users?.map((user) => {
      const href = getURL(`/u/${user.username.toLowerCase()}`);
      const mentions = element.querySelectorAll(`a.mention[href="${href}"]`);

      return { user, mentions };
    }) || []
  );
}
