        )}}
        {{(if
          @wrapperElement
          (modifier
            this.applyWrapperDataAttributes
            @wrapperElement
            (hash expanded=this.expanded)
          )
        )}}
      >
        {{~#if (has-block "title")~}}
          {{~yield to="title"~}}
        {{~else~}}
          {{~#if @quotedPostNotFound~}}
            {{~@quotedUsername~}}
          {{~else~}}
            {{~@title~}}
          {{~/if~}}
        {{~/if~}}
        {{~#if this.shouldDisplayQuoteControls~}}
          <div class="quote-controls">
            {{~#if this.shouldDisplayToggleButton~}}
              <DButton
                class="btn-flat quote-toggle"
                @action={{this.toggleExpanded}}
                @ariaControls={{@id}}
                @ariaExpanded={{this.expanded}}
                @ariaLabel={{if this.expanded "post.collapse" "expand"}}
                @title={{if this.expanded "post.collapse" "expand"}}
              >
                {{! rendering the icon in the block instead of using the parameter `@icon` prevents DButton from adding
                    extra whitespace that will interfere with the text captured when quoting a quoted content }}
                {{~dIcon this.toggleIcon~}}
              </DButton>
            {{~/if~}}
            {{~#if this.shouldDisplayNavigateToPostButton~}}
              <DButton
                class="btn-flat back"
                @ariaLabel="post.follow_quote"
                @href={{this.quotedPostUrl}}
                @title="post.follow_quote"
                {{on "click" this.followQuote}}
              >
                {{! rendering the icon in the block instead of using the parameter `@icon` prevents DButton from adding
                    extra whitespace that will interfere with the text captured when quoting a quoted content }}
                {{~dIcon this.navigateToPostIcon~}}
              </DButton>
            {{~/if~}}
          </div>
        {{~/if~}}
      </div>
      <blockquote id={{@id}}>
        {{~#unless this.isQuotedPostIgnored~}}
          {{~#if this.expanded~}}
            <DAsyncContent
              @asyncData={{this.loadQuotedPost}}
              @context={{hash
                topicNumber=@quotedTopicId
                postNumber=@quotedPostNumber
                cachedPost=@quotedPost
              }}
            >
              <:content as |expandedPost|>
                <div class="expanded-quote" data-post-id={{expandedPost.id}}>
                  <PostCookedHtml
                    @className="post__contents-cooked-quote"
                    @decoratorState={{@decoratorState}}
                    @extraDecorators={{this.extraDecorators}}
                    @highlightTerm={{@highlightTerm}}
                    @post={{expandedPost}}
                    @selectionBarrier={{false}}
                    @streamElement={{@streamElement}}
                  />
                </div>
              </:content>
              <:error as |error AsyncContentInlineErrorMessage|>
                {{~#if (eq error.jqXHR.status 403)~}}
                  <div class="quote-error expanded-quote icon-only">
                    {{~dIcon "lock"~}}
                  </div>
                {{~else if (eq error.jqXHR.status 404)~}}
                  <div class="quote-error expanded-quote icon-only">
                    {{~dIcon "trash-can"~}}
                  </div>
                {{~else~}}
                  <div class="quote-error expanded-quote">
                    <AsyncContentInlineErrorMessage />
                  </div>
                {{~/if~}}
              </:error>
            </DAsyncContent>
          {{~else~}}
            <PostCookedHtml
              @className="post__contents-cooked-quote"
              @cooked={{@collapsedContent}}
              @decoratorState={{@decoratorState}}
              @extraDecorators={{this.extraDecorators}}
              @highlightTerm={{@highlightTerm}}
              @post={{@post}}
              @selectionBarrier={{false}}
              @streamElement={{@streamElement}}
            />
          {{~/if~}}
        {{~/unless~}}
      </blockquote>
    </this.OptionalWrapperComponent>
  </template>
}
import { trustHTML } from "@ember/template";
import curryComponent from "ember-curry-component";
import PostQuotedContent from "discourse/components/post/quoted-content";

export default function quoteControls(element, context) {
  // Extract required properties from context
  const {
    decoratorState,
    helper,
    highlightTerm,
    ignoredUsers,
    owner,
    post,
    streamElement,
  } = context;

  // Find all quote blocks in the element
  const quotes = element.querySelectorAll("aside.quote");

  if (quotes.length === 0) {
    return;
  }

  // Process each quote block
  quotes.forEach((aside, index) => {
    // Extract quote metadata from HTML dataset
    const {
      post: quotedPostRaw,
      topic: topicRaw,
      username,
      expanded,
      full,
    } = aside.dataset;

    if (!quotedPostRaw) {
      return;
    }

    // Parse quoted post/topic IDs
    const quotedTopicId = parseInt(topicRaw || post.topic_id, 10);
    const quotedPostNumber = parseInt(quotedPostRaw, 10);

    // Extract and sanitize quote title
    const titleEl = aside.querySelector(".title");

    let title;
    if (titleEl) {
      // Remove existing quote controls if present
      titleEl.querySelector(".quote-controls")?.remove();
      title = trustHTML(titleEl.innerHTML);
    }

    // Get quote content
    const blockquote = aside.querySelector("blockquote");

    // Build props for PostQuotedContent component
    const componentProps = {
      collapsedContent: trustHTML(blockquote?.innerHTML),
      decoratorState,
      expanded: expanded === "true",
      fullQuote: full === "true",
      highlightTerm,
      id: `quote-id-${quotedTopicId}-${quotedPostNumber}-${index}`,
      ignoredUsers,
      originalQuote: blockquote,
      post,
      quotedPostNotFound: aside.classList.contains("quote-post-not-found"),
      quotedPostNumber,
      quotedTopicId,
      quotedUsername: username,
      streamElement,
      title,
      wrapperElement: aside,
    };

    aside.setAttribute("role", "none");

    // Render the PostQuotedContent component in place of original quote
    helper.renderGlimmer(
      aside,
      curryComponent(PostQuotedContent, componentProps, owner),
      null,
      { append: false }
    );
  });
}
import { schedule } from "@ember/runloop";
import { reveal } from "discourse/lib/highlight-html";
import { highlightQuote, QUOTE_HIGHLIGHT_ID } from "discourse/lib/quote";

export default function (element, { quoteHighlight }) {
  if (!quoteHighlight) {
    return;
  }

  schedule("afterRender", () => {
    const highlights = highlightQuote(element, quoteHighlight.quote);
    const anchor = highlights[0] ?? element.closest(".topic-post") ?? element;
    anchor.id = QUOTE_HIGHLIGHT_ID;

    if (!quoteHighlight.revealed) {
      quoteHighlight.revealed = true;
      reveal(highlights);
    }
  });
}
import highlightSearch from "discourse/lib/highlight-search";

export default function (element, context) {
  const { highlightTerm } = context;

  if (highlightTerm && highlightTerm.length > 2) {
    highlightSearch(element, highlightTerm, { defaultClassName: true });
  }
}
// On WebKit-based browsers, triple clicking on the last paragraph of a post won't stop at the end of the paragraph.
// It looks like the browser is selecting EOL characters, and that causes the selection to leak into the following
// nodes until it finds a non-empty node. This is a workaround to prevent that from happening.
// We insert a div after the last paragraph at the end of the cooked content, containing a <br> element.
// The line break works as a barrier, causing the selection to stop at the correct place.
// To prevent layout shifts this div is styled to be invisible with height 0 and overflow hidden and set aria-hidden
// to true to prevent screen readers from reading it.
export default function (element) {
  const selectionBarrier = document.createElement("div");
  selectionBarrier.classList.add("cooked-selection-barrier");
  selectionBarrier.ariaHidden = "true";
  selectionBarrier.appendChild(document.createElement("br"));
  element.appendChild(selectionBarrier);
}
import { REVEAL_EVENT } from "discourse/lib/highlight-html";

export default function (element, context) {
  restoreOpenedDetails(element, context);
  openDetailsOnReveal(element);
}

function openDetailsOnReveal(element) {
  element.querySelectorAll("details").forEach((details) => {
    details.addEventListener(REVEAL_EVENT, () => (details.open = true));
  });
}

function restoreOpenedDetails(element, context) {
  const details = element.querySelectorAll("details");

  details.forEach((detailElement, index) => {
    const id = tagId(detailElement, context, index);
    const state = context.decoratorState;

    if (state.has(id)) {
      detailElement.open = true;
    }

    detailElement.addEventListener("toggle", (event) => {
      if (event.target.open) {
        state.set(id, true);
      } else {
        state.delete(id);
      }
    });
  });
}

export function tagId(
  element,
  context,
  index,
  { topicId, postId, prefix = "" } = {}
) {
  if (element.id) {
    // If the element already has an ID, we don't want to overwrite it.
    return element.id;
  }

  prefix ||= element.tagName.toLowerCase();
  topicId ||= context.post.topic_id || "";
  postId ||= context.post.post_number;

  const id = `post-cooked-html__${prefix}-${topicId}-${postId}-${index}`;
  element.id = id;

  return id;
}
