  mentionAutocomplete = modifier((textarea) => {
    if (!this.siteSettings.enable_mentions) {
      return;
    }

    const textHandler = new TextareaAutocompleteHandler(textarea);
    const autocomplete = dAutocomplete.setupAutocomplete(
      getOwner(this),
