    return this.args.reviewable?.post_version > 1;
  }

  get editCount() {
    return this.args.reviewable?.post_version - 1;
  }

  get historyClass() {
    return historyHeat(
      this.siteSettings,
      new Date(this.args.reviewable?.post_updated_at)
    );
