  get isScrubbed() {
    return !!this.reviewable?.payload?.scrubbed_by;
  }

  @computed("reviewable.target_user.silenced_till")
  get silencedTill() {
    return this.penaltyDate(this.reviewable?.target_user?.silenced_till);
