export default class extends Controller {
  @service currentUser;
  @service pmTopicTrackingState;
  @service router;
  @controller user;
  @controller userTopicsList;

  @tracked group;
  @tracked tagId;

  @computed("group.name")
  get groupFilter() {
    return this.group?.name;
  }

  set groupFilter(value) {
    set(this, "group.name", value);
  }

  @computed("user.viewingSelf", "currentUser.can_send_private_messages")
  get showNewPM() {
    return (
      this.user?.viewingSelf && this.currentUser?.can_send_private_messages
    );
  }

  @computed("currentParentRouteName")
  get isGroup() {
    return this.currentParentRouteName === "userPrivateMessages.group";
  }

  @computed("user.viewingSelf")
  get viewingSelf() {
    return this.user?.viewingSelf;
  }

  @computed("router.currentRoute.parent.name")
  get currentParentRouteName() {
    return this.router?.currentRoute?.parent?.name;
  }

  @computed("site.can_tag_pms")
  get pmTaggingEnabled() {
    return this.site?.can_tag_pms;
  }

  get bulkSelectHelper() {
    return this.userTopicsList.bulkSelectHelper;
  }

  get messagesDropdownValue() {
    let value;

    const currentURL = this.router.currentURL.toLowerCase();

    for (let i = this.messagesDropdownContent.length - 1; i >= 0; i--) {
      const row = this.messagesDropdownContent[i];

      if (
        currentURL.includes(
          row.id.toLowerCase().replace(this.router.rootURL, "/")
        )
      ) {
        value = row.id;
        break;
      }
    }

    return value;
  }

  get showCount() {
    return this.currentUser.sidebarShowCountOfNewItems;
  }

  @cached
  get messagesDropdownContent() {
    const usernameLower = this.model.username_lower;
    let inboxName = i18n("user.messages.inbox");
    let userMsgsCount = 0;
    userMsgsCount = ["new", "unread"].reduce((count, type) => {
      return (
        count +
        this.pmTopicTrackingState.lookupCount(type, {
          inboxFilter: "user",
        })
      );
    }, userMsgsCount);
    if (userMsgsCount && this.showCount) {
      inboxName = trustHTML(`${inboxName}&nbsp;(${userMsgsCount})`);
    }
    const content = [
      {
        id: this.router.urlFor("userPrivateMessages.user", usernameLower),
        name: inboxName,
        showUnreadIcon: !!userMsgsCount && !this.showCount,
      },
    ];

    this.model.groupsWithMessages.forEach(({ name }) => {
      let groupName = name;
      let groupMsgsCount = 0;
      groupMsgsCount = ["new", "unread"].reduce((count, type) => {
        return (
          count +
          this.pmTopicTrackingState.lookupCount(type, {
            inboxFilter: "group",
            groupName: name,
          })
        );
      }, groupMsgsCount);
      if (groupMsgsCount && this.showCount) {
        groupName = trustHTML(`${name}&nbsp;(${groupMsgsCount})`);
      }
      content.push({
        id: this.router.urlFor(
          "userPrivateMessages.group",
          usernameLower,
          name
        ),
        name: groupName,
        icon: "inbox",
        showUnreadIcon: !!groupMsgsCount && !this.showCount,
      });
    });

    if (this.pmTaggingEnabled) {
      content.push({
        id: this.router.urlFor("userPrivateMessages.tags", usernameLower),
        name: i18n("user.messages.tags"),
        icon: "tags",
      });
    }

    customUserNavMessagesDropdownRows.forEach((row) => {
      content.push({
        id: this.router.urlFor(row.routeName, usernameLower),
        name: row.name,
        icon: row.icon,
      });
    });

    return content;
  }

  @action
  onMessagesDropdownChange(item) {
    return DiscourseURL.routeTo(item);
  }

  @action
  changeGroupNotificationLevel(notificationLevel) {
    this.group?.setNotification(notificationLevel, this.currentUser.id);
  }
}
import EmberObject from "@ember/object";
import { next } from "@ember/runloop";
import cookie, { removeCookie } from "discourse/lib/cookie";
import getURL from "discourse/lib/get-url";
import { i18n } from "discourse-i18n";

const AuthErrors = [
  "admin_not_allowed_from_ip_address",
  "awaiting_activation",
  "awaiting_approval",
  "not_allowed_from_ip_address",
  "requires_invite",
];

const beforeAuthCompleteCallbacks = [];

export function addBeforeAuthCompleteCallback(fn) {
  beforeAuthCompleteCallbacks.push(fn);
}

export function resetBeforeAuthCompleteCallbacks() {
  beforeAuthCompleteCallbacks.length = 0;
}

export default {
  after: "inject-objects",
  initialize(owner) {
    const lastAuthResult = document.getElementById("data-authentication")
      ?.dataset?.authenticationData;

    if (lastAuthResult) {
      const router = owner.lookup("service:router");
      router.one("routeDidChange", () => {
        next(() => {
          const options = JSON.parse(lastAuthResult);

          if (!beforeAuthCompleteCallbacks.every((fn) => fn(options))) {
            return;
          }

          if (router.currentRouteName === "invites.show") {
            owner
              .lookup("controller:invites.show")
              .authenticationComplete(options);
          } else {
            const siteSettings = owner.lookup("service:site-settings");

            const loginError = (flash, properties, callback) => {
              const props = {
                flash,
                flashType: "error",
                awaitingApproval: options.awaiting_approval,
                ...properties,
              };

              router.transitionTo("login").then(() => {
                const controller = owner.lookup("controller:login");
                controller.setProperties(props);
              });

              next(() => callback?.());
            };

            const error = AuthErrors.find((name) => options[name]);
            if (error) {
              return loginError(i18n(`login.${error}`));
            }

            if (options.suspended) {
              return loginError(options.suspended_message);
            }

            if (options.omniauth_disallow_totp) {
              return loginError(
                i18n("login.omniauth_disallow_totp"),
                {
                  loginName: options.email,
                  showLoginButtons: false,
                },
                () => document.getElementById("login-account-password").focus()
              );
            }

            if (options.authenticated) {
              const destinationUrl =
                cookie("destination_url") || options.destination_url;
              if (destinationUrl) {
                removeCookie("destination_url");
                window.location.href = destinationUrl;
              } else if (window.location.pathname === getURL("/login")) {
                window.location = getURL("/");
              } else {
                window.location.reload();
              }
              return;
            }

            next(() => {
              // A bare email prefill (no external auth provider) feeds the
              // email+code signup flow when it's enabled
              if (
                siteSettings.enable_local_logins_via_code &&
                options.email &&
                !options.auth_provider
              ) {
                router.transitionTo("signup").then(() => {
                  owner.lookup("controller:signup").accountEmail =
                    options.email;
                });
                return;
              }

              const site = owner.lookup("service:site");
              const hasRequiredName =
                !site.full_name_required_for_signup ||
                options.name_from_provider;

              const props = {
                accountEmail: options.email,
                accountUsername: options.username,
                accountName: options.name,
                authOptions: EmberObject.create(options),
                skipConfirmation:
                  siteSettings.auth_skip_create_confirm &&
                  options.username &&
                  hasRequiredName,
              };

              router.transitionTo("signup").then(() => {
                const controller = owner.lookup("controller:signup");
                controller.setProperties(props);
                controller.handleSkipConfirmation();
              });
            });
          }
        });
      });
    }
  },
};
