import { Promise } from "rsvp";
import KeyValueStore from "discourse/lib/key-value-store";
import discourseLater from "discourse/lib/later";
import DiscourseURL from "discourse/lib/url";
import { formatUsername } from "discourse/lib/utilities";
import Site from "discourse/models/site";
import User from "discourse/models/user";
import { i18n } from "discourse-i18n";

let primaryTab = false;
let liveEnabled = false;
let havePermission = null;
let mbClientId = "xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx";

const focusTrackerKey = "focus-tracker";
const context = "discourse_desktop_notifications_";
const keyValueStore = new KeyValueStore(context);

let desktopNotificationHandlers = [];
export function registerDesktopNotificationHandler(handler) {
  desktopNotificationHandlers.push(handler);
}
export function clearDesktopNotificationHandlers() {
  desktopNotificationHandlers = [];
}

// Called from an initializer
function init(messageBus) {
  liveEnabled = false;
  mbClientId = messageBus.clientId;

  if (!User.current()) {
    return;
  }

  try {
    keyValueStore.getItem(focusTrackerKey);
  } catch {
    // eslint-disable-next-line no-console
    console.info(
      "Discourse desktop notifications are disabled - localStorage denied."
    );
    return;
  }

  if (!("Notification" in window)) {
    // eslint-disable-next-line no-console
    console.info(
      "Discourse desktop notifications are disabled - not supported by browser"
    );
    return;
  }

  try {
    if (Notification.permission === "granted") {
      havePermission = true;
    } else if (Notification.permission === "denied") {
      havePermission = false;
      return;
    }
  } catch (e) {
    // eslint-disable-next-line no-console
    console.warn(
      "Notification is defined on window but is not responding correctly " + e
    );
  }

  liveEnabled = true;
  try {
    // Preliminary checks passed, continue with setup
    setupNotifications();
  } catch (e) {
    // eslint-disable-next-line no-console
    console.error(e);
  }
}

function confirmNotification(siteSettings) {
  const notification = new Notification(
    i18n("notifications.popup.confirm_title", {
      site_title: siteSettings.title,
    }),
    {
      body: i18n("notifications.popup.confirm_body"),
      icon: siteSettings.site_logo_small_url || siteSettings.site_logo_url,
      tag: "confirm-subscription",
    }
  );

  const clickEventHandler = () => notification.close();

  notification.addEventListener("click", clickEventHandler);
  discourseLater(() => {
    notification.close();
    notification.removeEventListener("click", clickEventHandler);
  }, 10 * 1000);
}

// This function is only called if permission was granted
function setupNotifications() {
  window.addEventListener("storage", function (e) {
    // note: This event only fires when other tabs setItem()
    const key = e.key;
    if (key !== `${context}${focusTrackerKey}`) {
      return true;
    }
    primaryTab = false;
  });

  window.addEventListener("focus", function () {
    if (!primaryTab) {
      primaryTab = true;
      keyValueStore.setItem(focusTrackerKey, mbClientId);
    }
  });

  if (
    document &&
    typeof document.hidden !== "undefined" &&
    document["hidden"]
  ) {
    primaryTab = false;
  } else {
    primaryTab = true;
    keyValueStore.setItem(focusTrackerKey, mbClientId);
  }
}

function canUserReceiveNotifications(user) {
  if (!primaryTab) {
    return false;
  }

  if (user.isInDoNotDisturb()) {
    return false;
  }

  if (keyValueStore.getItem("notifications-disabled") === "disabled") {
    return false;
  }

  return true;
}

// Call-in point from message bus
async function onNotification(data, siteSettings, user, appEvents) {
  // handlers run first: the permission request below can reject, or stay
  // pending until a background tab is shown again
  desktopNotificationHandlers.forEach((handler) =>
    handler(data, siteSettings, user)
  );

  const showNotifications = canUserReceiveNotifications(user) && liveEnabled;

  if (showNotifications) {
    const notificationTitle =
      data.translated_title ||
      i18n(i18nKey(data.notification_type), {
        site_title: siteSettings.title,
        topic: data.topic_title,
        username: formatUsername(data.username),
        group_name: data.group_name,
      });

    const notificationIcon =
      siteSettings.site_logo_small_url || siteSettings.site_logo_url;
    const notificationTag =
      "discourse-notification-" +
      siteSettings.title +
      "-" +
      (data.topic_id || 0);

    await requestPermission();

    const notification = new Notification(notificationTitle, {
      body: data.excerpt,
      icon: notificationIcon,
      tag: notificationTag,
    });

    notification.addEventListener(
      "click",
      () => {
        DiscourseURL.routeTo(data.post_url);
        appEvents.trigger("desktop-notification-opened", {
          url: data.post_url,
        });
        notification.close();
      },
      { once: true }
    );
  }
}

// Utility function
// Wraps Notification.requestPermission in a Promise
function requestPermission() {
  if (havePermission === true) {
    return Promise.resolve();
  } else if (havePermission === false) {
    return Promise.reject();
  } else {
    return new Promise(function (resolve, reject) {
      Notification.requestPermission(function (status) {
        if (status === "granted") {
          resolve();
        } else {
          reject();
        }
      });
    });
  }
}

function i18nKey(notification_type) {
  return (
    "notifications.popup." +
    Site.current().get("notificationLookup")[notification_type]
  );
}

function alertChannel(user) {
  return `/notification-alert/${user.get("id")}`;
}

function unsubscribe(bus, user) {
  bus.unsubscribe(alertChannel(user));
}

function disable() {
  keyValueStore.setItem("notifications-disabled", "disabled");
}

export {
  context,
  init,
  onNotification,
  unsubscribe,
  alertChannel,
  confirmNotification,
  disable,
  canUserReceiveNotifications,
};
import Component from "@glimmer/component";
import { action } from "@ember/object";
import { service } from "@ember/service";
import Form from "discourse/components/form";
import { addToCalendar } from "discourse/lib/download-calendar";
import DButton from "discourse/ui-kit/d-button";
import DModal from "discourse/ui-kit/d-modal";
import DModalCancel from "discourse/ui-kit/d-modal-cancel";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

export default class DownloadCalendar extends Component {
  @service currentUser;

  formData = { calendar: "ics", remember: false };
  #formApi;

  @action
  handleSubmit(data) {
    if (data.remember) {
      this.currentUser.set("user_option.default_calendar", data.calendar);
      this.currentUser.save(["default_calendar"]);
    }

    addToCalendar(
      data.calendar,
      this.args.model.calendar.title,
      this.args.model.calendar.dates,
      {
        rrule: this.args.model.calendar.rrule,
        location: this.args.model.calendar.location,
        details: this.args.model.calendar.details,
        timezone: this.args.model.calendar.timezone,
      }
    );
    this.args.closeModal();
  }

  @action
  registerFormApi(api) {
    this.#formApi = api;
  }

  @action
  submit() {
    this.#formApi.submit();
  }

  <template>
    <DModal
      class="download-calendar-modal"
      @closeModal={{@closeModal}}
      @title={{i18n "download_calendar.title"}}
    >
      <:body>
        <Form
          @data={{this.formData}}
          @onRegisterApi={{this.registerFormApi}}
          @onSubmit={{this.handleSubmit}}
          as |form|
        >
          <form.Field
            @format="full"
            @name="calendar"
            @title={{i18n "download_calendar.calendar"}}
            @type="radio-group"
            @validation="required"
            as |field|
          >
            <field.Control as |radioGroup|>
              <radioGroup.Radio @value="ics" as |radio|>
                <radio.Title>
                  {{dIcon "download"}}
                  {{i18n "download_calendar.save_ics"}}
                </radio.Title>
              </radioGroup.Radio>
              <radioGroup.Radio @value="google" as |radio|>
                <radio.Title>
                  {{dIcon "fab-google"}}
                  {{i18n "download_calendar.save_google"}}
                </radio.Title>
              </radioGroup.Radio>
              <radioGroup.Radio @value="outlook" as |radio|>
                <radio.Title>
                  {{dIcon "fab-microsoft"}}
                  {{i18n "download_calendar.save_outlook"}}
                </radio.Title>
              </radioGroup.Radio>
              <radioGroup.Radio @value="apple" as |radio|>
                <radio.Title>
                  {{dIcon "fab-apple"}}
                  {{i18n "download_calendar.save_apple"}}
                </radio.Title>
              </radioGroup.Radio>
            </field.Control>
          </form.Field>

          {{#if this.currentUser}}
            <form.Field
              @format="full"
              @name="remember"
              @title={{i18n "download_calendar.remember"}}
              @type="checkbox"
              as |field|
            >
              <field.Control>
                {{i18n "download_calendar.remember_explanation"}}
              </field.Control>
            </form.Field>
          {{/if}}
        </Form>
      </:body>
      <:footer>
        <DButton
          class="btn-primary"
          @action={{this.submit}}
          @label="download_calendar.add_to_calendar"
        />
        <DModalCancel @close={{@closeModal}} />
      </:footer>
    </DModal>
  </template>
}
import downloadCalendarModal from "discourse/components/modal/download-calendar";
import { getOwnerWithFallback } from "discourse/lib/get-owner";
import getURL from "discourse/lib/get-url";
import User from "discourse/models/user";
import { i18n } from "discourse-i18n";

export function downloadCalendar(title, dates, options = {}) {
  const currentUser = User.current();

  const formattedDates = formatDates(dates);
  title = (title || i18n("download_calendar.default_title")).trim();

  const defaultCalendar = currentUser?.user_option.default_calendar;

  if (["ics", "google", "outlook", "apple"].includes(defaultCalendar)) {
    addToCalendar(defaultCalendar, title, formattedDates, options);
  } else {
    _displayModal(title, formattedDates, options);
  }
}

export function addToCalendar(calendar, title, dates, options = {}) {
  switch (calendar) {
    case "google":
      downloadGoogle(title, dates, options);
      break;
    case "outlook":
      downloadOutlook(title, dates, options);
      break;
    case "apple":
    case "ics":
      downloadIcs(title, dates, options);
      break;
  }
}

export function downloadIcs(title, dates, options = {}) {
  const REMOVE_FILE_AFTER = 20_000;
  const file = new File([generateIcsData(title, dates, options)], {
    type: "text/plain",
  });

  const a = document.createElement("a");
  document.body.appendChild(a);
  a.style = "display: none";
  a.href = window.URL.createObjectURL(file);
  a.download = `${title.toLowerCase().replace(/[^\w]/g, "-")}.ics`;
  a.click();
  setTimeout(() => window.URL.revokeObjectURL(file), REMOVE_FILE_AFTER);
}

export function downloadGoogle(title, dates, options = {}) {
  const parsedRrule = _parseRRule(options.rrule);

  dates.forEach((date) => {
    const link = new URL("https://www.google.com/calendar/event");
    link.searchParams.append("action", "TEMPLATE");
    link.searchParams.append("text", title);

    let dateRange;
    if (date.allDay) {
      const { startDate, endDate } = _allDayMoments(date);
      dateRange = `${startDate.format("YYYYMMDD")}/${endDate.format("YYYYMMDD")}`;
    } else {
      dateRange = `${_formatDateForGoogleApi(date.startsAt, date.timezone)}/${_formatDateForGoogleApi(
        date.endsAt,
        date.timezone
      )}`;
    }
    link.searchParams.append("dates", dateRange);

    if (parsedRrule && _hasFreq(parsedRrule)) {
      const rrule = date.allDay ? _dateOnlyUntil(parsedRrule) : parsedRrule;
      link.searchParams.append("recur", `RRULE:${rrule}`);
    }

    if (options.location) {
      link.searchParams.append("location", options.location);
    }

    if (options.details) {
      link.searchParams.append("details", options.details);
    }

    window.open(getURL(link.href).trim(), "_blank", "noopener", "noreferrer");
  });
}

export function downloadOutlook(title, dates, options = {}) {
  const parsedRrule = _parseRRule(options.rrule);

  if (parsedRrule && _hasFreq(parsedRrule)) {
    downloadIcs(title, dates, options);
    return;
  }

  dates.forEach((date) => {
    const link = new URL(
      "https://outlook.live.com/calendar/0/deeplink/compose"
    );
    link.searchParams.append("path", "/calendar/action/compose");
    link.searchParams.append("rru", "addevent");
    link.searchParams.append("subject", title);

    if (date.allDay) {
      const { startDate, endDate } = _allDayMoments(date);
      link.searchParams.append("startdt", startDate.format("YYYY-MM-DD"));
      link.searchParams.append("enddt", endDate.format("YYYY-MM-DD"));
      link.searchParams.append("allday", "true");
    } else {
      link.searchParams.append(
        "startdt",
        _formatDateForOutlookApi(date.startsAt, date.timezone)
      );
      link.searchParams.append(
        "enddt",
        _formatDateForOutlookApi(date.endsAt, date.timezone)
      );
      link.searchParams.append("allday", "false");
    }

    if (options.location) {
      link.searchParams.append("location", options.location);
    }

    if (options.details) {
      link.searchParams.append("body", options.details);
    }

    window.open(getURL(link.href).trim(), "_blank", "noopener", "noreferrer");
  });
}

export function formatDates(dates) {
  return dates.map((date) => {
    const formatted = {
      startsAt: date.startsAt,
      endsAt: date.endsAt
        ? date.endsAt
        : date.allDay
          ? null
          : moment.utc(date.startsAt).add(1, "hours").format(),
    };

    // Preserve timezone if present
    if (date.timezone) {
      formatted.timezone = date.timezone;
    }

    if (date.allDay) {
      formatted.allDay = true;
    }

    return formatted;
  });
}

/**
 * Escape special characters in ICS field values per RFC 5545
 * - Backslashes must be escaped as \\
 * - Newlines (CR, LF, CRLF) must be encoded as \n
 * - Semicolons must be escaped as \;
 * - Commas must be escaped as \,
 *
 * @param {string} value - The value to escape
 * @returns {string} - The escaped value
 */
function _escapeIcsValue(value) {
  return value
    .replace(/\\/g, "\\\\")
    .replace(/\r\n|\r|\n/g, "\\n")
    .replace(/;/g, "\\;")
    .replace(/,/g, "\\,");
}

/**
 * Fold a line to comply with RFC 5545 line length limit (75 octets)
 * Continuation lines start with a space
 *
 * @param {string} line - The line to fold
 * @returns {string} - The folded line
 */
function _foldLine(line) {
  const maxLength = 75;
  if (line.length <= maxLength) {
    return line;
  }

  const result = [];
  let currentLine = line;

  while (currentLine.length > maxLength) {
    result.push(currentLine.substring(0, maxLength));
    currentLine = " " + currentLine.substring(maxLength);
  }
  result.push(currentLine);

  return result.join("\r\n");
}

/**
 * Parse and extract the RRULE line from a string that may contain
 * both DTSTART and RRULE (legacy format)
 *
 * @param {string} rruleString - The RRULE string (may include DTSTART)
 * @returns {string|null} - The extracted RRULE value or null if invalid
 */
function _parseRRule(rruleString) {
  if (!rruleString) {
    return null;
  }

  const lines = rruleString.split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith("RRULE:")) {
      return trimmed.substring(6);
    } else if (/^FREQ=/i.test(trimmed)) {
      return trimmed;
    }
  }

  if (/^FREQ=/i.test(rruleString.trim())) {
    return rruleString.trim();
  }

  return null;
}

/**
 * Check if an RRULE string contains the required FREQ parameter
 *
 * @param {string} rrule - The RRULE string to check
 * @returns {boolean} - True if FREQ is present
 */
function _hasFreq(rrule) {
  return /FREQ=/i.test(rrule);
}

function _dateOnlyUntil(rrule) {
  return rrule.replace(/(UNTIL=\d{8})T\d{6}Z?/i, "$1");
}

function _allDayMoments(date) {
  const startDate = moment(date.startsAt, "YYYY-MM-DD");
  const endDate = (
    date.endsAt ? moment(date.endsAt, "YYYY-MM-DD") : startDate.clone()
  ).add(1, "day");
  return { startDate, endDate };
}

const ICAL_WEEKDAYS = ["SU", "MO", "TU", "WE", "TH", "FR", "SA"];

function _formatIcsUtcOffset(offsetMinutes) {
  const totalSeconds = Math.round(offsetMinutes * 60);
  const sign = totalSeconds < 0 ? "-" : "+";
  const absoluteSeconds = Math.abs(totalSeconds);
  const hours = Math.floor(absoluteSeconds / 3600);
  const minutes = Math.floor((absoluteSeconds % 3600) / 60);
  const seconds = absoluteSeconds % 60;

  return (
    sign +
    String(hours).padStart(2, "0") +
    String(minutes).padStart(2, "0") +
    (seconds ? String(seconds).padStart(2, "0") : "")
  );
}

function _vTimezoneTransition(zone, index) {
  const transitionAt = zone.untils[index];
  const offsetFrom = -zone.offsets[index];
  const offsetTo = -zone.offsets[index + 1];
  const localStart = moment.utc(transitionAt).utcOffset(offsetFrom);
  const day = localStart.date();
  const ordinal = day + 7 > localStart.daysInMonth() ? -1 : Math.ceil(day / 7);

  return {
    localStart: localStart.format("YYYYMMDDTHHmmss"),
    month: localStart.month() + 1,
    byDay: `${ordinal}${ICAL_WEEKDAYS[localStart.day()]}`,
    offsetFrom,
    offsetTo,
    name: zone.abbrs[index + 1],
  };
}

function _sameVTimezoneRule(a, b) {
  return (
    a.month === b.month &&
    a.byDay === b.byDay &&
    a.localStart.slice(8) === b.localStart.slice(8) &&
    a.offsetFrom === b.offsetFrom &&
    a.offsetTo === b.offsetTo
  );
}

function _renderVTimezoneObservance(observance) {
  const type =
    observance.offsetTo > observance.offsetFrom ? "DAYLIGHT" : "STANDARD";
  const lines = [
    `BEGIN:${type}`,
    `DTSTART:${observance.localStart}`,
    `RRULE:FREQ=YEARLY;BYMONTH=${observance.month};BYDAY=${observance.byDay}`,
    `TZOFFSETFROM:${_formatIcsUtcOffset(observance.offsetFrom)}`,
    `TZOFFSETTO:${_formatIcsUtcOffset(observance.offsetTo)}`,
  ];

  if (observance.name) {
    lines.push(`TZNAME:${_escapeIcsValue(observance.name)}`);
  }

  lines.push(`END:${type}`);

  return lines.map(_foldLine).join("\r\n") + "\r\n";
}

function _fixedVTimezone(timezone, referenceMs) {
  const reference = moment.tz(referenceMs, timezone);
  const offset = reference.utcOffset();
  const start = reference
    .clone()
    .subtract(1, "year")
    .startOf("year")
    .format("YYYYMMDDTHHmmss");

  return (
    "BEGIN:VTIMEZONE\r\n" +
    _foldLine(`TZID:${timezone}`) +
    "\r\n" +
    "BEGIN:STANDARD\r\n" +
    `DTSTART:${start}\r\n` +
    `TZOFFSETFROM:${_formatIcsUtcOffset(offset)}\r\n` +
    `TZOFFSETTO:${_formatIcsUtcOffset(offset)}\r\n` +
    _foldLine(`TZNAME:${_escapeIcsValue(reference.zoneAbbr())}`) +
    "\r\n" +
    "END:STANDARD\r\n" +
    "END:VTIMEZONE\r\n"
  );
}

function _generateVTimezone(timezone, referenceMs) {
  const zone = moment.tz.zone(timezone);

  if (!zone) {
    return "";
  }

  let previousIndex = -1;
  let nextIndex = -1;

  for (let i = 0; i < zone.untils.length - 1; i++) {
    const transitionAt = zone.untils[i];

    if (!Number.isFinite(transitionAt)) {
      break;
    }

    if (transitionAt <= referenceMs) {
      previousIndex = i;
    } else {
      nextIndex = i;
      break;
    }
  }

  if (previousIndex === -1 || nextIndex === -1) {
    return _fixedVTimezone(timezone, referenceMs);
  }

  const previous = _vTimezoneTransition(zone, previousIndex);
  const next = _vTimezoneTransition(zone, nextIndex);
  const followingPreviousIndex = previousIndex + 2;
  const followingNextIndex = nextIndex + 2;

  // A current seasonal pair reverses the same two UTC offsets and repeats
  // the same calendar rules in the following cycle. Otherwise, use the
  // current fixed offset rather than inventing an open-ended yearly rule.
  if (
    previous.offsetFrom !== next.offsetTo ||
    previous.offsetTo !== next.offsetFrom ||
    followingNextIndex >= zone.untils.length - 1
  ) {
    return _fixedVTimezone(timezone, referenceMs);
  }

  const followingPrevious = _vTimezoneTransition(zone, followingPreviousIndex);
  const followingNext = _vTimezoneTransition(zone, followingNextIndex);

  if (
    !_sameVTimezoneRule(previous, followingPrevious) ||
    !_sameVTimezoneRule(next, followingNext)
  ) {
    return _fixedVTimezone(timezone, referenceMs);
  }

  return (
    "BEGIN:VTIMEZONE\r\n" +
    _foldLine(`TZID:${timezone}`) +
    "\r\n" +
    _renderVTimezoneObservance(previous) +
    _renderVTimezoneObservance(next) +
    "END:VTIMEZONE\r\n"
  );
}

/**
 * Generate ICS calendar data for the given dates
 *
 * @param {string} title - Event title
 * @param {Array<{ startsAt: string, endsAt?: string | null, timezone?: string, allDay?: boolean }>} dates - Array of date objects with startsAt, endsAt, optional timezone, and optional allDay (date-only event)
 * @param {{ rrule?: string | null, location?: string | null, details?: string | null, timezone?: string | null }} [options] - Optional parameters (rrule, location, details, timezone)
 * @returns {string} - ICS formatted calendar data
 */
export function generateIcsData(title, dates, options = {}) {
  let data = "BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Discourse//EN\r\n";
  const parsedRrule = _parseRRule(options.rrule);

  const timezoneStarts = new Map();

  for (const date of dates) {
    if (date.allDay) {
      continue;
    }

    const timezone = date.timezone || options.timezone;

    if (!timezone || !moment.tz.zone(timezone)) {
      continue;
    }

    const startsAt = moment.tz(date.startsAt, timezone);

    if (!startsAt.isValid()) {
      continue;
    }

    const existing = timezoneStarts.get(timezone);

    if (existing === undefined || startsAt.valueOf() < existing) {
      timezoneStarts.set(timezone, startsAt.valueOf());
    }
  }

  for (const [timezone, startsAt] of timezoneStarts) {
    data += _generateVTimezone(timezone, startsAt);
  }

  dates.forEach((date) => {
    let rrule = parsedRrule;

    let startDate, endDate, dtStartValue, dtEndValue;

    if (date.allDay) {
      if (rrule) {
        rrule = _dateOnlyUntil(rrule);
      }
      ({ startDate, endDate } = _allDayMoments(date));
      dtStartValue = `DTSTART;VALUE=DATE:${startDate.format("YYYYMMDD")}`;
      dtEndValue = `DTEND;VALUE=DATE:${endDate.format("YYYYMMDD")}`;
    } else {
      const timezone = date.timezone || options.timezone;
      startDate = timezone
        ? moment.tz(date.startsAt, timezone)
        : moment(date.startsAt);
      endDate = timezone
        ? moment.tz(date.endsAt, timezone)
        : moment(date.endsAt);

      dtStartValue = timezone
        ? `DTSTART;TZID=${timezone}:${startDate.format("YYYYMMDDTHHmmss")}`
        : `DTSTART:${startDate.utc().format("YYYYMMDDTHHmmss")}Z`;
      dtEndValue = timezone
        ? `DTEND;TZID=${timezone}:${endDate.format("YYYYMMDDTHHmmss")}`
        : `DTEND:${endDate.utc().format("YYYYMMDDTHHmmss")}Z`;
    }

