  activeSources(linksSetting = "", privateContext = false) {
    const sources = linksSetting
      .split("|")
      .concat(_customSharingIds)
      .map((s) => _sources[s])
      .filter((item) => item != null);

    return privateContext
      ? sources.filter((s) => s.showInPrivateContext)
      : sources;
  },

  _reset() {
    _sources = {};
    _customSharingIds = [];
  },
