              />
            </div>

            <dl class="create-invite-with-roles-modal__summary-rows">
              {{#each this.summaryRows as |row|}}
                <div class="create-invite-with-roles-modal__summary-row">
                  <dt>{{row.label}}</dt>
                  <dd>{{row.value}}</dd>
                </div>
              {{/each}}
            </dl>
          </div>
        {{else}}
          <div class="create-invite-with-roles-modal__email-sent">
            <p>
              {{i18n
                "user.invited.invite_roles.email_sent.body"
                email=this.invite.email
              }}
            </p>
          </div>
        {{/if}}
      </:body>
      <:footer>
        {{#if (eq this.screen "form")}}
          <DButton
            class="btn-primary save-invite"
            @action={{this.submitForm}}
            @disabled={{this.submitDisabled}}
            @icon={{if
              this.inviteCreated
              "check"
              (if this.isEmailDelivery "paper-plane" "copy")
            }}
            @translatedLabel={{if
              this.inviteCreated
              (i18n "user.invited.invite_roles.update")
              (if
                this.isEmailDelivery
                (i18n "user.invited.invite_roles.create_and_send")
                (i18n "user.invited.invite_roles.create_and_copy")
              )
            }}
          />
          <DButton
            class="btn-transparent cancel-button"
            disabled={{this.submitDisabled}}
            @action={{this.cancel}}
            @label="user.invited.invite.cancel"
          />
          <AdvancedModeToggle
            disabled={{this.submitDisabled}}
            @active={{this.showAdvanced}}
            @onToggle={{this.toggleAdvanced}}
          />
        {{else if (eq this.screen "summary")}}
          <DButton
            class="btn-default edit-invite"
            @action={{this.editInvite}}
            @translatedLabel={{i18n "user.invited.invite_roles.summary.edit"}}
          />
          <LinkTo
            class="btn btn-default view-invites"
            @models={{array this.currentUser.username_lower "pending"}}
            @route="userInvited.show"
          >
            {{i18n "user.invited.invite_roles.summary.view_invites"}}
          </LinkTo>
        {{else}}
          <LinkTo
            class="btn btn-default view-invites"
            @models={{array this.currentUser.username_lower "pending"}}
            @route="userInvited.show"
          >
            {{i18n "user.invited.invite_roles.summary.view_invites"}}
          </LinkTo>
        {{/if}}
      </:footer>
    </DModal>
  </template>
}

const ExpiryField = <template>
  {{#if @created}}
    <@form.Field
      @format="full"
      @name="expiresAt"
      @title={{i18n "user.invited.invite.expires_at"}}
      @type="custom"
      @validation="required"
      as |field|
    >
      <field.Control>
        <DFutureDateInput
          @clearable={{true}}
          @input={{field.value}}
          @noRelativeOptions={{true}}
          @onChangeInput={{field.set}}
        />
      </field.Control>
    </@form.Field>
  {{else}}
    <@form.Field
      @format="full"
      @name="expiresAfterDays"
      @title={{i18n "user.invited.invite.expires_after"}}
      @type="select"
      @validation="required"
      as |field|
    >
      <field.Control as |select|>
        {{#each @options as |option|}}
          <select.Option @value={{option.value}}>{{option.text}}</select.Option>
        {{/each}}
      </field.Control>
    </@form.Field>
  {{/if}}
</template>;

class ShareOrCopyInviteLink extends Component {
  @service capabilities;

  @action
  async nativeShare() {
    await nativeShare(this.capabilities, { url: this.args.invite.link });
  }

  <template>
    <input
      class="invite-link"
      name="invite-link"
      readonly={{true}}
      type="text"
      value={{@invite.link}}
    />
    {{#if (canNativeShare this.capabilities)}}
      <DButton
        class="btn-primary"
        @action={{this.nativeShare}}
        @icon="share"
        @translatedLabel={{i18n "user.invited.invite.share_link"}}
      />
    {{else}}
      <DCopyButton
        @isCopied={{@isCopied}}
        @selector="input.invite-link"
        @translatedLabel={{i18n "user.invited.invite.copy_link"}}
        @translatedLabelAfterCopy={{i18n "user.invited.invite.link_copied"}}
      />
    {{/if}}
  </template>
}
import { getOwner } from "@ember/owner";
import CreateInvite from "discourse/components/modal/create-invite";
import CreateInviteWithRoles from "discourse/components/modal/create-invite-with-roles";

/**
 * Opens the invite creation modal, selecting the redesigned role-based
 * variant when the `enable_invite_modal_with_roles` upcoming change is enabled.
 *
 * @param {object} context - any owned object (component, route, controller)
 * @param {{ model?: { invites?: import("discourse/models/invite").default[], editing?: boolean, invite?: import("discourse/models/invite").default, groupIds?: number[], inviteToTopic?: boolean, topics?: import("discourse/models/topic").default[], topicId?: number, topicTitle?: string, defaultRole?: string } }} [opts] - options forwarded to `modal.show`, e.g. `{ model }`
 * @returns {Promise<unknown>} the modal promise from `modal.show`
 */
export function showCreateInviteModal(context, opts = {}) {
  const owner = getOwner(context);
  const modal = owner.lookup("service:modal");
  const siteSettings = owner.lookup("service:site-settings");

  const component = siteSettings.enable_invite_modal_with_roles
    ? CreateInviteWithRoles
    : CreateInvite;

  return modal.show(component, opts);
}
