import PreloadStore from "discourse/lib/preload-store";

class BannerInit {
  @service site;
  @service messageBus;

  constructor(owner) {
    setOwner(this, owner);

    const banner = EmberObject.create(PreloadStore.get("banner") || {});
    this.site.set("banner", banner);

    this.messageBus.subscribe("/site/banner", this.onMessage);
  }

  teardown() {
    this.messageBus.unsubscribe("/site/banner", this.onMessage);
  }

  @bind
  onMessage(data) {
    if (data) {
      this.site.set("banner", EmberObject.create(data));
    } else {
      this.site.set("banner", null);
    }
  }
}

export default {
  after: "message-bus",

  initialize(owner) {
    this.instance = new BannerInit(owner);
  },

  teardown() {
    this.instance.teardown();
    this.instance = null;
  },
};
export default {
  initialize(owner) {
    owner.lookup("service:client-error-handler");
    owner.lookup("service:deprecation-warning-handler");
  },
};
import { scheduleOnce } from "@ember/runloop";

let focusedBeforeTransition;

function _clean(transition) {
  if (window.MiniProfiler && transition.from) {
    window.MiniProfiler.pageTransition();
  }

  // Close some elements that may be open
  document.querySelectorAll("header ul.icons li").forEach((element) => {
    element.classList.remove("active");
  });

  document.querySelectorAll(`[data-toggle="dropdown"]`).forEach((element) => {
    element.parentElement.classList.remove("open");
  });

  // Close PhotoSwipe
  window.pswp?.close();

  // Remove focus from the link that triggered navigation, but keep focus the
  // new page set deliberately (e.g. on a linked post)
  const { activeElement } = document;
  if (
    activeElement === focusedBeforeTransition &&
    !activeElement.classList.contains("no-blur")
  ) {
    activeElement.blur();
  }
  focusedBeforeTransition = null;

  this.lookup("route:application").send("closeModal");

  this.lookup("service:app-events").trigger("dom:clean");
  this.lookup("service:document-title").updateContextCount(0);
}

export default {
  after: "inject-objects",

  initialize(owner) {
    const router = owner.lookup("service:router");

    router.on("routeWillChange", () => {
      focusedBeforeTransition = document.activeElement;
    });

    router.on("routeDidChange", (transition) => {
      if (transition.isAborted) {
        return;
      }

      scheduleOnce("afterRender", owner, _clean, transition);
    });
  },
};
import interceptClick from "discourse/lib/intercept-click";
import DiscourseURL from "discourse/lib/url";

export default {
  initialize(owner) {
    this.selector = owner.rootElement;
    document
      .querySelector(this.selector)
      .addEventListener("click", interceptClick);
    window.addEventListener("hashchange", this.hashChanged);
  },

  hashChanged() {
    DiscourseURL.routeTo(document.location.hash);
  },

  teardown() {
    document
      .querySelector(this.selector)
      .removeEventListener("click", interceptClick);
    window.removeEventListener("hashchange", this.hashChanged);
  },
};
