    const darkId = theme.dark_color_scheme_id;
    const dark = darkId && pairs.find((pair) => pair.dark?.id === darkId)?.key;
    const light = pairs.find(
      (pair) =>
        theme.color_scheme_id && pair.light?.id === theme.color_scheme_id
    )?.key;

