    let pending = false;
    try {
      pending = sessionStorage.getItem(SESSION_KEY_PENDING) === "1";
    } catch {}

    if (!pending) {
      return;
    }

    const currentUser = owner.lookup("service:current-user");
    if (!currentUser) {
      return;
