// Subscribe to "logout" change events via the Message Bus
class LogoutInit {
  @service messageBus;
  @service dialog;
  @service currentUser;

  constructor(owner) {
    setOwner(this, owner);

    if (this.currentUser) {
      this.messageBus.subscribe(
        `/logout/${this.currentUser.id}`,
        this.onMessage
      );
    }
  }

