    const header = document.querySelector(".d-header-wrap .d-header");
    if (header) {
      return window.getComputedStyle(header)?.backgroundColor;
    }
  },

  retry() {
    if (this.retryCount < 2) {
      this.retryCount++;
      this.updateAppBackground(1000);
    }
  },

  teardown() {
    if (this.isAppWebview) {
