in a placeholder component. It should not be used for any other case.
*/

import ApplicationInstance from "@ember/application/instance";
import { setOwner } from "@ember/owner";
import { service } from "@ember/service";
import { getLoadedFaker } from "discourse/lib/load-faker";
import { excerpt } from "./text.js";

let sequence = 1;

export function incrementSequence() {
  return sequence++;
}

export default class CoreFabricators {
  @service store;

  constructor(owner) {
    if (owner && !(owner instanceof ApplicationInstance)) {
      throw new Error(
        "First argument of CoreFabricators constructor must be the owning ApplicationInstance"
      );
    }

    setOwner(this, owner);
  }

  post(args = {}) {
    return this.store.createRecord("post", {
      id: args.id || incrementSequence(),
      topic: args.topic || this.topic(),
    });
  }

  tag(args = {}) {
    return this.store.createRecord("tag", {
      id: args.id || incrementSequence(),
      name: args.name ?? getLoadedFaker().faker.word.noun(),
      description: args.description ?? getLoadedFaker().faker.lorem.sentence(),
      count: args.count ?? 0,
      pm_count: args.pm_count ?? 0,
    });
  }

  topic(args = {}) {
    const id = args.id || incrementSequence();
    return this.store.createRecord("topic", {
      id,
      created_at: args.created_at || moment().subtract(2, "day"),
      updated_at: args.updated_at || moment().subtract(1, "day"),
      slug: args.slug || getLoadedFaker().faker.lorem.slug(),
      title: args.title || getLoadedFaker().faker.commerce.productName(),
      tags: args.tags || [],
      category: args.category,
      image_url: args.image_url ?? "/images/bubbles-bg.png",
      excerpt:
        args.excerpt ?? excerpt(getLoadedFaker().faker.lorem.sentences(5), 100),
    });
  }

  category(args = {}) {
    const name = args.name || getLoadedFaker().faker.commerce.product();

    return this.store.createRecord("category", {
      id: args.id || incrementSequence(),
      color: args.color || getLoadedFaker().faker.color.rgb({ prefix: "" }),
      read_restricted: args.read_restricted ?? false,
      name,
      slug: args.slug || name.toLowerCase(),
    });
  }

  user(args = {}) {
    return this.store.createRecord("user", {
      id: args.id || incrementSequence(),
      username: args.username || getLoadedFaker().faker.internet.domainWord(),
      name: args.name,
      avatar_template: "/letter_avatar_proxy/v3/letter/t/41988e/{size}.png",
      suspended_till: args.suspended_till,
      can_send_private_message_to_user:
        args.can_send_private_message_to_user ?? true,
    });
  }

  bookmark(args = {}) {
    return this.store.createRecord("bookmark", {
      id: args.id || incrementSequence(),
    });
  }

  group(args = {}) {
    return this.store.createRecord("group", {
      name: args.name || getLoadedFaker().faker.word.noun(),
    });
  }

  webhook(args = {}) {
    return this.store.createRecord("web-hook", args);
  }

  upload() {
    return {
      extension: "jpeg",
      filesize: 126177,
      height: 800,
      human_filesize: "123 KB",
      id: incrementSequence(),
      original_filename: "avatar.PNG.jpg",
      retain_hours: null,
      short_path: "/images/avatar.png",
      short_url: "upload://yoj8pf9DdIeHRRULyw7i57GAYdz.jpeg",
      thumbnail_height: 320,
      thumbnail_width: 690,
      url: "/images/avatar.png",
      width: 1920,
    };
  }
}
import { ajax } from "discourse/lib/ajax";
import escapeRegExp from "discourse/lib/escape-regexp";
import { removeAccents } from "discourse/lib/utilities";
import { i18n } from "discourse-i18n";

const MAX_RESULTS = 20;
const SEGMENT_PATTERN = /"[^"]*"|'[^']*'|\S+/g;
const PREFIX_PATTERN = /^(?:-=|=-|-|=)/;
const EMPTY_SEGMENT = Object.freeze({
  word: "",
  prefix: "",
  filterName: null,
  value: null,
});

/**
 * @typedef {{ name: string, description: string }} FilterOptionModifier
 * @typedef {{ id: number, name: string, slug: string }} FilterCategory
 * @typedef {object} FilterTip
 * @property {string} name
 * @property {string} description
 * @property {string} [alias]
 * @property {number} [priority]
 * @property {string} [type]
 * @property {number} [min]
 * @property {FilterOptionModifier[]} [prefixes]
 * @property {FilterOptionModifier[]} [delimiters]
 * @property {FilterOptionModifier[]} [extra_entries]
 * @typedef {object} FilterSuggestion
 * @property {string} name
 * @property {string} [description]
 * @property {string} [term]
 * @property {boolean} [isSuggestion]
 * @property {FilterCategory} [category]
 * @property {FilterOptionModifier[]} [delimiters]
 */
export default class FilterSuggestions {
  /**
   * Main entry point - takes raw input text and available tips, returns suggestions
   * @param {string} text - The full input text from the user
   * @param {FilterTip[]} [tips] - Available filter tips from the server
   * @param {{ site?: { categories?: FilterCategory[] } }} [context] - Additional context (site data, etc.)
   * @returns {Promise<{ suggestions: Array<FilterTip | FilterSuggestion>, activeFilter: string | null }>}
   */
  static async getSuggestions(text, tips = [], context = {}) {
    const lastSegment = parseLastSegment(text);

    if (!lastSegment.word) {
      return {
        suggestions: this.getTopLevelTips(tips),
        activeFilter: null,
      };
    }

    if (lastSegment.filterName) {
      const tip = this.findTipForFilter(lastSegment.filterName, tips);

      if (tip?.type) {
        const suggestions = await this.getFilterSuggestionsByType(
          tip,
          lastSegment,
          context
        );

        return {
          suggestions,
          activeFilter: lastSegment.filterName,
        };
      }
    }

    return {
      suggestions: this.filterTips(tips, lastSegment.word, lastSegment.prefix),
      activeFilter: null,
    };
  }

  static getTopLevelTips(tips) {
    return tips
      .filter((tip) => tip.priority === 1)
      .sort((a, b) => a.name.localeCompare(b.name))
      .slice(0, MAX_RESULTS);
  }

  static findTipForFilter(filterName, tips) {
    return tips.find((tip) => {
      const normalize = (str) => (str ? str.replace(/:$/, "") : str);
      return (
        normalize(tip.name) === filterName ||
        normalize(tip.alias) === filterName
      );
    });
  }

  static filterTips(tips, searchTerm, prefix = "") {
    const filtered = [];
    searchTerm = searchTerm.toLowerCase();
    // remove prefix from search term
    if (prefix) {
      searchTerm = searchTerm.replace(prefix, "");
    }

    for (const tip of tips) {
      if (filtered.length >= MAX_RESULTS) {
        break;
      }

      const tipName = tip.name;
      let matches =
        tipName.includes(searchTerm) ||
        (tip.alias && tip.alias.includes(searchTerm));

      if (tipName === searchTerm) {
        matches = false;
      }
      if (!matches) {
        continue;
      }

      if (tip.prefixes) {
        if (prefix) {
          const matchingPrefix = tip.prefixes.find((p) => p.name === prefix);
          if (matchingPrefix) {
            filtered.push({
              ...tip,
              name: `${prefix}${tip.name}`,
              description: matchingPrefix.description || tip.description,
              isSuggestion: true,
            });
          }
        } else {
          filtered.push(tip);
          tip.prefixes.forEach((pfx) => {
            filtered.push({
              ...tip,
              name: `${pfx.name}${tip.name}`,
              description: pfx.description || tip.description,
              isSuggestion: true,
            });
          });
        }
      } else {
        filtered.push({
          ...tip,
          name: `${prefix}${tip.name}`,
          isSuggestion: true,
        });
      }
    }

    return filtered.sort((a, b) => {
      const aStarts = a.name.toLowerCase().startsWith(searchTerm);
      const bStarts = b.name.toLowerCase().startsWith(searchTerm);

      if (aStarts && !bStarts) {
        return -1;
      }
      if (!aStarts && bStarts) {
        return 1;
      }

      return a.name.length - b.name.length;
    });
  }

  static async getFilterSuggestionsByType(tip, segment, context) {
    const suggester = new FilterTypeValueSuggester(tip, segment, context);

    switch (tip.type) {
      case "category":
        return await suggester.getCategorySuggestions();
      case "tag":
        return await suggester.getTagSuggestions();
      case "tag_group":
        return await suggester.getTagGroupSuggestions();
      case "username":
        return await suggester.getUserSuggestions();
      case "group":
        return await suggester.getGroupSuggestions();
      case "username_group_list":
        return await suggester.getUsernameGroupListSuggestions();
      case "date":
        return suggester.getDateSuggestions();
      case "number":
        return suggester.getNumberSuggestions();
      default:
        return [];
    }
  }
}

function parseLastSegment(text) {
  if (!text || text.endsWith(" ")) {
    return EMPTY_SEGMENT;
  }

  const word = text.match(SEGMENT_PATTERN)?.at(-1);

  if (!word) {
    return EMPTY_SEGMENT;
  }

  const prefix = word.match(PREFIX_PATTERN)?.[0] || "";
  const withoutPrefix = word.substring(prefix.length);
  const colonIndex = withoutPrefix.indexOf(":");

  if (colonIndex <= 0) {
    return { word, prefix, filterName: null, value: null };
  }

  return {
    word,
    prefix,
    filterName: withoutPrefix.substring(0, colonIndex),
    value: withoutPrefix.substring(colonIndex + 1),
  };
}

class FilterTypeValueSuggester {
  constructor(tip, segment, context) {
    this.tip = tip;
    this.segment = segment;
    this.context = context;
    this.prefix = segment.prefix || "";
    this.filterName = segment.filterName;

    this.parseMultiValue();
  }

  parseMultiValue() {
    const value = this.segment.value || "";

    if (this.tip.delimiters) {
      const delimiterPattern = new RegExp(
        `[${this.tip.delimiters.map((d) => escapeRegExp(d.name)).join("")}]`
      );

      const parts = value.split(delimiterPattern);
      this.previousValues = parts
        .slice(0, -1)
        .map((p) => p.trim())
        .filter(Boolean);
      this.searchTerm = parts.at(-1).trim();
      this.valuePrefix = value.substring(
        0,
        value.length - this.searchTerm.length
      );
    } else {
      this.previousValues = [];
      this.searchTerm = value;
      this.valuePrefix = "";
    }
  }

  buildSuggestionName(term) {
    return `${this.prefix}${this.filterName}:${this.valuePrefix}${term}`;
  }

  prepareDelimiterSuggestions(results) {
    if (!this.tip.delimiters || this.tip.delimiters.length === 0) {
      return results;
    }
    results.forEach((r) => (r.delimiters = this.tip.delimiters));

    const used = new Set(this.previousValues.map((v) => v.toLowerCase()));
    results = results.filter((r) => !used.has((r.term || "").toLowerCase()));

    const searchLower = (this.searchTerm || "").toLowerCase();
    if (
      searchLower &&
      results.some((r) => (r.term || "").toLowerCase() === searchLower)
    ) {
      this.tip.delimiters.forEach((delimiter) => {
        results.push({
          name: this.buildSuggestionName(`${this.searchTerm}${delimiter.name}`),
          description: delimiter.description,
          isSuggestion: true,
          delimiters: this.tip.delimiters,
        });
      });
    }

    return results;
  }

  async getCategorySuggestions() {
    const categories = this.context.site?.categories || [];
    const normalize = (str) => removeAccents(str.toLowerCase());
    const searchNormalized = normalize(this.searchTerm);

    return categories
      .filter((cat) => {
        const name = normalize(cat.name);
        const slug = normalize(cat.slug);
        return (
          !searchNormalized ||
          name.includes(searchNormalized) ||
          slug.includes(searchNormalized)
        );
      })
      .slice(0, 10)
      .map((cat) => ({
        name: this.buildSuggestionName(cat.slug),
        description: cat.name,
        term: cat.slug,
        category: cat,
        isSuggestion: true,
      }));
  }

  async getTagSuggestions() {
    try {
      const response = await ajax("/tags/filter/search.json", {
        data: { q: this.searchTerm || "", limit: 5 },
      });

      let results = response.results.map((tag) => ({
        name: this.buildSuggestionName(tag.name),
        description: `${tag.count}`,
        term: tag.name,
        isSuggestion: true,
      }));
      results = this.prepareDelimiterSuggestions(results);
      return results;
    } catch {
      return [];
    }
  }

  async getTagGroupSuggestions() {
    try {
      const response = await ajax("/tag_groups/filter/search.json", {
        data: { q: this.searchTerm || "", limit: 10 },
      });

      return response.results.map((tagGroup) => {
        const quotedName = this.quoteIfNeeded(tagGroup.name);

        return {
          name: this.buildSuggestionName(quotedName),
          description: tagGroup.tag_names?.join(", ") || "",
          term: quotedName,
          isSuggestion: true,
        };
      });
    } catch {
      return [];
    }
  }

  quoteIfNeeded(name) {
    if (!/[\s&\-()'"]/.test(name)) {
      return name;
    }

    return name.includes('"') ? `'${name}'` : `"${name}"`;
  }

  async getUserSuggestions() {
    return this.prepareDelimiterSuggestions(await this.#fetchUsers());
  }

  async getGroupSuggestions() {
    return this.prepareDelimiterSuggestions(await this.#fetchGroups());
  }

  async getUsernameGroupListSuggestions() {
    let suggestions = [];

    if (this.tip.extra_entries && this.previousValues.length === 0) {
      suggestions = this.tip.extra_entries
        .filter((entry) => {
          if (!this.searchTerm) {
            return true;
          }

          const searchLower = this.searchTerm.toLowerCase();

          return (
            entry.name.toLowerCase().includes(searchLower) ||
            entry.description.toLowerCase().includes(searchLower)
          );
        })
        .map((entry) => ({
          name: this.buildSuggestionName(entry.name),
          description: entry.description,
          term: entry.name,
          isSuggestion: true,
        }));
    }

    suggestions = this.prepareDelimiterSuggestions(
      suggestions.concat(await this.#fetchUsers(), await this.#fetchGroups(5))
    );

    const searchLower = this.searchTerm?.toLowerCase();

    return suggestions
      .sort((a, b) => {
        const aExact = (a.term || "").toLowerCase() === searchLower;
        const bExact = (b.term || "").toLowerCase() === searchLower;

        if (aExact && !bExact) {
          return -1;
        }

        if (!aExact && bExact) {
          return 1;
        }

        return 0;
      })
      .slice(0, MAX_RESULTS);
  }

  getDateSuggestions() {
    const options = [
      { value: "1", key: "yesterday" },
      { value: "7", key: "last_week" },
      { value: "30", key: "last_month" },
      { value: "365", key: "last_year" },
    ];

    return options
      .map((opt) => ({
        name: this.buildSuggestionName(opt.value),
        description: i18n(`filter.description.${opt.key}`),
        term: opt.value,
        isSuggestion: true,
      }))
      .filter(
        (s) =>
          !this.searchTerm ||
          s.term.includes(this.searchTerm) ||
          s.description.toLowerCase().includes(this.searchTerm.toLowerCase())
      );
  }

  getNumberSuggestions() {
    const options = [
      { value: "0" },
      { value: "1" },
      { value: "5" },
      { value: "10" },
      { value: "20" },
    ];

    return options
      .filter((opt) => Number(opt.value) >= (this.tip.min ?? 0))
      .filter((opt) => !this.searchTerm || opt.value.includes(this.searchTerm))
      .map((opt) => ({
        name: this.buildSuggestionName(opt.value),
        term: opt.value,
        isSuggestion: true,
      }));
  }

  async #fetchGroups(limit = 10) {
    const data = { limit };

    if (this.searchTerm) {
      data.term = this.searchTerm;
    }

    try {
      const response = await ajax("/groups/search.json", { data });

      return response.map((group) => ({
        name: this.buildSuggestionName(group.name),
        description: group.full_name || group.name,
        term: group.name,
        isSuggestion: true,
      }));
    } catch {
      return [];
    }
  }

  async #fetchUsers(limit = 10) {
    const data = { limit };

    if (this.searchTerm) {
      data.term = this.searchTerm;
    } else {
      data.last_seen_users = true;
    }

    try {
      const response = await ajax("/u/search/users.json", { data });

      return response.users.map((user) => ({
        name: this.buildSuggestionName(user.username),
        description: user.name || "",
        term: user.username,
        isSuggestion: true,
      }));
    } catch {
      return [];
    }
  }
}
import { popupAjaxError } from "discourse/lib/ajax-error";

export default class Flag {
  targetsTopic() {
    return false;
  }

  editable() {
    return true;
  }

  /**
   * @returns {Promise<boolean>} resolves `false` when the flag was not created
   */
  create(flagModal, opts) {
    // an instance of ActionSummary
    const postAction = this.postActionFor(flagModal);
    flagModal.appEvents.trigger(
      this.flagCreatedEvent(),
      flagModal.args.model.flagModel,
      postAction,
      opts
    );

    flagModal.args.closeModal();
    return postAction
      .act(flagModal.args.model.flagModel, opts)
      .then((result) => !!result?.acted)
      .catch((error) => {
        popupAjaxError(error);
        return false;
      });
  }
}
import Flag from "discourse/lib/flag-targets/flag";
import { getAbsoluteURL } from "discourse/lib/get-url";
import { applyValueTransformer } from "discourse/lib/transformer";
import { i18n } from "discourse-i18n";

export default class PostFlag extends Flag {
  title() {
    return applyValueTransformer("post-flag-title", "flagging.title");
  }

  customSubmitLabel() {
    return "flagging.notify_action";
  }

  submitLabel() {
    return "flagging.action";
  }

  anonymousFlagDescription(post, email) {
    return i18n("anonymous_flagging.description", {
      email,
      topic_title: post.topic.title,
      url: getAbsoluteURL(post.url),
    });
  }

  flagCreatedEvent() {
    return "post:flag-created";
  }

  flagsAvailable(flagModal) {
    let flagsAvailable = flagModal.args.model.flagModel.flagsAvailable;

    flagsAvailable = flagsAvailable.filter((flag) => {
      return flag.applies_to.includes("Post");
    });

    // "message user" option should be at the top
    const notifyUserIndex = flagsAvailable.findIndex(
      (flag) => flag.name_key === "notify_user"
    );

    if (notifyUserIndex !== -1) {
      const notifyUser = flagsAvailable[notifyUserIndex];
      flagsAvailable.splice(notifyUserIndex, 1);
      flagsAvailable.splice(0, 0, notifyUser);
    }

    flagsAvailable = applyValueTransformer(
      "post-flag-available-flags",
      flagsAvailable
    );

    return flagsAvailable;
  }

  postActionFor(flagModal) {
    return flagModal.args.model.flagModel.actionByName?.[
      flagModal.selected.name_key
    ];
  }
}
import EmberObject from "@ember/object";
import Flag from "discourse/lib/flag-targets/flag";
import ActionSummary from "discourse/models/action-summary";

export default class TopicFlag extends Flag {
  title() {
    return "flagging_topic.title";
  }

  targetsTopic() {
    return true;
  }

  customSubmitLabel() {
    return "flagging_topic.notify_action";
  }

  submitLabel() {
    return "flagging_topic.action";
  }

  flagCreatedEvent() {
    return "topic:flag-created";
  }

  flagsAvailable(flagModal) {
    let lookup = EmberObject.create();

    flagModal.args.model.flagModel.actions_summary.forEach((a) => {
      a.flagTopic = flagModal.args.model.flagModel;
      a.actionType = flagModal.site.topicFlagTypeById(a.id);
      lookup.set(a.actionType.name_key, ActionSummary.create(a));
    });
    flagModal.topicActionByName = lookup;

    return flagModal.site.topic_flag_types.filter((item) => {
      return flagModal.args.model.flagModel.actions_summary.some((a) => {
        return a.id === item.id && a.can_act;
      });
    });
  }

  postActionFor(flagModal) {
    return flagModal.topicActionByName[flagModal.selected.name_key];
  }
}
/**
 * The axis a gesture runs along: a resize, a scroll, or the midpoint a drop
 * is measured against.
 */
export type Axis = "vertical" | "horizontal";

/**
 * A logical side of a box along an axis, resolved against the writing
 * direction rather than a physical edge.
 */
export type Side = "start" | "end";
import { convertIconClass } from "discourse/lib/icon-library";

export function grantableBadges(allBadges, userBadges) {
  const granted = new Set(userBadges.map((ub) => ub.badge_id));

  return allBadges
    .filter(
      (badge) =>
        badge.enabled &&
        badge.manually_grantable &&
        (!granted.has(badge.id) || badge.multiple_grant)
    )
    .sort((a, b) => a.name.localeCompare(b.name));
}

// `ComboBox` renders `item.icon` directly, so it needs the converted class.
// Derived rather than assigned back: badge records are shared through the
// store, and everything else converts at render time (`d-icon-or-image`).
export function grantableBadgeOptions(badges) {
  return badges.map((badge) => ({
    id: badge.id,
    name: badge.name,
    icon: badge.icon ? convertIconClass(badge.icon) : null,
  }));
}

export function isBadgeGrantable(badgeId, availableBadges) {
  return !!(availableBadges && availableBadges.some((b) => b.id === badgeId));
}
import { AUTO_GROUPS } from "discourse/lib/constants";

// TODO (martin) Remove all this indirection when
// granular_anonymous_and_logged_in_groups_permissions is Permanent
const EVERYONE_ID = AUTO_GROUPS.everyone.id.toString();
const LOGGED_IN_USERS_ID = AUTO_GROUPS.logged_in_users.id.toString();

function normalizeIds(ids) {
  return ids.map((id) => id.toString());
}

export function mapEveryoneToLoggedInUsersIds(ids, granularPermissionsEnabled) {
  ids = normalizeIds(ids);

  if (!granularPermissionsEnabled || !ids.includes(EVERYONE_ID)) {
    return ids;
  }

  return [
    ...new Set(ids.map((id) => (id === EVERYONE_ID ? LOGGED_IN_USERS_ID : id))),
  ];
}

export function mapLoggedInUsersToEveryoneForStorage(
  ids,
  granularPermissionsEnabled,
  storedValue,
  tokenSeparator
) {
  if (!granularPermissionsEnabled) {
    return normalizeIds(ids);
  }

  const storedIds = normalizeIds(
    (storedValue || "").split(tokenSeparator).filter(Boolean)
  );

  if (
    !storedIds.includes(EVERYONE_ID) ||
    storedIds.includes(LOGGED_IN_USERS_ID)
  ) {
    return normalizeIds(ids);
  }

  return [
    ...new Set(
      normalizeIds(ids).map((id) =>
        id === LOGGED_IN_USERS_ID ? EVERYONE_ID : id
      )
    ),
  ];
}
const NON_CARET_INPUT_TYPES = new Set([
  "button",
  "checkbox",
  "file",
  "image",
  "reset",
  "submit",
]);

/**
 * Whether the target owns a text caret and should keep the native context menu.
 *
 * Intentionally separate from the predicate that decides which elements own the arrow keys:
 * that one counts `select` as editable, which is the wrong answer to this question.
 *
 * @param target - The contextmenu event's target.
 */
export default function isContextMenuExemptTarget(
  target: EventTarget | null
): boolean {
  if (!(target instanceof HTMLElement)) {
    return false;
  }

  const tag = target.tagName;

  if (tag === "TEXTAREA" || target.isContentEditable) {
    return true;
  }

  return (
    tag === "INPUT" &&
    !NON_CARET_INPUT_TYPES.has((target as HTMLInputElement).type)
  );
}
export default function (element) {
  if (!element) {
    return;
  }

  const rect = element.getBoundingClientRect();

  return (
    rect.top >= 0 &&
