    <@field.Control>
      <ListSetting
        @choices={{this.choices}}
        @mandatoryValues={{@definition.mandatory_values}}
        @nameProperty={{if this.hasEnumChoices "name"}}
        @onChange={{this.onChange}}
        @onChangeChoices={{this.onChangeChoices}}
