    this.rect = {
      top: this.caretCoords.y + yOffset,
      right: this.caretCoords.x,
      bottom: this.caretCoords.y + yOffset,
      left: this.caretCoords.x + xOffset,
      width: 0,
      height: 0,
      x: this.caretCoords.x,
      y: this.caretCoords.y,
      toJSON() {
        return this;
      },
    };
    return this.rect;
  }

  getBoundingClientRect() {
    return this.rect;
  }

  getClientRects() {
    return [this.rect];
  }
