export default function virtualElementFromPoint(
  x: number,
  y: number
): VirtualElement {
  return {
    getBoundingClientRect() {
      return {
        x,
        y,
        left: x,
        right: x,
        top: y,
        bottom: y,
        width: 0,
        height: 0,
      };
