    clearTimers(): void {
      this.#timers.forEach((timer) => {
        if (timer) {
          cancel(timer);
        }
      });
      this.#timers.clear();

      this.#restores.forEach((timer) => cancel(timer));
      this.#restores.clear();
    }

    /**
     * Cancels the pending repeat-restore for a type, if there is one
     * @param type - Type of announcement
