    // awaited by `settled()`; a live region is polled asynchronously, so the one-tick
    // delay is imperceptible.
    next(() => {
      if (this.isDestroying) {
        return;
      }

      this.#state.setMessage(type, trimmed, clearDelay);
    });
  }
}
