  /*
   * Block Registry Methods
   */

  /**
   * Gets a registered block by name.
   *
   * @param name - The block name (e.g., "hero-banner")
   * @returns The block entry, or undefined if not found
   *
   * @example
   * ```javascript
   * const HeroBanner = this.blocks.getBlock("hero-banner");
   * ```
