    return ajax(`/bookmarks/${bookmarkId}.json`, {
      method: "DELETE",
    }).catch(popupAjaxError);
  }

  update(bookmarkFormData) {
    return ajax(`/bookmarks/${bookmarkFormData.id}.json`, {
      method: "PUT",
      data: bookmarkFormData.saveData,
    }).catch(popupAjaxError);
  }
}
