            type="button"
            {{on "click" this.handleConfirm}}
          >
            {{this.confirmLabel}}
          </button>
        {{/unless}}
        <button
          class="btn btn-default"
          type="button"
          {{on "click" this.handleCancel}}
        >
          {{i18n "embed_mode.signin_flow.cancel"}}
        </button>
      </:footer>
    </DModal>
  </template>
}
