      if (count > 0) {
        return this.dialog.confirm({
          message: i18n(
            "admin.groups.manage.membership.automatic_membership_user_count",
            { count }
          ),
        });
      }

      return true;
    } catch (error) {
      popupAjaxError(error);
    }
  }
