  #buildPayload() {
    return {
      session_id: this.#sessionId,
      ...this.#counts,
      engaged_seconds: this.#engagedSeconds(),
      time_to_first_interaction_ms:
        this.#firstInteractionAt === null
          ? null
          : Math.round(this.#firstInteractionAt - this.#startedAt),
