import { i18n } from "discourse-i18n";

export default class DsaModerationAction extends Component {
  @tracked flash;
  @tracked saving = false;

  get buttonClass() {
    return this.hasActionDetails && !this.#editing
      ? "btn-danger"
      : "btn-primary";
  }

  get buttonLabel() {
    if (this.#editing) {
      return i18n("review.continue_to_editor");
    }
    return this.hasActionDetails
      ? this.args.model.action.label
      : i18n("dsa_statements.save");
  }

  get hasActionDetails() {
    return Boolean(this.args.model.action.confirm_message);
  }

  get nextStepLabel() {
    return this.#editing ? this.args.model.action.label : null;
  }

  get title() {
    return this.hasActionDetails || this.#editing
      ? this.args.model.action.label
      : i18n("dsa_statements.title");
  }

  get #editing() {
    return this.args.model.action.client_action === "edit";
  }

  @action
  async submit(data) {
    if (this.saving) {
      return;
    }
    this.saving = true;
    this.flash = null;
    try {
      await this.args.model.perform(data);
      this.args.closeModal();
    } catch (error) {
      this.flash = extractError(error);
    } finally {
      this.saving = false;
    }
  }

  <template>
    <DsaModeration
      @actionStepLabel={{i18n "review.moderation_steps.confirm"}}
      @hasActionDetails={{this.hasActionDetails}}
      @nextStepLabel={{this.nextStepLabel}}
      @onSubmit={{this.submit}}
      @options={{@model.options}}
      as |flow|
    >
      <DModal
        class="dsa-moderation-action"
        ...attributes
        @closeModal={{@closeModal}}
        @dismissable={{not this.saving}}
        @flash={{this.flash}}
        @title={{this.title}}
      >
        <:headerBelowTitle>
          {{#if flow.showTitleHelp}}
            <flow.Help class="dsa-moderation-title-help" />
          {{/if}}
        </:headerBelowTitle>
        <:belowHeader>
          <flow.Steps @disabled={{this.saving}} />
        </:belowHeader>
        <:body>
          <flow.Body>
            <p>{{@model.action.confirm_message}}</p>
          </flow.Body>
        </:body>
        <:footer>
          <flow.Footer
            @cancel={{if @model.action.confirm_message @closeModal}}
            @cancelDisabled={{this.saving}}
            @disabled={{this.saving}}
            @isLoading={{this.saving}}
            @submitClass={{this.buttonClass}}
            @submitLabel={{this.buttonLabel}}
          />
        </:footer>
      </DModal>
    </DsaModeration>
  </template>
}
import Service, { service } from "@ember/service";
import DsaModerationAction from "discourse/components/modal/dsa-moderation-action";

export default class ReviewableDsa extends Service {
  @service modal;

  optionsFor({ action, options }) {
    if (
      action.dsa_classification_required &&
      options?.community_rules?.length
    ) {
      return options;
    }
  }

  handlesConfirmation({ action, options, modalClass }) {
    return (
      this.optionsFor({ action, options }) &&
      (!modalClass || action.server_action === "revise_and_reject_post")
    );
  }

  async perform({
    action,
    reviewable,
    options,
    modalClass,
    claim,
    dispatch,
    performAction,
  }) {
    const classify = async (perform, data = {}) => {
      if (await claim()) {
        return this.modal.show(DsaModerationAction, {
          model: {
            action,
            options,
            reviewable,
            perform: (classification) =>
              perform({ ...data, ...classification }),
          },
        });
      }
    };

    if (action.client_action === "edit") {
      return classify((classification) =>
        dispatch((data) => performAction({ ...data, ...classification }))
      );
    }

    if (modalClass) {
      if (await claim()) {
        return this.modal.show(modalClass, {
          model: {
            action,
            reviewable,
            classificationOptions: options,
            performConfirmed: (_action, data) => performAction(data),
          },
        });
      }
      return;
    }

    let classificationPromise;
    await dispatch((data) => {
      if (data?.dsa_classification) {
        return performAction(data);
      }
      classificationPromise = classify(performAction, data);
      return classificationPromise;
    });
    return classificationPromise;
  }
}
