  /** @type {string | null} */
  context = null;

  constructor(ctx = DISCOURSE_PREFIX) {
    super(...arguments);
    this.context = isTesting() ? `${TEST_KEY_PREFIX}${ctx}` : ctx;
  }

  abandonLocal() {
    return this.removeKeys();
  }

  removeKeys(predicate = () => true) {
    if (!sessionStorage) {
      return;
    }

    let i = sessionStorage.length - 1;

    while (i >= 0) {
      let k = sessionStorage.key(i);
