      } catch {}

      if (
        k.substring(0, this.context.length) === this.context &&
        predicate(k, v)
      ) {
        sessionStorage.removeItem(k);
      }
      i--;
    }

    return true;
  }

  remove(key) {
    if (!sessionStorage) {
      return;
    }

    return sessionStorage.removeItem(this.context + key);
  }

  get(key) {
    if (!sessionStorage) {
      return null;
    }

    return sessionStorage.getItem(this.context + key);
  }

  set(opts) {
    if (!sessionStorage) {
      return false;
    }

    sessionStorage.setItem(this.context + opts.key, opts.value);
  }

  setObject(opts) {
    this.set({ key: opts.key, value: JSON.stringify(opts.value) });
  }

  getInt(key, def) {
    if (!def) {
      def = 0;
    }

    if (!sessionStorage) {
      return def;
    }

    const result = parseInt(this.get(key), 10);
    if (!isFinite(result)) {
      return def;
    }

    return result;
  }

  getObject(key) {
    if (!sessionStorage) {
      return null;
    }

    let v = sessionStorage.getItem(this.context + key);
    if (v === null) {
      return null;
    }

    try {
      v = JSON.parse(v);
    } catch {}

    return v;
  }

  // API compatibility with `sessionStorage`
  getItem(key) {
    return this.get(key);
  }

  removeItem(key) {
    return this.remove(key);
  }

  setItem(key, value) {
    this.set({ key, value });
  }
}
