    return this.args.options.find((option) => option.id === this.args.value)
      ?.name;
  }

  @action
  select(close, permission) {
    close();
    this.args.onChange(permission);
  }

  <template>
    <DMenu
      data-permission={{@value}}
      ...attributes
      @autofocus={{false}}
      @disabled={{@disabled}}
      @identifier="d-access-control__permission-menu"
      @modalForMobile={{true}}
      @triggerComponent={{component
        PermissionTrigger
        disabled=@disabled
        label=this.label
      }}
    >
      <:content as |menu|>
        <DDropdownMenu as |dropdown|>
          {{#each @options key="id" as |option|}}
            {{#if (eq option.id "remove")}}
              <dropdown.divider />
            {{/if}}
            <dropdown.item>
              <DButton
                class={{dConcatClass
                  "d-access-control__permission-option"
                  "--with-description"
                  (if (eq option.id "remove") "--remove")
                  (if (eq option.id @value) "-selected")
                }}
                data-permission-id={{option.id}}
                @action={{fn this.select menu.close option.id}}
              >
                <div class="d-access-control__permission-texts">
                  <span
                    class="d-access-control__permission-label"
                  >{{option.name}}</span>
                  {{#if option.description}}
                    <span
                      class="d-access-control__permission-description"
                    >{{option.description}}</span>
                  {{/if}}
                </div>
              </DButton>
            </dropdown.item>
          {{/each}}
        </DDropdownMenu>
      </:content>
    </DMenu>
  </template>
}
import { action } from "@ember/object";
import { classNames } from "@ember-decorators/component";
import MultiSelectFilterComponent from "discourse/select-kit/components/multi-select/multi-select-filter";

@classNames("email-group-user-chooser-filter")
export default class EmailGroupUserChooserFilter extends MultiSelectFilterComponent {
  @action
  onPaste(event) {
    if (this.selectKit.options.maximum === 1) {
      return;
    }

    const data = event?.clipboardData;

    if (!data) {
      return;
    }

    const recipients = [];
    data
      .getData("text")
      .split(/[, \n]+/)
      .forEach((recipient) => {
        recipient = recipient.replace(/^@+/, "").trim();
        if (recipient.length > 0) {
          recipients.push(recipient);
        }
      });

    if (recipients.length > 0) {
      event.stopPropagation();
      event.preventDefault();

      this.selectKit.append(recipients);

      return false;
    }
  }
}
import { classNames } from "@ember-decorators/component";
import decorateUsernameSelector from "discourse/helpers/decorate-username-selector";
import formatUsername from "discourse/helpers/format-username";
import SelectKitRowComponent from "discourse/select-kit/components/select-kit/select-kit-row";
import DUserStatusMessage from "discourse/ui-kit/d-user-status-message";
import dAvatar from "discourse/ui-kit/helpers/d-avatar";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import dIcon from "discourse/ui-kit/helpers/d-icon";

@classNames("email-group-user-chooser-row")
export default class EmailGroupUserChooserRow extends SelectKitRowComponent {
  get userNameOrdering() {
    if (
      !this.selectKit.options.prioritizeUserNameOrdering ||
      this.siteSettings.prioritize_username_in_ux
    ) {
      return "usernameFirst";
    }

    return "nameFirst";
  }

  get groupNameOrdering() {
    if (!this.selectKit.options.prioritizeGroupFullNameOrdering) {
      return "groupNameFirst";
    }

    return "groupFullNameFirst";
  }

  get shouldExcludeGroupName() {
    return (
      this.selectKit.options.excludeGroupNameWhenMatchingFullName &&
      (this.item.full_name || "").toLowerCase() ===
        this.item.id.toLowerCase().replaceAll("_", " ").replaceAll("-", " ")
    );
  }

  <template>
    {{#if this.item.isUser}}
      {{dAvatar this.item imageSize="tiny"}}
      <div
        class={{dConcatClass
          "email-group-user-chooser__user"
          (if
            (eq this.userNameOrdering "usernameFirst")
            "--username-first"
            "--name-first"
          )
        }}
      >
        {{#if (eq this.userNameOrdering "usernameFirst")}}
          <span class="identifier">{{formatUsername this.item.id}}</span>
          {{#if this.item.name}}
            <span class="name">{{this.item.name}}</span>
          {{/if}}
        {{else}}
          {{#if this.item.name}}
            <span class="name">{{this.item.name}}</span>
          {{/if}}
          <span class="identifier">{{formatUsername this.item.id}}</span>
        {{/if}}
      </div>
      {{#if (and this.item.showUserStatus this.item.status)}}
        <DUserStatusMessage
          @showDescription={{true}}
          @status={{this.item.status}}
        />
      {{/if}}
      {{decorateUsernameSelector this.item.id}}
    {{else if this.item.isGroup}}
      {{dIcon "users"}}
      <div
        class={{dConcatClass
          "email-group-user-chooser__group"
          (if
            (eq this.groupNameOrdering "groupNameFirst")
            "--group-name-first"
            "--group-full-name-first"
          )
        }}
      >
        {{#if (eq this.groupNameOrdering "groupNameFirst")}}
          {{#unless this.shouldExcludeGroupName}}
            <span class="identifier">{{this.item.id}}</span>
          {{/unless}}
          <span class="name">{{this.item.full_name}}</span>
        {{else if (eq this.groupNameOrdering "groupFullNameFirst")}}
          {{#if this.item.full_name}}
            <span class="name">{{this.item.full_name}}</span>
            {{#unless this.shouldExcludeGroupName}}
              <span class="identifier">{{this.item.id}}</span>
            {{/unless}}
          {{else}}
            {{#unless this.shouldExcludeGroupName}}
              <span class="name">{{this.item.id}}</span>
            {{/unless}}
          {{/if}}
        {{/if}}
      </div>
    {{else}}
      {{dIcon "envelope"}}
      <span class="identifier">{{this.item.id}}</span>
    {{/if}}

    {{#if this.item.badgeText}}
      <span class="email-group-user-chooser__badge">
        {{#if this.item.badgeIcon}}
          {{dIcon this.item.badgeIcon}}
        {{/if}}
        {{this.item.badgeText}}
      </span>
    {{/if}}
  </template>
}
import { classNameBindings, classNames } from "@ember-decorators/component";
import {
  pluginApiIdentifiers,
  selectKitOptions,
} from "discourse/select-kit/components/select-kit";
import UserChooserComponent from "discourse/select-kit/components/user-chooser";
import EmailGroupUserChooserFilter from "./email-group-user-chooser-filter.js";
import EmailGroupUserChooserRow from "./email-group-user-chooser-row.gjs";

@classNames("email-group-user-chooser")
@classNameBindings("selectKit.options.fullWidthWrap:full-width-wrap")
@selectKitOptions({
  filterComponent: EmailGroupUserChooserFilter,
  fullWidthWrap: false,
  autoWrap: false,
  prioritizeUserNameOrdering: false,
  prioritizeGroupFullNameOrdering: false,
  excludeGroupNameWhenMatchingFullName: false,
})
@pluginApiIdentifiers(["email-group-user-chooser"])
export default class EmailGroupUserChooser extends UserChooserComponent {
  valueProperty = "id";
  nameProperty = "name";

  modifyComponentForRow() {
    return EmailGroupUserChooserRow;
  }

  search() {
    const superPromise = super.search(...arguments);
    if (!superPromise) {
      return;
    }
    return superPromise.then((results) => {
      if (!results || results.length === 0) {
        return;
      }
      return results.map((item) => {
        const reconstructed = {};
        if (item.username) {
          reconstructed.id = item.username;
          if (item.username.includes("@")) {
            reconstructed.isEmail = true;
          } else {
            reconstructed.isUser = true;
            reconstructed.name = item.name;
            reconstructed.showUserStatus = this.showUserStatus;
          }
        } else if (item.name) {
          reconstructed.id = item.name;
          reconstructed.name = item.full_name || item.name;
          reconstructed.isGroup = true;
        }
        return { ...item, ...reconstructed };
      });
    });
  }
}
import { ajax } from "discourse/lib/ajax";
import EmailGroupUserChooser from "discourse/select-kit/components/email-group-user-chooser";
import { selectKitOptions } from "discourse/select-kit/components/select-kit";
import { i18n } from "discourse-i18n";

const ACCESS_CONTROL_GRANTEE_SEARCH_URL = "/access-control/grantees/search";

export function granteeValue(type, id) {
  return `${type}:${id}`;
}

export function groupGranteeResult(group, isDisabled = false) {
  return {
    value: granteeValue("group", group.id),
    id: group.name,
    aclId: group.id,
    aclType: "group",
    name: group.name,
    full_name: group.full_name,
    display_name: group.display_name,
    automatic: group.automatic,
    isGroup: true,
    disabled: isDisabled,
    badgeText: isDisabled ? i18n("access_control.manage.disallowed") : null,
    badgeIcon: isDisabled ? "ban" : null,
  };
}

function userGranteeResult(user, isDisabled = false) {
  const sortName = user.name || user.display_name || user.username;

  return {
    value: granteeValue("user", user.id),
    id: user.username,
    aclId: user.id,
    aclType: "user",
    name: user.name,
    sort_name: sortName,
    username: user.username,
    showUserStatus: false,
    avatar_template: user.avatar_template,
    isUser: true,
    disabled: isDisabled,
    badgeText: isDisabled ? i18n("access_control.manage.disallowed") : null,
    badgeIcon: isDisabled ? "ban" : null,
  };
}

/**
 * excludedGrantees: an array of grantee values (in format type:id) that should be excluded from the search results,
 * since they have already been selected. These are passed from DAccessControl.
 *
 * prioritizeUserNameOrdering: for DAccessControl, we want to respect the prioritize_username_in_ux site setting and
 * show the name before the username in the search results depending on the setting.
 *
 * prioritizeGroupFullNameOrdering: for DAccessControl, we want to show the full
 * name before the group name in the search results.
 */
@selectKitOptions({
  excludedGrantees: undefined,
  prioritizeUserNameOrdering: true,
  prioritizeGroupFullNameOrdering: true,
  excludeGroupNameWhenMatchingFullName: true,
})
export default class DAccessControlGranteeChooser extends EmailGroupUserChooser {
  valueProperty = "value";

  async search(filter = "") {
    if (!filter) {
      return Promise.resolve(
        this.selectKit.options.customSearchOptions?.defaultSearchResults || []
      );
    }

    try {
      const results = await ajax(ACCESS_CONTROL_GRANTEE_SEARCH_URL, {
        data: {
          term: filter,
          acl_target: this.selectKit.options.aclTargetType,
        },
      });
      return this.excludeSelectedGrantees(
        this.normalizeGranteeResults(results)
      );
    } catch {
      return [];
    }
  }

  normalizeGranteeResults(results) {
    if (!results) {
      return [];
    }

    return [
      ...(results.groups || []).map((group) =>
        groupGranteeResult(group, this.isGranteeDisabled(group))
      ),
      ...(results.users || []).map((user) =>
        userGranteeResult(user, this.isGranteeDisabled(user))
      ),
    ];
  }

  excludeSelectedGrantees(results) {
    const excludedGrantees = this.selectKit.options.excludedGrantees || [];

    if (!excludedGrantees.length) {
      return results;
    }

    return results.filter((result) => !excludedGrantees.includes(result.value));
  }

  isGranteeDisabled(grantee) {
    const disabledGrantees = this.selectKit.options.disabledGrantees || [];

    return disabledGrantees.includes(granteeValue(grantee.type, grantee.id));
  }
}
import Component from "@glimmer/component";
import { cached } from "@glimmer/tracking";
import { fn, hash } from "@ember/helper";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { isEmpty } from "@ember/utils";
import DTooltip from "discourse/float-kit/components/d-tooltip";
import { AUTO_GROUPS } from "discourse/lib/constants";
import { prioritizeNameFallback } from "discourse/lib/settings";
import DAccessControlPermissionMenu from "discourse/ui-kit/d-access-control-permission-menu";
import dAvatar from "discourse/ui-kit/helpers/d-avatar";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";
import DAccessControlGranteeChooser, {
  granteeValue,
  groupGranteeResult,
} from "./d-access-control-grantee-chooser.gjs";

const EDIT_PERMISSION = "edit";
const OWNER_PERMISSION = "owner";
const READ_ONLY_PERMISSION = "view";
const READ_ONLY_DEFAULT_AUTO_GROUPS = [
  AUTO_GROUPS.anonymous_users.id,
  AUTO_GROUPS.everyone.id,
  AUTO_GROUPS.trust_level_0.id,
];
const ROW_TYPE_SORT_ORDER = {
  group: 0,
  user: 1,
};
const REMOVE_ACTION = {
  id: "remove",
  name: i18n("access_control.manage.access_permission_remove"),
  description: i18n(
    "access_control.manage.access_permission_remove_description"
  ),
};

function ownerOption(target) {
  return {
    id: OWNER_PERMISSION,
    name: i18n("access_control.manage.access_permission_owner"),
    description: target
      ? i18n("access_control.manage.access_permission_owner_description", {
          target,
        })
      : undefined,
  };
}

export function defaultPermissions() {
  return [
    {
      id: READ_ONLY_PERMISSION,
      level: 1,
      name: i18n("access_control.manage.access_permission_viewer"),
      description: i18n(
        "access_control.manage.access_permission_viewer_description"
      ),
    },
    {
      id: EDIT_PERMISSION,
      level: 2,
      name: i18n("access_control.manage.access_permission_editor"),
      description: i18n(
        "access_control.manage.access_permission_editor_description"
      ),
    },
  ];
}

function rowTypeSortOrder(type) {
  return ROW_TYPE_SORT_ORDER[type] ?? 2;
}

export default class DAccessControl extends Component {
  @service site;

  constructor() {
    super(...arguments);
    this.permissionOptions = this.buildPermissionOptions();
  }

  /**
   * Mandatory permissions are defined per-target server-side via a mandatory_acl
   * method, which is attached to the Site JSON. Any mandatory permissions will
   * be added to the ACL and cannot be removed or changed in the UI.
   */
  @cached
  get mandatoryAcl() {
    if (!this.args.aclTarget) {
      return [];
    }

    return (
      this.site.access_control?.mandatory_acl?.[
        this.args.aclTarget.key ?? this.args.aclTarget.type
      ] || []
    );
  }

  /**
   * Banned permissions are defined per-target server-side via a banned_acl
   * method, similar to mandatory_acl, which is attached to the Site JSON.
   * Any banned permisions will be filtered out, e.g. the `edit` permission might
   * be banned for the `anonymous_users` auto group ID.
   */
  @cached
  get bannedAcl() {
    if (!this.args.aclTarget) {
      return [];
    }

    return (
      this.site.access_control?.banned_acl?.[
        this.args.aclTarget.key ?? this.args.aclTarget.type
      ] || []
    );
  }

  /**
   * Construct the ACL for the target by combining the mandatory ACL with the
   * ACL passed in via args.  The ACL passed in via args will be whatever is
   * saved to the database for the target, so for new records this will be an
   * empty array.
   */
  get acl() {
    if (!this.mandatoryAcl.length) {
      return this.args.acl || [];
    }

    const mandatoryEntryKeys = new Set(
      this.mandatoryAcl.map((entry) => granteeValue(entry.type, entry.id))
    );

    // The passed in ACL (if any) without the mandatory entries, which are
    // added back in below.
    const resolvedAcl = (this.args.acl || []).filter(
      (entry) => !mandatoryEntryKeys.has(granteeValue(entry.type, entry.id))
    );

    this.mandatoryAcl.forEach((entry) => {
      // NOTE (martin) This is groups only for now...not sure we will need mandatory
      // user ACLs, but we can figure that out later.
      if (entry.type === "group") {
        const group = (this.args.groups || []).find((g) => g.id === entry.id);
        if (group) {
          resolvedAcl.push({
            type: "group",
            id: entry.id,
            name: group.name,
            display_name: group.full_name || group.name,
            permission: entry.permission,
            metadata: {
              auto_group: group.automatic,
            },
            mandatory: true,
          });
        }
      }
    });

    return resolvedAcl;
  }

  get rows() {
    const mappedAcl = this.acl.map((entry) => {
      const hydratedEntry = this.#hydrateDisplayName({ ...entry });

      return {
        key: `${granteeValue(hydratedEntry.type, hydratedEntry.id)}:${hydratedEntry.permission}`,
        id: hydratedEntry.id,
        permission: hydratedEntry.permission,
        display_name: hydratedEntry.display_name,
        sort_name:
          hydratedEntry.sort_name ||
          hydratedEntry.name ||
          hydratedEntry.display_name,
        username: hydratedEntry.username,
        name: hydratedEntry.name,
        avatar_template: hydratedEntry.avatar_template,
        type: hydratedEntry.type,
        mandatory:
          hydratedEntry.permission !== OWNER_PERMISSION &&
          Boolean(hydratedEntry.mandatory),
        owner: hydratedEntry.permission === OWNER_PERMISSION,
        permission_menu_disabled:
          hydratedEntry.permission === OWNER_PERMISSION
            ? !this.args.canManageOwners
            : Boolean(hydratedEntry.mandatory),
      };
    });

    return mappedAcl.sort((a, b) => {
      if (a.mandatory !== b.mandatory) {
        return a.mandatory ? -1 : 1;
      }

      if (a.owner !== b.owner) {
        return a.owner ? -1 : 1;
      }

      const nameSort = (a.sort_name || "").localeCompare(b.sort_name || "");

      if ((a.mandatory && b.mandatory) || (a.owner && b.owner)) {
        return nameSort;
      }

      if (a.type !== b.type) {
        return rowTypeSortOrder(a.type) - rowTypeSortOrder(b.type);
      }

      return nameSort;
    });
  }

  /**
   * The default available grantees which are shown in the preloaded
   * search results for DAccessControlGranteeChooser. This is used to show
   * the available groups which can be added to the ACL, with users
   * gated behind an async search request.
   */
  get defaultAvailableGrantees() {
    return this.availableGroups.map((group) =>
      groupGranteeResult(
        group,
        this.disabledGrantees.includes(granteeValue("group", group.id))
      )
    );
  }

  get availableGroups() {
    const takenGroupIds = new Set(
      this.acl
        .filter((entry) => entry.type === "group")
        .map((entry) => entry.id)
    );

    return (this.args.groups || [])
      .filter((group) => !takenGroupIds.has(group.id))
      .sort((a, b) => {
        if (a.automatic !== b.automatic) {
          return a.automatic ? -1 : 1;
        }

        return (a.full_name || a.name).localeCompare(b.full_name || b.name);
      });
  }

  /**
   * Grantees which should not show in the search results for
   * DAccessControlGranteeChooser. This is used to prevent users from adding the
   * same grantee (a user or group) multiple times.
   */
  get excludedGrantees() {
    return this.acl.map((entry) => granteeValue(entry.type, entry.id));
  }

  /**
   * Grantees where it's impossible for them to be added because of a combination
   * of banned ACL rules, e.g. if the anonymous_users group cannot view, edit, or
   * manage. We disable so we can show a message/tooltip so it's not confusing
   * where the grantee went.
   */
  get disabledGrantees() {
    return this.availableGroups
      .filter((group) => {
        const availablePermissions = this.excludeBannedPermissions(
          this.permissionOptions.filter((opt) => opt.id !== REMOVE_ACTION.id),
          { type: "group", id: group.id }
        );

        return availablePermissions.length === 0;
      })
      .map((group) => granteeValue("group", group.id));
  }

  /**
   * If a transformPermissionOptions function is provided, it is passed all
   * default permissions and can change the name, description, or level of
   * these options, OR add new options, returning the new array.
   *
   * The level property is used to sort the options, and is an indicator
   * of the level of access the permission provides, since e.g. Edit is a
   * higher level of access than View, and to Edit by definition you need
   * to be able to View.
   *
   * Otherwise, the default permissions are used.
   */
  buildPermissionOptions() {
    const permissions = (
      this.args.transformPermissionOptions?.(defaultPermissions()) ||
      defaultPermissions()
    ).filter((permission) => permission.id !== OWNER_PERMISSION);

    return [...permissions.sort((a, b) => a.level - b.level), REMOVE_ACTION];
  }

  /**
   * Fired when a grantee is chosen from the DAccessControlGranteeChooser
   * search results.
   */
  @action
  onGranteeChosen(_value, selectedGrantees) {
    const selectedGrantee = selectedGrantees?.[0];

    const isReadOnlyDefaultGroup =
      selectedGrantee.aclType === "group" &&
      READ_ONLY_DEFAULT_AUTO_GROUPS.includes(selectedGrantee.aclId);

    const newPermission = {
      id: selectedGrantee.aclId,
      type: selectedGrantee.aclType,
      permission: isReadOnlyDefaultGroup
        ? READ_ONLY_PERMISSION
        : EDIT_PERMISSION,
    };

    if (selectedGrantee.aclType === "group") {
      newPermission.name = selectedGrantee.id;
      newPermission.display_name =
        selectedGrantee.full_name || selectedGrantee.id;
      newPermission.metadata = {
        auto_group: selectedGrantee.automatic,
      };
    }

    if (selectedGrantee.aclType === "user") {
      const sortName =
        selectedGrantee.sort_name ||
        selectedGrantee.name ||
        selectedGrantee.display_name ||
        selectedGrantee.username;

      newPermission.username = selectedGrantee.username;
      newPermission.name = selectedGrantee.name;
      newPermission.sort_name = sortName;
      newPermission.display_name = prioritizeNameFallback(
        selectedGrantee.name,
        selectedGrantee.username
      );
      newPermission.avatar_template = selectedGrantee.avatar_template;
    }

    const next = [...this.acl, newPermission];

    this.args.onChange(next);
  }

  @action
  onRowPermissionChange(granteeType, granteeId, permission) {
    if (permission === REMOVE_ACTION.id) {
      this.args.onChange(
        this.acl.filter(
          (entry) => !(entry.type === granteeType && entry.id === granteeId)
        )
      );
      return;
    }

    const next = this.acl.map((entry) =>
      entry.type === granteeType && entry.id === granteeId
        ? { ...entry, permission }
        : entry
    );

    this.args.onChange(next);
  }

  /**
   * Certain ACL permissions are banned so we need to filter these out
   * based on grantee type and the available permissions for a row.
   */
  @action
  excludeBannedPermissions(permissions, grantee) {
    if (!this.bannedAcl.length) {
      return permissions;
    }

    return permissions.filter((permission) => {
      return !this.bannedAcl.some(
        (banned) =>
          banned.permission === permission.id &&
          banned.type === grantee.type &&
          banned.id === grantee.id
      );
    });
  }

  @action
  permissionOptionsFor(row) {
    const ownerOptionForTarget = ownerOption(this.args.aclTarget?.name);

    if (row.owner) {
      return this.args.canManageOwners
        ? [ownerOptionForTarget, REMOVE_ACTION]
        : [ownerOptionForTarget];
    }

    const permissionOptions = this.excludeBannedPermissions(
      this.permissionOptions,
      row
    );

    if (row.type === "user" && this.args.canManageOwners && !this.args.isNew) {
      return [
        ...permissionOptions.filter(
          (permission) => permission.id !== REMOVE_ACTION.id
        ),
        ownerOptionForTarget,
        REMOVE_ACTION,
      ];
    }

    return permissionOptions;
  }

  #hydrateDisplayName(entry) {
    if (!isEmpty(entry.display_name)) {
      return entry;
    }

    if (entry.type === "group") {
      const group = (this.args.groups || []).find(({ id }) => id === entry.id);
      entry.display_name = group?.full_name || group?.name;
    } else if (entry.type === "user") {
      entry.display_name = prioritizeNameFallback(entry.name, entry.username);
    }

    return entry;
  }

  <template>
    <div class="d-access-control">
      <DAccessControlGranteeChooser
        class="d-access-control__chooser"
        @filterPlaceholder="access_control.manage.add_group"
