import Component from "@glimmer/component";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { ajax } from "discourse/lib/ajax";
import DAccessControl from "discourse/ui-kit/d-access-control";
import { i18n } from "discourse-i18n";

export default class DAccessControlField extends Component {
  @service site;
  @service dialog;

  get name() {
    return this.args.name ?? "acl";
  }

  @action
  async validateAccess(name, value, { addError, preventSubmit }) {
    const acl = value || [];

    if (this.args.mustHavePermissions) {
      if (
        !acl.some((entry) =>
          this.args.mustHavePermissions.includes(entry.permission)
        )
      ) {
        addError(name, {
          title: this.args.title,
          message: i18n("access_control.manage.required_permission_not_added", {
            permission: this.args.mustHavePermissions.join(", "),
            typeName: this.args.aclTarget.name,
          }),
        });
      }
    }

    if (
      this.args.aclTarget.id &&
      !acl.some(
        (entry) => entry.type === "user" && entry.permission === "owner"
      )
    ) {
      addError(name, {
        title: this.args.title,
        message: i18n("access_control.manage.owner_required", {
          typeName: this.args.aclTarget.name,
        }),
      });
    }

    let evaluation = {};

    try {
      await ajax("/access-control/evaluate.json", {
        type: "POST",
        contentType: "application/json",
        data: JSON.stringify({
          target_type: this.args.aclTarget.type,
          target_id: this.args.aclTarget.id,
          new_acl: acl,
        }),
      });
    } catch (err) {
      if (
        !Object.hasOwn(
          err.jqXHR.responseJSON.extras,
          "current_user_will_lose_permission"
        )
      ) {
        addError(name, {
          title: this.args.title,
          message: i18n("generic_error"),
        });
        return;
      } else {
        // extras is where we store current_user_will_lose_permission and loss_warning_permissions
        Object.assign(evaluation, err.jqXHR.responseJSON.extras);
        evaluation.errorMessage = err.jqXHR.responseJSON.errors[0];
      }
    }

    if (!evaluation.current_user_will_lose_permission) {
      return;
    }

    const confirmed = await this.dialog.confirm({
      message: evaluation.errorMessage,
    });

    if (!confirmed) {
      preventSubmit();
      return;
    }

    this.args.onAccessLossConfirmed?.({
      permissions: evaluation.loss_warning_permissions ?? [],
    });
  }

  <template>
    <@form.Field
      @description={{@description}}
      @format="max"
      @name={{this.name}}
      @onSet={{@onSet}}
      @showOptional={{@showOptional}}
      @title={{@title}}
      @type="custom"
      @validate={{this.validateAccess}}
      @validation={{@validation}}
      as |field|
    >
      <field.Control>
        <DAccessControl
          @acl={{field.value}}
          @aclTarget={{@aclTarget}}
          @canManageOwners={{@canManageOwners}}
          @groups={{this.site.groups}}
          @isNew={{@isNew}}
          @onChange={{or @onChange field.set}}
          @transformPermissionOptions={{@transformPermissionOptions}}
        />
      </field.Control>
    </@form.Field>
  </template>
}
import Component from "@glimmer/component";
import type Owner from "@ember/owner";
import { service } from "@ember/service";
import { animatedEmojiUrlFor, emojiUrlFor } from "discourse/lib/text";
import type EmojiStoreService from "discourse/services/emoji-store";

interface DAnimatedEmojiSignature {
  Args: {
    /** The emoji's name, optionally with a skin tone (`clap`, `clap:t3`). */
    code: string;
    /** Translated tooltip and alternative text. Defaults to the emoji's name. */
    title?: string;
  };
  Element: HTMLImageElement;
}

/**
 * Renders an emoji animated, when an animation exists for it and the user
 * hasn't asked for reduced motion; otherwise renders the site's static image,
 * as do custom emojis. Renders nothing when emojis are disabled or the name is
 * unknown.
 */
export default class DAnimatedEmoji extends Component<DAnimatedEmojiSignature> {
  @service declare emojiStore: EmojiStoreService;

  constructor(owner: Owner, args: DAnimatedEmojiSignature["Args"]) {
    super(owner, args);
    // Which emojis are animated comes with the emoji list; until it loads,
    // and if it fails to, the static image stands in.
    if (animatedEmojiUrlFor(this.code)) {
      this.emojiStore.loadList().catch(() => {});
    }
  }

  get code() {
    return this.args.code.toLowerCase();
  }

  get staticUrl(): string | undefined {
    return emojiUrlFor(this.code);
  }

  get animatedUrl(): string | undefined {
    if (this.emojiStore.isAnimated(this.code)) {
      return animatedEmojiUrlFor(this.code);
    }
  }

  get title() {
    return this.args.title ?? this.code;
  }

  <template>
    {{#if this.staticUrl}}
      <picture class="d-animated-emoji">
        {{#if this.animatedUrl}}
          <source
            media="(prefers-reduced-motion: no-preference)"
            srcset={{this.animatedUrl}}
            type="image/avif"
          />
        {{/if}}
        <img
          alt={{this.title}}
          class="emoji d-animated-emoji__image"
          src={{this.staticUrl}}
          title={{this.title}}
          ...attributes
        />
      </picture>
    {{/if}}
  </template>
}
