import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { trustHTML } from "@ember/template";
import PostCookedHtml from "discourse/components/post/cooked-html";
import userPrioritizedName from "discourse/helpers/user-prioritized-name";
import { relativeAge } from "discourse/lib/formatter";
import DiscourseURL from "discourse/lib/url";
import DButton from "discourse/ui-kit/d-button";
import DRelativeDate from "discourse/ui-kit/d-relative-date";
import DUserLink from "discourse/ui-kit/d-user-link";
import dBoundAvatarTemplate from "discourse/ui-kit/helpers/d-bound-avatar-template";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import dOnResize from "discourse/ui-kit/modifiers/d-on-resize";
import { i18n } from "discourse-i18n";

export default class DPostAccordionItem extends Component {
  @service a11y;

  @tracked measured = false;
  @tracked isOverflowing = false;

  get post() {
    return this.args.post;
  }

  get quoteId() {
    return `post-accordion-item-${this.post.topic_id}-${this.post.post_number}`;
  }

  get hasContent() {
    return !!this.post?.cooked;
  }

  get srDate() {
    if (this.a11y.autoUpdatingRelativeDateRef && this.post.created_at) {
      return relativeAge(new Date(this.post.created_at), {
        format: "medium-with-ago",
        wrapInSpan: false,
      });
    }
  }

  get userDisplayName() {
    return userPrioritizedName({
      username: this.post.username,
      name: this.post.name,
    });
  }

  get maxHeightStyle() {
    if (this.args.linesDisplayed) {
      return trustHTML(`--max-lines-displayed: ${this.args.linesDisplayed}`);
    }
  }

  get overflowingAttr() {
    return this.measured ? String(this.isOverflowing) : "true";
  }

  @action
  onClickHeader(event) {
    if (event.target.closest("a")) {
      return;
    }

    if (this.hasContent) {
      this.args.onToggleExpanded();
    } else {
      DiscourseURL.routeTo(this.post.url);
    }
  }

  @action
  checkOverflow(entries) {
    if (!this.args.isExpanded) {
      this.isOverflowing = false;
      this.measured = true;
    }

    const blockquote = entries?.[0]?.target;
    if (!blockquote) {
      return;
    }

    this.isOverflowing = blockquote.scrollHeight > blockquote.clientHeight + 1;
    this.measured = true;
  }

  <template>
    {{#if this.post}}
      <div
        class={{dConcatClass
          "quote d-post-accordion-item"
          (if this.hasContent "d-post-accordion-item--has-content")
        }}
        data-expanded={{@isExpanded}}
        data-overflowing={{this.overflowingAttr}}
        data-post={{this.post.post_number}}
        data-topic={{this.post.topic_id}}
        data-username={{this.post.username}}
        style={{this.maxHeightStyle}}
      >
        {{! eslint-disable ember/template-no-invalid-interactive }}
        <div
          class="d-post-accordion-item__header"
          {{on "click" this.onClickHeader}}
        >
          <div class="d-post-accordion-item__metadata">
            {{#if @hasItemMetadataBlock}}
              {{yield this.post to="itemMetadata"}}
            {{else}}
              <DUserLink class="user-link" @username={{this.post.username}}>
                {{dBoundAvatarTemplate this.post.avatar_template "tiny"}}
                <span>{{this.userDisplayName}}</span>
              </DUserLink>
              <span class="dot-separator"></span>
              <a
                aria-label={{this.srDate}}
                class="date-link"
                href={{this.post.url}}
                title={{i18n "post.sr_date"}}
              >
                <span aria-hidden="true">
                  <DRelativeDate @date={{this.post.created_at}} />
                </span>
              </a>
            {{/if}}
          </div>
          <div class="d-post-accordion-item__controls">
            {{#if this.hasContent}}
              <DButton
                class="btn-flat d-post-accordion-item__toggle"
                @action={{@onToggleExpanded}}
                @ariaExpanded={{@isExpanded}}
                @ariaLabel={{if @isExpanded "post.collapse" "expand"}}
                @icon={{if @isExpanded "chevron-up" "chevron-down"}}
                @title={{if @isExpanded "post.collapse" "expand"}}
              />
            {{else}}
              <DButton
                class="btn-flat d-post-accordion-item__jump"
                @ariaLabel="post.follow_quote"
                @href={{this.post.url}}
                @icon="arrow-down"
                @title="post.follow_quote"
              />
            {{/if}}
          </div>
        </div>

        {{#if this.hasContent}}
          <div class="d-post-accordion-item__body">
            <blockquote
              class="d-post-accordion-item__content"
              id={{this.quoteId}}
              {{dOnResize this.checkOverflow}}
            >
              {{#if @hasBeforeItemContentBlock}}
                {{yield this.post to="beforeItemContent"}}
              {{/if}}

              <PostCookedHtml
                @decoratorState={{@decoratorState}}
                @post={{this.post}}
              />

            </blockquote>

            <div class="d-post-accordion-item__read-more">
              <a class="read-more-link" href={{this.post.url}}>
                {{i18n "read_more"}}
              </a>
            </div>
          </div>
        {{/if}}
      </div>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import { fn } from "@ember/helper";
import { action } from "@ember/object";
import { trackedSet } from "@ember/reactive/collections";
import didUpdate from "@ember/render-modifiers/modifiers/did-update";
import DPostAccordionItem from "./d-post-accordion-item.gjs";

export default class DPostAccordion extends Component {
  expandedIds = trackedSet();

  constructor() {
    super(...arguments);

    this.resetExpandedIds();
  }

  get posts() {
    return this.args.posts ?? [];
  }

  get allExpanded() {
    return this.posts.every((post) => this.expandedIds.has(post.id));
  }

  @action
  resetExpandedIds() {
    const defaultExpanded = this.args.defaultExpanded;

    this.expandedIds.clear();

    switch (defaultExpanded) {
      case "all":
        this.posts.forEach((post) => this.expandedIds.add(post.id));
        break;
      case "none":
        break;
      case "first":
      case "":
      default:
        const firstPostId = this.args.posts?.[0]?.id;
        if (firstPostId) {
          this.expandedIds.add(firstPostId);
        }
    }
  }

  @action
  toggleAllExpanded() {
    if (this.allExpanded) {
      this.resetExpandedIds();
    } else {
      this.posts.forEach((post) => this.expandedIds.add(post.id));
    }
  }

  @action
  toggleItemExpanded(postId) {
    this.expandedIds.has(postId)
      ? this.expandedIds.delete(postId)
      : this.expandedIds.add(postId);
  }

  @action
  itemIsExpanded(postId) {
    return this.expandedIds.has(postId);
  }

  <template>
    {{#if this.posts.length}}
      <aside
        class="d-post-accordion"
        ...attributes
        {{didUpdate this.resetExpandedIds this.posts}}
      >
        <div class="d-post-accordion__layout">
          <div class="d-post-accordion__header">
            {{#if (has-block "header")}}
              {{yield this.posts to="header"}}
            {{/if}}
          </div>

          <div class="d-post-accordion__items">
            {{#each this.posts as |post|}}
              <DPostAccordionItem
                @decoratorState={{@decoratorState}}
                @hasBeforeItemContentBlock={{has-block "beforeItemContent"}}
                @hasItemMetadataBlock={{has-block "itemMetadata"}}
                @isExpanded={{this.itemIsExpanded post.id}}
                @linesDisplayed={{@linesDisplayed}}
                @onToggleExpanded={{fn this.toggleItemExpanded post.id}}
                @post={{post}}
              >

                <:itemMetadata>
                  {{yield post to="itemMetadata"}}
                </:itemMetadata>

                <:beforeItemContent>
                  {{yield post to="beforeItemContent"}}
                </:beforeItemContent>
              </DPostAccordionItem>
            {{/each}}
          </div>
        </div>
      </aside>
    {{/if}}
  </template>
}
import type { ComponentLike } from "@glint/template";

/**
 * One normalized move, as both input methods report it. The indices and item
 * arrays all describe the VISIBLE list — the `items` the consumer passed —
 * never a backing store the consumer may keep behind it.
 */
export interface ReorderableMove<T = unknown> {
  /** How the user asked for the move. */
  method: "drag" | "menu" | "keyboard";

  /** The item that moved, resolved against the current items at commit time. */
  item: T;

  /** The list the item left. Always `"default"` for a standalone list. */
  fromList: string;

  /** The list the item entered. Always `"default"` for a standalone list. */
  toList: string;

  /** The item's visible index before the move. */
  fromIndex: number;

  /** The item's visible index after the move. */
  toIndex: number;

  /** The source list's visible items before the move. */
  fromItems: readonly T[];

  /**
   * The destination list's visible items before the move. The same array as
   * `fromItems` for an in-list move.
   */
  toItems: readonly T[];

  /** The source list's proposed visible order after the move. */
  proposedFromItems: readonly T[];

  /**
   * The destination list's proposed visible order after the move. The same
   * array as `proposedFromItems` for an in-list move.
   */
  proposedToItems: readonly T[];
}

/**
 * The row's own position and its pre-wired controls, yielded to `<:row>`
 * beside the item. Conventionally bound as `controls`, matching the
 * `@controls` argument that decides whether the list places them or the
 * consumer does.
 */
export interface ReorderableRowApi {
  /** The row's index in the visible list. */
  index: number;

  /** Whether the row occupies the first movable slot. */
  isFirst: boolean;

  /** Whether the row occupies the last movable slot. */
  isLast: boolean;

  /** Whether the row can be reordered at all. */
  movable: boolean;

  /**
   * The pre-wired handle for this row. Yielded only under `@controls="manual"`
   * on a movable row that renders a handle: one with a reachable destination,
   * or any grouped row, whose handle stays the cross-list drag source. It is
   * the drag source and the move menu's trigger at once, so a row yielded one
   * must place it; a development assertion fires when one does not.
   */
  handle?: ComponentLike<{ Element: HTMLElement }>;

  /**
   * The pre-wired remove control. Yielded only under `@controls="manual"` on a
   * movable, removable row when `onRemove` is set; a frozen row yields no
   * controls at all. Carries its own accessible name; everything visual passes
   * through.
   */
  remove?: ComponentLike<{
    Args: { buttonClass?: string };
    Element: HTMLElement;
  }>;
}

/** The context handed to a `@rowClass` function. */
export interface RowClassContext {
  index: number;
  movable: boolean;
}

/**
 * What a member list registers with its group: identity, the optional
 * translated list name for cross-list announcements, and closures reading the
 * member's live state — closures rather than snapshots, so a drop resolves
 * against the source list as it stands at drop time.
 */
export interface ReorderableGroupMember {
  listId: string;

  /** Whether the member currently refuses every move. */
  disabled: () => boolean;

  /** The member's current translated name. */
  listLabel: () => string | undefined;

  /** The member's current visible items. */
  getItems: () => readonly unknown[];

  /**
   * The member's root element, for resolving which member sits next to which
   * in document order. Undefined before the member has rendered.
   */
  element: () => HTMLElement | undefined;

  /**
   * The source half of a cross-list move: resolves the dragged key against
   * the member's current rows and returns the item, its visible index, and
   * the member's proposed order without it — or `undefined` when the key no
   * longer resolves to a movable row.
   */
  removalProjection: (key: string) =>
    | {
        item: unknown;
        fromIndex: number;
        proposedFromItems: readonly unknown[];
      }
    | undefined;

  /**
   * The destination half of a cross-list move, as the menu path calls it. A
   * drop already runs on the destination, but a menu item runs on the source,
   * so the source reaches across to the member that owns the projections and
   * the announcement for where the item is landing.
   *
   * @param sourceListId - The member the item is leaving.
   * @param key - The moved row's key in that member.
   * @param toIndex - The visible landing index in this member.
   * @param method - Which input method asked, carried across so a spilled
   *   accelerator is not reported to the consumer as a menu choice.
   */
  acceptMove: (
    sourceListId: string,
    key: string,
    toIndex: number,
    method: "menu" | "keyboard"
  ) => ReorderableMove | null;
}

/**
 * The API a `DReorderableListGroup` yields to its block. Member lists receive
 * it as `@group`; everything on it is wiring between the group and its
 * members rather than a consumer surface. `T` is the item type the group's
 * `@onMove` takes, which every member list's items must match.
 */
export interface ReorderableGroupApi<T = unknown> {
  /**
   * The shared drag discriminator. Members adopt it in place of their own, so
   * drags travel freely inside the group and nowhere else.
   */
  token: string;

  /** Lets projections react without tracking the construction-time registry. */
  generation: () => number;

  /** Adds a member; returns its deregistration. Duplicate listIds assert. */
  registerMember: (member: ReorderableGroupMember) => () => void;

  /** The member registered under a listId, if it still exists. */
  lookupMember: (listId: string) => ReorderableGroupMember | undefined;

  /**
   * The other members registered right now, in document order, as the move
   * menu's cross-list destinations. Only enabled members carrying a
   * `listLabel` are returned: an unnamed destination has nothing to put in the
   * menu item, so it stays pointer-only rather than offering "Move to
   * undefined".
   */
  siblings: (listId: string) => { listId: string; listLabel: string }[];

  /**
   * The member immediately before or after another **in reading order**, which
   * is what a row spilling past its own list's end travels into. Disabled
   * members are skipped because they cannot accept the spill.
   *
   * Reading order, not screen position or registration order: the group cannot
   * see where its members landed, and registration order stops matching the
   * document as soon as the members themselves are reordered. `spill` is
   * opt-in because "next in the document" meaning "next on screen" is the
   * consumer's claim to make.
   *
   * @param listId - The member to look out from.
   * @param direction - Which way along the document to look.
   */
  neighbour: (
    listId: string,
    direction: "previous" | "next"
  ) => ReorderableGroupMember | undefined;

  /** The group's single move callback, shared by every member. */
  onMove: (move: ReorderableMove<T>) => void | false;
}

/**
 * The internal per-row view model the component renders from. Rows are
 * recomputed from `@items` on every relevant change, so anything an event
 * handler needs later is re-resolved by `key` rather than captured.
 */
export interface Row<T> {
  item: T;
  key: string;
  index: number;
  movable: boolean;
  isFirst: boolean;
  isLast: boolean;
  /** Whether stepping in this direction lands anywhere the row is not already. */
  canMoveUp: boolean;
  canMoveDown: boolean;

  /**
   * Whether the move menu has a reachable destination. A grouped row may still
   * render a handle as its cross-list drag source when this is false.
   */
  hasDestinations: boolean;

  /**
   * Whether the row renders a handle. What the arrow cursor lands on: the
   * handle where this is true, the row element itself where it is not.
   */
  rendersHandle: boolean;

  /** The row's own accessible name: what the reader is moving. */
  label: string;
  handleLabel: string;

  /** Shared by the row's `aria-describedby` and its handle's description. */
  descriptionId: string;

  /** Whether this row may be removed at all. */
  removable: boolean;

  /** The remove control's accessible name. */
  removeLabel: string;
  yieldControls: boolean;
}

export interface DReorderableListSignature<T> {
  Args: {
    /**
     * The visible items in display order. The component reasons, indexes, and
     * announces only in this list; projecting a reorder onto hidden backing
     * storage stays with the consumer. Never mutated by the component.
     */
    items: readonly T[];

    /**
     * Property path resolving each item's stable identity, used for keyed
     * rendering and for resolving drag payloads at drop time. The literal
     * value `"@index"` opts into index-based identity for primitive
     * collections whose values may repeat. Omitted, object identity is used,
     * which is only safe when the same objects are passed on every render.
     *
     * Index identity is positional by definition: after a move, rows keep
     * their positions while items flow through them, so focus and drag state
     * stay with a position rather than following the moved item. That is how
     * position-addressed value lists already behave, and is the trade-off
     * accepted when items carry no identity of their own.
     */
    key?: string;

    /**
     * Translated display name for an item. It names the drag handle, the
     * remove control, and the announcements, so every control stays
     * distinguishable when read out of context.
     */
    label: (item: T) => string;

    /**
     * The single move callback. Pointer drops and arrow presses both arrive
     * here, already normalized and no-op-suppressed. Return `false` to veto
     * the announcement; the consumer then owns whatever feedback replaces it.
     * Required for a standalone list; a grouped member omits it — the group's
     * own callback receives every member move instead.
     */
    onMove?: (move: ReorderableMove<T>) => void | false;

    /**
     * The API yielded by a surrounding `DReorderableListGroup`. Joining a
     * group makes cross-list moves between members possible and routes every
     * move through the group's callback. Requires `@listId`. Fixed at
     * construction: a list that must change groups is re-created, not
     * re-pointed. Every member carrying a `@listLabel` also becomes a
     * destination in the other members' move menus, which is how a cross-list
     * move is reachable without a pointer. The group's item type must match
     * `@items`, since the group's `@onMove` receives this list's moves.
     */
    group?: ReorderableGroupApi<NoInfer<T>>;

    /**
     * This member's identity inside its group. Required with `@group`, and
     * fixed at construction like the group itself.
     */
    listId?: string;

    /**
     * Translated name for this list, spoken in cross-list announcements when
     * an item lands here from another member, and shown as this list's
     * "Move to …" entry in every other member's move menu. Without it the
     * standard announcement is used and the list stays a pointer-only
     * destination.
     */
    listLabel?: string;

    /**
     * Whether a row refused at this list's own end carries on into the
     * adjacent group member instead. Requires `@group`; ignored without one.
     *
     * For members that read as one continuous run: moving down enters the next
     * member at the top and moving up enters the previous one at the bottom,
     * so the row keeps travelling the way it was pushed. The ends of the
     * outermost members still refuse and still announce it.
     *
     * **Setting this asserts that the group runs top to bottom in reading
     * order** — the only order the group can resolve. In a group laid out side
     * by side, Down would carry a row into the list beside it.
     *
     * Off by default, and not only for that reason: members that are genuinely
     * separate lists should stop at their own edges, with "Move to …" in the
     * menu as the deliberate way across.
     */
    spill?: boolean;

    /**
     * Rows failing this predicate are frozen: they render no controls, are
     * not drag sources, refuse drops, and keep their exact visible index in
     * every proposed order. Arrow moves hop over them. Defaults to every row
     * being movable.
     */
    movable?: (item: T) => boolean;

    /** Tag name for the list element. Defaults to `"ul"`. */
    tag?: string;

    /** Tag name for each row element. Defaults to `"li"`. */
    itemTag?: string;

    /** Optional ARIA role for the list element. */
    role?: string;

    /**
     * Optional ARIA role for each row element. Use roles that permit
     * interactive descendants (such as `row`): a role whose children are
     * presentational (`option`, `menuitem`, `tab`) flattens the rendered
     * controls out of the accessibility tree.
     */
    itemRole?: string;

    /**
     * Extra class(es) for the row element: a static string, or a function of
     * the item and its `{ index, movable }` state.
     */
    rowClass?: string | ((item: T, context: RowClassContext) => string);

    /**
     * Who places the row's handle. `"auto"` (the default) renders it ahead of
     * the row's block content; `"manual"` renders none and instead yields a
     * pre-wired `handle` component on the row API, for layouts where it must
     * occupy a specific cell, grid track, or position.
     *
     * There is deliberately no automatic "at the end": a handle is focusable,
     * so where it sits in the DOM is its position in the reading and focus
     * order, not decoration. A row that wants it last says so by placing it
     * last.
     */
    controls?: "auto" | "manual";

    /**
     * Read-only mode: rows render without controls and without any drag
     * wiring, as if every row were frozen.
     */
    disabled?: boolean;

    /**
     * Overrides the announcement for a committed move. Return the text to
     * announce, or `false` to suppress the announcement entirely. `onMove`
     * has already run either way.
     */
    announceMove?: (move: ReorderableMove<T>) => string | false;

    /**
     * Renders a create affordance after the rows: a text input and an add
     * button by default, or the `<:create>` block when one is given. The
     * default row is list-shaped (it renders as one extra item element), and
     * wraps its controls in a spanning cell when `@itemTag="tr"`. A table that
     * needs richer cell markup can supply its own `<:create>` block.
     */
    allowCreate?: boolean;

    /**
     * Reports that the reader asked to remove an item. Supplying it is what
     * renders the remove control: trailing the row's own content by default,
     * or wherever `controls.remove` is placed under `@controls="manual"`.
     *
     * The visible index comes with it, because an index-keyed list may hold
     * the same value twice and the item alone would not say which row went.
     *
     * The list announces the removal and puts focus somewhere sensible
     * afterwards; the handler's only job is to drop the item from its store.
     *
     * Return a promise to hold both back until the removal has actually
     * happened — what a confirmation in front of it needs, since the handler
     * is otherwise back long before the reader has answered. Either way the
     * list checks that an item really went before speaking, so a handler that
     * declines is not reported as a removal.
     */
    onRemove?: (item: T, index: number) => void | Promise<void>;

    /**
     * Whether an item may be removed, defaulting to all of them.
     *
     * Mirrors `@movable`, which renders no handle on a row that cannot move:
     * a row that cannot be removed renders no remove control either. A
     * permanently protected row would otherwise carry a dead tab stop that
     * announces itself as unavailable on every pass.
     */
    removable?: (item: T) => boolean;

    /**
     * The remove control's icon. One list-level argument rather than a
     * per-row one, because the control is placed by the list in every mode
     * except manual.
     */
    removeIcon?: string;

    /**
     * The remove control's button weight, defaulting to `btn-flat`. List-level
     * for the same reason as `removeIcon`: the control is placed by the list in
     * every mode except manual, where `controls.remove` takes its own
     * `@buttonClass` to override this.
     */
    removeButtonClass?: string;

    /**
     * Called with the trimmed value when the default create affordance is
     * submitted. Never called for an empty or whitespace-only value.
     */
    onCreate?: (value: string) => void;
  };
  Blocks: {
    /**
     * The contents of one row, rendered inside the row element the component
     * owns. Named rather than the implicit block because what it fills is not
     * obvious: a table shell yields `td`s into a `tr` the consumer never
     * writes, and `<:default>` gave no way to tell that from replacing the
     * row outright.
     */
    row: [item: T, row: ReorderableRowApi];

    /** Rendered inside the list element, before every row. */
    header: [];

    /**
     * Rendered before the header, for the visible sentence that teaches the
     * interaction ("Drag the handle, or press Enter for move options"). The
     * component never renders one of its own: a dense table wants no such
     * paragraph, and where it belongs on the page is the surface's call. The
     * screen-reader description on each handle is separate and always
     * present.
     */
    hint: [];

    /** Rendered in the rows' position when `@items` is empty. */
    empty: [];

    /**
     * Replaces the default create affordance when `@allowCreate` is set,
     * rendered after the rows.
     */
    create: [];
  };
  Element: HTMLElement;
}

/** Where a menu-driven move sends the row. */
export type MoveTarget = "up" | "down" | "top" | "bottom";
import Component from "@glimmer/component";
import { DEBUG } from "@glimmer/env";
import { assert } from "@ember/debug";
import { registerDestructor } from "@ember/destroyable";
import { fn } from "@ember/helper";
import { action } from "@ember/object";
import type Owner from "@ember/owner";
import willDestroy from "@ember/render-modifiers/modifiers/will-destroy";
import { isTrustedHTML, type TrustedHTML } from "@ember/template";
import dPointerDrag, {
  type DPointerDragInfo,
} from "discourse/ui-kit/modifiers/d-pointer-drag";

/** One of the eight compass directions of the built-in box resize. */
export type BoxDirection = "n" | "ne" | "e" | "se" | "s" | "sw" | "w" | "nw";

/**
 * The eight compass handles of a box resize, in clockwise order. The common
 * case (resizing a rectangle's edges + corners) — generated from `@handleClass`
 * so consumers don't repeat the list. Each handle's `payload` is its direction.
 */
export const BOX_DIRECTIONS: BoxDirection[] = [
  "n",
  "ne",
  "e",
  "se",
  "s",
  "sw",
  "w",
  "nw",
];

/**
 * One handle to render. The escape hatch from the built-in box: supply these
 * when the handles are not a rectangle's edges and corners.
 */
export interface DResizeHandleDescriptor<Payload extends string | number> {
  /**
   * What makes this handle itself. It must be unique among its siblings and
   * stable across recomputes, so that a list changing under a held pointer
   * destroys the handle that really went rather than the last one.
   *
   * Not derived from `payload`, which says what a handle means rather than which
   * one it is. Several handles can legitimately mean the same thing.
   */
  key: string;

  /** What the handle means. Handed back to every callback, and may repeat. */
  payload: Payload;

  /** Positions and styles the handle. */
  class?: string;

  /**
   * Inline positioning. Wrap the string in `trustHTML` before passing it here.
   * Only the caller knows whether the values it interpolated are safe, so this
   * component will not make that call for it.
   */
  style?: TrustedHTML;
}

/** What one gesture carries for as long as it runs. */
interface Gesture<Payload, Session> {
  payload: Payload;
  /** The element pressed, so its teardown can close this gesture. */
  handle: HTMLElement;
  /** The last report, so teardown can close the gesture at its last position. */
  event: PointerEvent;
  info: DPointerDragInfo;
  measured: Element | null;
  measuredRect: DOMRect | null;
  session: Session;
}

/**
 * The pointer geometry of a move, reported to every callback. Deliberately raw:
 * the consumer decides what a pixel delta means in its own units.
 *
 * Everything here is a snapshot of the moment it was handed over, EXCEPT
 * `session`, which is the one thing that lives for the gesture.
 */
export interface DResizeHandleDragInfo<
  Payload extends string | number,
  Session extends object = object,
> {
  /** The handle being dragged — the same value the callback's first argument carries. */
  readonly payload: Payload;

  /** The pointer event that produced this report. */
  readonly event: PointerEvent;

  /** Where the press landed, in client coordinates. */
  readonly origin: Readonly<{ x: number; y: number }>;

  /** Where the pointer is now, in client coordinates. */
  readonly current: Readonly<{ x: number; y: number }>;

  /** How far the pointer has travelled since the press. */
  readonly delta: Readonly<{ x: number; y: number }>;

  /**
   * Whether `@onResize` has fired at least once for THIS gesture. It tells a
   * resize apart from a click that landed on a handle. Commit on `@onResizeEnd`
   * only when it is set, or a bare click records a no-op change.
   */
  readonly moved: boolean;

  /**
   * Scratch for the length of one gesture, and the same object throughout it.
   *
   * Write the press-time snapshot here in `@onResizeStart` and read it back on
   * every later report. It lives here rather than on the consumer so that each
   * gesture starts with a fresh one.
   */
  readonly session: Session;

  /**
   * The element named by `@measure`, or `null` when none was named. Handed back
   * so a consumer that also needs the element itself (to paint a preview on it,
   * say) does not resolve it a second time.
   */
  readonly measured: Element | null;

  /**
   * The bounds of the element named by `@measure`, or `null` when none was
   * named. Viewport-relative, with transforms applied, so a consumer working in
   * unscaled units divides by the scale factor and subtracts `left` and `top`.
   *
   * A LIVE reading, re-read on scroll and viewport resize, so it stays correct
   * when the box moves under a held pointer. It is NOT re-read when the element
   * changes size, or on a layout shift or transform. Those raise no event.
   */
  readonly measuredRect: DOMRect | null;
}

/**
 * The box whose bounds a gesture reports: the element itself, or a function
 * receiving the pressed handle and returning it.
 */
type MeasureTarget =
  | Element
  | ((handle: HTMLElement) => Element | null | undefined);

interface DResizeHandlesSignature<
  Payload extends string | number,
  Session extends object = object,
> {
  Args: {
    /**
     * BEM block for the built-in 8-direction box. Each handle is classed
     * `<handleClass> --<dir>`. Ignored when `@handles` is supplied.
     */
    handleClass?: string;

    /**
     * A subset of the eight compass directions to render for the built-in box
     * (e.g. only the edges and corners that can actually move). Defaults to all
     * eight; ignored when `@handles` is supplied.
     */
    directions?: BoxDirection[];

    /**
     * Explicit handle descriptors. The escape hatch for anything that is not a
     * box — N column-gutter handles at computed offsets, say. Takes precedence
     * over `@handleClass`.
     */
    handles?: DResizeHandleDescriptor<Payload>[];

    /**
     * The gesture began. Snapshot the press-time state onto `dragInfo.session`
     * here. Return `false` to veto it.
     *
     * The callbacks sit in `NoInfer` positions so that `@handles` alone decides
     * the payload type. Without it a handler taking a number would infer
     * `Payload` as `number` on the built-in box, hiding a real mismatch.
     */
    onResizeStart?: (
      payload: NoInfer<Payload>,
      dragInfo: DResizeHandleDragInfo<NoInfer<Payload>, Session>
    ) => boolean | void;

    /** Fired on every move. Compute and preview here. */
    onResize?: (
      payload: NoInfer<Payload>,
      dragInfo: DResizeHandleDragInfo<NoInfer<Payload>, Session>
    ) => void;

    /**
     * Fired once on release, and on teardown for a gesture still held. Commit
     * here, guarded on `dragInfo.moved`.
     */
    onResizeEnd?: (
      payload: NoInfer<Payload>,
      dragInfo: DResizeHandleDragInfo<NoInfer<Payload>, Session>
    ) => void;

    /**
     * Fired when the gesture is cancelled rather than released, teardown with a
     * gesture still held included. Mutually exclusive with `@cancelCommits`,
     * which routes cancels to `@onResizeEnd` and so leaves this one unreachable.
     */
    onResizeCancel?: (
      payload: NoInfer<Payload>,
      dragInfo: DResizeHandleDragInfo<NoInfer<Payload>, Session>
    ) => void;

    /**
     * A class toggled on the active handle while it is being dragged. Under a
     * `@threshold` it waits for that distance, so a click on a handle never
     * looks like a resize.
     */
    draggingClass?: string;

    /**
     * Pixels of travel before `@onResize` starts firing and `@draggingClass`
     * goes on, to absorb the jitter of a click that was never meant to be a drag.
     */
    threshold?: number;

    /**
     * Whether a gesture cut short — `pointercancel`, a lost capture, or another
     * registration claiming the pointer — reports through `@onResizeEnd` rather
     * than `@onResizeCancel`, leaving the latter unreachable.
     *
     * A consumer that commits the terminal event's position must NOT set this: a
     * cancel carries no position the user chose, so the commit would write a
     * coordinate the pointer was never at.
     */
    cancelCommits?: boolean;

    /**
     * The box being resized, so it and its bounds ride along on every report.
     * Either the element, or a function receiving the pressed handle and
     * returning it. See `measuredRect` for what is and is not re-read.
     */
    measure?: MeasureTarget;

    /**
     * Whether an accepted press stops propagating. Defaults to `false`, because
     * document-level listeners need to see `pointerdown`. Set it when the handles
     * sit inside another gesture that would otherwise steal the pointer.
     */
    stopPropagation?: boolean;
  };
}

/**
 * Renders a set of drag handles and drives each through the pointer-drag
 * lifecycle, owning what every consumer would otherwise repeat: the handle loop,
 * the per-handle pointer wiring, and one gesture's state for as long as it runs.
 *
 * It reports pointer geometry rather than a size. The consumer does the math in
 * its own units, paints its own preview, and commits on `@onResizeEnd`.
 *
 * Every gesture ends with exactly one terminal callback, whether it ends on
 * release, on its handle being removed, or on the component being destroyed.
 * Each gesture carries a `session` for press-time state.
 *
 * ONE gesture at a time. A press arriving while another is held is refused, so
 * two handles on one box can never fight over the same geometry. Two separate
 * boxes still drag at once, because each renders its own handles.
 *
 * The common case, a box's 8 edge and corner handles, is built in through
 * `@handleClass`. Anything else passes explicit `@handles` descriptors.
 *
 * @example
 * Box (edges + corners) from a BEM block:
 * ```gjs
 * <DResizeHandles @handleClass="my-block__handle" @onResize={{this.onResize}} />
 * ```
 *
 * @example
 * Escape hatch — explicit descriptors:
 * ```gjs
 * <DResizeHandles @handles={{this.columnHandles}} @onResize={{this.onResize}} />
 * ```
 *
 * `role="separator"` is wrong here and must not be used: a box resized from its
 * corners has no single value to report.
 *
 * Deliberately POINTER-ONLY. The handles are `aria-hidden` and out of the tab
 * order: eight tab stops per box would be hostile, and no ARIA role describes a
 * corner drag. Put keyboard resizing on the resized object itself.
 *
 * @see The `DResizeSeparator` component for a ONE-axis resize between two regions, which is
 *   operable by keyboard and announced.
 * @see The `dOnResize` modifier to merely OBSERVE a size change. It is not a gesture.
 */
export default class DResizeHandles<
  Payload extends string | number = BoxDirection,
  Session extends object = object,
> extends Component<DResizeHandlesSignature<Payload, Session>> {
  /** The gesture in flight, or `null` when nothing is held. */
  #gesture: Gesture<Payload, Session> | null = null;

  /**
   * Re-measures the live gesture's box.
   *
   * Bound to scroll and resize for the gesture's length because the bounds are
   * viewport-relative: the box can move under a held pointer without changing
   * size, and stale bounds put the pointer in the wrong place.
   */
  #onReflow = () => {
    if (this.#gesture) {
      this.#gesture.measuredRect =
        this.#gesture.measured?.getBoundingClientRect() ?? null;
    }
  };

  #watchingReflow = false;

  constructor(
    owner: Owner,
    args: DResizeHandlesSignature<Payload, Session>["Args"]
  ) {
    super(owner, args);
    registerDestructor(this, () => this.#closeGesture());
  }

  /**
   * The resolved handle descriptors: explicit `@handles` when named, otherwise
   * the built-in box from `@handleClass`.
   *
   * The branch tests whether `@handles` was NAMED, not whether it holds
   * anything, because naming it is what `Payload` is inferred from. Falling
   * through to the box would hand compass strings to differently-typed callbacks.
   */
  get handles() {
    const source =
      "handles" in this.args ? (this.args.handles ?? []) : this.#boxHandles();

    if (DEBUG) {
      const seen = new Set<string>();
      for (const handle of source) {
        assert(
          "DResizeHandles: wrap a descriptor's `style` in `trustHTML` before passing it",
          handle.style == null || isTrustedHTML(handle.style)
        );
        // Glimmer reports neither a missing nor a duplicate key. It derives a
        // positional one, which is what keying exists to avoid.
        assert(
          "DResizeHandles: every handle descriptor needs a unique `key`",
          handle.key != null
        );
        assert(
          `DResizeHandles: two handles share the key \`${handle.key}\``,
          !seen.has(handle.key)
        );
        seen.add(handle.key);
      }
    }

    return source;
  }

  @action
  onHandleDown(payload: Payload, event: PointerEvent, info: DPointerDragInfo) {
    // Returning false vetoes the press, so only one gesture runs at a time.
    if (this.#gesture) {
      return false;
    }

    const handle = event.currentTarget as HTMLElement;
    const measured = this.#measureTarget(handle);
    const gesture: Gesture<Payload, Session> = {
      payload,
      handle,
      event,
      info,
      measured,
      measuredRect: measured?.getBoundingClientRect() ?? null,
      session: {} as Session,
    };
    this.#gesture = gesture;
    this.#watchReflow();

    let started;
    try {
      started = this.args.onResizeStart?.(
        payload,
        this.#dragInfo(gesture, event, info)
      );
    } catch (error) {
      this.#reset();
      throw error;
    }

    // The press was vetoed, so no terminal callback will arrive to clear it.
    if (started === false) {
      this.#reset();
    }

    return started;
  }

  @action
  onHandleMove(event: PointerEvent, info: DPointerDragInfo) {
    const gesture = this.#gesture;
    if (!gesture) {
      return;
    }
    // Build the report first. `onResize?.()` skips its arguments when there is
    // no handler, and the gesture's snapshot has to update either way.
    const dragInfo = this.#dragInfo(gesture, event, info);
    this.args.onResize?.(gesture.payload, dragInfo);
  }

  @action
  onHandleUp(event: PointerEvent, info: DPointerDragInfo) {
    const gesture = this.#gesture;
    if (!gesture) {
      return;
    }
    const dragInfo = this.#dragInfo(gesture, event, info);
    // Released in a `finally` so a throwing consumer cannot strand the gesture
    // and leave the reflow listeners attached.
    try {
      this.args.onResizeEnd?.(gesture.payload, dragInfo);
    } finally {
      this.#reset();
    }
  }

  @action
  onHandleCancel(event: PointerEvent, info: DPointerDragInfo) {
    const gesture = this.#gesture;
    if (!gesture) {
      return;
    }
    const dragInfo = this.#dragInfo(gesture, event, info);
    try {
      this.args.onResizeCancel?.(gesture.payload, dragInfo);
    } finally {
      this.#reset();
    }
  }

  /**
   * Closes the gesture when the handle holding it is destroyed. That happens
   * when `@handles` or `@directions` drops a handle while the pointer is down.
   *
   * The engine reports nothing when its element goes. Without this, the consumer
   * would never get to close what it opened at the press.
   *
   * @param element - The handle being torn down.
   */
  @action
  onHandleTeardown(element: Element) {
    if (this.#gesture?.handle === element) {
      this.#closeGesture();
    }
  }

  /**
   * Ends a gesture that is still held. Runs both when a single handle is
   * destroyed and when the whole component is.
   */
  #closeGesture() {
    const gesture = this.#gesture;
    if (!gesture) {
      return;
    }
    // Clear it first. At teardown the handle and the component both close the
    // gesture, and whichever runs second has to do nothing.
    this.#reset();

    const dragInfo = {
      ...gesture.info,
      payload: gesture.payload,
      event: gesture.event,
      session: gesture.session,
      measured: gesture.measured,
      measuredRect: gesture.measuredRect,
    };
    try {
      if (this.args.cancelCommits) {
        this.args.onResizeEnd?.(gesture.payload, dragInfo);
      } else {
        this.args.onResizeCancel?.(gesture.payload, dragInfo);
      }
    } catch (error) {
      // Swallowed only here. A throw from a destructor aborts the teardown
      // flush and takes every sibling's cleanup with it.
      // eslint-disable-next-line no-console
      console.error(error);
    }
  }

  #boxHandles(): DResizeHandleDescriptor<Payload>[] {
    const handleClass = this.args.handleClass;
    if (!handleClass) {
      return [];
    }
    const directions = this.args.directions ?? BOX_DIRECTIONS;
    return directions.map((dir) => ({
      // A direction appears once in a box, so it is the handle's identity too.
      key: dir,
      // The cast is safe. Only `@handles` pins `Payload` to something else, and
      // supplying it makes this branch unreachable. TypeScript cannot see that.
      payload: dir as Payload,
      class: `${handleClass} --${dir}`,
    }));
  }

  #dragInfo(
    gesture: Gesture<Payload, Session>,
    event: PointerEvent,
    info: DPointerDragInfo
  ): DResizeHandleDragInfo<Payload, Session> {
    gesture.event = event;
    gesture.info = info;

    return {
      payload: gesture.payload,
      event,
      origin: info.origin,
      current: info.current,
      delta: info.delta,
      moved: info.moved,
      session: gesture.session,
      measured: gesture.measured,
      measuredRect: gesture.measuredRect,
    };
  }

  #reset() {
    this.#gesture = null;
    this.#unwatchReflow();
  }

  #measureTarget(handle: HTMLElement): Element | null {
    const target = this.args.measure;
    return (typeof target === "function" ? target(handle) : target) ?? null;
  }

  #watchReflow() {
    // Skip the listeners when nothing is measured, which is the common case.
    // Otherwise a document-wide scroll listener fires on every scroll for nothing.
    if (this.#watchingReflow || !this.#gesture?.measured) {
      return;
    }
    this.#watchingReflow = true;
    window.addEventListener("scroll", this.#onReflow, true);
    window.addEventListener("resize", this.#onReflow);
  }

  #unwatchReflow() {
    if (!this.#watchingReflow) {
      return;
    }
    this.#watchingReflow = false;
    window.removeEventListener("scroll", this.#onReflow, true);
    window.removeEventListener("resize", this.#onReflow);
  }

  <template>
    {{! Keyed by identity so that removing a handle destroys the right one. With
      positional keys the last handle goes instead. That strands its gesture, and
      leaves the handles after the gap bound to descriptors nobody pressed. }}
    {{#each this.handles key="key" as |handle|}}
      <span
        aria-hidden="true"
        class={{handle.class}}
        data-resize-handle={{handle.payload}}
        style={{handle.style}}
        {{willDestroy this.onHandleTeardown}}
        {{dPointerDrag
          onDragStart=(fn this.onHandleDown handle.payload)
          onDrag=this.onHandleMove
          onDragEnd=this.onHandleUp
          onDragCancel=this.onHandleCancel
          draggingClass=@draggingClass
          threshold=@threshold
          stopPropagation=@stopPropagation
          cancelCommits=@cancelCommits
        }}
      ></span>
    {{/each}}
