export interface DTabsBag {
  /** Declares one tab: its strip button and its panel content together. */
  Tab: ComponentLike<{
    Element: DTabsTabSignature["Element"];
    Args: Omit<DTabsTabSignature["Args"], "tabs">;
    Blocks: DTabsTabSignature["Blocks"];
