/** TODO(typescript-pending): remove this projection when SettingObjectHelper types its setting and getters. */
type TypedSettingObjectHelper = Omit<
  SettingObjectHelper,
  | "settingObj"
  | "computedValueProperty"
  | "computedNameProperty"
  | "validValues"
  | "anyValue"
> & {
  settingObj: SiteSetting;
