const DEFAULT_LOCATION = "above_main_container";

const STEPS = [
  class SelectTheme extends OnboardingStep {
    static name = "select_theme";

    @service designWizard;

    icon = "paintbrush";

    #onComplete = () => this.markAsCompleted();

    constructor() {
      super(...arguments);
      this.designWizard.resumeAfterThemePreview({
        onComplete: this.#onComplete,
      });
    }

    // a homepage preview routes away from this component while the sheet lives on
    willDestroy() {
      super.willDestroy(...arguments);
      this.designWizard.clearCompletionCallback(this.#onComplete);
    }

    @action
    prefetch() {
      this.designWizard.prefetch();
    }

    @action
    performAction() {
      this.designWizard.start({ onComplete: this.#onComplete });
    }
  },
  class StartPosting extends OnboardingStep {
    static name = "start_posting";

    @service appEvents;
    @service modal;

    icon = "comments";

    constructor() {
      super(...arguments);

      this.appEvents.on("topic:created", this, this.completeStep);
      this.appEvents.on(
        "admin-onboarding:posting-complete",
        this,
        this.completeStep
      );
    }

    willDestroy() {
      super.willDestroy(...arguments);

      this.appEvents.off("topic:created", this, this.completeStep);
      this.appEvents.off(
        "admin-onboarding:posting-complete",
        this,
        this.completeStep
      );
    }

    completeStep(_post, composer) {
      return this.markAsCompleted({
        topicOption: composer?.adminOnboardingTopicOption,
      });
    }

    showStartPostingOptions() {
      const options = applyValueTransformer(
        "admin-onboarding-start-posting-options",
        [PredefinedTopicOption]
      );

      if (options.length === 1) {
        // show predefined topics directly if it's the only option available
        return this.modal.show(PredefinedTopicsOptionsModal);
      }

      this.modal.show(StartPostingOptions, {
        model: {
          options,
          isStepComplete: this.completed,
        },
      });
    }

    @action
    async performAction() {
      this.showStartPostingOptions();
    }
  },
  class InviteCollaborators extends OnboardingStep {
    static name = "invite_collaborators";

    @service appEvents;

    icon = "paper-plane";

    constructor() {
      super(...arguments);
      this.appEvents.on("create-invite:saved", this, this.markAsCompleted);
    }

    willDestroy() {
      super.willDestroy(...arguments);
      this.appEvents.off("create-invite:saved", this, this.markAsCompleted);
    }

    @action
    performAction() {
      showCreateInviteModal(this, {
        model: { invites: trackedArray(), defaultRole: "admin" },
      });
    }
  },
];

export default class AdminOnboardingBanner extends Component {
  @service appEvents;
  @service currentUser;
  @service keyValueStore;
  @service router;
  @service toasts;

  @tracked dismissed = false;
  @tracked minimized = false;
  // the key value store isn't reactive, but the progress count must be
  completedStepNames = trackedSet(
    this.steps
      .filter(
        (Step) => !!this.keyValueStore.get(`onboarding_step_${Step.name}`)
      )
      .map((Step) => Step.name)
  );

  #heightContainer;

  constructor() {
    super(...arguments);
    this.appEvents.on(
      "onboarding-step:completed",
      this,
      this.markStepCompleted
    );
  }

  willDestroy() {
    super.willDestroy(...arguments);
    this.appEvents.off(
      "onboarding-step:completed",
      this,
      this.markStepCompleted
    );
  }

  get #currentHomepage() {
    const routeName = this.router.currentRouteName;
    return (Site.current()?.homepage_choices ?? []).find(
      (choice) =>
        routeName === `discovery.${choice}` ||
        routeName?.startsWith(`${choice}.`)
    );
  }

  // Where the banner renders. A customization can return a location of its
  // own and render the banner there, as long as it passes a matching @location
  get location() {
    return applyValueTransformer(
      "admin-onboarding-banner-location",
      DEFAULT_LOCATION,
      { homepage: this.#currentHomepage ?? defaultHomepage() }
    );
  }

  // A bare <AdminOnboardingBanner> without @location renders regardless of the chosen location
  get matchesLocation() {
    return (
      this.args.location === undefined || this.args.location === this.location
    );
  }

  get shouldDisplay() {
    if (this.dismissed) {
      return false;
    }

    if (!this.currentUser?.show_site_owner_onboarding) {
      return false;
    }

    if (!this.matchesLocation) {
      return false;
    }

    const { currentRouteName, currentURL } = this.router;
    const path = currentURL?.split(/[?#]/)[0];

    return (
      this.#currentHomepage !== undefined ||
      currentRouteName === `discovery.${defaultHomepage()}` ||
      path === "/" ||
      path === homepagePath()
    );
  }

  /**
   * @returns {(typeof OnboardingStep)[]}
   */
  @cached
  get steps() {
    return applyValueTransformer("admin-onboarding-steps", [...STEPS], {
      homepage: this.#currentHomepage ?? defaultHomepage(),
    });
  }

  get completedSteps() {
    return this.completedStepNames.size;
  }

  @action
  markStepCompleted(name) {
    this.completedStepNames.add(name);
  }

  @action
  async checkIfOnboardingIsComplete() {
    const allStepsAreDone = this.steps.every(
      (Step) => !!this.keyValueStore.get(`onboarding_step_${Step.name}`)
    );

    if (allStepsAreDone) {
      await this.endOnboarding({ skipped: false });
    }
  }

  @action
  minimize() {
    this.minimized = !this.minimized;
  }

  @action
  updateHeight(entries) {
    const element = entries[0].target;
    this.#heightContainer = element.parentElement;
    this.#heightContainer.style.setProperty(
      "--admin-onboarding-banner-height",
      `${element.getBoundingClientRect().height}px`
    );
  }

  @action
  clearHeight() {
    this.#heightContainer?.style.removeProperty(
      "--admin-onboarding-banner-height"
    );
    this.#heightContainer = undefined;
  }

  @action
  async endOnboarding({ skipped = true } = {}) {
    await SiteSetting.update("enable_site_owner_onboarding", false);
    await logOnboardingEvent(skipped ? "dismissed" : "completed");
    this.dismissed = true;
    this.steps.forEach((Step) => {
      this.keyValueStore.remove(`onboarding_step_${Step.name}`);
    });
    this.completedStepNames.clear();

    if (!skipped) {
      this.toasts.success({
        data: {
          message: i18n("admin_onboarding_banner.congrats_onboarding_complete"),
        },
      });
    }
  }

  <template>
    {{#if this.shouldDisplay}}
      <div
        class="admin-onboarding-banner"
        {{dOnResize this.updateHeight}}
        {{willDestroy this.clearHeight}}
      >
        <div class="admin-onboarding-banner__wrap">
          <div class="admin-onboarding-banner__header">
            <div class="admin-onboarding-banner__header-text">
              <span class="admin-onboarding-banner__title">
                {{dIcon "list" class="admin-onboarding-banner__title-icon"}}
                {{i18n "admin_onboarding_banner.launch_in_easy_steps"}}
              </span>
              {{#if this.minimized}}
                <span class="admin-onboarding-banner__subtitle">
                  {{i18n
                    "admin_onboarding_banner.launch_in_easy_steps_subtitle"
                    (hash
                      completed_steps=this.completedSteps
                      step_count=this.steps.length
                    )
                  }}
                </span>
              {{/if}}
            </div>
            <div class="admin-onboarding-banner__header-actions">
              <DButton
                class="btn no-text btn-transparent btn-minimize"
                @action={{this.minimize}}
                @ariaLabel={{if
                  this.minimized
                  "admin_onboarding_banner.expand"
                  "admin_onboarding_banner.collapse"
                }}
                @icon={{if this.minimized "angle-down" "angle-up"}}
              />
              <DButton
                class="btn no-text btn-transparent btn-close"
                @action={{this.endOnboarding}}
                @ariaLabel="admin_onboarding_banner.dismiss"
                @icon="xmark"
              />
            </div>
          </div>
          {{#unless this.minimized}}
            <div class="admin-onboarding-banner__content">
              <div class="admin-onboarding-banner__steps">
                {{#each this.steps as |Step|}}
                  <Step @onCompleted={{this.checkIfOnboardingIsComplete}} />
                {{/each}}
              </div>
            </div>
          {{/unless}}
        </div>
      </div>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import { fn } from "@ember/helper";
import { action } from "@ember/object";
import { getOwner } from "@ember/owner";
import { service } from "@ember/service";
import DButton from "discourse/ui-kit/d-button";
import DDropdownMenu from "discourse/ui-kit/d-dropdown-menu";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";

export default class AdminPostMenu extends Component {
  @service currentUser;
  @service siteSettings;
  @service adminPostMenuButtons;
  @service router;

  constructor() {
    super(...arguments);
    this.router.on("routeWillChange", this.args.close);
  }

  willDestroy() {
    super.willDestroy(...arguments);
    this.router.off("routeWillChange", this.args.close);
  }

  get reviewUrl() {
    return `/review?topic_id=${this.args.data.post.id}&status=all`;
  }

  get extraButtons() {
    return this.adminPostMenuButtons.callbacks
      .map((callback) => {
        return callback(this.args.data.post);
      })
      .filter(Boolean);
  }

  get canChangePostOwner() {
    return this.currentUser?.canChangePostOwner;
  }

  get nestedPinButton() {
    if (!this.siteSettings.nested_replies_enabled) {
      return null;
    }
    const topicController = getOwner(this).lookup("controller:topic");
    if (!topicController?.shouldRenderNestedView) {
      return null;
    }

    const post = this.args.data.post;
    if (post.post_number === 1) {
      return null;
    }
    if (post.reply_to_post_number && post.reply_to_post_number !== 1) {
      return null;
    }

    const nestedController = getOwner(this).lookup("controller:nested");
    const isPinned = nestedController?.pinnedPostIds?.includes(post.id);

    return {
      isPinned,
      label: isPinned
        ? "nested_replies.unpin_reply"
        : "nested_replies.pin_reply",
      action: () => nestedController?.togglePinPost(post),
    };
  }

  @action
  async topicAction(actionName) {
    await this.args.close();

    try {
      await this.args.data[actionName]?.();
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error(`Unknown error while attempting \`${actionName}\`:`, error);
    }

    await this.args.data.scheduleRerender?.();
  }

  @action
  async extraAction(button) {
    await this.args.close();
    await button.action(this.args.data.post);
    await this.args.data.scheduleRerender?.();
  }

  <template>
    <DDropdownMenu as |dropdown|>
      {{#if this.currentUser.staff}}
        <dropdown.item>
          <DButton
            class="btn btn-transparent moderation-history"
            @href={{this.reviewUrl}}
            @icon="list"
            @label="review.moderation_history"
          />
        </dropdown.item>
      {{/if}}

      {{#if (and this.currentUser.staff (not @data.post.isWhisper))}}
        <dropdown.item>
          <DButton
            class={{dConcatClass
              "btn btn-transparent toggle-post-type"
              (if @data.post.isModeratorAction "btn-success")
            }}
            @action={{fn this.topicAction "togglePostType"}}
            @icon="shield-halved"
            @label={{if
              @data.post.isModeratorAction
              "post.controls.revert_to_regular"
              "post.controls.convert_to_moderator"
            }}
            @title={{if
              @data.post.isModeratorAction
              ""
              "post.controls.convert_to_moderator_description"
            }}
          />
        </dropdown.item>
      {{/if}}

      {{#if @data.post.canEditStaffNotes}}
        <dropdown.item>
          <DButton
            class={{dConcatClass
              "btn btn-transparent"
              (if @data.post.notice "change-notice" "add-notice")
              (if @data.post.notice "btn-success")
            }}
            @action={{fn this.topicAction "changeNotice"}}
            @icon="user-shield"
            @label={{if
              @data.post.notice
              "post.controls.change_post_notice"
              "post.controls.add_post_notice"
            }}
            @title="post.controls.add_post_notice_description"
          />
        </dropdown.item>
      {{/if}}

      {{#if (and this.currentUser.staff @data.post.hidden)}}
        <dropdown.item>
          <DButton
            class="btn btn-transparent unhide-post"
            @action={{fn this.topicAction "unhidePost"}}
            @icon="far-eye"
            @label="post.controls.unhide"
          />
        </dropdown.item>
      {{/if}}

      {{#if this.canChangePostOwner}}
        <dropdown.item>
          <DButton
            class="btn btn-transparent change-owner"
            @action={{fn this.topicAction "changePostOwner"}}
            @icon="user"
            @label="post.controls.change_owner"
          />
        </dropdown.item>
      {{/if}}

      {{#if (and @data.post.user_id this.currentUser.staff)}}
        {{#if this.siteSettings.enable_badges}}
          <dropdown.item>
            <DButton
              class="btn btn-transparent grant-badge"
              @action={{fn this.topicAction "grantBadge"}}
              @icon="certificate"
              @label="post.controls.grant_badge"
            />
          </dropdown.item>
        {{/if}}

        {{#if @data.post.locked}}
          <dropdown.item>
            <DButton
              class={{dConcatClass
                "btn btn-transparent unlock-post"
                (if @data.post.locked "btn-success")
              }}
              @action={{fn this.topicAction "unlockPost"}}
              @icon="unlock"
              @label="post.controls.unlock_post"
              @title="post.controls.unlock_post_description"
            />
          </dropdown.item>
        {{else}}
          <dropdown.item>
            <DButton
              class="btn btn-transparent lock-post"
              @action={{fn this.topicAction "lockPost"}}
              @icon="lock"
              @label="post.controls.lock_post"
              @title="post.controls.lock_post_description"
            />
          </dropdown.item>
        {{/if}}
      {{/if}}

      {{#if @data.post.canPermanentlyDelete}}
        <dropdown.item>
          <DButton
            class="btn btn-transparent permanently-delete"
            @action={{fn this.topicAction "permanentlyDeletePost"}}
            @icon="trash-can"
            @label="post.controls.permanently_delete"
          />
        </dropdown.item>
      {{/if}}

      {{#if (or @data.post.canManage @data.post.can_wiki)}}
        {{#if @data.post.wiki}}
          <dropdown.item>
            <DButton
              class={{dConcatClass
                "btn btn-transparent wiki wikied"
                (if @data.post.wiki "btn-success")
              }}
              @action={{fn this.topicAction "toggleWiki"}}
              @icon="far-pen-to-square"
              @label="post.controls.unwiki"
            />
          </dropdown.item>
        {{else}}
          <dropdown.item>
            <DButton
              class="btn btn-transparent wiki"
              @action={{fn this.topicAction "toggleWiki"}}
              @icon="far-pen-to-square"
              @label="post.controls.wiki"
              @title="post.controls.wiki_description"
            />
          </dropdown.item>
        {{/if}}
      {{/if}}

      {{#if @data.post.canPublishPage}}
        <dropdown.item>
          <DButton
            class="btn btn-transparent publish-page"
            @action={{fn this.topicAction "showPagePublish"}}
            @icon="file"
            @label="post.controls.publish_page"
            @title="post.controls.publish_page_description"
          />
        </dropdown.item>
      {{/if}}

      {{#if @data.post.canManage}}
        <dropdown.item>
          <DButton
            class="btn btn-transparent rebuild-html"
            @action={{fn this.topicAction "rebakePost"}}
            @icon="rotate"
            @label="post.controls.rebake"
            @title="post.controls.rebake_description"
          />
        </dropdown.item>
      {{/if}}

      {{#if this.nestedPinButton}}
        <dropdown.item>
          <DButton
            class="btn btn-transparent pin-reply"
            @action={{fn this.extraAction this.nestedPinButton}}
            @icon="thumbtack"
            @label={{this.nestedPinButton.label}}
          />
        </dropdown.item>
      {{/if}}

      {{#each this.extraButtons as |button|}}
        <dropdown.item>
          <DButton
            class={{dConcatClass "btn btn-transparent" button.className}}
            @action={{fn this.extraAction button}}
            @icon={{button.icon}}
            @label={{button.label}}
            @title={{button.title}}
            @translatedLabel={{button.translatedLabel}}
            @translatedTitle={{button.translatedTitle}}
          />
        </dropdown.item>
      {{/each}}
    </DDropdownMenu>
  </template>
}
