import DButton from "discourse/ui-kit/d-button";
import { i18n } from "discourse-i18n";

// https://developer.mozilla.org/en-US/docs/Web/API/WindowBase64/Base64_encoding_and_decoding
function b64EncodeUnicode(str) {
  return btoa(
    encodeURIComponent(str).replace(
      /%([0-9A-F]{2})/g,
      function toSolidBytes(match, p1) {
        return String.fromCharCode("0x" + p1);
      }
    )
  );
}

export default class BackupCodes extends Component {
  @service siteSettings;

  get siteTitleSlug() {
    const title = this.siteSettings.title;
    const convertedTitle = toAsciiPrintable(title, "discourse");
    return slugify(convertedTitle);
  }

  get base64BackupCode() {
    return b64EncodeUnicode(this.formattedBackupCodes);
  }

  get formattedBackupCodes() {
    if (!this.args.backupCodes) {
      return null;
    }

    return this.args.backupCodes.join("\r\n").trim();
  }

  @action
  copyToClipboard() {
    this._selectAllBackupCodes();
    const copied = copyText("", this.backupCodesArea);
    this.args.copyBackupCode(copied);
  }

  @action
  registerBackupCodesArea(element) {
    this.backupCodesArea = element;
    element.style.height = element.scrollHeight;
  }

  @action
  _selectAllBackupCodes() {
    this.backupCodesArea.focus();
    this.backupCodesArea.setSelectionRange(0, this.formattedBackupCodes.length);
  }

  <template>
    <div class="backup-codes">
      <div class="wrapper">
        <textarea
          class="backup-codes-area"
          id="backupCodes"
          readonly
          rows="10"
          {{didInsert this.registerBackupCodesArea}}
          {{on "click" this._selectAllBackupCodes}}
        >{{this.formattedBackupCodes}}</textarea>

        <div class="controls">
          <DButton
            class="backup-codes-copy-btn"
            @action={{this.copyToClipboard}}
            @ariaLabel="user.second_factor_backup.copy_to_clipboard"
            @icon="copy"
            @title="user.second_factor_backup.copy_to_clipboard"
          />

          <DButton
            aria-label={{i18n
              "user.second_factor_backup.download_backup_codes"
            }}
            class="backup-codes-download-btn"
            download="{{this.siteTitleSlug}}-backup-codes.txt"
            rel="noopener noreferrer"
            target="_blank"
            title={{i18n "user.second_factor_backup.download_backup_codes"}}
            @href="data:application/octet-stream;charset=utf-8;base64,{{this.base64BackupCode}}"
            @icon="download"
          />
        </div>
      </div>
    </div>
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { fn } from "@ember/helper";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { ajax } from "discourse/lib/ajax";
import ComboBox from "discourse/select-kit/components/combo-box";
import DButton from "discourse/ui-kit/d-button";
import { i18n } from "discourse-i18n";

export default class BadgeTitle extends Component {
  @service currentUser;
  @service dialog;

  @tracked _selectedUserBadgeId;
  @tracked _isSaved = false;
  @tracked _isSaving = false;

  constructor() {
    super(...arguments);

    const badge = this._findBadgeByTitle(
      this.args.selectableUserBadges,
      this.currentUser.title
    );
    this._selectedUserBadgeId = badge?.id || 0;
  }

  @action
  saveBadgeTitle() {
    this._isSaved = false;
    this._isSaving = true;

    const selectedUserBadge = this._findBadgeById(
      this.args.selectableUserBadges,
      this._selectedUserBadgeId
    );

    return ajax(`${this.currentUser.path}/preferences/badge_title`, {
      type: "PUT",
      data: { user_badge_id: selectedUserBadge?.id || 0 },
    })
      .then(
        () => {
          this._isSaved = true;
          this.currentUser.set("title", selectedUserBadge?.badge?.name || "");
        },
        () => {
          this.dialog.alert(i18n("generic_error"));
        }
      )
      .finally(() => (this._isSaving = false));
  }

  _findBadgeById(badges, id) {
    return (badges || []).find((b) => b.id === id);
  }

  _findBadgeByTitle(badges, title) {
    return (badges || []).find((b) => b.badge.name === title);
  }

  <template>
    <div class="badge-title">
      <form class="form-horizontal">

        <h3>{{i18n "badges.select_badge_for_title"}}</h3>

        <div class="control-group">
          <div class="controls">
            <ComboBox
              @content={{@selectableUserBadges}}
              @nameProperty="badge.name"
              @onChange={{fn (mut this._selectedUserBadgeId)}}
              @value={{this._selectedUserBadgeId}}
            />
          </div>
        </div>

        <div class="control-group">
          <div class="controls">
            <DButton
              class="btn-primary"
              @action={{this.saveBadgeTitle}}
              @disabled={{this._isSaving}}
              @label={{if this._isSaving "saving" "save"}}
            />
            {{#if @closeAction}}
              <DButton
                class="btn-default close-btn"
                @action={{@closeAction}}
                @label="close"
              />
            {{/if}}
            {{#if this._isSaved}}
              <span class="badge-title__saved" role="status">{{i18n
                  "saved"
                }}</span>
            {{/if}}
          </div>
        </div>
      </form>
    </div>
  </template>
}
import { action, computed } from "@ember/object";
import { classNames } from "@ember-decorators/component";
import DropdownSelectBoxComponent from "discourse/select-kit/components/dropdown-select-box";
import {
  pluginApiIdentifiers,
  selectKitOptions,
} from "discourse/select-kit/components/select-kit";
import { i18n } from "discourse-i18n";

const ACTION_REMOVE = "remove";
const ACTION_EDIT = "edit";
const ACTION_CLEAR_REMINDER = "clear_reminder";
const ACTION_PIN = "pin";

@classNames("bookmark-actions-dropdown")
@selectKitOptions({
  icon: null,
  translatedNone: "...",
  showFullTitle: true,
})
@pluginApiIdentifiers("bookmark-actions-dropdown")
export default class BookmarkActionsDropdown extends DropdownSelectBoxComponent {
  @computed("bookmark")
  get content() {
    const actions = [];

    actions.push({
      id: ACTION_REMOVE,
      icon: "trash-can",
      name: i18n("post.bookmarks.actions.delete_bookmark.name"),
      description: i18n("post.bookmarks.actions.delete_bookmark.description"),
    });

    actions.push({
      id: ACTION_EDIT,
      icon: "pencil",
      name: i18n("post.bookmarks.actions.edit_bookmark.name"),
      description: i18n("post.bookmarks.actions.edit_bookmark.description"),
    });

    if (this.bookmark.reminder_at) {
      actions.push({
        id: ACTION_CLEAR_REMINDER,
        icon: "clock-rotate-left",
        name: i18n("post.bookmarks.actions.clear_bookmark_reminder.name"),
        description: i18n(
          "post.bookmarks.actions.clear_bookmark_reminder.description"
        ),
      });
    }

    actions.push({
      id: ACTION_PIN,
      icon: "thumbtack",
      name: i18n(
        `post.bookmarks.actions.${this.bookmark.pinAction()}_bookmark.name`
      ),
      description: i18n(
        `post.bookmarks.actions.${this.bookmark.pinAction()}_bookmark.description`
      ),
    });

    return actions;
  }

  @action
  onChange(selectedAction) {
    if (selectedAction === ACTION_REMOVE) {
      this.removeBookmark(this.bookmark);
    } else if (selectedAction === ACTION_EDIT) {
      this.editBookmark(this.bookmark);
    } else if (selectedAction === ACTION_CLEAR_REMINDER) {
      this.clearBookmarkReminder(this.bookmark);
    } else if (selectedAction === ACTION_PIN) {
      this.togglePinBookmark(this.bookmark);
    }
  }
}
import Component from "@glimmer/component";
import {
  NO_REMINDER_ICON,
  NOT_BOOKMARKED,
  WITH_REMINDER_ICON,
} from "discourse/models/bookmark";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

export default class BookmarkIcon extends Component {
  get icon() {
    if (this.args.bookmark?.get("reminder_at")) {
      return WITH_REMINDER_ICON;
    } else if (this.args.bookmark) {
      return NO_REMINDER_ICON;
    }

    return NOT_BOOKMARKED;
  }

  get cssClasses() {
    return this.args.bookmark
      ? "bookmark-icon bookmark-icon__bookmarked"
      : "bookmark-icon";
  }

  get title() {
    if (!this.args.bookmark) {
      return i18n("bookmarks.create");
    }

    return this.args.bookmark.get("reminderTitle");
  }

  <template>
    {{dIcon this.icon translatedTitle=this.title class=this.cssClasses}}
  </template>
}
import { action } from "@ember/object";
import { service } from "@ember/service";
import { classNames } from "@ember-decorators/component";
import { popupAjaxError } from "discourse/lib/ajax-error";
import Bookmark from "discourse/models/bookmark";
import DropdownSelectBoxComponent from "discourse/select-kit/components/dropdown-select-box";
import { i18n } from "discourse-i18n";
import { selectKitOptions } from "./select-kit.js";

const _customButtons = [];
const _customActions = {};

export function addBulkDropdownAction(name, customAction) {
  _customActions[name] = customAction;
}

@classNames("bulk-select-bookmarks-dropdown")
@selectKitOptions({
  showCaret: true,
  showFullTitle: true,
  none: "select_kit.components.bulk_select_bookmarks_dropdown.title",
})
export default class BulkSelectBookmarksDropdown extends DropdownSelectBoxComponent {
  @service router;
  @service toasts;
  @service dialog;

  headerIcon = null;

  get content() {
    let options = [];
    options = options.concat([
      {
        id: "clear-reminders",
        icon: "tag",
        name: i18n("bookmark_bulk_actions.clear_reminders.name"),
      },
      {
        id: "delete-bookmarks",
        icon: "trash-can",
        name: i18n("bookmark_bulk_actions.delete_bookmarks.name"),
      },
    ]);

    return [...options, ..._customButtons];
  }

  getSelectedBookmarks() {
    return this.bulkSelectHelper.selected;
  }

  @action
  onSelect(id) {
    switch (id) {
      case "clear-reminders":
        this.dialog.yesNoConfirm({
          message: i18n(
            `js.bookmark_bulk_actions.clear_reminders.description`,
            {
              count: this.getSelectedBookmarks().length,
            }
          ),
          didConfirm: () => {
            Bookmark.bulkOperation(this.getSelectedBookmarks(), {
              type: "clear_reminder",
            })
              .then(() => {
                this.router.refresh();
                this.bulkSelectHelper.clear();
                this.toasts.success({
                  duration: "short",
                  data: { message: i18n("bookmarks.bulk.reminders_cleared") },
                });
              })
              .catch(popupAjaxError);
          },
        });
        break;
      case "delete-bookmarks":
        this.dialog.deleteConfirm({
          message: i18n(
            `js.bookmark_bulk_actions.delete_bookmarks.description`,
            {
              count: this.getSelectedBookmarks().length,
            }
          ),
          didConfirm: () => {
            Bookmark.bulkOperation(this.getSelectedBookmarks(), {
              type: "delete",
            })
              .then(() => {
                this.router.refresh();
                this.bulkSelectHelper.clear();
                this.toasts.success({
                  duration: "short",
                  data: { message: i18n("bookmarks.bulk.delete_completed") },
                });
              })
              .catch(popupAjaxError);
          },
        });
    }
  }
}
import Component from "@glimmer/component";
import { fn } from "@ember/helper";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { trustHTML } from "@ember/template";
import { Promise } from "rsvp";
import BookmarkActionsDropdown from "discourse/components/bookmark-actions-dropdown";
import BookmarkModal from "discourse/components/modal/bookmark";
import PluginOutlet from "discourse/components/plugin-outlet";
import ActivityCell from "discourse/components/topic-list/item/activity-cell";
import TopicStatus from "discourse/components/topic-status";
import lazyHash from "discourse/helpers/lazy-hash";
import { ajax } from "discourse/lib/ajax";
import {
  addUniqueValueToArray,
  removeValueFromArray,
} from "discourse/lib/array-tools";
import { BookmarkFormData } from "discourse/lib/bookmark-form-data";
import {
  openLinkInNewTab,
  shouldOpenInNewTab,
} from "discourse/lib/click-track";
import BulkSelectBookmarksDropdown from "discourse/select-kit/components/bulk-select-bookmarks-dropdown";
import DButton from "discourse/ui-kit/d-button";
import DConditionalLoadingSpinner from "discourse/ui-kit/d-conditional-loading-spinner";
import DLoadMore from "discourse/ui-kit/d-load-more";
import dAvatar from "discourse/ui-kit/helpers/d-avatar";
import dCategoryLink from "discourse/ui-kit/helpers/d-category-link";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import dDiscourseTags from "discourse/ui-kit/helpers/d-discourse-tags";
import dFormatDate from "discourse/ui-kit/helpers/d-format-date";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import dReplaceEmoji from "discourse/ui-kit/helpers/d-replace-emoji";
import dTopicLink from "discourse/ui-kit/helpers/d-topic-link";
import { i18n } from "discourse-i18n";

export default class BookmarkList extends Component {
  @service appEvents;
  @service dialog;
  @service modal;
  @service site;

  #lastChecked = null;

  get canDoBulkActions() {
    return this.args.bulkSelectHelper?.selected.length;
  }

  get selected() {
    return this.args.bulkSelectHelper?.selected;
  }

  get selectedCount() {
    return this.selected?.length || 0;
  }

  get bulkSelectEnabled() {
    return this.args.bulkSelectHelper?.bulkSelectEnabled;
  }

  @action
  removeBookmark(bookmark) {
    return new Promise((resolve, reject) => {
      const deleteBookmark = () => {
        bookmark
          .destroy()
          .then(() => {
            this.appEvents.trigger(
              "bookmarks:changed",
              null,
              bookmark.attachedTo()
            );
            removeValueFromArray(this.args.content, bookmark);
            resolve(true);
          })
          .catch((error) => {
            reject(error);
          });
      };
      if (!bookmark.reminder_at) {
        return deleteBookmark();
      }
      this.dialog.deleteConfirm({
        message: i18n("bookmarks.confirm_delete"),
        didConfirm: () => deleteBookmark(),
        didCancel: () => resolve(false),
      });
    });
  }

  @action
  screenExcerptForExternalLink(event) {
    if (event?.target?.tagName === "A") {
      if (shouldOpenInNewTab(event.target.href)) {
        openLinkInNewTab(event, event.target);
      }
    }
  }

  @action
  editBookmark(bookmark) {
    this.modal.show(BookmarkModal, {
      model: {
        bookmark: new BookmarkFormData(bookmark),
        afterSave: (savedData) => {
          this.appEvents.trigger(
            "bookmarks:changed",
            savedData,
            bookmark.attachedTo()
          );
          this.args.reload();
        },
        afterDelete: () => {
          this.args.reload();
        },
      },
    });
  }

  @action
  clearBookmarkReminder(bookmark) {
    return ajax(`/bookmarks/${bookmark.id}`, {
      type: "PUT",
      data: { reminder_at: null },
    }).then(() => {
      bookmark.set("reminder_at", null);
    });
  }

  @action
  togglePinBookmark(bookmark) {
    bookmark.togglePin().then(this.args.reload);
  }

  @action
  toggleBulkSelect() {
    this.args.bulkSelectHelper?.toggleBulkSelect();
  }

  @action
  selectAll() {
    this.args.bulkSelectHelper.autoAddBookmarksToBulkSelect = true;
    document
      .querySelectorAll("input.bulk-select:not(:checked)")
      .forEach((el) => el.click());
  }

  @action
  clearAll() {
    this.args.bulkSelectHelper.autoAddBookmarksToBulkSelect = false;
    document
      .querySelectorAll("input.bulk-select:checked")
      .forEach((el) => el.click());
  }

  @action
  toggleBookmarkSelection(bookmark, event) {
    const target = event.target;
    const selected = this.selected;

    if (target.checked) {
      addUniqueValueToArray(selected, bookmark);

      if (this.#lastChecked && event.shiftKey) {
        const bulkSelects = Array.from(
            document.querySelectorAll("input.bulk-select")
          ),
          from = bulkSelects.indexOf(target),
          to = bulkSelects.findIndex((el) => el.id === this.#lastChecked.id),
          start = Math.min(from, to),
          end = Math.max(from, to);

        bulkSelects
          .slice(start, end)
          .filter((el) => el.checked !== true)
          .forEach((checkbox) => {
            checkbox.click();
          });
      }
      this.#lastChecked = target;
    } else {
      removeValueFromArray(selected, bookmark);
      this.#lastChecked = null;
    }
  }

  <template>
    <div class="bookmark-list-wrapper" ...attributes>
      <DConditionalLoadingSpinner @condition={{@loading}}>
        <DLoadMore @action={{@loadMore}}>
          <table class="topic-list bookmark-list">
            <thead class="topic-list-header">
              <tr>
                {{#if this.site.desktopView}}
                  <PluginOutlet @name="bookmark-list-table-header">
                    {{#if this.bulkSelectEnabled}}
                      <th class="bulk-select topic-list-data">
                        <DButton
                          class="bulk-select btn-flat"
                          @action={{this.toggleBulkSelect}}
                          @icon="list-check"
                          @title="bookmarks.bulk.toggle"
                        />
                      </th>
                    {{/if}}
                    <th class="topic-list-data">

                      {{#if this.bulkSelectEnabled}}
                        <span class="bulk-select-topics">
                          {{~#if this.canDoBulkActions}}
                            <div class="bulk-select-bookmarks-dropdown">
                              <span
                                class="bulk-select-bookmark-dropdown__count"
                              >
