                        {{else}}
                          <a
                            aria-level="2"
                            class="title"
                            href={{bookmark.bookmarkable_url}}
                            role="heading"
                          >
                            {{bookmark.fancy_title}}
                          </a>
                        {{/if}}
                      </div>
                    </span>
                    {{#if bookmark.bookmarkableTopicAlike}}
                      <div class="link-bottom-line">
                        {{dCategoryLink bookmark.category}}
                        <PluginOutlet
                          @name="bookmark-list-tags-wrapper"
                          @outletArgs={{lazyHash
                            bookmark=bookmark
                            tags=bookmark.visibleListTags
                            tagsForUser=@tagsForUser
                          }}
                        >
                          {{dDiscourseTags
                            bookmark
                            mode="list"
                            tagsForUser=@tagsForUser
                          }}
                        </PluginOutlet>
                      </div>
                    {{/if}}
                    {{#if
                      (and
                        this.site.mobileView
                        bookmark.excerpt
                        bookmark.user.avatar_template
                      )
                    }}
                      <a
                        class="avatar"
                        data-user-card={{bookmark.user.username}}
                        href={{bookmark.bookmarkableUser.path}}
                      >
                        {{dAvatar
                          bookmark.bookmarkableUser
                          avatarTemplatePath="avatar_template"
                          usernamePath="username"
                          namePath="name"
                          imageSize="large"
                        }}
                      </a>
                    {{/if}}

                    {{! eslint-disable ember/template-no-invalid-interactive }}
                    {{#if bookmark.excerpt}}
                      <p
                        class="post-excerpt"
                        {{on "click" this.screenExcerptForExternalLink}}
                      >{{trustHTML bookmark.excerpt}}</p>
                    {{/if}}
                  </td>
                  {{#if this.site.desktopView}}
                    <td class="author-avatar topic-list-data">
                      {{#if bookmark.user.avatar_template}}
                        <a
                          class="avatar"
                          data-user-card={{bookmark.user.username}}
                          href={{bookmark.user.path}}
                        >
                          {{dAvatar
                            bookmark.user
                            avatarTemplatePath="avatar_template"
                            usernamePath="username"
                            namePath="name"
                            imageSize="large"
                          }}
                        </a>
                      {{/if}}
                    </td>
                    <td
                      class="post-metadata topic-list-data updated-at"
                    >{{dFormatDate bookmark.updated_at format="tiny"}}</td>
                    <ActivityCell class="post-metadata" @topic={{bookmark}} />
                  {{/if}}
                  <td class="topic-list-data">
                    <BookmarkActionsDropdown
                      @bookmark={{bookmark}}
                      @clearBookmarkReminder={{this.clearBookmarkReminder}}
                      @editBookmark={{this.editBookmark}}
                      @removeBookmark={{this.removeBookmark}}
                      @togglePinBookmark={{this.togglePinBookmark}}
                    />
                  </td>
                </tr>
              {{/each}}
            </tbody>
          </table>
          <DConditionalLoadingSpinner @condition={{@loadingMore}} />
        </DLoadMore>
      </DConditionalLoadingSpinner>
    </div>
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { fn } from "@ember/helper";
import { action } from "@ember/object";
import { service } from "@ember/service";
import BookmarkModal from "discourse/components/modal/bookmark";
import DMenu from "discourse/float-kit/components/d-menu";
import { popupAjaxError } from "discourse/lib/ajax-error";
import {
  TIME_SHORTCUT_TYPES,
  timeShortcuts,
} from "discourse/lib/time-shortcut";
import {
  NO_REMINDER_ICON,
  NOT_BOOKMARKED,
  WITH_REMINDER_ICON,
} from "discourse/models/bookmark";
import DButton from "discourse/ui-kit/d-button";
import DDropdownMenu from "discourse/ui-kit/d-dropdown-menu";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

export default class BookmarkMenu extends Component {
  @service modal;
  @service currentUser;
  @service toasts;

  @tracked quicksaved = false;
  @tracked reminderAtOptions = [];

  timezone = this.currentUser?.user_option?.timezone || moment.tz.guess();
  timeShortcuts = timeShortcuts(this.timezone);

  /** @type {Promise<void> | null} */
  bookmarkCreatePromise = null;

  get bookmarkManager() {
    return this.args.bookmarkManager;
  }

  get existingBookmark() {
    return this.bookmarkManager.trackedBookmark?.id
      ? this.bookmarkManager.trackedBookmark
      : null;
  }

  get showEditDeleteMenu() {
    return this.existingBookmark && !this.quicksaved;
  }

  get buttonTitle() {
    if (!this.existingBookmark) {
      return i18n("bookmarks.not_bookmarked");
    } else {
      if (this.existingBookmark.reminderAt) {
        return i18n("bookmarks.created_with_reminder_generic", {
          date: this.existingBookmark.formattedReminder(this.timezone),
          name: this.existingBookmark.name || "",
        });
      } else {
        return i18n("bookmarks.created_generic", {
          name: this.existingBookmark.name || "",
        });
      }
    }
  }

  get buttonClasses() {
    let cssClasses = ["bookmark widget-button bookmark-menu__trigger"];

    if (!this.args.showLabel) {
      cssClasses.push("btn-icon no-text");
    } else {
      cssClasses.push("btn-icon-text");
    }

    if (this.args.buttonClasses) {
      cssClasses.push(this.args.buttonClasses);
    }

    if (this.existingBookmark) {
      cssClasses.push("bookmarked");
      if (this.existingBookmark.reminderAt) {
        cssClasses.push("with-reminder");
      }
    }

    return cssClasses.join(" ");
  }

  get buttonIcon() {
    if (this.existingBookmark?.reminderAt) {
      return WITH_REMINDER_ICON;
    } else if (this.existingBookmark) {
      return NO_REMINDER_ICON;
    } else {
      return NOT_BOOKMARKED;
    }
  }

  get buttonLabel() {
    if (!this.args.showLabel) {
      return;
    }

    if (this.existingBookmark) {
      return i18n("bookmarked.edit_bookmark", { count: 1 });
    } else {
      return i18n("bookmarked.title");
    }
  }

  @action
  setReminderShortcuts() {
    this.reminderAtOptions = [
      this.timeShortcuts.twoHours(),
      this.timeShortcuts.tomorrow(),
      this.timeShortcuts.threeDays(),
    ];

    const custom = this.timeShortcuts.custom();
    custom.label = "time_shortcut.more_options";
    custom.icon = "far-calendar-plus";
    this.reminderAtOptions.push(custom);
  }

  @action
  reminderShortcutTimeTitle(option) {
    if (!option.time) {
      return "";
    }
    return option.time.format(i18n(option.timeFormatKey));
  }

  @action
  onBookmark() {
    this.bookmarkCreatePromise = this.bookmarkManager.create();
    this.bookmarkCreatePromise
      .then(() => {
        // We show the menu with Edit/Delete options if the bookmark exists,
        // so this "quicksave" will do nothing in that case.
        // NOTE: Need a nicer way to handle this; otherwise as soon as you save
        // a bookmark, it switches to the other Edit/Delete menu.
        this.quicksaved = true;
        this.toasts.success({
          duration: "short",
          views: ["mobile"],
          data: { message: i18n("bookmarks.bookmarked_success") },
        });
      })
      .catch((error) => popupAjaxError(error))
      .finally(() => {
        this.bookmarkCreatePromise = null;
      });
  }

  @action
  onShowMenu() {
    this.setReminderShortcuts();
    if (!this.existingBookmark) {
      this.onBookmark();
    }
  }

  @action
  onRegisterApi(api) {
    this.dMenu = api;
  }

  @action
  onEditBookmark() {
    this._openBookmarkModal();
  }

  @action
  onCloseMenu() {
    this.quicksaved = false;
  }

  @action
  async onRemoveBookmark() {
    try {
      const response = await this.bookmarkManager.delete();
      this.bookmarkManager.afterDelete(response, this.existingBookmark.id);
      this.toasts.success({
        duration: "short",
        data: {
          icon: "trash-can",
          message: i18n("bookmarks.deleted_bookmark_success"),
        },
      });
    } catch (error) {
      popupAjaxError(error);
    } finally {
      this.dMenu.close();
    }
  }

  @action
  async onClearReminder() {
    try {
      this.existingBookmark.selectedReminderType = null;
      this.existingBookmark.selectedDatetime = null;
      this.existingBookmark.reminderAt = null;

      await this.bookmarkManager.save();

      this.toasts.success({
        duration: "short",
        data: { message: i18n("bookmarks.reminder_clear_success") },
      });
    } catch (error) {
      popupAjaxError(error);
    } finally {
      this.dMenu.close();
    }
  }

  @action
  async onChooseReminderOption(option) {
    if (this.bookmarkCreatePromise) {
      await this.bookmarkCreatePromise;
    }

    if (option.id === TIME_SHORTCUT_TYPES.CUSTOM) {
      this._openBookmarkModal();
    } else {
      this.existingBookmark.selectedReminderType = option.id;
      this.existingBookmark.selectedDatetime = option.time;
      this.existingBookmark.reminderAt = option.time;

      try {
        await this.bookmarkManager.save();
        this.toasts.success({
          duration: "short",
          views: ["mobile"],
          data: { message: i18n("bookmarks.reminder_set_success") },
        });
      } catch (error) {
        popupAjaxError(error);
      } finally {
        this.dMenu.close();
      }
    }
  }

  async _openBookmarkModal() {
    await this.dMenu.close();

    try {
      const closeData = await this.modal.show(BookmarkModal, {
        model: {
          bookmark: this.existingBookmark,
          afterSave: (savedData) => {
            return this.bookmarkManager.afterSave(savedData);
          },
          afterDelete: (response, bookmarkId) => {
            this.bookmarkManager.afterDelete(response, bookmarkId);
          },
        },
      });
      this.bookmarkManager.afterModalClose(closeData);
    } catch (error) {
      popupAjaxError(error);
    }
  }

  <template>
    <DMenu
      ...attributes
      class={{this.buttonClasses}}
      @arrow={{false}}
      @icon={{this.buttonIcon}}
      @identifier="bookmark-menu"
      @label={{this.buttonLabel}}
      @onClose={{this.onCloseMenu}}
      @onRegisterApi={{this.onRegisterApi}}
      @onShow={{this.onShowMenu}}
      @title={{this.buttonTitle}}
    >
      <:content>
        <DDropdownMenu as |dropdown|>
          {{#unless this.showEditDeleteMenu}}
            <dropdown.item class="bookmark-menu__title">
              {{dIcon "circle-check"}}
              <span>{{i18n "bookmarks.bookmarked_success"}}</span>
            </dropdown.item>
          {{/unless}}

          {{#if this.showEditDeleteMenu}}
            <dropdown.item
              class="bookmark-menu__row -edit"
              data-menu-option-id="edit"
            >
              <DButton
                class="bookmark-menu__row-btn btn-transparent"
                @action={{this.onEditBookmark}}
                @icon="pencil"
                @label="edit"
              />
            </dropdown.item>

            {{#if this.existingBookmark.reminderAt}}
              <dropdown.item
                class="bookmark-menu__row --clear-reminder"
                data-menu-option-id="clear-reminder"
                role="button"
                tabindex="0"
              >
                <DButton
                  class="bookmark-menu__row-btn btn-transparent"
                  @action={{this.onClearReminder}}
                  @icon="bell-slash"
                  @label="bookmarks.clear_reminder"
                />
              </dropdown.item>
            {{/if}}

            <dropdown.item
              class="bookmark-menu__row --remove"
              data-menu-option-id="delete"
              role="button"
              tabindex="0"
            >
              <DButton
                class="bookmark-menu__row-btn --danger"
                @action={{this.onRemoveBookmark}}
                @icon="trash-can"
                @label="delete"
              />
            </dropdown.item>

          {{else}}
            <dropdown.item class="bookmark-menu__row-title">
              {{dIcon "bell"}}
              {{i18n "bookmarks.also_set_reminder"}}
            </dropdown.item>

            <dropdown.divider />

            {{#each this.reminderAtOptions as |option|}}
              <dropdown.item
                class="bookmark-menu__row"
                data-menu-option-id={{option.id}}
              >
                <DButton
                  class="bookmark-menu__row-btn btn-transparent"
                  @action={{fn this.onChooseReminderOption option}}
                  @icon={{option.icon}}
                  @label={{option.label}}
                  @translatedTitle={{this.reminderShortcutTimeTitle option}}
                />
              </dropdown.item>
            {{/each}}
          {{/if}}
        </DDropdownMenu>
      </:content>
    </DMenu>
  </template>
}
import Component from "@glimmer/component";
import { hash } from "@ember/helper";
import { LinkTo } from "@ember/routing";
import {
  ALL_CATEGORIES_ID,
  NO_CATEGORIES_ID,
} from "discourse/select-kit/components/category-drop";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

export default class CategoryDropMoreCollection extends Component {
  tagName = "";

  get moreCount() {
    if (!this.args.selectKit.totalCount) {
      return 0;
    }

    const currentCount = this.args.collection.content.filter(
      (category) =>
        category.id !== NO_CATEGORIES_ID && category.id !== ALL_CATEGORIES_ID
    ).length;

    return this.args.selectKit.totalCount - currentCount;
  }

  get slugPath() {
    return this.args.selectKit.options.parentCategory.path.substring(
      "/c/".length
    );
  }

  <template>
    {{#if this.moreCount}}
      <div class="category-drop-footer">
        <span>
          {{i18n "categories.plus_more_count" (hash count=this.moreCount)}}
        </span>

        {{#if @selectKit.options.parentCategory}}
          <LinkTo @model={{this.slugPath}} @route="discovery.subcategories">
            {{i18n "categories.view_all"}}
            {{dIcon "up-right-from-square"}}
          </LinkTo>
        {{else}}
          <LinkTo @route="discovery.categories">
            {{i18n "categories.view_all"}}
            {{dIcon "up-right-from-square"}}
          </LinkTo>
        {{/if}}
      </div>
    {{/if}}
  </template>
}
import { computed } from "@ember/object";
import { classNames } from "@ember-decorators/component";
import ComboBoxSelectBoxHeaderComponent from "discourse/select-kit/components/combo-box/combo-box-header";
import { resolveComponent } from "discourse/select-kit/components/select-kit";
import dIcon from "discourse/ui-kit/helpers/d-icon";

@classNames("category-drop-header")
export default class CategoryDropHeader extends ComboBoxSelectBoxHeaderComponent {
