        </tr>
      {{else}}
        <tr
          class="{{if
              this.category.description_excerpt
              'has-description'
              'no-description'
            }}
            {{if this.category.uploaded_logo.url 'has-logo' 'no-logo'}}"
          data-category-id={{this.category.id}}
          data-notification-level={{this.category.notificationLevelString}}
