import Component from "@ember/component";
import { on } from "@ember/modifier";
import { action, computed } from "@ember/object";
import { trustHTML } from "@ember/template";
import { tagName } from "@ember-decorators/component";
import { SECOND_FACTOR_METHODS } from "discourse/models/user";
import { i18n } from "discourse-i18n";

@tagName("")
export default class SecondFactorForm extends Component {
  @computed("secondFactorMethod")
  get secondFactorTitle() {
    switch (this.secondFactorMethod) {
      case SECOND_FACTOR_METHODS.TOTP:
        return i18n("login.second_factor_title");
      case SECOND_FACTOR_METHODS.SECURITY_KEY:
        return i18n("login.second_factor_title");
      case SECOND_FACTOR_METHODS.PASSKEY:
        return i18n("login.second_factor_title");
      case SECOND_FACTOR_METHODS.BACKUP_CODE:
        return i18n("login.second_factor_backup_title");
    }
  }

  @computed("secondFactorMethod")
  get secondFactorDescription() {
    switch (this.secondFactorMethod) {
      case SECOND_FACTOR_METHODS.TOTP:
        return i18n("login.second_factor_description");
      case SECOND_FACTOR_METHODS.SECURITY_KEY:
        return i18n("login.security_key_description");
      case SECOND_FACTOR_METHODS.PASSKEY:
        return i18n("login.passkey_2fa_description");
      case SECOND_FACTOR_METHODS.BACKUP_CODE:
        return i18n("login.second_factor_backup_description");
    }
  }

  @computed("secondFactorMethod", "isLogin")
  get linkText() {
    if (this.isLogin) {
      return this.secondFactorMethod === SECOND_FACTOR_METHODS.TOTP
        ? "login.second_factor_backup"
        : "login.second_factor";
    } else {
      return this.secondFactorMethod === SECOND_FACTOR_METHODS.TOTP
        ? "user.second_factor_backup.use"
        : "user.second_factor.use";
    }
  }

  @computed("backupEnabled", "totpEnabled", "secondFactorMethod")
  get showToggleMethodLink() {
    return (
      this.backupEnabled &&
      this.totpEnabled &&
      this.secondFactorMethod !== SECOND_FACTOR_METHODS.SECURITY_KEY
    );
  }

  @action
  toggleSecondFactorMethod(event) {
    event?.preventDefault();
    const secondFactorMethod = this.secondFactorMethod;
    this.set("secondFactorToken", "");
    if (secondFactorMethod === SECOND_FACTOR_METHODS.TOTP) {
      this.set("secondFactorMethod", SECOND_FACTOR_METHODS.BACKUP_CODE);
    } else {
      this.set("secondFactorMethod", SECOND_FACTOR_METHODS.TOTP);
    }
  }

  <template>
    <div id="second-factor" ...attributes>
      <h3>{{this.secondFactorTitle}}</h3>

      {{#if this.optionalText}}
        <p>{{trustHTML this.optionalText}}</p>
      {{/if}}

      <p class="second-factor__description">{{this.secondFactorDescription}}</p>

      {{yield}}

      {{#if this.showToggleMethodLink}}
        <p>
          <a
            class="toggle-second-factor-method"
            href
            {{on "click" this.toggleSecondFactorMethod}}
          >{{i18n this.linkText}}</a>
        </p>
      {{/if}}
    </div>
  </template>
}
import Component from "@glimmer/component";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import { SECOND_FACTOR_METHODS } from "discourse/models/user";
import DButton from "discourse/ui-kit/d-button";
import { i18n } from "discourse-i18n";

export default class SecurityKeyForm extends Component {
  get showSecurityKeyButton() {
    // when the granular args aren't passed, keep the legacy single-button
    // rendering driven by `@action`
    return this.args.securityKeysEnabled ?? true;
  }

  get securityKeyAction() {
    return this.args.securityKeyAction ?? this.args.action;
  }

  get securityKeyLabel() {
    return this.args.passkeysEnabled
      ? "login.use_security_key"
      : "login.security_key_authenticate";
  }

  @action
  useAnotherMethod(event) {
    event.preventDefault();
    this.args.setShowSecurityKey?.(false);
    this.args.setShowSecondFactor?.(true);

    if (this.args.totpEnabled) {
      this.args.setSecondFactorMethod?.(SECOND_FACTOR_METHODS.TOTP);
    } else if (this.args.backupEnabled) {
      this.args.setSecondFactorMethod?.(SECOND_FACTOR_METHODS.BACKUP_CODE);
    }
  }

  <template>
    <div id="security-key">
      {{#if @passkeysEnabled}}
        <DButton
          class="btn-large btn-primary"
          id="passkey-authenticate-button"
          @action={{@passkeyAction}}
          @icon="user"
          @label="login.use_passkey"
        />
      {{/if}}
      {{#if this.showSecurityKeyButton}}
        <DButton
          class="btn-large {{if @passkeysEnabled 'btn-default' 'btn-primary'}}"
          id="security-key-authenticate-button"
          @action={{this.securityKeyAction}}
          @icon="key"
          @label={{this.securityKeyLabel}}
        />
      {{/if}}
      <p>
        {{#if @otherMethodAllowed}}
          <a
            class="toggle-second-factor-method"
            href
            {{on "click" this.useAnotherMethod}}
          >{{i18n "login.security_key_alternative"}}</a>
        {{/if}}
      </p>
    </div>
  </template>
}
