    this._step = this.args.initialStep ?? "email";
    if (this.isCodeStep) {
      this.startResendCooldown();
    }
  }

  willDestroy() {
    super.willDestroy(...arguments);
    cancel(this.#cooldownTimer);
    cancel(this.#usernameDebounce);
    this.#usernameCheckSeq++;
    this.#clearPendingAvatarUrl();
