@classNames("title-input")
export default class ComposerTitle extends Component {
  isTitleFocused = false;

  @computed("composer.canEditTopicFeaturedLink")
  get watchForLink() {
    return this.composer?.canEditTopicFeaturedLink;
  }

  set watchForLink(value) {
    set(this, "composer.canEditTopicFeaturedLink", value);
  }

  @computed("composer.loading", "composer.disableTitleInput")
  get disabled() {
    return this.composer?.loading || this.composer?.disableTitleInput;
  }

  @computed(
    "composer.titleLength",
    "composer.missingTitleCharacters",
    "composer.minimumTitleLength",
    "lastValidatedAt",
    "isTitleFocused"
  )
  get validation() {
    let reason;
    if (this.isTitleFocused) {
      return;
    }
    if (this.composer?.titleLength < 1) {
      reason = i18n("composer.error.title_missing");
    } else if (this.composer?.missingTitleCharacters > 0) {
      reason = i18n("composer.error.title_too_short", {
        count: this.composer?.minimumTitleLength,
      });
    } else if (
      this.composer?.titleLength > this.siteSettings.max_topic_title_length
    ) {
      reason = i18n("composer.error.title_too_long", {
        count: this.siteSettings.max_topic_title_length,
      });
    }

    if (reason) {
      return EmberObject.create({
        failed: true,
        reason,
        lastShownAt: this.lastValidatedAt,
      });
    }
  }

  @computed("watchForLink")
  get titleMaxLength() {
    // maxLength gets in the way of pasting long links, so don't use it if featured links are allowed.
    // Validation will display a message if titles are too long.
    return this.watchForLink ? null : this.siteSettings.max_topic_title_length;
  }

  @computed("composer.title", "composer.titleLength")
  get isAbsoluteUrl() {
    return (
      this.composer?.titleLength > 0 &&
      /^(https?:)?\/\/[\w\.\-]+/i.test(this.composer?.title) &&
      !/\s/.test(this.composer?.title)
    );
  }

  @computed("composer.categoryTitlePlaceholder", "composer.titlePlaceholder")
  get titleAriaLabel() {
    return (
      this.composer.categoryTitlePlaceholder ||
      i18n(this.composer.titlePlaceholder)
    );
  }

  didInsertElement() {
    super.didInsertElement(...arguments);
    const titleInput = this.element.querySelector("input");

    this._focusHandler = () => this.set("isTitleFocused", true);
    this._blurHandler = () => this.set("isTitleFocused", false);

    titleInput.addEventListener("focus", this._focusHandler);
    titleInput.addEventListener("blur", this._blurHandler);

    if (this.focusTarget === "title") {
      putCursorAtEnd(titleInput);
    }

    if (this.get("composer.titleLength") > 0) {
      discourseDebounce(this, this._titleChanged, 10);
    }
  }

  willDestroyElement() {
    super.willDestroyElement(...arguments);
    const titleInput = this.element.querySelector("input");

    if (titleInput) {
      titleInput.removeEventListener("focus", this._focusHandler);
      titleInput.removeEventListener("blur", this._blurHandler);
    }
  }

  changeTitle(val) {
    if (val && val.length > 0) {
      this.set("composer.title", val.trim());
    }
  }

  bodyIsDefault() {
    const reply = this.get("composer.reply") || "";
    return (
      reply.length === 0 ||
      reply === (this.get("composer.category.topic_template") || "")
    );
  }

  @observes("composer.titleLength", "watchForLink")
  _titleChanged() {
    if (this.get("composer.titleLength") === 0) {
      this.set("autoPosted", false);
    }
    if (this.autoPosted || !this.watchForLink) {
      return;
    }

    if (isTesting()) {
      next(() =>
        // not ideal but we don't want to run this in current
        // runloop to avoid an error in console
        this._checkForUrl()
      );
    } else {
      discourseDebounce(this, this._checkForUrl, 500);
    }
  }

  @observes("composer.replyLength")
  _clearFeaturedLink() {
    if (this.watchForLink && this.bodyIsDefault()) {
      this.set("composer.featuredLink", null);
    }
  }

  _checkForUrl() {
    if (!this.element || this.isDestroying) {
      return;
    }

    if (!this.isAbsoluteUrl) {
      return;
    }

    // only feature links to external sites
    if (
      this.get("composer.title").match(
        new RegExp("^https?:\\/\\/" + window.location.hostname, "i")
      )
    ) {
      return;
    }

    // Try to onebox. If success, update post body and title.
    this.set("composer.loading", true);

    const link = document.createElement("a");
    link.href = this.get("composer.title");

    const loadOnebox = load({
      elem: link,
      refresh: false,
      ajax,
      synchronous: true,
      categoryId: this.get("composer.category.id"),
      topicId: this.get("composer.topic.id"),
    });

    if (loadOnebox && loadOnebox.then) {
      loadOnebox
        .then(() => {
          const v = lookupCache(this.get("composer.title"));
          this._updatePost(v ? v : link);
        })
        .finally(() => {
          this.set("composer.loading", false);
          schedule("afterRender", () => {
            putCursorAtEnd(this.element.querySelector("input"));
          });
        });
    } else {
      this._updatePost(loadOnebox);
      this.set("composer.loading", false);
      schedule("afterRender", () => {
        putCursorAtEnd(this.element.querySelector("input"));
      });
    }
  }

  _updatePost(html) {
    if (html) {
      const frag = document.createRange().createContextualFragment(html),
        composer = this.composer;

      this.set("autoPosted", true);
      this.set("composer.featuredLink", this.get("composer.title"));

      composer.appendText(this.get("composer.title"), null, { block: true });

      if (frag.querySelector(".twitterstatus")) {
        this.set("composer.title", "");
        return;
      }

      const heading = frag.querySelector("h3, h4");

      const title =
        (heading && heading.textContent) ||
        (frag.firstElementChild && frag.firstElementChild.title);

      if (title) {
        this.changeTitle(title);
      } else {
        const firstTitle =
          (frag.firstChild &&
            frag.firstChild.attributes &&
            frag.firstChild.attributes.title) ||
          (frag.querySelector("[title]") &&
            frag.querySelector("[title]").attributes.title);

        if (firstTitle) {
          this.changeTitle(firstTitle);
        }
      }
    }
  }

  <template>
    <DTextField
      @aria-label={{this.titleAriaLabel}}
      @autocomplete="off"
      @disabled={{this.disabled}}
      @id="reply-title"
      @maxLength={{this.titleMaxLength}}
      @placeholder={{this.composer.categoryTitlePlaceholder}}
      @placeholderKey={{this.composer.titlePlaceholder}}
      @value={{this.composer.title}}
    />

    <PluginOutlet
      @connectorTagName="div"
      @name="after-composer-title-input"
      @outletArgs={{lazyHash composer=this.composer}}
    />

    <DPopupInputTip @validation={{this.validation}} />
  </template>
}
import Component from "@glimmer/component";
import { service } from "@ember/service";
import PluginOutlet from "discourse/components/plugin-outlet";
import { applyValueTransformer } from "discourse/lib/transformer";
import DButton from "discourse/ui-kit/d-button";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";

export default class ComposerToggles extends Component {
  @service composer;
  @service site;
  @service siteSettings;

  get additionalClasses() {
    return applyValueTransformer("composer-toggles-class", "");
  }

  get showCollapseButton() {
    return (
      this.args.composeState !== "draft" && this.args.composeState !== "saving"
    );
  }

  get showPreviewToggle() {
    return this.args.composeState !== "draft";
  }

  get toggleToolbarTitle() {
    return this.args.showToolbar
      ? "composer.hide_toolbar"
      : "composer.show_toolbar";
  }

  get fullscreenTitle() {
    return this.args.composeState === "fullscreen"
      ? "composer.exit_fullscreen"
      : "composer.enter_fullscreen";
  }

  get fullscreenIcon() {
    return this.args.composeState === "fullscreen"
      ? "discourse-compress"
      : "discourse-expand";
  }

  get showFullScreenButton() {
    if (this.site.mobileView || this.args.composeState === "draft") {
      return false;
    }
    return !this.args.disableTextarea;
  }

  get showToolbarToggle() {
    return this.site.mobileView;
  }

  <template>
    <div class={{dConcatClass "composer-controls" this.additionalClasses}}>
      <PluginOutlet @connectorTagName="div" @name="before-composer-toggles" />

      {{#unless this.siteSettings.enable_composer_redesign}}
        {{#if this.showToolbarToggle}}
          <DButton
            class="btn-transparent toggle-toolbar btn-small"
            @action={{@toggleToolbar}}
            @icon="bars"
            @preventFocus={{true}}
            @title={{this.toggleToolbarTitle}}
          />
        {{/if}}
      {{/unless}}
      {{#if
        (and
          this.composer.allowPreview
          this.site.desktopView
          this.showPreviewToggle
        )
      }}
        <DButton
          class={{dConcatClass
            "btn-transparent btn-mini-toggle toggle-preview"
            (unless this.composer.isPreviewVisible "active")
          }}
          @action={{this.composer.togglePreview}}
          @icon="angles-left"
          @translatedTitle={{this.composer.toggleText}}
        />
      {{/if}}

      {{#if this.showFullScreenButton}}
        <DButton
          class="btn-transparent toggle-fullscreen btn-small"
          @action={{@toggleFullscreen}}
          @icon={{this.fullscreenIcon}}
          @title={{this.fullscreenTitle}}
        />
      {{/if}}

      {{#if this.showCollapseButton}}
        <DButton
          class="btn-transparent toggler toggle-minimize btn-small"
          @action={{@toggleComposer}}
          @icon="minus"
          @title="composer.collapse"
        />
      {{/if}}

      {{#if @saveAndClose}}
        <DButton
          class="btn-transparent toggler toggle-save-and-close btn-small"
          @action={{@saveAndClose}}
          @icon="xmark"
          @title="composer.save_and_close"
        />
      {{/if}}
    </div>
  </template>
}
