import { concat } from "@ember/helper";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import { service } from "@ember/service";
import NavigationItem from "discourse/components/navigation-item";
import PluginOutlet from "discourse/components/plugin-outlet";
import DMenu from "discourse/float-kit/components/d-menu";
import lazyHash from "discourse/helpers/lazy-hash";
import { filterTypeForMode } from "discourse/lib/filter-mode";
import { applyValueTransformer } from "discourse/lib/transformer";
import DDropdownMenu from "discourse/ui-kit/d-dropdown-menu";
import dIcon from "discourse/ui-kit/helpers/d-icon";

export default class NavigationBarComponent extends Component {
  @service site;

  get filterType() {
    return filterTypeForMode(this.args.filterMode);
  }

  get selectedNavItem() {
    const { navItems } = this.args;
    let item = navItems.find((i) => i.active === true);

    item = item || navItems.find((i) => i.filterType === this.filterType);

    return item || navItems[0];
  }

  get showDropdown() {
    return applyValueTransformer(
      "navigation-bar-dropdown-mode",
      this.site.mobileView
    );
  }

  get navigationBarIcon() {
    return applyValueTransformer(
      "navigation-bar-dropdown-icon",
      "discourse-chevron-expand"
    );
  }

  @action
  onRegisterApi(api) {
    this.dMenu = api;
  }

  <template>
    <ul class="nav nav-pills" id="navigation-bar">
      {{#if this.showDropdown}}
        <li>
          <DMenu
            @autofocus={{true}}
            @identifier="list-control-toggle-link"
            @modalForMobile={{true}}
            @onRegisterApi={{this.onRegisterApi}}
          >
            <:trigger>
              <span
                class="list-control-toggle-link__text"
              >{{this.selectedNavItem.displayName}}</span>
              {{dIcon this.navigationBarIcon}}
            </:trigger>

            <:content>
              <DDropdownMenu {{on "click" this.dMenu.close}} as |dropdown|>
                {{#each @navItems as |navItem|}}
                  <NavigationItem
                    class={{concat "nav-item_" navItem.name}}
                    @category={{@category}}
                    @content={{navItem}}
                    @filterMode={{@filterMode}}
                  />

                {{/each}}
                <dropdown.item>
                  <PluginOutlet
                    @connectorTagName="span"
                    @name="extra-nav-item"
                    @outletArgs={{lazyHash
                      category=@category
                      tag=@tag
                      filterMode=@filterMode
                    }}
                  />
                </dropdown.item>
              </DDropdownMenu>
            </:content>
          </DMenu>
        </li>
        <li>
          <PluginOutlet
            @connectorTagName="span"
            @name="inline-extra-nav-item"
            @outletArgs={{lazyHash category=@category filterMode=@filterMode}}
          />
        </li>
      {{else}}
        {{#each @navItems as |navItem|}}
          <NavigationItem
            class={{concat "nav-item_" navItem.name}}
            @category={{@category}}
            @content={{navItem}}
            @filterMode={{@filterMode}}
          />
        {{/each}}
        <PluginOutlet
          @connectorTagName="li"
          @name="extra-nav-item"
          @outletArgs={{lazyHash
            category=@category
            tag=@tag
            filterMode=@filterMode
          }}
        />

      {{/if}}
    </ul>
  </template>
}
import DButton from "discourse/ui-kit/d-button";

const TagInfoButton = <template>
  <DButton
    class="btn-default"
    id="show-tag-info"
    @action={{@toggleInfo}}
    @ariaLabel="tagging.info"
    @ariaPressed={{if @active true false}}
    @icon="circle-info"
    @isLoading={{@loading}}
    @title="tagging.info"
  />
</template>;

export default TagInfoButton;
import NotificationsTracking from "discourse/components/notifications-tracking";

const TagNotificationsTracking = <template>
  <NotificationsTracking
    class="tag-notifications-tracking"
    @levelId={{@levelId}}
    @onChange={{@onChange}}
    @prefix="tagging.notifications"
    @showCaret={{false}}
    @showFullTitle={{false}}
  />
</template>;

export default TagNotificationsTracking;
import Component from "@glimmer/component";
import { action } from "@ember/object";
import { service } from "@ember/service";
import DismissReadModal from "discourse/components/modal/dismiss-read";
import DButton from "discourse/ui-kit/d-button";
import DComboButton from "discourse/ui-kit/d-combo-button";
import DDropdownMenu from "discourse/ui-kit/d-dropdown-menu";
import { i18n } from "discourse-i18n";

export default class TopicDismissButtons extends Component {
  @service currentUser;
  @service modal;
  @service site;

  dMenu;

  get showBasedOnPosition() {
    return this.args.position === "top" || this.args.model.topics.length > 5;
  }

  get dismissLabel() {
    if (this.args.selectedTopics.length === 0) {
      return i18n("topics.bulk.dismiss_button");
    }

    return i18n("topics.bulk.dismiss_button_with_selected", {
      count: this.args.selectedTopics.length,
    });
  }

  get dismissNewLabel() {
    if (this.currentUser?.unified_new_enabled) {
      switch (this.newListSubset) {
        case "topics":
          if (this.args.selectedTopics.length > 0) {
            return i18n("topics.bulk.dismiss_new_topics_with_selected", {
              count: this.args.selectedTopics.length,
            });
          }
          return i18n("topics.bulk.dismiss_new_topics");
        case "replies":
          if (this.args.selectedTopics.length > 0) {
            return i18n("topics.bulk.dismiss_new_replies_with_selected", {
              count: this.args.selectedTopics.length,
            });
          }
          return i18n("topics.bulk.dismiss_new_replies");
        default:
          if (this.args.selectedTopics.length > 0) {
            return i18n("topics.bulk.dismiss_all_with_selected", {
              count: this.args.selectedTopics.length,
            });
          }
          return i18n("topics.bulk.dismiss_all");
      }
    }

    if (this.args.selectedTopics.length === 0) {
      return i18n("topics.bulk.dismiss_new");
    }

    return i18n("topics.bulk.dismiss_new_with_selected", {
      count: this.args.selectedTopics.length,
    });
  }

  get newListSubset() {
    return (
      this.args.model?.params?.subset ?? this.args.model?.listParams?.subset
    );
  }

  get showDismissNewStopTracking() {
    return this.newListSubset !== "topics";
  }

  get showDismissNewMenu() {
    // On mobile the bottom dismiss button is the floating control, so the
    // stop-tracking menu only renders on the top button.
    return (
      this.showDismissNewStopTracking &&
      !(this.site.mobileView && this.args.position === "bottom")
    );
  }

  get dismissNewOptions() {
    const options = {
      dismissPosts: true,
      dismissTopics: true,
      untrack: false,
    };

    if (this.newListSubset === "topics") {
      options.dismissPosts = false;
    } else if (this.newListSubset === "replies") {
      options.dismissTopics = false;
    }

    return options;
  }

  @action
  dismissReadPosts() {
    this.modal.show(DismissReadModal, {
      model: {
        title: this.args.selectedTopics.length
          ? "topics.bulk.dismiss_read_with_selected"
          : "topics.bulk.dismiss_read",
        count: this.args.selectedTopics.length,
        dismissRead: this.args.dismissRead,
      },
    });
  }

  @action
  registerDMenu(api) {
    this.dMenu = api;
  }

  @action
  dismissNew(untrack = false) {
    this.args.resetNew({ ...this.dismissNewOptions, untrack });
  }

  @action
  async dismissNewAndStopTracking() {
    await this.dMenu?.close();
    this.dismissNew(true);
  }

  <template>
    {{~#if this.showBasedOnPosition~}}
      <div class="row dismiss-container-{{@position}}">
        {{~#if @showDismissRead~}}
          <DButton
            class="btn-default dismiss-read"
            id="dismiss-topics-{{@position}}"
            @action={{this.dismissReadPosts}}
            @title="topics.bulk.dismiss_tooltip"
            @translatedLabel={{this.dismissLabel}}
          />
        {{~/if~}}
        {{~#if @showResetNew~}}
          {{#if @showNewDismissCombo}}
            <DComboButton
              class="topic-dismiss-buttons__combo"
              @btnTypeClass="btn-default dismiss-read"
              @hasMenu={{this.showDismissNewMenu}}
              as |combo|
            >
              <combo.Button
                class="topic-dismiss-buttons__button"
                id="dismiss-new-{{@position}}"
                @action={{this.dismissNew}}
                @translatedLabel={{this.dismissNewLabel}}
              />

              <combo.Menu
                aria-label={{i18n "topics.bulk.dismiss_new_menu"}}
                class="topic-dismiss-buttons__menu"
                id="dismiss-new-menu-{{@position}}"
                @identifier="dismiss-new-menu"
                @modalForMobile={{true}}
                @onRegisterApi={{this.registerDMenu}}
              >
                <DDropdownMenu as |dropdown|>
                  <dropdown.item class="topic-dismiss-buttons__menu-item">
                    <DButton
                      class="dismiss-new-stop-tracking"
                      @action={{this.dismissNewAndStopTracking}}
                      @translatedLabel={{i18n
                        "topics.bulk.dismiss_and_stop_tracking"
                      }}
                    />
                  </dropdown.item>
                </DDropdownMenu>
              </combo.Menu>
            </DComboButton>
          {{else}}
            <DButton
              class="btn-default dismiss-read"
              id="dismiss-new-{{@position}}"
              @action={{@resetNew}}
              @icon="check"
              @translatedLabel={{this.dismissNewLabel}}
            />
          {{/if}}
        {{~/if~}}
      </div>
    {{~/if~}}
  </template>
}
import { computed } from "@ember/object";
import { classNames } from "@ember-decorators/component";
import DropdownSelectBoxComponent from "discourse/select-kit/components/dropdown-select-box";
import { i18n } from "discourse-i18n";
import { pluginApiIdentifiers, selectKitOptions } from "./select-kit.js";

@classNames("categories-admin-dropdown")
@selectKitOptions({
  icons: ["wrench", "angle-down"],
  showFullTitle: false,
  autoFilterable: false,
  filterable: false,
  none: "select_kit.components.categories_admin_dropdown.title",
  focusAfterOnChange: false,
})
@pluginApiIdentifiers(["categories-admin-dropdown"])
export default class CategoriesAdminDropdown extends DropdownSelectBoxComponent {
  @computed
  get content() {
    const items = [
      {
        id: "create",
        name: i18n("category.create"),
        description: i18n("category.create_long"),
        icon: "plus",
      },
    ];

    items.push({
      id: "reorder",
      name: i18n("categories.reorder.title"),
      description: i18n("categories.reorder.title_long"),
      icon: "shuffle",
    });

    return items;
  }

  _onChange(value, item) {
    if (item.onChange) {
      item.onChange(value, item);
    } else if (this.onChange) {
      this.onChange(value, item);
    }
  }
}
import { computed } from "@ember/object";
import { classNames } from "@ember-decorators/component";
import renderTag from "discourse/lib/render-tag";
import DropdownSelectBoxComponent from "discourse/select-kit/components/dropdown-select-box";
import { categoryBadgeHTML } from "discourse/ui-kit/helpers/d-category-link";
import { i18n } from "discourse-i18n";
import { pluginApiIdentifiers, selectKitOptions } from "./select-kit.js";

@classNames("tag-category-admin-dropdown")
@selectKitOptions({
  icons: ["wrench", "angle-down"],
  showFullTitle: false,
  autoFilterable: false,
  filterable: false,
  none: "select_kit.components.tag_category_admin_dropdown.title",
  focusAfterOnChange: false,
})
@pluginApiIdentifiers(["tag-category-admin-dropdown"])
export default class TagCategoryAdminDropdown extends DropdownSelectBoxComponent {
  @computed("category", "tag")
  get content() {
    return [
      {
        id: "editCategory",
        name: i18n(
          "select_kit.components.tag_category_admin_dropdown.edit_category"
        ),
        description: i18n(
          "select_kit.components.tag_category_admin_dropdown.edit_category_description",
          {
            badge: categoryBadgeHTML(this.category, {
              link: false,
              allowUncategorized: true,
            }),
          }
        ),
        icon: "folder-open",
      },
      {
        id: "editTag",
        name: i18n(
          "select_kit.components.tag_category_admin_dropdown.edit_tag"
        ),
        description: i18n(
          "select_kit.components.tag_category_admin_dropdown.edit_tag_description",
          { badge: renderTag(this.tag, { tagName: "span" }) }
        ),
        icon: "tag",
      },
    ];
  }

  _onChange(value, item) {
    if (item.onChange) {
      item.onChange(value, item);
    } else if (this.onChange) {
      this.onChange(value, item);
    }
  }
}
/* eslint-disable ember/no-classic-components */
import Component from "@ember/component";
import { hash } from "@ember/helper";
import { action, computed } from "@ember/object";
import { dependentKeyCompat } from "@ember/object/compat";
import { service } from "@ember/service";
import { tagName } from "@ember-decorators/component";
import BreadCrumbs from "discourse/components/bread-crumbs";
import BulkSelectToggle from "discourse/components/bulk-select-toggle";
import CategoryNotificationsTracking from "discourse/components/category-notifications-tracking";
import CreateTopicButton from "discourse/components/create-topic-button";
import NavigationBar from "discourse/components/navigation-bar";
import PluginOutlet from "discourse/components/plugin-outlet";
import TagInfoButton from "discourse/components/tag-info-button";
import TagNotificationsTracking from "discourse/components/tag-notifications-tracking";
import TopicDismissButtons from "discourse/components/topic-dismiss-buttons";
import lazyHash from "discourse/helpers/lazy-hash";
import { filterTypeForMode } from "discourse/lib/filter-mode";
import { NotificationLevels } from "discourse/lib/notification-levels";
import {
  applyBehaviorTransformer,
  applyValueTransformer,
} from "discourse/lib/transformer";
import NavItem from "discourse/models/nav-item";
import CategoriesAdminDropdown from "discourse/select-kit/components/categories-admin-dropdown";
import TagCategoryAdminDropdown from "discourse/select-kit/components/tag-category-admin-dropdown";
import DButton from "discourse/ui-kit/d-button";

@tagName("")
export default class DNavigation extends Component {
  @service router;
  @service site;
  @service siteSettings;
  @service currentUser;

  @computed("siteSettings.fixed_category_positions")
  get fixedCategoryPositions() {
    return this.siteSettings.fixed_category_positions;
  }

  @computed("category", "site.shared_drafts_category_id", "site.desktopView")
  get createTopicLabel() {
    const defaultKey = "topic.create";
    let value = this.site.desktopView ? defaultKey : "";

    if (
      value === defaultKey &&
      this.site.shared_drafts_category_id &&
      this.category?.id === this.site.shared_drafts_category_id
    ) {
      value = "topic.create_shared_draft";
    }

    return applyValueTransformer("create-topic-label", value, {
      site: this.site,
      defaultKey,
      category: this.category,
      currentUser: this.currentUser,
    });
  }

  @computed("category")
  get createTopicIcon() {
    const defaultIcon = "far-pen-to-square";

    return applyValueTransformer("create-topic-icon", defaultIcon, {
      site: this.site,
      defaultIcon,
      category: this.category,
      currentUser: this.currentUser,
    });
  }

  get showBulkSelectInNavControls() {
    const enableOnDesktop = applyValueTransformer(
      "bulk-select-in-nav-controls",
      false,
      { site: this.site }
    );

    return (
      (this.site.mobileView || enableOnDesktop) &&
      this.notCategoriesRoute &&
      this.canBulkSelect
    );
  }

  @dependentKeyCompat
  get filterType() {
    return filterTypeForMode(this.filterMode);
  }

  // Should be a `readOnly` instead but some themes/plugins still pass
  // the `categories` property into this component
  @computed()
  get categories() {
    let categories = this.site.categoriesList;

    if (!this.siteSettings.allow_uncategorized_topics) {
      categories = categories.filter(
        (category) => category.id !== this.site.uncategorized_category_id
      );
    }

    if (this.currentUser?.indirectly_muted_category_ids) {
      categories = categories.filter(
        (category) =>
          !this.currentUser.indirectly_muted_category_ids.includes(category.id)
      );
    }

    return categories;
  }

  @computed("category")
  get showCategoryNotifications() {
    return this.category && this.currentUser;
  }

  @computed("category.notification_level")
  get categoryNotificationLevel() {
    if (
      this.currentUser?.indirectly_muted_category_ids?.includes(
        this.category.id
      )
    ) {
      return NotificationLevels.MUTED;
    } else {
      return this.category?.notification_level;
    }
  }

  // don't show tag notification menu on tag intersections
  @computed("tagNotification", "additionalTags")
  get showTagNotifications() {
    return this.tagNotification && !this.additionalTags;
  }

  @computed("category", "createTopicDisabled")
  get categoryReadOnlyBanner() {
    if (this.category && this.currentUser && this.createTopicDisabled) {
      return this.category.read_only_banner;
    }
  }

  @computed("category.can_edit")
  get showCategoryEdit() {
    return this.category?.can_edit;
  }

  @computed("tag", "tag.name", "additionalTags", "currentUser.canEditTags")
  get showTagEdit() {
    return (
      this.tag &&
      this.tag.name !== "none" &&
      !this.additionalTags &&
      this.currentUser?.canEditTags
    );
  }

  @computed("toggleTagInfo", "tag", "tag.name", "additionalTags", "category")
  get showTagInfoButton() {
    return (
      this.toggleTagInfo &&
      this.tag &&
      this.tag.name !== "none" &&
      !this.additionalTags &&
      !this.category
    );
  }

  @computed(
    "category.can_edit",
    "tag",
    "tag.name",
    "additionalTags",
    "currentUser.canEditTags"
  )
  get showCombinedAdminDropdown() {
    return this.category?.can_edit && this.showTagEdit;
  }

  @computed(
    "filterType",
    "category",
    "noSubcategories",
    "tag",
    "router.currentRoute.queryParams",
    "skipCategoriesNavItem"
  )
  get navItems() {
    const items = NavItem.buildList(this.category, {
      filterType: this.filterType,
      noSubcategories: this.noSubcategories,
      currentRouteQueryParams: this.router?.currentRoute?.queryParams,
      tag: this.tag,
      siteSettings: this.siteSettings,
      skipCategoriesNavItem: this.skipCategoriesNavItem,
    });

    return applyValueTransformer("navigation-items", items, {
      category: this.category,
      tag: this.tag,
      filterType: this.filterType,
    });
  }

  @computed("showResetNew", "filterType", "currentUser.unified_new_enabled")
  get showNewDismissCombo() {
    return (
      this.showResetNew &&
      this.filterType === "new" &&
      this.currentUser.unified_new_enabled
    );
  }

  @computed("filterType")
  get notCategoriesRoute() {
    return this.filterType !== "categories";
  }

  @action
  async changeTagNotificationLevel(notificationLevel) {
    const response = await this.tagNotification.update({
      notification_level: notificationLevel,
    });

    const payload = response.responseJson;

    this.tagNotification.set("notification_level", notificationLevel);

    this.currentUser.setProperties({
      watched_tags: payload.watched_tags,
      watching_first_post_tags: payload.watching_first_post_tags,
      tracked_tags: payload.tracked_tags,
      muted_tags: payload.muted_tags,
      regular_tags: payload.regular_tags,
    });
  }

  @action
  changeCategoryNotificationLevel(notificationLevel) {
    this.category.setNotification(notificationLevel);
  }

  @action
  selectCategoryAdminDropdownAction(actionId) {
    switch (actionId) {
      case "create":
        this.createCategory();
        break;
      case "reorder":
        this.reorderCategories();
        break;
    }
  }

  @action
  handleTagCategoryAdmin(actionId) {
    switch (actionId) {
      case "editCategory":
        this.editCategory();
        break;
      case "editTag":
        this.router.transitionTo(
          "tag.edit.tab",
          this.tag.slug,
          this.tag.id,
          "general"
        );
        break;
    }
  }

  @action
  clickCreateTopicButton() {
    applyBehaviorTransformer(
      "create-topic-button-click",
      () => this.createTopic(),
      { category: this.category, tag: this.tag }
    );
  }

  @action
  editTag() {
    this.router.transitionTo(
      "tag.edit.tab",
      this.tag.slug,
      this.tag.id,
      "general"
    );
  }

  <template>
    <BreadCrumbs
      @additionalTags={{this.additionalTags}}
      @categories={{this.categories}}
      @category={{this.category}}
      @noSubcategories={{this.noSubcategories}}
      @tag={{this.tag}}
    />

    <PluginOutlet
      @name="after-breadcrumbs"
      @outletArgs={{lazyHash
        categories=this.categories
        category=this.category
        tag=this.tag
        additionalTags=this.additionalTags
      }}
    />

    {{#unless this.additionalTags}}
      {{! nav bar doesn't work with tag intersections }}
      <NavigationBar
        @category={{this.category}}
        @filterMode={{this.filterMode}}
        @navItems={{this.navItems}}
        @tag={{this.tag}}
      />
    {{/unless}}

    <div class="navigation-controls">
      {{#if this.showBulkSelectInNavControls}}
        <BulkSelectToggle @bulkSelectHelper={{@bulkSelectHelper}} />
      {{/if}}

      <TopicDismissButtons
        @dismissRead={{@dismissRead}}
        @model={{@model}}
        @position="top"
        @resetNew={{@resetNew}}
        @selectedTopics={{@bulkSelectHelper.selected}}
        @showDismissRead={{@showDismissRead}}
        @showNewDismissCombo={{this.showNewDismissCombo}}
        @showResetNew={{@showResetNew}}
      />

      {{#if this.showCategoryAdmin}}
        {{#if this.fixedCategoryPositions}}
          <CategoriesAdminDropdown
            @onChange={{this.selectCategoryAdminDropdownAction}}
            @options={{hash triggerOnChangeOnTab=false}}
          />
        {{else}}
          <DButton
            class="btn-default"
            id="create-category"
            @action={{this.createCategory}}
            @icon="plus"
            @label={{if
              this.site.mobileView
              "categories.category"
              "category.create"
            }}
          />
        {{/if}}
      {{/if}}

      {{#if this.showCombinedAdminDropdown}}
        <TagCategoryAdminDropdown
          @category={{this.category}}
          @onChange={{this.handleTagCategoryAdmin}}
          @options={{hash triggerOnChangeOnTab=false}}
          @tag={{this.tag}}
        />
      {{else}}
        {{#if (and this.category this.showCategoryEdit)}}
          <DButton
            class="btn-default edit-category"
            @action={{this.editCategory}}
            @icon="wrench"
            @title="category.edit_title"
          />
        {{/if}}

        {{#if this.showTagEdit}}
          <DButton
            class="btn-default"
            id="edit-tag"
            @action={{this.editTag}}
            @ariaLabel="tagging.edit"
            @icon="wrench"
            @title="tagging.edit"
          />
        {{/if}}
      {{/if}}

      {{#if this.showTagInfoButton}}
        <TagInfoButton
          @active={{@showTagInfo}}
          @loading={{@loadingTagInfo}}
          @toggleInfo={{@toggleTagInfo}}
        />
      {{/if}}

      <PluginOutlet
        @name="before-create-topic-button"
        @outletArgs={{lazyHash
          canCreateTopic=this.canCreateTopic
          createTopicDisabled=this.createTopicDisabled
          createTopicLabel=this.createTopicLabel
          additionalTags=this.additionalTags
          category=this.category
          tag=this.tag
        }}
      />

      <CreateTopicButton
        @action={{this.clickCreateTopicButton}}
        @btnTypeClass={{if
          this.siteSettings.modernize_foundation_theme
          "btn-primary"
        }}
        @canCreateTopic={{this.canCreateTopic}}
        @icon={{this.createTopicIcon}}
        @label={{this.createTopicLabel}}
        @showDrafts={{if (gt this.draftCount 0) true false}}
      />

      <PluginOutlet
        @name="after-create-topic-button"
        @outletArgs={{lazyHash
          canCreateTopic=this.canCreateTopic
          createTopicDisabled=this.createTopicDisabled
          createTopicLabel=this.createTopicLabel
