class ThemeCard extends Component {
  @service interfaceColor;
  @service session;

  @tracked screenshotLoaded = false;

  get currentScreenshotUrl() {
    const { screenshot_dark_url, screenshot_light_url } = this.args.theme;
    return this.#showDarkScreenshot
      ? screenshot_dark_url || screenshot_light_url
      : screenshot_light_url || screenshot_dark_url;
  }

  get selected() {
    return this.args.theme.id === this.args.selectedThemeId;
  }

  get showSkeleton() {
    return !!this.currentScreenshotUrl && !this.screenshotLoaded;
  }

  get #showDarkScreenshot() {
    return (
      this.interfaceColor?.colorModeIsDark ||
      window.matchMedia("(prefers-color-scheme: dark)").matches ||
      this.session?.defaultColorSchemeIsDark
    );
  }

  // a broken screenshot should still clear the skeleton
  @action
  screenshotSettled() {
    this.screenshotLoaded = true;
  }

  <template>
    <div class="design-wizard__theme-card-wrapper">
      <label
        class={{dConcatClass
          "design-wizard__theme-card"
          (if this.selected "--selected")
          (unless this.currentScreenshotUrl "--without-screenshot")
        }}
        data-theme-id={{@theme.id}}
      >
        <input
          checked={{this.selected}}
          class="sr-only"
          disabled={{@applying}}
          name="design-wizard-theme"
          type="radio"
          value={{@theme.id}}
          {{on "change" (fn @onSelect @theme.id)}}
        />
        {{#if (and this.selected @applying)}}
          <span class="design-wizard__theme-enabled-badge">
            <span class="spinner small design-wizard__theme-spinner"></span>
            {{i18n "design_wizard.theme.applying"}}
          </span>
        {{else if this.selected}}
          <span class="design-wizard__theme-enabled-badge">
            {{dIcon "check"}}
            {{i18n "design_wizard.theme.selected"}}
          </span>
        {{/if}}
        {{#if this.currentScreenshotUrl}}
          <span
            class="design-wizard__theme-screenshot
              {{if this.showSkeleton '--loading'}}"
          >
            <img
              alt=""
              class="design-wizard__theme-screenshot-image"
              decoding="async"
              fetchpriority="high"
              height={{SCREENSHOT_HEIGHT}}
              src={{this.currentScreenshotUrl}}
              width={{SCREENSHOT_WIDTH}}
              {{on "load" this.screenshotSettled}}
              {{on "error" this.screenshotSettled}}
            />
          </span>
        {{/if}}
        <span class="design-wizard__theme-name">{{@theme.name}}</span>
        <span class="design-wizard__theme-description">
          {{@theme.description}}
        </span>
      </label>
    </div>
  </template>
}

const DesignWizardThemeSection = <template>
  {{#if @currentTheme}}
    <p class="design-wizard__custom-theme-notice">
      {{i18n "design_wizard.theme.custom_theme_notice" name=@currentTheme.name}}
    </p>
  {{/if}}
  <fieldset
    aria-busy={{if @applying "true"}}
    class="design-wizard__theme-cards"
  >
    <legend class="sr-only">
      {{i18n "design_wizard.steps.theme.title"}}
    </legend>
    {{#each @themes as |theme|}}
      <ThemeCard
        @applying={{@applying}}
        @onSelect={{@onSelect}}
        @selectedThemeId={{@selectedThemeId}}
        @theme={{theme}}
      />
    {{/each}}
  </fieldset>
</template>;

export default DesignWizardThemeSection;
import Component from "@glimmer/component";
import { fn } from "@ember/helper";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import { service } from "@ember/service";
import ColorsSection from "discourse/components/design-wizard/colors-section";
import FontsSection from "discourse/components/design-wizard/fonts-section";
import HomepageSection from "discourse/components/design-wizard/homepage-section";
import LogoSection from "discourse/components/design-wizard/logo-section";
import Section from "discourse/components/design-wizard/section";
import ThemeSection from "discourse/components/design-wizard/theme-section";
import DButton from "discourse/ui-kit/d-button";
import { i18n } from "discourse-i18n";

export const STEPS = ["theme", "colors", "homepage"];

export default class DesignWizardControls extends Component {
  @service designWizard;

  get currentStep() {
    return STEPS[this.designWizard.stepIndex] ?? STEPS[0];
  }

  get isFirstStep() {
    return this.designWizard.stepIndex <= 0;
  }

  get isLastStep() {
    return this.designWizard.stepIndex >= STEPS.length - 1;
  }

  // a site whose default theme is custom starts with no theme selected, and
  // the later steps are meaningless until one is chosen
  get needsThemeChoice() {
    return this.currentStep === "theme" && !this.designWizard.themeId;
  }

  // a theme preview replaces the page, so anything else clicked in the meantime
  // would either be lost or save selections the reload is about to discard
  get busy() {
    return this.designWizard.applyingTheme;
  }

  get stepProgress() {
    return i18n("design_wizard.step_progress", {
      current: this.designWizard.stepIndex + 1,
      total: STEPS.length,
    });
  }

  get stepTitle() {
    return i18n(`design_wizard.steps.${this.currentStep}.title`);
  }

  get stepDescription() {
    return i18n(`design_wizard.steps.${this.currentStep}.description`);
  }

  goToStepLabel(index) {
    return i18n("design_wizard.step_label", { index: index + 1 });
  }

  @action
  async goToStep(index) {
    if (index === this.designWizard.stepIndex || this.busy) {
      return;
    }

    if (index > this.designWizard.stepIndex && this.needsThemeChoice) {
      return;
    }

    if (
      index < this.designWizard.stepIndex ||
      (await this.designWizard.saveProgress())
    ) {
      this.designWizard.setStepIndex(index);
    }
  }

  @action
  back() {
    if (this.busy) {
      return;
    }

    this.designWizard.setStepIndex(
      Math.max(this.designWizard.stepIndex - 1, 0)
    );
  }

  @action
  async next() {
    if (this.busy) {
      return;
    }

    if (await this.designWizard.saveProgress()) {
      this.designWizard.setStepIndex(
        Math.min(this.designWizard.stepIndex + 1, STEPS.length - 1)
      );
    }
  }

  @action
  selectTheme(themeId) {
    this.designWizard.selectTheme(themeId);
  }

  @action
  selectPalette(mode, pairKey) {
    this.designWizard.selectPalette(mode, pairKey);
  }

  @action
  selectPaletteMode(paletteMode) {
    this.designWizard.selectPaletteMode(paletteMode);
  }

  @action
  selectBodyFont(fontKey) {
    this.designWizard.selectBodyFont(fontKey);
  }

  @action
  selectHeadingFont(fontKey) {
    this.designWizard.selectHeadingFont(fontKey);
  }

  @action
  selectHomepage(homepage) {
    this.designWizard.selectHomepage(homepage);
  }

  @action
  selectCategoryPageStyle(value) {
    this.designWizard.selectCategoryPageStyle(value);
  }

  @action
  uploadLogo(upload) {
    this.designWizard.selectLogo(upload);
  }

  @action
  removeLogo() {
    this.designWizard.selectLogo(null);
  }

  @action
  save() {
    this.designWizard.save();
  }

  <template>
    <div class="design-wizard__content">
      <header class="design-wizard__header">
        {{#if this.designWizard.docked}}
          <span class="design-wizard__step-progress">
            {{this.stepProgress}}
          </span>
        {{/if}}
        <h2 class="design-wizard__title">{{this.stepTitle}}</h2>
        <p class="design-wizard__description">{{this.stepDescription}}</p>
      </header>

      <div class="design-wizard__sections">
        {{#if (eq this.currentStep "theme")}}
          <Section @type="theme">
            <ThemeSection
              @applying={{this.busy}}
              @currentTheme={{this.designWizard.data.current_theme}}
              @onSelect={{this.selectTheme}}
              @selectedThemeId={{this.designWizard.themeId}}
              @themes={{this.designWizard.data.themes}}
            />
          </Section>
        {{else if (eq this.currentStep "colors")}}
          <Section @title={{i18n "design_wizard.sections.logo"}} @type="logo">
            <LogoSection
              @disabled={{this.busy}}
              @logoUrl={{this.designWizard.logo}}
              @onRemove={{this.removeLogo}}
              @onUpload={{this.uploadLogo}}
            />
          </Section>

          <Section
            @title={{i18n "design_wizard.sections.colors"}}
            @type="colors"
          >
            <ColorsSection
              @darkPairs={{this.designWizard.darkPairs}}
              @lightPairs={{this.designWizard.lightPairs}}
              @onSelectPalette={{this.selectPalette}}
              @onSelectPaletteMode={{this.selectPaletteMode}}
              @paletteMode={{this.designWizard.paletteMode}}
              @selectedDarkKey={{this.designWizard.selectedDarkPair.key}}
              @selectedLightKey={{this.designWizard.selectedLightPair.key}}
              @showsDarkPalettes={{this.designWizard.showsDarkPalettes}}
              @showsLightPalettes={{this.designWizard.showsLightPalettes}}
            />
          </Section>
        {{else}}
          <Section @title={{i18n "design_wizard.sections.fonts"}} @type="fonts">
            <FontsSection
              @bodyFont={{this.designWizard.bodyFont}}
              @headingFont={{this.designWizard.headingFont}}
              @onSelectBodyFont={{this.selectBodyFont}}
              @onSelectHeadingFont={{this.selectHeadingFont}}
            />
          </Section>

          <Section
            @title={{i18n "design_wizard.sections.homepage"}}
            @type="homepage"
          >
            <HomepageSection
              @additionalHomepages={{this.designWizard.additionalHomepages}}
              @categoryPageStyle={{this.designWizard.categoryPageStyle}}
              @homepage={{this.designWizard.homepage}}
              @onSelectCategoryPageStyle={{this.selectCategoryPageStyle}}
              @onSelectHomepage={{this.selectHomepage}}
              @themeId={{this.designWizard.themeId}}
            />
          </Section>
        {{/if}}
      </div>

      <footer class="design-wizard__actions">
        <div class="design-wizard__step-dots">
          {{#each STEPS as |step index|}}
            <button
              aria-current={{if (eq step this.currentStep) "true"}}
              aria-label={{this.goToStepLabel index}}
              class="design-wizard__step-dot
                {{if (eq step this.currentStep) '--active'}}"
              disabled={{this.busy}}
              type="button"
              {{on "click" (fn this.goToStep index)}}
            ></button>
          {{/each}}
        </div>
        <DButton
          class="btn-flat design-wizard__back"
          @action={{this.back}}
          @disabled={{if this.busy true this.isFirstStep}}
          @label="design_wizard.back"
        />
        {{#if this.isLastStep}}
          <DButton
            class="btn-primary design-wizard__save"
            @action={{this.save}}
            @disabled={{this.busy}}
            @isLoading={{this.designWizard.saving}}
            @label="design_wizard.save"
          />
        {{else}}
          <DButton
            class="btn-primary design-wizard__next"
            @action={{this.next}}
            @disabled={{if this.busy true this.needsThemeChoice}}
            @isLoading={{this.designWizard.saving}}
            @label="design_wizard.next"
          />
        {{/if}}
      </footer>
    </div>
  </template>
}
import Component from "@glimmer/component";
import { action } from "@ember/object";
import didInsert from "@ember/render-modifiers/modifiers/did-insert";
import { schedule } from "@ember/runloop";
import { service } from "@ember/service";
import DesignWizardControls, {
  STEPS,
} from "discourse/components/design-wizard/controls";
import htmlClass from "discourse/helpers/html-class";
import { isTesting } from "discourse/lib/environment";
import { prefersReducedMotion } from "discourse/lib/utilities";
import DButton from "discourse/ui-kit/d-button";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import dAutoFocus from "discourse/ui-kit/modifiers/d-auto-focus";
import { i18n } from "discourse-i18n";

export default class DesignWizardPanel extends Component {
  @service designWizard;
  @service dialog;

  element;

  get collapsed() {
    return this.designWizard.docked && this.designWizard.minimized;
  }

  // docked, the minimized panel stays on screen as a rail instead
  get hidden() {
    return this.designWizard.minimized && !this.designWizard.docked;
  }

  get stepProgress() {
    return i18n("design_wizard.step_progress", {
      current: this.designWizard.stepIndex + 1,
      total: STEPS.length,
    });
  }

  @action
  minimize() {
    this.designWizard.setMinimized(true);
  }

  @action
  restore() {
    this.designWizard.setMinimized(false);
    schedule("afterRender", () => {
      this.element
        ?.querySelector(".design-wizard__minimize")
        ?.focus({ preventScroll: true });
    });
  }

  @action
  registerElement(element) {
    this.element = element;
  }

  @action
  async close() {
    // steps are saved as they are completed, so closing a run that changed the
    // live site is a decision rather than a dismissal
    if (this.designWizard.needsCloseConfirmation) {
      const canRevert = this.designWizard.canRevert;

      this.dialog.alert({
        message: i18n(
          canRevert
            ? "design_wizard.close.message"
            : "design_wizard.close.message_without_revert"
        ),
        buttons: [
          {
            label: i18n("design_wizard.close.keep"),
            class: "btn-primary",
            action: () => this.dismiss(),
          },
          {
            label: i18n("design_wizard.close.continue_editing"),
            class: "btn-flat",
          },
          // last, so the destructive choice is not the one landed on by accident
          ...(canRevert
            ? [
                {
                  label: i18n("design_wizard.close.revert"),
                  class: "btn-danger",
                  action: () => this.designWizard.revert(),
                },
              ]
            : []),
        ],
      });
      return;
    }

    await this.dismiss();
  }

  @action
  async dismiss() {
    if (this.element && !isTesting() && !prefersReducedMotion()) {
      const slideOut =
        getComputedStyle(this.element)
          .getPropertyValue("--design-wizard-slide-out")
          .trim() || "translateX(100%)";

      await this.element
        .animate([{ transform: "translate(0, 0)" }, { transform: slideOut }], {
          duration: 250,
          easing: "ease-in",
          fill: "forwards",
        })
        .finished.catch(() => {});
    }

    this.designWizard.stop();
  }

  <template>
    {{#if this.designWizard.active}}
      {{#if this.designWizard.docked}}
        {{htmlClass
          "design-wizard-docked"
          (if this.collapsed "design-wizard-collapsed")
        }}
      {{/if}}
      <aside
        aria-hidden={{if this.hidden "true"}}
        aria-label={{i18n "design_wizard.title"}}
        class={{dConcatClass
          "design-wizard"
          (unless this.designWizard.animateEntrance "--no-entrance")
          (if this.designWizard.applyingTheme "--busy")
          (if this.designWizard.docked "--docked")
          (if this.collapsed "--collapsed")
          (if this.hidden "--minimized")
        }}
        id="design-wizard-panel"
        inert={{this.hidden}}
        ...attributes
        {{didInsert this.registerElement}}
      >
        {{#if this.collapsed}}
          <DButton
            aria-controls="design-wizard-panel"
            class="btn-transparent design-wizard__expand"
            @action={{this.restore}}
            @ariaExpanded={{false}}
            @title="design_wizard.expand"
            {{dAutoFocus}}
          >
            {{dIcon "angles-left"}}
            <span class="design-wizard__expand-label">
              <span>{{i18n "design_wizard.title"}}</span>
              <span class="design-wizard__expand-progress">
                {{this.stepProgress}}
              </span>
            </span>
          </DButton>
        {{/if}}
        <div class="design-wizard__panel-actions">
          <DButton
            class="btn-transparent design-wizard__minimize"
            @action={{this.minimize}}
            @disabled={{this.designWizard.applyingTheme}}
            @icon={{if this.designWizard.docked "angles-right" "minus"}}
            @title={{if
              this.designWizard.docked
              "design_wizard.collapse"
              "design_wizard.minimize"
            }}
          />
          <DButton
            class="btn-transparent design-wizard__close"
            @action={{this.close}}
            @icon="xmark"
            @title="modal.close"
          />
        </div>
        <DesignWizardControls />
      </aside>
      {{#if this.hidden}}
        <DButton
          aria-controls="design-wizard-panel"
          class="btn-default design-wizard__restore"
          @action={{this.restore}}
          @ariaExpanded={{false}}
          @title="design_wizard.restore"
          {{dAutoFocus}}
        >
          <span class="design-wizard__restore-title">
            {{i18n "design_wizard.title"}}
          </span>
          <span class="design-wizard__restore-progress">
            {{this.stepProgress}}
          </span>
          {{dIcon "chevron-up"}}
        </DButton>
      {{/if}}
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import { service } from "@ember/service";
