                class="btn-transparent close"
                @action={{this.dismiss}}
                @ariaLabel="banner.close"
                @icon="xmark"
                @title="banner.close"
              />
            </div>

            <DDecoratedHtml @html={{this.content}} @id="banner-content" />
          </div>
        </div>
      </div>
