            {{yield to="navigation"}}
          </div>
        </div>
      </ConditionalWrap>

      <ConditionalWrap
        @class="discovery-layout__content"
        @when={{this.hasSidebarLayout}}
      >
        <PluginOutlet
          @connectorTagName="div"
          @name="discovery-above"
          @outletArgs={{lazyHash
            category=@model.category
            tag=@model.tag
            model=@model
          }}
        />

        <ConditionalWrap
          @class="discovery-layout__list"
          @when={{this.hasSidebarLayout}}
        >
          <div class={{dConcatClass "container list-container" @listClass}}>
            <div class="row full-width">
              <div id="header-list-area">
                {{yield to="header"}}
                <PluginOutlet
                  @name="header-list-container-bottom"
                  @outletArgs={{lazyHash
                    category=@model.category
                    tag=@model.tag
                  }}
                />
              </div>
            </div>
            <div class="row full-width">
              <PluginOutlet
                @name="before-list-area"
                @outletArgs={{lazyHash category=@model.category tag=@model.tag}}
              />
              <div id="list-area">
                <PluginOutlet
                  @defaultGlimmer={{true}}
                  @name="discovery-list-area"
                  @outletArgs={{lazyHash
                    category=@model.category
                    tag=@model.tag
                    model=@model
                  }}
                >
                  <PluginOutlet
                    @connectorTagName="span"
                    @name="discovery-list-container-top"
                    @outletArgs={{lazyHash
                      category=@model.category
                      tag=@model.tag
                    }}
                  />
                  {{yield to="list"}}
                </PluginOutlet>
              </div>
            </div>
          </div>
        </ConditionalWrap>

        {{#if this.hasSidebarLayout}}
          <div class="discovery-layout__sidebar">
            <BlockOutlet
              @name="sidebar-discovery"
              @outletArgs={{lazyHash category=@model.category tag=@model.tag}}
            />
          </div>
        {{/if}}

        <PluginOutlet
          @connectorTagName="div"
          @name="discovery-below"
          @outletArgs={{lazyHash category=@model.category tag=@model.tag}}
        />
      </ConditionalWrap>
    </ConditionalWrap>
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { concat, fn } from "@ember/helper";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import { schedule } from "@ember/runloop";
import { service } from "@ember/service";
import { compare } from "@ember/utils";
import withEventValue from "discourse/helpers/with-event-value";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import DButton from "discourse/ui-kit/d-button";
import DModal from "discourse/ui-kit/d-modal";
import dCategoryBadge from "discourse/ui-kit/helpers/d-category-badge";
import { i18n } from "discourse-i18n";

class Entry {
  @tracked position;

  constructor({ position, depth, category, descendantCount }) {
    this.position = position;
    this.depth = depth;
    this.category = category;
    this.descendantCount = descendantCount;
  }
}

export default class ReorderCategories extends Component {
  @service site;

  @tracked changed = false;
  @tracked entries = this.reorder();

  /** @type {number | null} */
  @tracked highlightedCategoryId = null;

  get sortedEntries() {
    return this.entries.sort((a, b) => compare(a?.position, b?.position));
  }

  reorder(from) {
    from ??= this.site.categories.map((category) => ({
      category,
      position: category.position,
    }));

    return this.createEntries([
      ...from.sort((a, b) => compare(a?.position, b?.position)),
    ]);
  }

  /**
   * 1. Make sure all categories have unique position numbers.
   * 2. Place sub-categories after their parent categories while maintaining
   *    the same relative order.
   *
   *    e.g.
   *      parent/c2/c1          parent
   *      parent/c1             parent/c1
   *      parent          =>    parent/c2
   *      other                 parent/c2/c1
   *      parent/c2             other
   **/
  createEntries(from, position = 0, categoryId = null, depth = 0) {
    let result = [];

    for (const entry of from) {
      if (
        (categoryId === null && !entry.category.parent_category_id) ||
        entry.category.parent_category_id === categoryId
      ) {
        const descendants = this.createEntries(
          from,
          position + result.length + 1,
          entry.category.id,
          depth + 1
        );

        result = [
          ...result,
          new Entry({
            position: position + result.length,
            depth,
            category: entry.category,
            descendantCount: descendants.length,
          }),
          ...descendants,
        ];
      }
    }

    return result;
  }

  @action
  move(entry, delta) {
    let targetPosition = entry.position + delta;

    // Adjust target position for sub-categories
    if (delta > 0) {
      // Moving down (position gets larger)
      if (entry.descendantCount) {
        // This category has subcategories, adjust targetPosition to account for them
        if (entry.descendantCount >= delta) {
          // Only apply offset if target position is occupied by a subcategory
          // Seems weird but fixes a UX quirk
          targetPosition += entry.descendantCount;
        }
      }
    } else {
      // Moving up (position gets smaller)
      const ancestors = this.sortedEntries[targetPosition]?.category?.ancestors;
      if (ancestors) {
        // Target category is a subcategory, adjust targetPosition to account for ancestors
        const highestAncestorEntry = this.sortedEntries.find(
          (value) => value.category.id === ancestors[0].id
        );
        targetPosition = highestAncestorEntry.position;
      }
    }

    // Adjust target position for range bounds
    if (targetPosition >= this.entries.length) {
      // Set to max
      targetPosition = this.entries.length - 1;
    } else if (targetPosition < 0) {
      // Set to min
      targetPosition = 0;
    }

    // Update other categories between current and target position
    for (const e of this.sortedEntries) {
      if (delta > 0) {
        // Moving down (position gets larger)
        if (e.position > entry.position && e.position <= targetPosition) {
          e.position -= 1;
        }
      } else {
        // Moving up (position gets smaller)
        if (e.position < entry.position && e.position >= targetPosition) {
          e.position += 1;
        }
      }
    }

    // Update this category's position to target position
    entry.position = targetPosition;

    this.entries = this.reorder(this.sortedEntries);
    this.changed = true;

    this.toggleHighlight(entry.category.id);

    const focused = document.activeElement;
    schedule("afterRender", () => {
      if (document.activeElement === document.body) {
        focused?.focus();
      }
    });
  }

  @action
  toggleHighlight(categoryId) {
    this.highlightedCategoryId = categoryId;
    setTimeout(() => {
      if (this.highlightedCategoryId === categoryId) {
        this.highlightedCategoryId = null;
      }
    }, 3000);
  }

  @action
  change(entry, newPosition) {
    const delta = parseInt(newPosition, 10) - entry.position;
    this.move(entry, delta);
  }

  @action
  async save() {
    const entries = this.reorder(this.sortedEntries);

    const data = {};
    for (const { category, position } of entries) {
      data[category.id] = position;
    }

    try {
      await ajax("/categories/reorder", {
        type: "POST",
        data: { mapping: JSON.stringify(data) },
      });
      window.location.reload();
    } catch (e) {
      popupAjaxError(e);
    }
  }

  <template>
    <DModal
      class="reorder-categories"
      @closeModal={{@closeModal}}
      @inline={{@inline}}
      @title={{i18n "categories.reorder.title"}}
    >
      <:body>
        <table>
          <thead>
            <th>{{i18n "categories.category"}}</th>
            <th class="reorder-categories__header-position">
              {{i18n "categories.reorder.position"}}
            </th>
          </thead>
          <tbody>
            {{#each this.sortedEntries key="category.id" as |entry|}}
              <tr
                class={{if
                  (eq this.highlightedCategoryId entry.category.id)
                  "highlighted"
                }}
                data-category-id={{entry.category.id}}
              >
                <td>
                  <div class={{concat "reorder-categories-depth-" entry.depth}}>
                    {{dCategoryBadge entry.category allowUncategorized="true"}}
                  </div>
                </td>

                <td>
                  <div class="reorder-categories-actions">
                    <input
                      min="0"
                      type="number"
                      value={{entry.position}}
                      {{on "change" (withEventValue (fn this.change entry))}}
                    />
                    <DButton
                      class="btn-default no-text move-up"
                      @action={{fn this.move entry -1}}
                      @icon="arrow-up"
                    />
                    <DButton
                      class="btn-default no-text move-down"
                      @action={{fn this.move entry 1}}
                      @icon="arrow-down"
                    />
                  </div>
                </td>
              </tr>
            {{/each}}
          </tbody>
        </table>
      </:body>

      <:footer>
        <DButton
          class="btn-primary"
          @action={{this.save}}
          @disabled={{not this.changed}}
          @label="categories.reorder.save"
        />
      </:footer>
    </DModal>
  </template>
}
import Component from "@glimmer/component";
import { array } from "@ember/helper";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { trustHTML } from "@ember/template";
import AddCategoryTagClasses from "discourse/components/add-category-tag-classes";
import CategoryLogo from "discourse/components/category-logo";
import DNavigation from "discourse/components/d-navigation";
import AccessibleDiscoveryHeading from "discourse/components/discovery/accessible-discovery-heading";
import ReorderCategories from "discourse/components/modal/reorder-categories";
import PluginOutlet from "discourse/components/plugin-outlet";
import bodyClass from "discourse/helpers/body-class";
import categoryColorVariable from "discourse/helpers/category-color-variable";
import lazyHash from "discourse/helpers/lazy-hash";
import { calculateFilterMode } from "discourse/lib/filter-mode";
import { TRACKED_QUERY_PARAM_VALUE } from "discourse/lib/topic-list-tracked-filter";
import { applyValueTransformer } from "discourse/lib/transformer";
import DiscourseURL from "discourse/lib/url";
import Category from "discourse/models/category";
import dCategoryBadge from "discourse/ui-kit/helpers/d-category-badge";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";

export default class DiscoveryNavigation extends Component {
  @service categoryTypeChooser;
  @service currentUser;
  @service modal;
  @service router;
  @service siteSettings;

  get filterMode() {
    return calculateFilterMode({
      category: this.args.category,
      filterType: this.args.filterType,
      noSubcategories: this.args.noSubcategories,
    });
  }

  get skipCategoriesNavItem() {
    return this.router.currentRoute.queryParams.f === TRACKED_QUERY_PARAM_VALUE;
  }

  get canCreateTopic() {
    let value = this.currentUser?.can_create_topic ?? false;

    if (
      value &&
      this.siteSettings.hide_disabled_create_topic_button &&
      this.args.createTopicDisabled
    ) {
      value = false;
    }

    return applyValueTransformer("can-create-topic-button", value, {
      category: this.args.category,
      tag: this.args.tag,
      createTopicDisabled: this.args.createTopicDisabled,
    });
  }

  get bodyClass() {
    if (this.args.tag) {
      return [
        "tags-page",
        this.args.additionalTags ? "tags-intersection" : null,
      ]
        .filter(Boolean)
        .join(" ");
    } else if (this.filterMode === "categories") {
      return "navigation-categories";
    } else if (this.args.category) {
      return "navigation-category";
    } else {
      return "navigation-topics";
    }
  }

  get headingClasses() {
    return dConcatClass(
      "category-heading",
      this.args.category?.uploaded_logo?.url
        ? "--has-logo discovery-heading"
        : null
    );
  }

  @action
  editCategory() {
    DiscourseURL.routeTo(`/c/${Category.slugFor(this.args.category)}/edit`);
  }

  @action
  createCategory() {
    this.categoryTypeChooser.createCategory();
  }

  @action
  reorderCategories() {
    this.modal.show(ReorderCategories);
  }

  <template>
    <AddCategoryTagClasses
      @category={{@category}}
      @tags={{if @tag (array @tag.name)}}
    />

    <AccessibleDiscoveryHeading
      @additionalTags={{@additionalTags}}
      @category={{@category}}
      @filter={{this.filterMode}}
      @tag={{@tag}}
    />

    {{#if @category}}
      <PluginOutlet
        @name="above-category-heading"
        @outletArgs={{lazyHash category=@category tag=@tag}}
      />

      <section
        class={{this.headingClasses}}
        style={{categoryColorVariable @category.color}}
      >
        {{#if @category.uploaded_logo.url}}
          <CategoryLogo
            class="category-heading__logo"
            @category={{@category}}
          />
          {{#if @category.description}}
            <div class="category-heading__content">
              {{dCategoryBadge @category class="category-heading__badge"}}
              <p class="category-heading__description">
                {{trustHTML @category.description}}
              </p>
            </div>
          {{/if}}
        {{/if}}

        <PluginOutlet
          @connectorTagName="div"
          @name="category-heading"
          @outletArgs={{lazyHash category=@category tag=@tag}}
        />

      </section>
    {{/if}}

    {{bodyClass this.bodyClass}}

    <section
      class={{dConcatClass
        "navigation-container"
        (if @category "category-navigation")
      }}
    >
      <DNavigation
        @additionalTags={{@additionalTags}}
        @bulkSelectHelper={{@bulkSelectHelper}}
        @canBulkSelect={{@canBulkSelect}}
        @canCreateTopic={{this.canCreateTopic}}
        @canCreateTopicOnTag={{@canCreateTopicOnTag}}
        @category={{@category}}
        @createCategory={{this.createCategory}}
        @createTopic={{@createTopic}}
        @createTopicDisabled={{@createTopicDisabled}}
        @dismissRead={{@dismissRead}}
        @draftCount={{this.currentUser.draft_count}}
        @editCategory={{this.editCategory}}
        @filterMode={{this.filterMode}}
        @loadingTagInfo={{@loadingTagInfo}}
        @model={{@model}}
        @noSubcategories={{@noSubcategories}}
        @reorderCategories={{this.reorderCategories}}
        @resetNew={{@resetNew}}
        @showCategoryAdmin={{@showCategoryAdmin}}
        @showDismissRead={{@showDismissRead}}
        @showResetNew={{@showResetNew}}
        @showTagInfo={{@showTagInfo}}
        @skipCategoriesNavItem={{this.skipCategoriesNavItem}}
        @tag={{@tag}}
        @tagNotification={{@tagNotification}}
        @toggleTagInfo={{@toggleTagInfo}}
      />

      {{#if @category}}
        <PluginOutlet
          @connectorTagName="div"
          @name="category-navigation"
          @outletArgs={{lazyHash category=@category tag=@tag}}
        />
      {{/if}}

      {{#if @tag}}
        <PluginOutlet
          @connectorTagName="div"
          @name="tag-navigation"
          @outletArgs={{lazyHash category=@category tag=@tag}}
        />
      {{/if}}
    </section>
  </template>
}
