import { clipboardHelpers } from "discourse/lib/utilities";
import DButton from "discourse/ui-kit/d-button";
import DEditor from "discourse/ui-kit/d-editor";
import DResizeSeparator from "discourse/ui-kit/d-resize-separator";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import { i18n } from "discourse-i18n";

// Reusable chat-style "docked" composer. There is deliberately no
// markdown-preview toggle — users who want to see rendered output
// switch to the rich editor via the toolbar's RTE toggle, which is
// effectively a live preview. Skipping preview also avoids the
// cook-on-change CPU cost on every keystroke.
//
// @onSubmit is required; all other args are optional. See the
// styleguide entry (/styleguide → Organisms → Docked Composer) for
// the live API surface.
export default class DockedComposer extends Component {
  @service capabilities;
  @service currentUser;
  @service keyValueStore;
  @service mediaOptimizationWorker;
  @service siteSettings;

  @tracked dragOffset = 0;
  @tracked reply = "";
  @tracked uploads = trackedArray();

  /** @type {HTMLElement | null} */
  inputElement = null;

  /** @type {import("discourse/lib/uppy/uppy-upload").default | null} */
  uppyUpload = null;

  /** @type {HTMLInputElement | null} */
  fileInputEl = null;
  #rootElement = null;

  #handlePaste = (event) => {
    if (!this.inputElement || document.activeElement !== this.inputElement) {
      return;
    }
    const { canUpload, canPasteHtml, types } = clipboardHelpers(event, {
      siteSettings: this.siteSettings,
      canUpload: true,
    });
    if (!canUpload || canPasteHtml || types.includes("text/plain")) {
      return;
    }
    if (event?.clipboardData?.files?.length) {
      this.uppyUpload?.addFiles([...event.clipboardData.files], {
        pasted: true,
      });
    }
  };

  #handleKeyDown = (event) => {
    if (event.key !== "Enter" || event.isComposing) {
      return;
    }

    const submitOnEnter =
      this.args.submitOnEnter ??
      this.currentUser?.user_option?.send_shortcut !== SEND_SHORTCUT_META_ENTER;

    if (submitOnEnter) {
      if (
        !event.shiftKey &&
        !event.metaKey &&
        !event.ctrlKey &&
        !event.altKey
      ) {
        event.preventDefault();
        event.stopPropagation();
        this.submit();
      }
    } else {
      if (event.metaKey || event.ctrlKey) {
        event.preventDefault();
        event.stopPropagation();
        this.submit();
      }
    }
  };

  get autoResize() {
    return this.args.autoResize ?? false;
  }

  get resizable() {
    return (this.args.resizable ?? false) && !this.autoResize;
  }

  get maxResizeOffset() {
    return this.args.maxResizeOffset ?? null;
  }

  get resizeAriaMax() {
    return this.maxResizeOffset ?? 400;
  }

  get show() {
    return this.args.show ?? true;
  }

  get draftKey() {
    return this.args.draftKey ?? "docked-composer-draft";
  }

  get uploaderId() {
    return (
      this.args.uploaderId ?? `docked-composer-file-uploader-${guidFor(this)}`
    );
  }

  get uploadType() {
    return this.args.uploadType ?? "composer";
  }

  get minLength() {
    return this.args.minLength ?? 1;
  }

  // DEditor's composer-event bus (quote-reply insert, toolbar replace,
  // etc.). Defaults on for real app use; tests can pass false to avoid
  // app-event listener churn in rendering harnesses.
  get composerEvents() {
    return this.args.composerEvents ?? true;
  }

  get inProgressUploads() {
    return this.uppyUpload?.inProgressUploads || [];
  }

  get canSubmit() {
    if (this.args.isSubmitting || this.args.disabled) {
      return false;
    }
    if (this.inProgressUploads.length > 0) {
      return false;
    }
    return (
      this.reply.trim().length >= this.minLength || this.uploads.length > 0
    );
  }

  get submitDisabled() {
    return !this.canSubmit;
  }

  get showUploadsContainer() {
    return this.uploads?.length > 0 || this.inProgressUploads?.length > 0;
  }

  @action
  setupEditor(textManipulation) {
    this.inputElement?.removeEventListener(
      "keydown",
      this.#handleKeyDown,
      true
    );
    this.inputElement?.removeEventListener("paste", this.#handlePaste);

    this.inputElement =
      textManipulation?.textarea ??
      // Scope the fallback to this instance's root so multiple docked
      // composers on the same page can't cross-wire.
      this.#rootElement?.querySelector(".d-editor-input") ??
      null;
    if (this.inputElement) {
      // capture phase so Enter-to-send wins over ItsATrap / smart-list handlers
      this.inputElement.addEventListener("keydown", this.#handleKeyDown, true);
      this.inputElement.addEventListener("paste", this.#handlePaste);
      this.syncAutoResizeHeight();
    }
  }

  @action
  loadDraft() {
    const saved = this.keyValueStore.get(this.draftKey);
    if (saved) {
      this.reply = saved;
      this.syncAutoResizeHeight();
    }
  }

  @action
  persistDraft(value) {
    if (value?.length) {
      this.keyValueStore.set({ key: this.draftKey, value });
    } else {
      this.keyValueStore.remove(this.draftKey);
    }
  }

  @action
  onReplyChange(event) {
    const value = event?.target?.value ?? "";
    this.reply = value;
    this.persistDraft(value);
    this.syncAutoResizeHeight();
  }

  @action
  updateMaxResizeOffset() {
    this.#rootElement?.style.setProperty(
      "--docked-composer-max-resize-offset",
      `${this.maxResizeOffset ?? 400}px`
    );
  }

  @action
  setReply(value) {
    this.reply = value ?? "";
    this.persistDraft(this.reply);
  }

  @action
  setupContainer(element) {
    this.#rootElement = element;
    this.updateMaxResizeOffset();
    this.args.onRegisterApi?.({ setReply: this.setReply, focus: this.focus });
    this.loadDraft();

    this.uppyUpload = new UppyUpload(this, {
      id: this.uploaderId,
      type: this.uploadType,
      useMultipartUploadsIfAvailable: true,
      uppyReady: () => {
        if (this.siteSettings.composer_media_optimization_image_enabled) {
          this.uppyUpload.uppyWrapper.useUploadPlugin(UppyMediaOptimization, {
            optimizeFn: (data, opts) =>
              this.mediaOptimizationWorker.optimizeImage(data, opts),
            cancelFn: (fileId) => this.mediaOptimizationWorker.cancel(fileId),
            runParallel: !this.capabilities.isMobileDevice,
          });
        }
      },
      uploadDone: (upload) => {
        this.uploads.push(upload);
      },
    });

    if (this.fileInputEl) {
      this.uppyUpload.setup(this.fileInputEl);
    }
  }

  @action
  teardown() {
    this.inputElement?.removeEventListener(
      "keydown",
      this.#handleKeyDown,
      true
    );
    this.inputElement?.removeEventListener("paste", this.#handlePaste);
    if (this.uppyUpload) {
      destroy(this.uppyUpload);
      this.uppyUpload = null;
    }
    this.#rootElement = null;
  }

  @action
  registerFileInput(element) {
    if (!element) {
      return;
    }
    this.fileInputEl = element;
    this.uppyUpload?.setup(element);
  }

  @action
  openFileUpload() {
    this.fileInputEl?.click();
  }

  @action
  addToolbarButtons(toolbar) {
    toolbar.addButton({
      id: "docked-composer-upload",
      group: "insertions",
      icon: "upload",
      title: this.args.uploadTitle ?? "composer.upload_title",
      sendAction: () => this.openFileUpload(),
    });

    this.args.extraToolbarButtons?.(toolbar);
  }

  @action
  removeUpload(upload) {
    this.uploads = trackedArray(this.uploads.filter((u) => u !== upload));
  }

  @action
  cancelUpload(upload) {
    this.uppyUpload?.cancelSingleUpload({ fileId: upload.id });
  }

  @action
  async submit() {
    if (!this.canSubmit || !this.args.onSubmit) {
      return;
    }
    try {
      const result = await this.args.onSubmit({
        raw: this.reply,
        uploads: this.uploads,
        inProgressUploadsCount: this.inProgressUploads.length,
      });
      // Falsy return → don't clear; consumer can short-circuit on
      // validation failure without losing the user's input.
      if (!result) {
        return;
      }
      this.reply = "";
      this.uploads = trackedArray();
      this.persistDraft("");
      this.syncAutoResizeHeight();
      schedule("afterRender", () => this.inputElement?.focus());
    } catch (error) {
      // Consumers can opt into custom error handling; otherwise we
      // fall back to the generic ajax-error popup for network failures.
      if (this.args.onError) {
        this.args.onError(error);
      } else {
        popupAjaxError(error);
      }
    }
  }

  @action
  focus() {
    this.inputElement?.focus();
  }

  @action
  syncAutoResizeHeight() {
    if (!this.autoResize || this.inputElement?.tagName !== "TEXTAREA") {
      return;
    }

    schedule("afterRender", () => {
      if (!this.inputElement?.isConnected) {
        return;
      }

      // CSS `field-sizing: content` handles modern browsers using the same
      // mechanism as ExpandingTextArea. This fallback keeps older browsers
      // usable without affecting the RTE, which naturally grows with content.
      if (globalThis.CSS?.supports?.("field-sizing", "content")) {
        return;
      }

      this.inputElement.style.height = "auto";
      this.inputElement.style.height = `${this.inputElement.scrollHeight}px`;
    });
  }

  @action
  onResize(offset) {
    this.dragOffset = offset;
    this.#rootElement?.style.setProperty(
      "--docked-composer-drag-offset",
      `${offset}px`
    );
  }

  <template>
    {{#if this.show}}
      {{#if @bodyClassName}}
        {{bodyClass @bodyClassName}}
      {{/if}}
      <div
        class={{dConcatClass
          "docked-composer"
          (if this.resizable "docked-composer--resizable")
          (if this.autoResize "docked-composer--auto-resize")
          @class
        }}
        ...attributes
        {{didInsert this.setupContainer}}
        {{didUpdate this.updateMaxResizeOffset this.maxResizeOffset}}
        {{willDestroy this.teardown}}
      >
        {{#if this.resizable}}
          <DResizeSeparator
            class="docked-composer__resize-handle"
            @axis="vertical"
            @label={{i18n "composer.resize"}}
            @max={{this.resizeAriaMax}}
            @min={{0}}
            @onResize={{this.onResize}}
            @side="end"
            @value={{this.dragOffset}}
          />
        {{/if}}
        {{#if (has-block "header")}}
          <div class="docked-composer__header">
            {{yield to="header"}}
          </div>
        {{/if}}
        <div class="docked-composer__inner">
          <div class="docked-composer__editor">
            <DEditor
              @categoryId={{@categoryId}}
              @change={{this.onReplyChange}}
              @composerEvents={{this.composerEvents}}
              @extraButtons={{this.addToolbarButtons}}
              @onSetup={{this.setupEditor}}
              @placeholder={{@placeholder}}
              @processPreview={{false}}
              @topicId={{@topicId}}
              @value={{this.reply}}
            >
              {{#if (has-block "submit")}}
                {{yield
                  (hash
                    submit=this.submit
                    disabled=this.submitDisabled
                    isSubmitting=@isSubmitting
                  )
                  to="submit"
                }}
              {{else}}
                <DButton
                  class="docked-composer__submit-btn"
                  @action={{this.submit}}
                  @disabled={{this.submitDisabled}}
                  @icon="reply"
                  @isLoading={{@isSubmitting}}
                  @title={{@submitTitle}}
                />
              {{/if}}
            </DEditor>
          </div>

          <input
            class="hidden-upload-field"
            id={{this.uploaderId}}
            multiple="multiple"
            type="file"
            {{didInsert this.registerFileInput}}
          />
        </div>

        {{#if this.showUploadsContainer}}
          <div class="docked-composer__uploads">
            {{#each this.uploads as |upload|}}
              <div class="docked-composer__upload">
                <span class="docked-composer__upload-filename">
                  {{upload.original_filename}}
                </span>
                <DButton
                  class="btn-transparent docked-composer__upload-remove"
                  @action={{fn this.removeUpload upload}}
                  @icon="xmark"
                />
              </div>
            {{/each}}
            {{#each this.inProgressUploads as |upload|}}
              <div
                class="docked-composer__upload docked-composer__upload--in-progress"
              >
                <span class="docked-composer__upload-filename">
                  {{upload.fileName}}
                </span>
                <span class="docked-composer__upload-progress">
                  {{upload.progress}}%
                </span>
                <DButton
                  class="btn-flat docked-composer__upload-cancel"
                  @action={{fn this.cancelUpload upload}}
                  @icon="xmark"
                />
              </div>
            {{/each}}
          </div>
        {{/if}}

        {{yield}}
      </div>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import { cached, tracked } from "@glimmer/tracking";
import { array, hash } from "@ember/helper";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { trustHTML } from "@ember/template";
import Form from "discourse/components/form";
import FKErrors from "discourse/form-kit/components/fk/errors";
import { ajax } from "discourse/lib/ajax";
import { extractError, popupAjaxError } from "discourse/lib/ajax-error";
import { emailValid, escapeExpression } from "discourse/lib/utilities";
import DButton from "discourse/ui-kit/d-button";
import DOtp from "discourse/ui-kit/d-otp";
import dLoadingSpinner from "discourse/ui-kit/helpers/d-loading-spinner";
import dAutoFocus from "discourse/ui-kit/modifiers/d-auto-focus";
import { i18n } from "discourse-i18n";

export default class DsaNoticeForm extends Component {
  @service currentUser;
  @service siteSettings;

  @tracked result;
  @tracked emailVerified = false;
  @tracked requestingCode = false;
  @tracked verificationError;
  @tracked verifyingCode = false;
  @tracked verificationToken;

  #form;

  get canSubmit() {
    return !this.requiresEmailVerification || this.emailVerified;
  }

  get emailCodeDisabled() {
    const email = this.#form?.get("email")?.trim();
    return (
      this.emailVerified ||
      this.requestingCode ||
      this.verifyingCode ||
      !email ||
      !emailValid(email)
    );
  }

  get emailCodeLabel() {
    if (this.emailVerified) {
      return "dsa_notice.email_verified";
    }
    return this.verificationToken
      ? "dsa_notice.resend_email_code"
      : "dsa_notice.get_email_code";
  }

  get requiresEmailVerification() {
    return !this.currentUser?.can_use_dsa_account_email;
  }

  @cached
  get initialData() {
    return {
      content_url: this.args.contentUrl,
      declaration: false,
    };
  }

  @action
  registerForm(form) {
    this.#form = form;
  }

  @action
  codeChanged(value) {
    this.#form.set("verification_code", value);
    this.verificationError = null;
    if (value.length === 6) {
      this.verifyCode(value);
    }
  }

  @action
  emailChanged(value, { set }) {
    set("email", value);
    set("verification_code", "");
    this.emailVerified = false;
    this.verificationError = null;
    this.verificationToken = null;
  }

  @action
  async requestCode() {
    const email = this.#form.get("email")?.trim().toLowerCase();
    if (!email || !emailValid(email)) {
      this.#form.addError("email", {
        title: i18n("dsa_notice.email"),
        message: i18n("user.email.invalid"),
      });
      return;
    }

    this.requestingCode = true;
    try {
      const result = await ajax("/dsa/report-illegal-content/verify-email", {
        type: "POST",
        data: { email },
      });
      if (this.#form.get("email")?.trim().toLowerCase() === email) {
        this.verificationToken = result.token;
        this.verificationError = null;
        this.#form.set("verification_code", "");
      }
    } catch (error) {
      popupAjaxError(error);
    } finally {
      this.requestingCode = false;
    }
  }

  @action
  async submit(data) {
    const notice = { ...data };
    delete notice.verification_code;
    try {
      this.result = await ajax("/dsa/report-illegal-content", {
        type: "POST",
        data: { notice, token: this.verificationToken },
      });
      if (!this.args.inModal) {
        window.scrollTo(0, 0);
      }
    } catch (error) {
      if (error.jqXHR?.responseJSON?.error_type === "verification_required") {
        this.emailVerified = false;
        this.verificationToken = null;
        this.verificationError = null;
        this.#form.set("verification_code", "");
      }
      popupAjaxError(error);
    }
  }

  @action
  async verifyCode(verification_code) {
    if (this.verifyingCode || this.emailVerified) {
      return;
    }

    this.verifyingCode = true;
    try {
      await ajax("/dsa/report-illegal-content/verify-code", {
        type: "POST",
        data: {
          token: this.verificationToken,
          email: this.#form.get("email")?.trim().toLowerCase(),
          verification_code,
        },
      });
      this.emailVerified = true;
    } catch (error) {
      this.verificationError =
        error.jqXHR?.responseJSON?.errors?.[0] || extractError(error);
    } finally {
      this.verifyingCode = false;
    }
  }

  @action
  validateEmail(name, value, { addError }) {
    if (value && !emailValid(value.trim())) {
      addError(name, {
        title: i18n("dsa_notice.email"),
        message: i18n("user.email.invalid"),
      });
    }
  }

  <template>
    <div class="dsa-notice" ...attributes>
      {{#if this.result}}
        <div class="dsa-notice__confirmation">
          {{#if @inModal}}
            <h2 tabindex="-1" {{dAutoFocus}}>{{i18n "dsa_notice.received"}}</h2>
          {{else}}
            <h1 tabindex="-1" {{dAutoFocus}}>{{i18n "dsa_notice.received"}}</h1>
          {{/if}}
          <p>{{i18n
              "dsa_notice.received_description"
              site=this.siteSettings.title
            }}</p>
          <p class="dsa-notice__reference">
            {{trustHTML
              (i18n
                "dsa_notice.reference"
                reference=(escapeExpression this.result.reference)
              )
            }}
          </p>
          <p>{{i18n "dsa_notice.contact_confirmation"}}</p>
        </div>
        {{#if @inModal}}
          <div class="dsa-notice__actions">
            <DButton class="btn-primary" @action={{@onClose}} @label="close" />
          </div>
        {{/if}}
      {{else}}
        {{#unless @inModal}}
          <h1>{{i18n "dsa_notice.title"}}</h1>
        {{/unless}}
        <Form
          class="dsa-notice__form"
          @data={{this.initialData}}
          @onRegisterApi={{this.registerForm}}
          @onSubmit={{this.submit}}
          as |form|
        >
          <form.Section class="dsa-notice__fields">
            {{#if this.requiresEmailVerification}}
              <form.Fieldset
                aria-busy={{or this.requestingCode this.verifyingCode}}
                aria-label={{i18n "dsa_notice.email"}}
                disabled={{or this.requestingCode this.verifyingCode}}
              >
                <form.Field
                  @disabled={{or this.emailVerified this.verifyingCode}}
                  @format="full"
                  @name="email"
                  @onSet={{this.emailChanged}}
                  @title={{i18n "dsa_notice.email"}}
                  @type="input-email"
                  @validate={{this.validateEmail}}
                  @validation="required"
                  as |field|
                >
                  <form.Actions>
                    <field.Control autocomplete="email" />
                    <form.Button
                      aria-live="polite"
                      class={{if
                        this.emailVerified
                        "btn-success"
                        "btn-default"
                      }}
                      @action={{this.requestCode}}
                      @disabled={{this.emailCodeDisabled}}
                      @icon={{if this.emailVerified "check"}}
                      @isLoading={{this.requestingCode}}
                      @label={{this.emailCodeLabel}}
                    />
                  </form.Actions>
                </form.Field>
                {{#if (and this.verificationToken (not this.emailVerified))}}
                  <form.Field
                    class={{if this.verificationError "has-error"}}
                    @disabled={{this.verifyingCode}}
                    @format="full"
                    @name="verification_code"
                    @title={{i18n "dsa_notice.verification_code"}}
                    @type="custom"
                    @validation="required"
                    as |field|
                  >
                    <form.Actions>
                      {{#each (array this.verificationToken) key="@identity"}}
                        <DOtp
                          aria-describedby={{if
                            this.verificationError
                            field.errorId
                          }}
                          aria-invalid={{if this.verificationError "true"}}
                          id={{field.id}}
                          @onChange={{this.codeChanged}}
                        />
                      {{/each}}
                      {{#if this.verifyingCode}}
                        <div aria-label={{i18n "loading"}} role="status">
                          {{dLoadingSpinner size="small"}}
                        </div>
                      {{/if}}
                    </form.Actions>
                    {{#if this.verificationError}}
                      <FKErrors
                        @error={{hash messages=(array this.verificationError)}}
                        @id={{field.errorId}}
                      />
                    {{/if}}
                  </form.Field>
                {{/if}}
              </form.Fieldset>
            {{/if}}
            <form.Field
              @disabled={{not this.canSubmit}}
              @format="full"
              @name="name"
              @title={{i18n "dsa_notice.name"}}
              @type="input"
              @validation="required:trim|length:1,200"
              as |field|
            >
              <field.Control autocomplete="name" />
            </form.Field>
            <form.Field
              @disabled={{not this.canSubmit}}
              @format="full"
              @name="content_url"
              @title={{i18n "dsa_notice.content_url"}}
              @type="input-url"
              @validation="required|url"
              as |field|
            >
              <field.Control />
            </form.Field>
            <form.Field
              @description={{i18n "dsa_notice.explanation_help"}}
              @disabled={{not this.canSubmit}}
              @format="full"
              @name="explanation"
              @title={{i18n "dsa_notice.explanation"}}
              @type="textarea"
              @validation="required:trim|length:50,20000"
              as |field|
            >
              <field.Control rows="6" />
            </form.Field>
            <form.Field
              @disabled={{not this.canSubmit}}
              @format="full"
              @name="declaration"
              @title={{i18n "dsa_notice.declaration_section"}}
              @type="checkbox"
              @validation="accepted"
              as |field|
            >
              <field.Control @title={{i18n "dsa_notice.declaration"}} />
            </form.Field>
          </form.Section>
          <form.Actions class="dsa-notice__actions">
            <form.Submit
              @disabled={{not this.canSubmit}}
              @label="dsa_notice.submit"
            />
            {{#if @inModal}}
              <DButton
                class="btn-flat"
                @action={{or @onBack @onClose}}
                @label={{if @onBack "dsa_notice.go_back" "cancel"}}
              />
            {{/if}}
          </form.Actions>
        </Form>
      {{/if}}
    </div>
  </template>
}
import Component from "@glimmer/component";
import { cached } from "@glimmer/tracking";
import {
  resolveSettingFieldType,
  settingFieldValidation,
} from "discourse/lib/setting-field-registry";

export default class SettingDefinitionField extends Component {
  @cached
  get entry() {
    return resolveSettingFieldType(this.args.definition);
  }

  get renderer() {
    return this.entry.renderer;
  }

  get description() {
    if (
      this.args.showDescription === false ||
      this.entry.includeDescription === false
    ) {
      return undefined;
    }

    return this.args.definition.description;
  }

  get format() {
    return this.args.format ?? this.args.definition.format ?? this.entry.format;
  }

  get validation() {
    return settingFieldValidation(this.args.definition);
  }

  <template>
    <@form.Field
