      {{#each this.buttons as |b|}}
        {{#if b.isDiscourseID}}
          <div class="discourse-id__wrapper">
            <button
              aria-label={{b.screenReaderTitle}}
              class="btn btn-social {{b.name}}"
              type="button"
              {{on "click" (fn @externalLogin b)}}
            >
              {{dIcon b.icon}}
              <span class="btn-social-title">{{b.title}}</span>
