  <template>
    <DModal
      @closeModal={{@closeModal}}
      @title={{i18n "admin.customize.bulk_delete"}}
    >
      <:body>
        {{i18n (concat "admin.customize.bulk_" @model.type "_delete_confirm")}}
        <ul>
          {{#each @model.selectedThemesOrComponents as |theme|}}
            <li>{{theme.name}}</li>
          {{/each}}
        </ul>

      </:body>
      <:footer>
        <DButton
          class="btn-primary"
          @action={{this.delete}}
          @label="yes_value"
        />
        <DModalCancel @close={{@closeModal}} />
      </:footer>
    </DModal>
  </template>
}
