const SLOW_MODE_OPTIONS = [
  {
    id: "600",
    name: i18n("topic.slow_mode_update.durations.10_minutes"),
  },
  {
    id: "900",
    name: i18n("topic.slow_mode_update.durations.15_minutes"),
  },
  {
    id: "1800",
    name: i18n("topic.slow_mode_update.durations.30_minutes"),
  },
  {
    id: "2700",
    name: i18n("topic.slow_mode_update.durations.45_minutes"),
  },
  {
    id: "3600",
    name: i18n("topic.slow_mode_update.durations.1_hour"),
  },
  {
    id: "7200",
    name: i18n("topic.slow_mode_update.durations.2_hours"),
  },
  {
    id: "14400",
    name: i18n("topic.slow_mode_update.durations.4_hours"),
  },
  {
    id: "28800",
    name: i18n("topic.slow_mode_update.durations.8_hours"),
  },
  {
    id: "43200",
    name: i18n("topic.slow_mode_update.durations.12_hours"),
  },
  {
    id: "86400",
    name: i18n("topic.slow_mode_update.durations.24_hours"),
  },
  {
    id: "custom",
    name: i18n("topic.slow_mode_update.durations.custom"),
  },
];

export default class EditSlowMode extends Component {
  @service currentUser;

  @tracked selectedSlowMode;
  @tracked hours;
  @tracked minutes;
  @tracked seconds;
  @tracked saveDisabled = false;
  @tracked flash;

  constructor() {
    super(...arguments);
    const currentDuration = parseInt(
      this.args.model.topic.slow_mode_seconds,
      10
    );
    if (currentDuration) {
      const selectedDuration = this.slowModes.find(
        (mode) => mode.id === currentDuration.toString()
      );

      if (selectedDuration) {
        this.selectedSlowMode = currentDuration.toString();
      } else {
        this.selectedSlowMode = "custom";
      }

      this._setFromSeconds(currentDuration);
    }
  }

  get slowModes() {
    return SLOW_MODE_OPTIONS;
  }

  get saveButtonLabel() {
    return this.args.model.topic.slow_mode_seconds &&
      this.args.model.topic.slow_mode_seconds !== 0
      ? "topic.slow_mode_update.update"
      : "topic.slow_mode_update.enable";
  }

  get timeShortcuts() {
    const timezone = this.currentUser.user_option.timezone;
    const shortcuts = timeShortcuts(timezone);

    const nextWeek = shortcuts.monday();
    nextWeek.label = "time_shortcut.next_week";

    return [
      shortcuts.laterToday(),
      shortcuts.tomorrow(),
      shortcuts.twoDays(),
      nextWeek,
      shortcuts.twoWeeks(),
      shortcuts.nextMonth(),
      shortcuts.twoMonths(),
    ];
  }

  get showCustomSelect() {
    return this.selectedSlowMode === "custom";
  }

  get durationIsSet() {
    return this.hours || this.minutes || this.seconds;
  }

  @action
  async enableSlowMode() {
    this.saveDisabled = true;
    const seconds = toSeconds(
      this._parseValue(this.hours),
      this._parseValue(this.minutes),
      this._parseValue(this.seconds)
    );

    try {
      await Topic.setSlowMode(
        this.args.model.topic.id,
        seconds,
        this.args.model.topic.slow_mode_enabled_until
      );
      this.args.model.topic.set("slow_mode_seconds", seconds);
      this.args.closeModal();
    } catch {
      this.flash = i18n("generic_error");
    } finally {
      this.saveDisabled = false;
    }
  }

  @action
  async disableSlowMode() {
    this.saveDisabled = true;
    try {
      await Topic.setSlowMode(this.args.model.topic.id, 0);
      this.args.model.topic.set("slow_mode_seconds", 0);
      this.args.closeModal();
    } catch (e) {
      this.flash = extractError(e);
    } finally {
      this.saveDisabled = false;
    }
  }

  @action
  setSlowModeDuration(duration) {
    if (duration !== "custom") {
      let seconds = parseInt(duration, 10);
      this._setFromSeconds(seconds);
    }

    this.selectedSlowMode = duration;
  }

  _setFromSeconds(seconds) {
    const { hours, minutes, seconds: componentSeconds } = fromSeconds(seconds);
    this.hours = hours;
    this.minutes = minutes;
    this.seconds = componentSeconds;
  }

  _parseValue(value) {
    return parseInt(value, 10) || 0;
  }

  <template>
    <DModal
      class="edit-slow-mode-modal"
      @closeModal={{@closeModal}}
      @flash={{this.flash}}
      @title={{i18n "topic.slow_mode_update.title"}}
    >
      <:body>
        <div class="control-group">
          <label class="slow-mode-label">
            {{i18n "topic.slow_mode_update.description"}}
          </label>
        </div>
        <div class="control-group">
          <label class="slow-mode-label">
            {{i18n "topic.slow_mode_update.select"}}
          </label>
          <ComboBox
            class="slow-mode-type"
            @content={{this.slowModes}}
            @onChange={{this.setSlowModeDuration}}
            @value={{this.selectedSlowMode}}
          />
        </div>
        {{#if this.showCustomSelect}}
          <div class="control-group">
            <label class="slow-mode-label">
              {{i18n "topic.slow_mode_update.hours"}}
            </label>
            <Input class="input-small" @type="number" @value={{this.hours}} />
            <label class="slow-mode-label">
              {{i18n "topic.slow_mode_update.minutes"}}
            </label>
            <Input class="input-small" @type="number" @value={{this.minutes}} />
            <label class="slow-mode-label">
              {{i18n "topic.slow_mode_update.seconds"}}
            </label>
            <Input class="input-small" @type="number" @value={{this.seconds}} />
          </div>
        {{/if}}

        <div class="control-group">
          <DFutureDateInput
            class="enabled-until"
            @clearable={{true}}
            @customShortcuts={{this.timeShortcuts}}
            @input={{@model.topic.slow_mode_enabled_until}}
            @label="topic.slow_mode_update.enabled_until"
            @labelClasses="slow-mode-label"
            @onChangeInput={{fn (mut @model.topic.slow_mode_enabled_until)}}
          />
        </div>
      </:body>
      <:footer>
        <DButton
          class="btn-primary"
          @action={{this.enableSlowMode}}
          @disabled={{this.submitDisabled}}
          @icon="hourglass-start"
          @label={{this.saveButtonLabel}}
        />
        {{#if @model.topic.slow_mode_seconds}}
          <DButton
            class="btn-danger"
            @action={{this.disableSlowMode}}
            @disabled={{this.submitDisabled}}
            @label="topic.slow_mode_update.remove"
          />
        {{/if}}
      </:footer>
    </DModal>
  </template>
}
import { trustHTML } from "@ember/template";
import { iconHTML } from "discourse/lib/icon-library";
import { i18n } from "discourse-i18n";

export default function directoryTableHeaderTitle(args) {
  // Args should include key/values { field, icon, translated }

  let html = "";
  if (args.icon) {
    html += iconHTML(args.icon);
  }
  const labelKey = `directory.${args.field}`;

  html += args.translated
    ? args.field
    : i18n(`${labelKey}_long`, { defaultValue: i18n(labelKey) });
  return trustHTML(html);
}
import { isTesting } from "discourse/lib/environment";

export function reload() {
  if (!isTesting()) {
    location.reload();
  }
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { Input } from "@ember/component";
import { action } from "@ember/object";
import directoryColumnIsAutomatic from "discourse/helpers/directory-column-is-automatic";
import directoryColumnIsUserField from "discourse/helpers/directory-column-is-user-field";
import directoryTableHeaderTitle from "discourse/helpers/directory-table-header-title";
import { reload } from "discourse/helpers/page-reloader";
import { ajax } from "discourse/lib/ajax";
import { extractError, popupAjaxError } from "discourse/lib/ajax-error";
import DButton from "discourse/ui-kit/d-button";
import DModal from "discourse/ui-kit/d-modal";
import DReorderableList from "discourse/ui-kit/d-reorderable-list";
import dLoadingSpinner from "discourse/ui-kit/helpers/d-loading-spinner";
import { i18n } from "discourse-i18n";

/**
 * The reordering surface behind `enable_new_reordering_controls`. Mirrors
 * `modal/edit-user-directory-columns.gjs`, over the shared reorderable list.
 *
 * TODO (ui-kit-reorderable-list-cleanup) rename this over `modal/edit-user-directory-columns.gjs`
 * and drop the branch in app/controllers/users.js.
 */
export default class EditUserDirectoryColumns extends Component {
  @tracked loading = true;
  @tracked columns;
  @tracked flash;

  /**
   * A plain-text name for a column, for the reorder controls and
   * announcements — the rendered header title can carry icon markup, which an
   * accessible name cannot.
   *
   * @param {{ name: string, type: string, user_field?: { name: string } | null }} column - The column to name.
   * @returns {string} The translated column name.
   */
  columnLabel = (column) => {
    if (column.type === "automatic") {
      return i18n(`directory.${column.name}_long`, {
        defaultValue: i18n(`directory.${column.name}`),
      });
    }
    if (column.user_field) {
      return column.user_field.name;
    }
    return i18n(column.name);
  };

  constructor() {
    super(...arguments);
    this.setupColumns();
  }

  @action
  async setupColumns() {
    try {
      const response = await ajax("edit-directory-columns.json");
      this.loading = false;
      this.columns = response.directory_columns
        .sort((a, b) => (a.position > b.position ? 1 : -1))
        .map((c) => ({ ...c, enabled: Boolean(c.enabled) }));
    } catch (e) {
      popupAjaxError(e);
    }
  }

  @action
  async save() {
    this.loading = true;
    this.flash = null;
    const data = {
      directory_columns: this.columns.map((c) => ({
        id: c.id,
        enabled: c.enabled,
        position: c.position,
      })),
    };

    try {
      await ajax("edit-directory-columns.json", { type: "PUT", data });
      reload();
    } catch (e) {
      this.loading = false;
      this.flash = extractError(e);
    }
  }

  @action
  resetToDefault() {
    const resetColumns = this.columns
      .sort((a, b) => {
        const a1 = a.automatic_position || (a.user_field?.position || 0) + 1000;
        const b1 = b.automatic_position || (b.user_field?.position || 0) + 1000;

        if (a1 === b1) {
          return a.name.localeCompare(b.name);
        } else {
          return a1 > b1 ? 1 : -1;
        }
      })
      .map((column, index) => ({
        ...column,
        position: column.automatic_position || index + 1,
        enabled: column.type === "automatic",
      }));

    this.columns = resetColumns;
  }

  /**
   * Applies a committed move and renumbers every column from its new visible
   * slot — the stored order is exactly the displayed one here.
   *
   * @param {import("discourse/ui-kit/d-reorderable-list/types").ReorderableMove<{ id: number, name: string, type: string, position: number, enabled: boolean, icon: string | null, user_field_id: number | null, automatic_position: number | null, user_field?: { name: string, position: number } | null }>} move - The normalized move from the list.
   */
  @action
  handleMove(move) {
    this.columns = move.proposedToItems.map((column, index) => ({
      ...column,
      position: index + 1,
    }));
  }

  <template>
    <DModal
      class="edit-user-directory-columns-modal"
      @closeModal={{@closeModal}}
      @flash={{this.flash}}
      @title={{i18n "directory.edit_columns.title"}}
    >
      <:body>
        {{#if this.loading}}
          {{dLoadingSpinner size="large"}}
        {{else}}
          <DReorderableList
            class="edit-directory-columns-container"
            @items={{this.columns}}
            @itemTag="div"
            @key="id"
            @label={{this.columnLabel}}
            @onMove={{this.handleMove}}
            @rowClass="edit-directory-column"
            @tag="div"
          >
            <:row as |column|>
              <div class="left-content">
                <label class="column-name">
                  <Input @checked={{column.enabled}} @type="checkbox" />
                  {{#if (directoryColumnIsAutomatic column=column)}}
                    {{directoryTableHeaderTitle
                      field=column.name
                      icon=column.icon
                    }}
                  {{else if (directoryColumnIsUserField column=column)}}
                    {{directoryTableHeaderTitle
                      field=column.user_field.name
                      translated=true
                    }}
                  {{else}}
                    {{directoryTableHeaderTitle
                      field=(i18n column.name)
                      translated=true
                    }}
                  {{/if}}
                </label>
              </div>
            </:row>
          </DReorderableList>
        {{/if}}
      </:body>
      <:footer>
        <DButton
          class="btn-primary"
          @action={{this.save}}
          @label="directory.edit_columns.save"
        />
        <DButton
          class="btn-default reset-to-default"
          @action={{this.resetToDefault}}
          @label="directory.edit_columns.reset_to_default"
        />
      </:footer>
    </DModal>
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { Input } from "@ember/component";
import { fn } from "@ember/helper";
import { action } from "@ember/object";
import directoryColumnIsAutomatic from "discourse/helpers/directory-column-is-automatic";
import directoryColumnIsUserField from "discourse/helpers/directory-column-is-user-field";
import directoryTableHeaderTitle from "discourse/helpers/directory-table-header-title";
import { reload } from "discourse/helpers/page-reloader";
import { ajax } from "discourse/lib/ajax";
import { extractError, popupAjaxError } from "discourse/lib/ajax-error";
import DButton from "discourse/ui-kit/d-button";
import DModal from "discourse/ui-kit/d-modal";
import dLoadingSpinner from "discourse/ui-kit/helpers/d-loading-spinner";
import { i18n } from "discourse-i18n";

const UP = "up";
const DOWN = "down";

// TODO (ui-kit-reorderable-list-cleanup) delete this file once
// `enable_new_reordering_controls` ships; `edit-user-directory-columns-reorderable.gjs` replaces it.
export default class EditUserDirectoryColumns extends Component {
  @tracked loading = true;
  @tracked columns;
  @tracked flash;

  constructor() {
    super(...arguments);
    this.setupColumns();
  }

  @action
  async setupColumns() {
    try {
      const response = await ajax("edit-directory-columns.json");
      this.loading = false;
      this.columns = response.directory_columns
        .sort((a, b) => (a.position > b.position ? 1 : -1))
        .map((c) => ({ ...c, enabled: Boolean(c.enabled) }));
    } catch (e) {
      popupAjaxError(e);
    }
  }

  @action
  async save() {
    this.loading = true;
    this.flash = null;
    const data = {
      directory_columns: this.columns.map((c) => ({
        id: c.id,
        enabled: c.enabled,
        position: c.position,
      })),
    };

    try {
      await ajax("edit-directory-columns.json", { type: "PUT", data });
      reload();
    } catch (e) {
      this.loading = false;
      this.flash = extractError(e);
    }
  }

  @action
  resetToDefault() {
    const resetColumns = this.columns
      .sort((a, b) => {
        const a1 = a.automatic_position || (a.user_field?.position || 0) + 1000;
        const b1 = b.automatic_position || (b.user_field?.position || 0) + 1000;

        if (a1 === b1) {
          return a.name.localeCompare(b.name);
        } else {
          return a1 > b1 ? 1 : -1;
        }
      })
      .map((column, index) => ({
        ...column,
        position: column.automatic_position || index + 1,
        enabled: column.type === "automatic",
      }));

    this.columns = resetColumns;
  }

  @action
  moveUp(column) {
    this._moveColumn(UP, column);
  }

  @action
  moveDown(column) {
    this._moveColumn(DOWN, column);
  }

  _moveColumn(direction, column) {
    if (
      (direction === UP && column.position === 1) ||
      (direction === DOWN && column.position === this.columns.length)
    ) {
      return;
    }

    const positionOnClick = column.position;
    const newPosition =
      direction === UP ? positionOnClick - 1 : positionOnClick + 1;
    const previousColumn = this.columns.find((c) => c.position === newPosition);
    column.position = newPosition;
    previousColumn.position = positionOnClick;
    this.columns = this.columns.sort((a, b) =>
      a.position > b.position ? 1 : -1
    );
  }

  <template>
    <DModal
      class="edit-user-directory-columns-modal"
      @closeModal={{@closeModal}}
      @flash={{this.flash}}
      @title={{i18n "directory.edit_columns.title"}}
    >
      <:body>
        {{#if this.loading}}
          {{dLoadingSpinner size="large"}}
        {{else}}
          <div class="edit-directory-columns-container">
            {{#each this.columns as |column|}}
              <div class="edit-directory-column">
                <div class="left-content">
                  <label class="column-name">
                    <Input @checked={{column.enabled}} @type="checkbox" />
                    {{#if (directoryColumnIsAutomatic column=column)}}
                      {{directoryTableHeaderTitle
                        field=column.name
                        icon=column.icon
                      }}
                    {{else if (directoryColumnIsUserField column=column)}}
                      {{directoryTableHeaderTitle
                        field=column.user_field.name
                        translated=true
                      }}
                    {{else}}
                      {{directoryTableHeaderTitle
                        field=(i18n column.name)
                        translated=true
                      }}
                    {{/if}}
                  </label>
                </div>
                <div class="right-content">
                  <DButton
                    class="btn-default button-secondary move-column-up"
                    @action={{fn this.moveUp column}}
                    @icon="arrow-up"
                  />
                  <DButton
                    class="btn-default button-secondary move-column-down"
                    @action={{fn this.moveDown column}}
                    @icon="arrow-down"
                  />
                </div>
              </div>
