                  />
                </dropdown.item>
              {{/if}}
              <dropdown.item class="update-translations-menu__add">
                <DButton
                  class="post-action-menu__add-translation"
                  @action={{this.addTranslation}}
                  @icon="plus"
                  @label="post.localizations.add"
                />
              </dropdown.item>
            </PluginOutlet>
          </DDropdownMenu>
        </:content>
      </DMenu>
    {{/if}}
  </template>
