export default class PostMetaDataReplyToTab extends Component {
  static shouldRender(args, context, owner) {
    const siteSettings = owner.lookup("service:site-settings");

    return (
      args.post.reply_to_user?.username &&
      (!args.isReplyingDirectlyToPostAbove ||
        !siteSettings.suppress_reply_directly_above)
    );
  }

  @service site;

  @action
  handleClick(event) {
    event.preventDefault();
    this.args.toggleReplyAbove();
  }

  <template>
    <a
      aria-expanded={{if this.site.desktopView @hasRepliesAbove}}
      class="reply-to-tab"
      disabled={{@repliesAbove.isPending}}
      href
      role={{if this.site.desktopView "button"}}
      title={{i18n "post.in_reply_to"}}
      {{on "click" this.handleClick}}
    >
      {{#if @repliesAbove.isPending}}
        <div class="spinner small"></div>
      {{else}}
        {{dIcon "share"}}
      {{/if}}
      <PluginOutlet
        @name="post-meta-data-reply-to-tab-info"
        @outletArgs={{lazyHash post=@post}}
      >
        {{dAvatar @post.reply_to_user imageSize="small"}}
        <span>{{userPrioritizedName @post.reply_to_user}}</span>
      </PluginOutlet>
    </a>
  </template>
}
import DButton from "discourse/ui-kit/d-button";

const PostMetaDataSelectPost = <template>
  <div class="select-posts">
    {{#if (and (not @selected) (not @post.firstPost))}}
      {{#if @post.hasReplies}}
        <DButton
          class="btn-flat select-replies"
          @action={{@selectReplies}}
          @label="topic.multi_select.select_replies.label"
          @title="topic.multi_select.select_replies.title"
        />
      {{/if}}
      <DButton
        class="btn-flat select-below"
        @action={{@selectBelow}}
        @label="topic.multi_select.select_below.label"
        @title="topic.multi_select.select_below.title"
      />
    {{/if}}
    <DButton
      class="btn-flat select-post"
      @action={{@togglePostSelection}}
      @label={{if
        @selected
        "topic.multi_select.selected_post.label"
        "topic.multi_select.select_post.label"
      }}
      @title={{if
        @selected
        "topic.multi_select.selected_post.title"
        "topic.multi_select.select_post.title"
      }}
    />
  </div>
</template>;

export default PostMetaDataSelectPost;
import Component from "@glimmer/component";
import { service } from "@ember/service";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

export default class PostMetaDataWhisperIndicator extends Component {
  @service site;

  get groups() {
    return this.site.whispers_allowed_groups_names;
  }

  get title() {
    if (this.groups?.length > 0) {
      return i18n("post.whisper_groups", {
        groupNames: this.groups.join(", "),
      });
    }

    return i18n("post.whisper");
  }

  <template>
    <div class="post-info whisper" title={{this.title}}>
      {{dIcon "far-eye-slash"}}
    </div>
  </template>
}
import Component from "@glimmer/component";
import { cached } from "@glimmer/tracking";
import { getOwner } from "@ember/owner";
import DAG from "discourse/lib/dag";
import { applyMutableValueTransformer } from "discourse/lib/transformer";
import PostMetaDataDate from "./meta-data/date.gjs";
import PostMetaDataEditsIndicator from "./meta-data/edits-indicator.gjs";
import PostMetaDataEmailIndicator from "./meta-data/email-indicator.gjs";
import PostMetaDataLanguage from "./meta-data/language.gjs";
import PostMetaDataLockedIndicator from "./meta-data/locked-indicator.gjs";
import PostMetaDataPosterName from "./meta-data/poster-name.gjs";
import PostMetaDataReadIndicator from "./meta-data/read-indicator.gjs";
import PostMetaDataReplyToTab from "./meta-data/reply-to-tab.gjs";
import PostMetaDataSelectPost from "./meta-data/select-post.gjs";
import PostMetaDataWhisperIndicator from "./meta-data/whisper-indicator.gjs";

const metaDataInfoKeys = Object.freeze({
  WHISPER_INDICATOR: "whisper_indicator",
  EMAIL_INDICATOR: "email_indicator",
  LOCKED_INDICATOR: "locked_indicator",
  EDITS_INDICATOR: "edits_indicator",
  SELECT_POST: "select_post",
  REPLY_TO_TAB: "reply_to_tab",
  LANGUAGE: "language",
  DATE: "date",
  READ_INDICATOR: "read_indicator",
});

const INFO_DEFINITIONS = {
  [metaDataInfoKeys.WHISPER_INDICATOR]: {
    Component: PostMetaDataWhisperIndicator,
    shouldRender: (args) => args.post.isWhisper,
  },
  [metaDataInfoKeys.EMAIL_INDICATOR]: {
    Component: PostMetaDataEmailIndicator,
    shouldRender: (args) => args.post.via_email,
  },
  [metaDataInfoKeys.LOCKED_INDICATOR]: {
    Component: PostMetaDataLockedIndicator,
    shouldRender: (args) => args.post.locked,
  },
  [metaDataInfoKeys.EDITS_INDICATOR]: {
    Component: PostMetaDataEditsIndicator,
    shouldRender: (args) => args.post.version > 1 || args.post.wiki,
  },
  [metaDataInfoKeys.SELECT_POST]: {
    Component: PostMetaDataSelectPost,
    shouldRender: (args) => args.multiSelect,
  },
  [metaDataInfoKeys.REPLY_TO_TAB]: {
    Component: PostMetaDataReplyToTab,
    shouldRender: (args, owner) =>
      PostMetaDataReplyToTab.shouldRender(args, null, owner),
  },
  [metaDataInfoKeys.LANGUAGE]: {
    Component: PostMetaDataLanguage,
    shouldRender: (args) => args.post.is_localized && args.post.language,
  },
  [metaDataInfoKeys.DATE]: {
    Component: PostMetaDataDate,
    shouldRender: () => true,
  },
  [metaDataInfoKeys.READ_INDICATOR]: {
    Component: PostMetaDataReadIndicator,
    shouldRender: () => true,
  },
};

const INFO_COMPONENTS = Array.from(Object.entries(INFO_DEFINITIONS)).map(
  ([key, { Component: InfoComponent }]) => [key, InfoComponent]
);

export default class PostMetaData extends Component {
  @cached
  get availableInfoComponents() {
    return this.#infoComponentsDag
      .resolve()
      .filter(({ key }) => {
        const shouldRender = INFO_DEFINITIONS[key]?.shouldRender;
        return shouldRender ? shouldRender(this.args, getOwner(this)) : true;
      })
      .map(({ key, value: InfoComponent }) => ({ key, InfoComponent }));
  }

  get shouldDisplayPosterName() {
    return this.args.displayPosterName ?? true;
  }

  // The metadata components are managed in a Directed Acyclic Graph (DAG)
  // to allow plugins to modify the list (e.g., add new items or reorder).
  get #infoComponentsDag() {
    return applyMutableValueTransformer(
      "post-meta-data-infos",
      DAG.from(INFO_COMPONENTS, {
        throwErrorOnCycle: false,
      }),
      { post: this.args.post, metaDataInfoKeys }
    );
  }

  <template>
    <div class="topic-meta-data">
      {{#if this.shouldDisplayPosterName}}
        <PostMetaDataPosterName @post={{@post}} />
      {{/if}}

      <div class="post-infos">
        {{! do not include PluginOutlets here, use the DAG API instead }}
        {{#each this.availableInfoComponents key="key" as |item|}}
          <item.InfoComponent
            @editPost={{@editPost}}
            @hasRepliesAbove={{@hasRepliesAbove}}
            @isReplyingDirectlyToPostAbove={{@isReplyingDirectlyToPostAbove}}
            @post={{@post}}
            @repliesAbove={{@repliesAbove}}
            @selectBelow={{@selectBelow}}
            @selected={{@selected}}
            @selectReplies={{@selectReplies}}
            @showHistory={{@showHistory}}
            @showRawEmail={{@showRawEmail}}
            @togglePostSelection={{@togglePostSelection}}
            @toggleReplyAbove={{@toggleReplyAbove}}
          />
        {{/each}}
      </div>
    </div>
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { trustHTML } from "@ember/template";
import { modifier } from "ember-modifier";
import { prioritizeNameInUx } from "discourse/lib/settings";
import DConditionalInElement from "discourse/ui-kit/d-conditional-in-element";
import DUserLink from "discourse/ui-kit/d-user-link";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

export default class PostNoticeCustom extends Component {
  @tracked createdByAnchorElement;

  registerCreatedByLink = modifier((element) => {
    this.createdByAnchorElement = element?.querySelector(".custom_created_by");
  });

  get createdByName() {
    if (!this.args.post.notice_created_by_user) {
      return;
    }

    return prioritizeNameInUx(this.args.post.notice_created_by_user.name)
      ? this.args.post.notice_created_by_user.name
      : this.args.post.notice_created_by_user.username;
  }

  <template>
    {{dIcon "user-shield"}}
    <div class="post-notice-message" {{this.registerCreatedByLink}}>
      {{trustHTML @notice.cooked}}
      {{#if this.createdByName}}
        {{trustHTML
          (i18n
            "post.notice.custom_created_by"
            userLinkHTML="<span class='custom_created_by'></span>"
          )
        }}
      {{/if}}
      {{! #in-element is used as an strategy to render the HTML content in the string from a real component
          instead defining it from a string }}
      <DConditionalInElement @element={{this.createdByAnchorElement}}>
        <DUserLink
          title={{this.createdByName}}
          @ariaHidden={{false}}
          @username={{@post.notice_created_by_user.username}}
        >
          {{this.createdByName}}
        </DUserLink>
      </DConditionalInElement>
    </div>
  </template>
}
import Component from "@glimmer/component";
import { service } from "@ember/service";
import { prioritizeNameInUx } from "discourse/lib/settings";
