}
import Component from "@glimmer/component";
import { action } from "@ember/object";
import { getOwner } from "@ember/owner";
import { service } from "@ember/service";
import BookmarkMenu from "discourse/components/bookmark-menu";
import BookmarkModal from "discourse/components/modal/bookmark";
import TopicBookmarkPostSubmenu from "discourse/components/topic-bookmark-post-submenu";
import DMenu from "discourse/float-kit/components/d-menu";
import { popupAjaxError } from "discourse/lib/ajax-error";
import { BookmarkFormData } from "discourse/lib/bookmark-form-data";
import TopicBookmarkManager from "discourse/lib/topic-bookmark-manager";
import DiscourseURL from "discourse/lib/url";
import {
  NO_REMINDER_ICON,
  NOT_BOOKMARKED,
  WITH_REMINDER_ICON,
} from "discourse/models/bookmark";
import DButton from "discourse/ui-kit/d-button";
import DDropdownMenu from "discourse/ui-kit/d-dropdown-menu";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import { i18n } from "discourse-i18n";

export default class TopicBookmarksMenu extends Component {
  @service modal;
  @service menu;
  @service dialog;
  @service bookmarkApi;
  @service toasts;
  @service currentUser;

  get topic() {
    return this.args.topic;
  }

  get allBookmarks() {
    return this.topic.bookmarks || [];
  }

  get postBookmarks() {
    return this.allBookmarks
      .filter((b) => b.bookmarkable_type === "Post")
      .sort((a, b) => (a.post_number || 0) - (b.post_number || 0));
  }

  get topicBookmark() {
    return this.allBookmarks.find((b) => b.bookmarkable_type === "Topic");
  }

  get hasPostBookmarks() {
    return this.postBookmarks.length > 0;
  }

  get useGroupedDropdown() {
    return this.hasPostBookmarks;
  }

  get isMultipleBookmarks() {
    return this.allBookmarks.length > 1;
  }

  get topicBookmarkManager() {
    return new TopicBookmarkManager(getOwner(this), this.topic);
  }

  get buttonLabel() {
    if (!this.args.showLabel) {
      return;
    }

    if (this.allBookmarks.length >= 1) {
      return i18n("bookmarked.edit_bookmark", {
        count: this.allBookmarks.length,
      });
    } else {
      return i18n("bookmarked.title");
    }
  }

  get buttonIcon() {
    if (this.topicBookmark?.reminder_at) {
      return WITH_REMINDER_ICON;
    } else if (this.topicBookmark) {
      return NO_REMINDER_ICON;
    } else if (this.hasPostBookmarks) {
      return NO_REMINDER_ICON;
    } else {
      return NOT_BOOKMARKED;
    }
  }

  get buttonTitle() {
    if (this.allBookmarks.length === 0) {
      return i18n("bookmarks.not_bookmarked");
    }

    if (this.allBookmarks.length === 1) {
      const bm = this.allBookmarks[0];
      if (bm.reminder_at) {
        return i18n("bookmarks.created_with_reminder_generic", {
          date: new BookmarkFormData(bm).formattedReminder(this.#timezone),
          name: bm.name || "",
        });
      }
      return i18n("bookmarks.created_generic", { name: bm.name || "" });
    }

    return i18n("bookmarked.edit_bookmark", {
      count: this.allBookmarks.length,
    });
  }

  get buttonClasses() {
    const classes = ["bookmark", "widget-button", "bookmark-menu__trigger"];

    if (!this.args.showLabel) {
      classes.push("btn-icon", "no-text");
    } else {
      classes.push("btn-icon-text");
    }

    if (this.args.buttonClasses) {
      classes.push(this.args.buttonClasses);
    }

    if (this.allBookmarks.length > 0) {
      classes.push("bookmarked");
      if (this.allBookmarks.some((b) => b.reminder_at)) {
        classes.push("with-reminder");
      }
      if (!this.topicBookmark) {
        classes.push("--post-bookmarked-only");
      }
    }

    return classes.join(" ");
  }

  get #timezone() {
    return this.currentUser?.user_option?.timezone || moment.tz.guess();
  }

  @action
  onRegisterApi(api) {
    this.dMenu = api;
  }

  @action
  openPostBookmarkSubmenu(bookmark, event) {
    this.menu.show(event.target.closest(".bookmark-menu__row-btn"), {
      identifier: "topic-bookmark-post-submenu",
      component: TopicBookmarkPostSubmenu,
      modalForMobile: true,
      placement: "right-start",
      offset: { mainAxis: 10, crossAxis: -5 },
      data: {
        bookmark,
        onJumpToPost: this.onJumpToPost,
        onEditPostBookmark: this.onEditPostBookmark,
        onRemoveBookmark: this.onRemoveBookmark,
      },
      onClose: () => this.dMenu.close(),
    });
  }

  @action
  async onJumpToPost(bookmark) {
    await this.dMenu.close();
    DiscourseURL.routeTo(this.topic.urlForPostNumber(bookmark.post_number));
  }

  @action
  async onBookmarkTopic() {
    await this.dMenu.close();

    try {
      await this.topicBookmarkManager.create();
      this.toasts.success({
        duration: "short",
        data: { message: i18n("bookmarks.bookmarked_success") },
      });
    } catch (error) {
      popupAjaxError(error);
    }
  }

  @action
  async onEditTopicBookmark() {
    await this.dMenu.close();

    const bookmark = this.topicBookmark;
    const formData = new BookmarkFormData(bookmark);
    try {
      await this.modal.show(BookmarkModal, {
        model: {
          bookmark: formData,
          afterSave: (savedData) => {
            this.#syncBookmark(savedData.saveData);
            this.topic.set("bookmarked", true);
            this.topic.incrementProperty("bookmarksWereChanged");
            this.topic.appEvents?.trigger(
              "bookmarks:changed",
              savedData.saveData,
              { target: "topic", targetId: bookmark.bookmarkable_id }
            );
          },
          afterDelete: (response, bookmarkId) => {
            this.topic.removeBookmark(bookmarkId);
          },
        },
      });
    } catch (error) {
      popupAjaxError(error);
    }
  }

  @action
  async onEditPostBookmark(bookmark) {
    await this.dMenu.close();

    const formData = new BookmarkFormData(bookmark);
    try {
      await this.modal.show(BookmarkModal, {
        model: {
          bookmark: formData,
          afterSave: (savedData) => {
            this.#syncBookmark(savedData.saveData);
            this.topic.set("bookmarked", true);
            this.topic.incrementProperty("bookmarksWereChanged");

            const post = this.topic.postStream?.findLoadedPost(
              bookmark.bookmarkable_id
            );
            if (post) {
              post.createBookmark(savedData.saveData);
            }
          },
          afterDelete: (response, bookmarkId) => {
            this.#removeBookmark(bookmark, bookmarkId, response);
          },
        },
      });
    } catch (error) {
      popupAjaxError(error);
    }
  }

  @action
  async onRemoveBookmark(bookmark) {
    try {
      const response = await this.bookmarkApi.delete(bookmark.id);
      this.#removeBookmark(bookmark, bookmark.id, response);
      this.toasts.success({
        duration: "short",
        data: {
          icon: "trash-can",
          message: i18n("bookmarks.deleted_bookmark_success"),
        },
      });
    } catch (error) {
      popupAjaxError(error);
    } finally {
      await this.dMenu.close();
    }
  }

  @action
  async onRemoveTopicBookmark() {
    try {
      const bookmark = this.topicBookmark;
      const response = await this.bookmarkApi.delete(bookmark.id);
      this.topic.removeBookmark(bookmark.id);
      if (response) {
        this.topic.appEvents?.trigger("bookmarks:changed", null, {
          target: "topic",
          targetId: bookmark.bookmarkable_id,
        });
      }
      this.toasts.success({
        duration: "short",
        data: {
          icon: "trash-can",
          message: i18n("bookmarks.deleted_bookmark_success"),
        },
      });
    } catch (error) {
      popupAjaxError(error);
    } finally {
      await this.dMenu.close();
    }
  }

  @action
  async onClearAllBookmarks() {
    await this.dMenu.close();

    this.dialog.yesNoConfirm({
      message: i18n("bookmarks.confirm_clear"),
      didConfirm: () => {
        return this.topic
          .deleteBookmarks()
          .then(() => this.topic.clearBookmarks())
          .catch(popupAjaxError);
      },
    });
  }

  #syncBookmark(data) {
    const existing = this.topic.bookmarks.find((b) => b.id === data.id);
    if (existing) {
      existing.setProperties({
        reminder_at: data.reminder_at,
        name: data.name,
        auto_delete_preference: data.auto_delete_preference,
      });
    }
    this.topic.incrementProperty("bookmarksWereChanged");
  }

  #removeBookmark(bookmark, bookmarkId, response) {
    if (bookmark.bookmarkable_type === "Post") {
      const post = this.topic.postStream?.findLoadedPost(
        bookmark.bookmarkable_id
      );
      if (post) {
        post.deleteBookmark(response?.topic_bookmarked);
      }
    }
    this.topic.removeBookmark(bookmarkId);
  }

  <template>
    {{#if this.useGroupedDropdown}}
      <DMenu
        ...attributes
        class={{this.buttonClasses}}
        @arrow={{false}}
        @icon={{this.buttonIcon}}
        @identifier="topic-bookmarks-menu"
        @label={{this.buttonLabel}}
        @modalForMobile={{true}}
        @onRegisterApi={{this.onRegisterApi}}
        @title={{this.buttonTitle}}
      >
        <:content>
          <DDropdownMenu as |dropdown|>
            {{! Post bookmark submenu triggers }}
            {{#each this.postBookmarks as |bookmark|}}
              <dropdown.item
                class={{dConcatClass
                  "bookmark-menu__row --post-bookmark"
                  (if bookmark.name "--has-name")
                }}
                data-menu-option-id="post-{{bookmark.post_number}}"
              >
                <DButton
                  class="bookmark-menu__row-btn"
                  @action={{this.openPostBookmarkSubmenu}}
                  @actionParam={{bookmark}}
                  @forwardEvent={{true}}
                  @icon="bookmark"
                  @suffixIcon="angle-right"
                  @translatedAriaLabel={{i18n
                    "bookmarks.post_bookmark"
                    post_number=bookmark.post_number
                  }}
                >
                  <span class="bookmark-menu__row-texts">
                    <span class="bookmark-menu__row-label">
                      {{i18n
                        "bookmarks.post_bookmark"
                        post_number=bookmark.post_number
                      }}
                    </span>
                    {{#if bookmark.name}}
                      <span class="bookmark-menu__row-description">
                        {{bookmark.name}}
                      </span>
                    {{/if}}
                  </span>
                </DButton>
              </dropdown.item>
            {{/each}}

            {{! Topic bookmark actions }}
            {{#if this.topicBookmark}}
              <dropdown.divider />
              <dropdown.item
                class={{dConcatClass
                  "bookmark-menu__row --edit"
                  (if this.topicBookmark.name "--has-name")
                }}
                data-menu-option-id="edit-topic-bookmark"
              >
                <DButton
                  class="bookmark-menu__row-btn"
                  @action={{this.onEditTopicBookmark}}
                  @icon="pencil"
                >
                  <span class="bookmark-menu__row-texts">
                    <span class="bookmark-menu__row-label">
                      {{i18n "bookmarks.edit_topic_bookmark"}}
                    </span>
                    {{#if this.topicBookmark.name}}
                      <span class="bookmark-menu__row-description">
                        {{this.topicBookmark.name}}
                      </span>
                    {{/if}}
                  </span>
                </DButton>
              </dropdown.item>
              <dropdown.item
                class="bookmark-menu__row --remove"
                data-menu-option-id="delete-topic-bookmark"
              >
                <DButton
                  class="bookmark-menu__row-btn --danger"
                  @action={{this.onRemoveTopicBookmark}}
                  @icon="trash-can"
                  @label="bookmarks.delete_topic_bookmark"
                />
              </dropdown.item>
            {{else}}
              <dropdown.divider />
              <dropdown.item
                class="bookmark-menu__row --bookmark-topic"
                data-menu-option-id="bookmark-topic"
              >
                <DButton
                  class="bookmark-menu__row-btn"
                  @action={{this.onBookmarkTopic}}
                  @icon="bookmark"
                  @label="bookmarks.bookmark_topic"
                />
              </dropdown.item>
            {{/if}}

            {{! Delete all bookmarks }}
            {{#if this.isMultipleBookmarks}}
              <dropdown.divider />
              <dropdown.item
                class="bookmark-menu__row --remove"
                data-menu-option-id="clear-all"
              >
                <DButton
                  class="bookmark-menu__row-btn --danger"
                  @action={{this.onClearAllBookmarks}}
                  @icon="trash-can"
                  @label="bookmarked.delete_bookmarks"
                />
              </dropdown.item>
            {{/if}}
          </DDropdownMenu>
        </:content>
      </DMenu>
    {{else}}
      <BookmarkMenu
        ...attributes
        @bookmarkManager={{this.topicBookmarkManager}}
        @buttonClasses={{@buttonClasses}}
        @showLabel={{@showLabel}}
      />
    {{/if}}
  </template>
}
/* eslint-disable ember/no-classic-components */
import Component from "@ember/component";
import { concat, hash } from "@ember/helper";
import { computed, set } from "@ember/object";
import { compare } from "@ember/utils";
import { tagName } from "@ember-decorators/component";
import PinnedButton from "discourse/components/pinned-button";
import PluginOutlet from "discourse/components/plugin-outlet";
import TopicAdminMenu from "discourse/components/topic-admin-menu";
import TopicBookmarksMenu from "discourse/components/topic-bookmarks-menu";
import UserTip from "discourse/components/user-tip";
import DMenu from "discourse/float-kit/components/d-menu";
import lazyHash from "discourse/helpers/lazy-hash";
import { NotificationLevels } from "discourse/lib/notification-levels";
import { getTopicFooterButtons } from "discourse/lib/register-topic-footer-button";
import { getTopicFooterDropdowns } from "discourse/lib/register-topic-footer-dropdown";
import DropdownSelectBox from "discourse/select-kit/components/dropdown-select-box";
import TopicNotificationsButton from "discourse/select-kit/components/topic-notifications-button";
import DButton from "discourse/ui-kit/d-button";
import DDropdownMenu from "discourse/ui-kit/d-dropdown-menu";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

function bind(fn, context) {
  return fn.bind(context);
}

@tagName("")
export default class TopicFooterButtons extends Component {
  @computed("currentUser.can_send_private_messages")
  get canSendPms() {
    return this.currentUser?.can_send_private_messages;
  }

  set canSendPms(value) {
    set(this, "currentUser.can_send_private_messages", value);
  }

  @computed("topic.details.can_invite_to")
  get canInviteTo() {
    return this.topic?.details?.can_invite_to;
  }

  set canInviteTo(value) {
    set(this, "topic.details.can_invite_to", value);
  }

  @computed("topic.archived", "topic.closed", "topic.deleted")
  get inviteDisabled() {
    return this.topic?.archived || this.topic?.closed || this.topic?.deleted;
  }

  get inlineButtons() {
    return getTopicFooterButtons(this);
  }

  get inlineDropdowns() {
    return getTopicFooterDropdowns(this);
  }

  @computed("canSendPms", "topic.isPrivateMessage")
  get canArchive() {
    return this.canSendPms && this.topic?.isPrivateMessage;
  }

  get inlineActionables() {
    return (
      this.inlineButtons
        .filter(
          (button) =>
            button.dropdown === false && button.anonymousOnly === false
        )
        .concat(this.inlineDropdowns)
        .sort((a, b) => compare(a?.priority, b?.priority))
        // Reversing the array is necessary because when priorities are not set,
        // we want to show the most recently added item first
        .reverse()
    );
  }

  get dropdownButtons() {
    return this.inlineButtons.filter((button) => button.dropdown);
  }

  get loneDropdownButton() {
    return this.dropdownButtons.length === 1 ? this.dropdownButtons[0] : null;
  }

  @computed("topic.isPrivateMessage")
  get showNotificationsButton() {
    return !this.topic?.isPrivateMessage || this.canSendPms;
  }

  @computed("topic.details.notification_level")
  get showNotificationUserTip() {
    return (
      this.topic?.details?.notification_level >= NotificationLevels.TRACKING
    );
  }

  @computed("topic.message_archived")
  get archiveIcon() {
    return this.topic?.message_archived ? "envelope" : "folder";
  }

  @computed("topic.message_archived")
  get archiveTitle() {
    return this.topic?.message_archived
      ? "topic.move_to_inbox.help"
      : "topic.archive_message.help";
  }

  @computed("topic.message_archived")
  get archiveLabel() {
    return this.topic?.message_archived
      ? "topic.move_to_inbox.title"
      : "topic.archive_message.title";
  }

  @computed("topic.isPrivateMessage")
  get showBookmarkLabel() {
    return !this.topic?.isPrivateMessage;
  }

  @computed("showCreate", "topic.details.can_create_post")
  get showCreateButton() {
    return this.showCreate !== false && this.topic?.details?.can_create_post;
  }

  <template>
    <div
      aria-label={{i18n "topic.footer_buttons.region_label"}}
      id="topic-footer-buttons"
      role="region"
      ...attributes
    >
      <div class="topic-footer-main-buttons">
        <div class="topic-footer-main-buttons__actions">
          <TopicAdminMenu
            @buttonClasses="topic-footer-button"
            @convertToPrivateMessage={{this.convertToPrivateMessage}}
            @convertToPublicTopic={{this.convertToPublicTopic}}
            @deleteTopic={{this.deleteTopic}}
            @recoverTopic={{this.recoverTopic}}
            @resetBumpDate={{this.resetBumpDate}}
            @showChangeTimestamp={{this.showChangeTimestamp}}
            @showFeatureTopic={{this.showFeatureTopic}}
            @showTopicSlowModeUpdate={{this.showTopicSlowModeUpdate}}
            @showTopicTimerModal={{this.showTopicTimerModal}}
            @toggleArchived={{this.toggleArchived}}
            @toggleClosed={{this.toggleClosed}}
            @toggleFeaturedOnProfile={{this.toggleFeaturedOnProfile}}
            @toggleMultiSelect={{this.toggleMultiSelect}}
            @toggleVisibility={{this.toggleVisibility}}
            @topic={{this.topic}}
          />

          {{#each this.inlineActionables key="id" as |actionable|}}
            {{#if (eq actionable.type "inline-button")}}
              {{#if (eq actionable.id "bookmark")}}
                <TopicBookmarksMenu
                  @buttonClasses="btn-default topic-footer-button"
                  @showLabel={{this.showBookmarkLabel}}
                  @topic={{this.topic}}
                />
              {{else}}
                <DButton
                  class={{dConcatClass
                    "btn-default"
                    "topic-footer-button"
                    actionable.classNames
                  }}
                  id={{concat "topic-footer-button-" actionable.id}}
                  @action={{actionable.action}}
                  @disabled={{actionable.disabled}}
                  @icon={{actionable.icon}}
                  @translatedAriaLabel={{actionable.ariaLabel}}
                  @translatedLabel={{actionable.label}}
                  @translatedTitle={{actionable.title}}
                />
              {{/if}}
            {{else}}
              <DropdownSelectBox
                class={{dConcatClass
                  "topic-footer-dropdown"
                  actionable.classNames
                }}
                @content={{actionable.content}}
                @id={{concat "topic-footer-dropdown-" actionable.id}}
                @onChange={{bind actionable.action this}}
                @options={{hash
                  icon=actionable.icon
                  none=actionable.noneItem
                  disabled=actionable.disabled
                }}
                @value={{actionable.value}}
              />
            {{/if}}
          {{/each}}

          {{#if this.site.mobileView}}
            {{#if this.loneDropdownButton}}
              <DButton
                class={{dConcatClass
                  "btn-default"
                  "topic-footer-button"
                  this.loneDropdownButton.classNames
                }}
                id={{concat "topic-footer-button-" this.loneDropdownButton.id}}
                @action={{this.loneDropdownButton.action}}
                @disabled={{this.loneDropdownButton.disabled}}
                @icon={{this.loneDropdownButton.icon}}
                @translatedAriaLabel={{this.loneDropdownButton.ariaLabel}}
                @translatedLabel={{this.loneDropdownButton.label}}
                @translatedTitle={{this.loneDropdownButton.title}}
              />
            {{else if (gt this.dropdownButtons.length 1)}}
              <DMenu
                class="topic-footer-button btn-default"
                @identifier="topic-footer-mobile-dropdown"
                @modalForMobile={{true}}
              >
                <:trigger>
                  {{dIcon "ellipsis-vertical"}}
                </:trigger>
                <:content>
                  <DDropdownMenu as |dropdown|>
                    {{#each this.dropdownButtons key="id" as |button|}}
                      <dropdown.item>
                        <DButton
                          class={{dConcatClass
                            "topic-footer-button"
                            button.classNames
                          }}
                          id={{concat "topic-footer-button-" button.id}}
                          @action={{button.action}}
                          @disabled={{button.disabled}}
                          @icon={{button.icon}}
                          @translatedAriaLabel={{button.ariaLabel}}
                          @translatedLabel={{button.label}}
                          @translatedTitle={{button.title}}
                        />
                      </dropdown.item>
                    {{/each}}
                  </DDropdownMenu>
                </:content>
              </DMenu>
            {{/if}}

            <PinnedButton
              @appendReason={{false}}
              @pinned={{this.topic.pinned}}
              @topic={{this.topic}}
            />

            {{#if this.showNotificationsButton}}
              <TopicNotificationsButton
                @appendReason={{false}}
                @topic={{this.topic}}
              />
            {{/if}}
          {{/if}}
        </div>

        <PluginOutlet
          @connectorTagName="span"
          @name="topic-footer-main-buttons-before-create"
          @outletArgs={{lazyHash topic=this.topic}}
        />

        {{#if this.showCreateButton}}
          <DButton
