import PermissionType from "discourse/models/permission-type";
import GroupChooser from "discourse/select-kit/components/group-chooser";
import TagChooser from "discourse/select-kit/components/tag-chooser";
import DButton from "discourse/ui-kit/d-button";
import DRadioButton from "discourse/ui-kit/d-radio-button";
import DTextField from "discourse/ui-kit/d-text-field";
import { i18n } from "discourse-i18n";

@tagName("")
export default class TagGroupsForm extends Component {
  @service dialog;
  @service site;

  // All but the "everyone" group
  allGroups = this.site.groups.filter(
    ({ id }) => id !== AUTO_GROUPS.everyone.id
  );

  @computed("model")
  get buffered() {
    return BufferedProxy.create({
      content: this.model,
    });
  }

  @computed("buffered.permissions")
  get selectedGroupIds() {
    const permissions = this.get("buffered.permissions"); // TODO (devxp) we need a buffered proxy that works with tracked properties
    if (!permissions) {
      return [];
    }

    let groupIds = [];

    for (const [groupId, permission] of Object.entries(permissions)) {
      // JS object keys are always strings, so we need to convert them to integers
      const id = parseInt(groupId, 10);

      if (
        id !== AUTO_GROUPS.everyone.id &&
        permission === PermissionType.FULL
      ) {
        groupIds.push(id);
      }
    }

    return groupIds;
  }

  @action
  setPermissionsGroups(groupIds) {
    let permissions = {};
    groupIds.forEach((id) => (permissions[id] = PermissionType.FULL));
    this.buffered.set("permissions", permissions);
  }

  @action
  save() {
    const attrs = this.buffered.getProperties(
      "name",
      "tags",
      "parent_tag",
      "one_per_topic",
      "permissions"
    );

    if (attrs.tags) {
      attrs.tags = attrs.tags.map(this.#serializeTag);
    }

    if (attrs.parent_tag) {
      attrs.parent_tag = attrs.parent_tag.map(this.#serializeTag);
    }

    if (isEmpty(attrs.name)) {
      this.dialog.alert(i18n("tagging.groups.cannot_save.empty_name"));
      return false;
    }

    if (isEmpty(attrs.tags)) {
      this.dialog.alert(i18n("tagging.groups.cannot_save.no_tags"));
      return false;
    }

    attrs.permissions = { ...(attrs.permissions ?? {}) };

    const permissionName = this.buffered.get("permissionName");

    if (permissionName === "public") {
      attrs.permissions = { 0: PermissionType.FULL };
    } else if (permissionName === "visible") {
      attrs.permissions[0] = PermissionType.READONLY;
    } else if (permissionName === "private") {
      delete attrs.permissions[0];

      const hasGroups = Object.keys(attrs.permissions).some(
        (k) => parseInt(k, 10) !== AUTO_GROUPS.everyone.id
      );
      if (!hasGroups) {
        this.dialog.alert(i18n("tagging.groups.cannot_save.no_groups"));
        return false;
      }
    }

    this.model
      .save(attrs)
      .then(() => this.onSave?.())
      .catch(popupAjaxError);
  }

  @action
  destroyTagGroup() {
    return this.dialog.yesNoConfirm({
      message: i18n("tagging.groups.confirm_delete"),
      didConfirm: () =>
        this.model.destroyRecord().then(() => this.onDestroy?.()),
    });
  }

  #serializeTag(t) {
    return typeof t.id === "number"
      ? { id: t.id, name: t.name }
      : { name: t.name };
  }

  <template>
    <section class="group-name">
      <label>{{i18n "tagging.groups.name_placeholder"}}</label>
      <div>
        <DTextField @value={{this.buffered.name}} /></div>
    </section>

    <section class="group-tags-list">
      <label>{{i18n "tagging.groups.tags_label"}}</label><br />
      <TagChooser
        @everyTag={{true}}
        @excludeSynonyms={{true}}
        @options={{hash
          allowAny=true
          filterPlaceholder="tagging.groups.tags_placeholder"
        }}
        @tags={{this.buffered.tags}}
        @unlimitedTagCount={{true}}
      />
    </section>

    <section class="parent-tag-section">
      <label>{{i18n "tagging.groups.parent_tag_label"}}</label>
      <div>
        <TagChooser
          @everyTag={{true}}
          @excludeSynonyms={{true}}
          @options={{hash
            allowAny=true
            filterPlaceholder="tagging.groups.parent_tag_placeholder"
            maximum=1
          }}
          @tags={{this.buffered.parent_tag}}
        />
      </div>
      <div class="description">{{i18n
          "tagging.groups.parent_tag_description"
        }}</div>
    </section>

    <section class="group-one-per-topic">
      <label>
        <Input
          name="onepertopic"
          @checked={{this.buffered.one_per_topic}}
          @type="checkbox"
        />
        {{i18n "tagging.groups.one_per_topic_label"}}
      </label>
    </section>

    <section class="group-visibility">
      <div class="group-visibility-option">
        <DRadioButton
          class="tag-permissions-choice"
          @id="public-permission"
          @name="tag-permissions-choice"
          @selection={{this.buffered.permissionName}}
          @value="public"
        />

        <label class="radio" for="public-permission">
          {{i18n "tagging.groups.everyone_can_use"}}
        </label>
      </div>
      <div class="group-visibility-option">
        <DRadioButton
          class="tag-permissions-choice"
          @id="visible-permission"
          @name="tag-permissions-choice"
          @selection={{this.buffered.permissionName}}
          @value="visible"
        />

        <label class="radio" for="visible-permission">
          {{i18n "tagging.groups.usable_only_by_groups"}}
        </label>

        <div class="group-access-control">
          <GroupChooser
            @content={{this.allGroups}}
            @labelProperty="name"
            @onChange={{this.setPermissionsGroups}}
            @options={{hash
              filterPlaceholder="tagging.groups.select_groups_placeholder"
            }}
            @value={{this.selectedGroupIds}}
          />
        </div>
      </div>
      <div class="group-visibility-option">
        <DRadioButton
          class="tag-permissions-choice"
          @id="private-permission"
          @name="tag-permissions-choice"
          @selection={{this.buffered.permissionName}}
          @value="private"
        />

        <label class="radio" for="private-permission">
          {{i18n "tagging.groups.visible_only_to_groups"}}
        </label>

        <div class="group-access-control">
          <GroupChooser
            @content={{this.allGroups}}
            @labelProperty="name"
            @onChange={{this.setPermissionsGroups}}
            @options={{hash
              filterPlaceholder="tagging.groups.select_groups_placeholder"
            }}
            @value={{this.selectedGroupIds}}
          />
        </div>
      </div>
    </section>

    <div class="tag-group-controls">
      <DButton
        class="btn-primary"
        @action={{this.save}}
        @disabled={{this.buffered.isSaving}}
        @label="tagging.groups.save"
      />

      <DButton
        class="btn-danger"
        @action={{this.destroyTagGroup}}
        @disabled={{this.buffered.isNew}}
        @icon="trash-can"
        @label="tagging.groups.delete"
      />
    </div>
  </template>
}
import { trustHTML } from "@ember/template";
import { isEmpty } from "@ember/utils";
import PluginOutlet from "discourse/components/plugin-outlet";
import lazyHash from "discourse/helpers/lazy-hash";
import renderTags from "discourse/lib/render-tags";
import dBasePath from "discourse/ui-kit/helpers/d-base-path";
import { categoryBadgeHTML } from "discourse/ui-kit/helpers/d-category-link";
import dDiscourseTag from "discourse/ui-kit/helpers/d-discourse-tag";
import { i18n } from "discourse-i18n";

function tagGroupsInfo(tagInfo) {
  return i18n("tagging.tag_groups_info", {
    count: tagInfo?.tag_group_names?.length,
    tag_groups: tagInfo?.tag_group_names?.join(", "),
  });
}

function categoriesInfo(tagInfo) {
  const categories = tagInfo?.categories || [];
  return i18n("tagging.category_restrictions", {
    count: categories.length,
    categories: categories.map((c) => categoryBadgeHTML(c)).join(" "),
  });
}

function synonymsDescription(tagInfo) {
  const synonyms = tagInfo?.synonyms || [];
  return i18n("tagging.synonyms_description", {
    count: synonyms.length,
    base_tag_name: renderTags(null, { tags: [tagInfo] }),
    synonyms: renderTags(null, { tags: synonyms }),
  });
}

function nothingToShow(tagInfo) {
  return (
    isEmpty(tagInfo?.tag_group_names) &&
    isEmpty(tagInfo?.categories) &&
    isEmpty(tagInfo?.synonyms) &&
    !tagInfo?.category_restricted
  );
}

const TagInfo = <template>
  {{#if @tagInfo}}
    <section class="tag-info discovery-heading {{if @loading '--loading'}}">
      <div class="tag-name">
        <div class="tag-name-wrapper">
          {{dDiscourseTag @tagInfo}}
        </div>
        {{#if @tagInfo.description_cooked}}
          <div class="tag-description-wrapper">
            <div class="cooked">{{trustHTML @tagInfo.description_cooked}}</div>
          </div>
        {{/if}}
      </div>

      <p class="tag-associations">
        {{#if @tagInfo.tag_group_names}}
          <span>{{tagGroupsInfo @tagInfo}}</span>
        {{/if}}
        {{#if @tagInfo.categories}}
          <span>{{trustHTML (categoriesInfo @tagInfo)}}</span>
        {{else if @tagInfo.category_restricted}}
          <span>{{i18n "tagging.category_restricted"}}</span>
        {{/if}}
        {{#if (nothingToShow @tagInfo)}}
          {{trustHTML (i18n "tagging.default_info")}}
          {{#if @currentUser.staff}}
            {{trustHTML (i18n "tagging.staff_info" basePath=(dBasePath))}}
          {{/if}}
        {{/if}}
      </p>

      {{#if @tagInfo.synonyms}}
        <div class="synonyms-list">{{trustHTML
            (synonymsDescription @tagInfo)
          }}</div>
      {{/if}}

      {{#if @currentUser.canEditTags}}
        <PluginOutlet
          @connectorTagName="section"
          @name="tag-custom-settings"
          @outletArgs={{lazyHash tag=@tagInfo}}
        />
      {{/if}}
    </section>
  {{/if}}
</template>;

export default TagInfo;
import Component from "@glimmer/component";
import CategoryTitleLink from "discourse/components/category-title-link";
import { arraySortedByProperties } from "discourse/lib/array-tools";
import { slugify } from "discourse/lib/utilities";
import Category from "discourse/models/category";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import dDiscourseTag from "discourse/ui-kit/helpers/d-discourse-tag";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

export default class TagList extends Component {
  get isPrivateMessage() {
    return this.args.isPrivateMessage ?? false;
  }

  get sortedTags() {
    return arraySortedByProperties(this.args.tags, this.args.sortProperties);
  }

  get title() {
    return this.args.titleKey && i18n(this.args.titleKey);
  }

  get category() {
    return this.args.categoryId && Category.findById(this.args.categoryId);
  }

  get categoryClass() {
    return this.category?.fullSlug && `tag-list-${this.category?.fullSlug}`;
  }

  get tagGroupNameSlug() {
    if (this.args.tagGroupName) {
      return slugify(this.args.tagGroupName);
    }
  }

  get tagGroupNameClass() {
    return this.tagGroupNameSlug && `tag-group-${this.tagGroupNameSlug}`;
  }

  <template>
    <div
      class={{dConcatClass
        "tags-list"
        "tag-list"
        this.categoryClass
        this.tagGroupNameClass
      }}
      ...attributes
    >
      {{#if this.title}}
        <h3>{{this.title}}</h3>
      {{/if}}
      {{#if this.category}}
        <CategoryTitleLink @category={{this.category}} />
      {{/if}}
      {{#if @tagGroupName}}
        <h3 id={{this.tagGroupNameSlug}}><a
            aria-label={{i18n "post.heading_anchor"}}
            class="anchor"
            href="#{{this.tagGroupNameSlug}}"
          ></a>{{@tagGroupName}}</h3>
      {{/if}}
      {{#each this.sortedTags as |tag|}}
        <div class="tag-box">
          {{dDiscourseTag
            tag
            description=tag.description
            isPrivateMessage=this.isPrivateMessage
            pmOnly=tag.pmOnly
            tagsForUser=@tagsForUser
          }}
          {{#if tag.pmOnly}}
            {{dIcon "envelope"}}
          {{/if}}
          {{#if tag.totalCount}}
            <span class="tag-count">
              x
              {{tag.totalCount}}
            </span>
          {{/if}}
        </div>
      {{/each}}
      <div class="clearfix"></div>
    </div>
  </template>
}
import Component from "@glimmer/component";
import DInterpolatedTranslation from "discourse/ui-kit/d-interpolated-translation";

export default class AddSynonymsConfirmation extends Component {
  get synonymNames() {
    return this.args.model.synonymNames;
  }

  get tagName() {
    return this.args.model.tagName;
  }

  <template>
    <p>
      <DInterpolatedTranslation
        @key="tagging.settings.add_synonyms_confirm"
        as |Placeholder|
      >
        <Placeholder @name="synonymNames">
          <b>{{this.synonymNames}}</b>
        </Placeholder>
        <Placeholder @name="tagName">
          <b>{{this.tagName}}</b>
        </Placeholder>
      </DInterpolatedTranslation>
    </p>
  </template>
}
import Component from "@glimmer/component";
import { fn, hash } from "@ember/helper";
import { service } from "@ember/service";
import { uniqueItemsFromArray } from "discourse/lib/array-tools";
import { i18n } from "discourse-i18n";

export default class TagSettingsLocalizations extends Component {
  @service siteSettings;
  @service languageNameLookup;

  get selectableLocales() {
    const supported =
      this.siteSettings.available_content_localization_locales.map(
        (obj) => obj.value
      );
    const committed = (this.args.localizations || []).map((obj) => obj.locale);
    const allLocales = uniqueItemsFromArray(
      [...supported, ...committed, this.args.locale].filter(Boolean)
    );

    return allLocales.map((value) => ({
      name: this.languageNameLookup.getLanguageName(value),
      value,
    }));
  }

  <template>
    <@form.Field
      @description={{i18n "tagging.localization.language_description"}}
      @name="locale"
      @title={{i18n "tagging.localization.language"}}
      @type="select"
      as |field|
    >
      <field.Control as |select|>
        {{#each this.selectableLocales as |locale|}}
          <select.Option @value={{locale.value}}>{{locale.name}}</select.Option>
        {{/each}}
      </field.Control>
    </@form.Field>

    <@form.Section @title={{i18n "tagging.settings.localizations"}}>
      {{#if (eq @localizations.length 0)}}
        <@form.Alert @icon="circle-info">
          {{i18n "tagging.localization.hint"}}
        </@form.Alert>
      {{/if}}

      {{#if @localizations.length}}
        <@form.Collection @name="localizations" as |collection index|>
          <collection.Field
            @disabled={{true}}
            @name="tag_id"
            @showTitle={{false}}
            @title="tag_id"
            @type="input-hidden"
            as |field|
          >
            <field.Control @value={{@tagId}} />
          </collection.Field>

          <@form.Row as |row|>
            <row.Col @size={{2}}>
              <collection.Field
                @name="locale"
                @title={{i18n "tagging.localization.locale"}}
                @type="select"
                @validation="required"
                as |field|
              >
                <field.Control as |select|>
                  {{#each this.selectableLocales as |locale|}}
                    <select.Option
                      @value={{locale.value}}
                    >{{locale.name}}</select.Option>
                  {{/each}}
                </field.Control>
              </collection.Field>
            </row.Col>

            <row.Col @size={{3}}>
              <collection.Field
                @name="name"
                @title={{i18n "tagging.localization.name"}}
                @type="input"
                @validation="required|length:1,50"
                as |field|
              >
                <field.Control
                  placeholder={{i18n "tagging.settings.name_placeholder"}}
                  @maxlength="50"
                />
              </collection.Field>
            </row.Col>

            <row.Col @size={{6}}>
              <collection.Field
                @name="description"
                @title={{i18n "tagging.localization.description"}}
                @type="composer"
                @validation="length:0,1000"
                as |field|
              >
                <field.Control @height={{120}} />
              </collection.Field>
            </row.Col>

            <row.Col @size={{1}}>
              <@form.Button
                class="btn-danger"
                @action={{fn collection.remove index}}
                @icon="trash-can"
                @title="tagging.localization.remove"
              />
            </row.Col>
          </@form.Row>
        </@form.Collection>
      {{/if}}
      <@form.Button
        class="btn-default"
        @action={{fn
          @form.addItemToCollection
          "localizations"
          (hash tag_id=@tagId locale="" name="" description="")
        }}
        @icon="plus"
        @label="tagging.localization.add"
      />
    </@form.Section>
  </template>
}
import { tracked } from "@glimmer/tracking";
import { action, computed } from "@ember/object";
import { classNames } from "@ember-decorators/component";
import DiscourseURL from "discourse/lib/url";
import ComboBoxComponent from "discourse/select-kit/components/combo-box";
import {
  pluginApiIdentifiers,
  selectKitOptions,
} from "discourse/select-kit/components/select-kit";

@classNames("tag-dropdown")
@selectKitOptions({
  caretDownIcon: "caret-down",
  caretUpIcon: "caret-up",
  filterable: true,
})
@pluginApiIdentifiers("tag-dropdown")
export default class TagDropdown extends ComboBoxComponent {
  valueProperty = "name";
  nameProperty = "name";

  @tracked _contentOverride;

  @computed("tags")
  get content() {
    if (this._contentOverride !== undefined) {
      return this._contentOverride;
    }
    return this.tags;
  }

  set content(value) {
    this._contentOverride = value;
  }

  @computed("tags.[]")
  get tagNames() {
    return (this.tags || []).map((t) => t.name);
  }

  @action
  onChange(tagName) {
    const tag = this.tags?.find((t) => t.name === tagName);
    if (tag) {
      DiscourseURL.routeToUrl(`/tag/${tag.name}/${tag.id}/edit/general`);
    }
  }
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { array, concat, hash } from "@ember/helper";
import { action } from "@ember/object";
import { LinkTo } from "@ember/routing";
import { service } from "@ember/service";
import Form from "discourse/components/form";
import AddSynonymsConfirmation from "discourse/components/tag-settings/add-synonyms-confirmation";
import TagSettingsLocalizations from "discourse/components/tag-settings/localizations";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import getURL from "discourse/lib/get-url";
import { slugify } from "discourse/lib/utilities";
import MiniTagChooser from "discourse/select-kit/components/mini-tag-chooser";
import TagDropdown from "discourse/select-kit/components/tag-dropdown";
import DBreadcrumbsItem from "discourse/ui-kit/d-breadcrumbs-item";
import DHorizontalOverflowNav from "discourse/ui-kit/d-horizontal-overflow-nav";
import DPageHeader from "discourse/ui-kit/d-page-header";
import { categoryBadgeHTML } from "discourse/ui-kit/helpers/d-category-link";
import { i18n } from "discourse-i18n";

/**
 * @typedef {{ id: number | string, name: string, isNew?: boolean }} TagSynonymChoice
 * @typedef {{ id?: number, tag_id: number, locale: string, name: string, description: string | null, description_cooked?: string | null }} TagSettingsLocalization
 * @typedef {{ name: string, locale: string | null | undefined, slug: string, description: string, synonyms: TagSynonymChoice[], new_synonyms: TagSynonymChoice[], removed_synonym_ids: number[], localizations: TagSettingsLocalization[] }} TagSettingsFormData
 */
export default class TagSettings extends Component {
  @service router;
  @service dialog;
  @service toasts;
  @service siteSettings;
  @service store;
  @service appEvents;

  /** @type {{ get: (name: string) => unknown, set: (name: string, value: unknown) => Promise<void> } | null} */
  @tracked form = null;
  @tracked tags = [];

  constructor() {
    super(...arguments);
    this.loadTags();
  }

  get tagNames() {
    return this.tags.map((t) => t.name);
  }

  /** @returns {TagSettingsFormData} */
  get formData() {
    return {
      name: this.args.tag.name,
      locale: this.args.tag.locale,
      slug: this.args.tag.slug,
      description: this.args.tag.description || "",
      synonyms: this.args.tag.synonyms || [],
      new_synonyms: [],
      removed_synonym_ids: [],
      localizations: this.args.tag.localizations || [],
    };
  }

  get showLocalizationsTab() {
    return this.siteSettings.content_localization_enabled;
  }

  get hasTagGroups() {
    return this.args.tag.tag_group_names?.length > 0;
  }

  get tagGroupsInfoPrefix() {
    const count = this.args.tag.tag_group_names?.length || 0;
    if (count === 1) {
      return i18n("tagging.tag_groups_info_prefix.one");
    }
    return i18n("tagging.tag_groups_info_prefix.other");
  }

  get tagGroupNames() {
    return this.args.tag.tag_group_names?.join(", ");
  }

  get hasCategories() {
    return this.args.tag.categories?.length > 0;
  }

  get isCategoryRestricted() {
    return this.args.tag.category_restricted;
  }

  // safe to build HTML here - tag names have <> stripped by TAGS_FILTER_REGEXP,
  // descriptions are sanitized in the backend
  get descriptionHtml() {
    const parts = [];

    if (this.hasTagGroups) {
      const prefix =
        this.args.tag.tag_group_names.length === 1
          ? i18n("tagging.tag_groups_info_prefix.one")
          : i18n("tagging.tag_groups_info_prefix.other");
      const groups = (this.args.tag.tag_groups || [])
        .map(
          (tg) => `<a href="${getURL(`/tag_groups/${tg.id}`)}">${tg.name}</a>`
        )
        .join(", ");
      parts.push(`${prefix}${groups}.`);
    }

    if (this.hasCategories) {
      parts.push(
        i18n("tagging.category_restrictions", {
          count: this.args.tag.categories.length,
          categories: this.args.tag.categories
            .map((cat) => categoryBadgeHTML(cat))
            .join(" "),
        })
      );
    } else if (this.isCategoryRestricted) {
      parts.push(i18n("tagging.category_restricted"));
    }

    return parts.join(" ");
  }

  get blockedTags() {
    return [this.args.tag?.name].filter(Boolean);
  }

  async loadTags() {
    try {
      const tags = await this.store.findAll("tag");
      this.tags = tags.content.map((tag) => ({
        id: tag.id,
        name: tag.name,
      }));
    } catch {}
  }

  @action
  async save(data) {
    const newSynonyms = data.new_synonyms || [];

    if (newSynonyms.length > 0) {
      this.dialog.confirm({
        bodyComponent: AddSynonymsConfirmation,
        bodyComponentModel: {
          count: newSynonyms.length,
          tagName: data.name,
          synonymNames: newSynonyms.map((t) => t.name).join(", "),
        },
        didConfirm: () => this.#performSave(data),
      });
    } else {
      await this.#performSave(data);
    }
  }

  @action
  registerForm(form) {
    this.form = form;
  }

  @action
  deleteTag() {
    const tag = this.args.tag;
    const topicCount = tag.topic_count || 0;

    const message = topicCount
      ? i18n("tagging.delete_confirm", { count: topicCount })
      : i18n("tagging.delete_confirm_no_topics");

    this.dialog.deleteConfirm({
      message,
      didConfirm: async () => {
        try {
          await ajax(`/tag/${tag.id}.json`, { type: "DELETE" });
          this.router.transitionTo("tags.index");
        } catch (error) {
          popupAjaxError(error);
        }
      },
    });
  }

  @action
  handleSynonymChange(selectedTags) {
    const originalSynonyms = this.args.tag.synonyms || [];
    const originalIds = originalSynonyms.map((s) => s.id);
    const selectedIds = selectedTags.map((t) => t.id);

    const removed = originalSynonyms.filter((s) => !selectedIds.includes(s.id));
    const removedIds = removed.map((s) => s.id);

    const newSynonyms = selectedTags.filter((t) => !originalIds.includes(t.id));

    this.form?.set("synonyms", selectedTags);
    this.form?.set("removed_synonym_ids", removedIds);
    this.form?.set("new_synonyms", newSynonyms);
  }

  @action
  validateSlug(name, slug, { addError }) {
    if (slug?.trim() && slug !== slugify(slug)) {
      addError(name, {
        title: i18n("tagging.settings.slug"),
        message: i18n("tagging.settings.invalid_slug"),
      });
    }
  }

  async #performSave(data) {
    const tag = this.args.tag;

    try {
      const result = await ajax(`/tag/${tag.id}/settings.json`, {
        type: "PUT",
        contentType: "application/json",
        data: JSON.stringify({ tag_settings: data }),
      });

      if (result.tag_settings) {
        this.args.tag.setProperties(result.tag_settings);

        if (result.tag_settings.slug !== this.args.parentParams.tag_slug) {
          this.router.replaceWith(
            "tag.edit.tab",
            result.tag_settings.slug,
            result.tag_settings.id,
            this.args.selectedTab
          );
        }

        this.appEvents.trigger("tag-info:updated", result.tag_settings.id);
      }

      this.toasts.success({
        duration: "short",
        data: { message: i18n("tagging.settings.saved") },
      });
    } catch (error) {
      popupAjaxError(error);
    }
  }

  <template>
    <div class="tag-settings">
      <DPageHeader
        @descriptionLabel={{this.descriptionHtml}}
        @hideTabs={{true}}
      >
        <:breadcrumbs>
          <DBreadcrumbsItem @label={{i18n "tagging.tags"}} @path="/tags" />
          <DBreadcrumbsItem
            @label={{@tag.name}}
            @path="/tag/{{@tag.slug}}/{{@tag.id}}"
          />
          <DBreadcrumbsItem
            @label={{i18n "edit"}}
            @path="/tag/{{@tag.slug}}/{{@tag.id}}/edit/general"
          />
          {{#if this.showLocalizationsTab}}
            <DBreadcrumbsItem
              @label={{i18n (concat "tagging.settings." @selectedTab)}}
              @path="/tag/{{@tag.slug}}/{{@tag.id}}/edit/{{@selectedTab}}"
            />
          {{/if}}
        </:breadcrumbs>
        <:title>
          <span class="tag-settings-title__label">{{i18n
              "tagging.settings.edit_tag_prefix"
            }}</span>
          <span class="tag-settings-title__dropdown">
            <TagDropdown
              aria-label={{i18n "tagging.settings.select_tag"}}
              @tags={{this.tags}}
              @value={{@tag.name}}
            />
          </span>
        </:title>
        <:actions as |actions|>
          {{#if @tag.can_admin}}
            <actions.Danger
              @action={{this.deleteTag}}
              @icon="trash-can"
              @label="tagging.settings.delete"
            />
          {{/if}}
        </:actions>
      </DPageHeader>

      {{#if this.showLocalizationsTab}}
        <div class="d-nav-submenu">
          <DHorizontalOverflowNav class="d-nav-submenu__tabs">
            <li>
              <LinkTo
                @models={{array
                  @parentParams.tag_slug
                  @parentParams.tag_id
                  "general"
                }}
                @route="tag.edit.tab"
              >
                {{i18n "tagging.settings.general"}}
              </LinkTo>
            </li>
            <li>
              <LinkTo
                @models={{array
                  @parentParams.tag_slug
                  @parentParams.tag_id
                  "localizations"
                }}
                @route="tag.edit.tab"
              >
                {{i18n "tagging.settings.localizations"}}
              </LinkTo>
            </li>
          </DHorizontalOverflowNav>
        </div>
      {{/if}}

      <Form
        class="tag-settings__form"
        @data={{this.formData}}
        @onRegisterApi={{this.registerForm}}
        @onSubmit={{this.save}}
        as |form transientData|
      >
        {{#if (eq @selectedTab "general")}}
          <form.Field
            @format="large"
            @name="name"
            @title={{i18n "tagging.settings.name"}}
            @type="input"
            @validation="required"
            as |field|
          >
            <field.Control
              class="tag-name-input"
              placeholder={{i18n "tagging.settings.name_placeholder"}}
              @maxlength={{this.siteSettings.max_tag_length}}
            />
          </form.Field>

          <form.Field
            @format="large"
            @name="slug"
            @title={{i18n "tagging.settings.slug"}}
            @type="input"
            @validate={{this.validateSlug}}
            as |field|
          >
            <field.Control
              placeholder={{i18n "tagging.settings.slug_placeholder"}}
            />
          </form.Field>

          <form.Field
            @format="large"
            @name="description"
            @title={{i18n "tagging.description"}}
            @type="composer"
            @validation="length:0,1000"
            as |field|
          >
            <field.Control @height={{200}} />
          </form.Field>

          <form.Field
            @description={{i18n
              "tagging.settings.synonyms_subtitle"
              name=@tag.name
            }}
            @format="large"
            @name="synonyms"
            @title={{i18n "tagging.synonyms"}}
            @type="custom"
            as |field|
          >
            <field.Control>
              <MiniTagChooser
                @onChange={{this.handleSynonymChange}}
                @options={{hash
                  everyTag=true
                  allowAny=false
                  blockedTags=this.blockedTags
                  filterPlaceholder="tagging.settings.add_synonym_placeholder"
                  maximum=200
                }}
                @value={{transientData.synonyms}}
              />
            </field.Control>
          </form.Field>
        {{else if (eq @selectedTab "localizations")}}
          <TagSettingsLocalizations
            @form={{form}}
            @locale={{transientData.locale}}
            @localizations={{transientData.localizations}}
            @tagId={{@tag.id}}
          />
        {{/if}}

        <form.Actions>
          <form.Submit id="save-tag" @label="tagging.settings.save" />
        </form.Actions>
      </Form>
    </div>
  </template>
}
