export default UserNotificationScheduleDay;
import Component from "@glimmer/component";
import { cached } from "@glimmer/tracking";
import EmberObject, { action, computed } from "@ember/object";
import PreferenceCheckbox from "discourse/components/preference-checkbox";
import UserNotificationScheduleDay from "discourse/components/user-notification-schedule-day";
import { i18n } from "discourse-i18n";

const DAYS = [
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday",
  "sunday",
];

class Day extends EmberObject {
  /** @type {number | null} */
  id = null;

  /** @type {Array<{ name: string, value: number }> | null} */
  startTimeOptions = null;

  /** @type {import("discourse/models/user").default | null} */
  model = null;

  @computed("model.user_notification_schedule.day_{0,1,2,3,4,5,6}_start_time")
  get startTimeValue() {
    return this.model?.user_notification_schedule[`day_${this.id}_start_time`];
  }

  @computed("model.user_notification_schedule.day_{0,1,2,3,4,5,6}_start_time")
  get endTimeOptions() {
    return this.buildEndTimeOptionsFor(
      this.model?.user_notification_schedule[`day_${this.id}_start_time`]
    );
  }

  @computed("model.user_notification_schedule.day_{0,1,2,3,4,5,6}_end_time")
  get endTimeValue() {
    return this.model?.user_notification_schedule[`day_${this.id}_end_time`];
  }

  @action
  onChangeStartTime(val) {
    this.startingTimeChangedForDay(val);
  }

  @action
  onChangeEndTime(val) {
    this.set(`model.user_notification_schedule.day_${this.id}_end_time`, val);
  }

  startingTimeChangedForDay(val) {
    val = parseInt(val, 10);
    this.model.set(`user_notification_schedule.day_${this.id}_start_time`, val);
    if (
      val !== "-1" &&
      this.model.user_notification_schedule[`day_${this.id}_end_time`] <= val
    ) {
      this.model.set(
        `user_notification_schedule.day_${this.id}_end_time`,
        val + 30
      );
    }
  }

  buildEndTimeOptionsFor(startTime) {
    startTime = parseInt(startTime, 10);
    if (startTime === -1) {
      return null;
    }
    return buildTimeOptions(startTime + 30, {
      includeNone: false,
      showMidnight: true,
    });
  }
}

function buildTimeOptions(
  startAt,
  opts = { includeNone: false, showMidnight: true }
) {
  let timeOptions = [];

  if (opts.includeNone) {
    timeOptions.push({
      name: i18n("user.notification_schedule.none"),
      value: -1,
    });
  }

  for (let timeInMin = startAt; timeInMin <= 1440; timeInMin += 30) {
    let hours = Math.floor(timeInMin / 60);
    let minutes = timeInMin % 60;

    if (minutes === 0) {
      minutes = "00";
    }
    if (hours === 24) {
      if (opts.showMidnight) {
        timeOptions.push({
          name: i18n("user.notification_schedule.midnight"),
          value: 1440,
        });
      }
      break;
    }
    timeOptions.push({
      name: moment().set("hour", hours).set("minute", minutes).format("LT"),
      value: timeInMin,
    });
  }
  return timeOptions;
}

export default class UserNotificationSchedule extends Component {
  @cached
  get days() {
    const startTimeOptions = buildTimeOptions(0, {
      includeNone: true,
      showMidnight: false,
    });

    return DAYS.map((day, index) =>
      Day.create({
        id: index,
        day,
        model: this.args.model,
        startTimeOptions,
      })
    );
  }

  <template>
    <div
      class="control-group notification-schedule"
      data-setting-name="user-notification-schedule"
      ...attributes
    >
      <label class="control-label">{{i18n
          "user.notification_schedule.title"
        }}</label>
      <PreferenceCheckbox
        @checked={{@model.user_notification_schedule.enabled}}
        @labelKey="user.notification_schedule.label"
      />

      {{#if @model.user_notification_schedule.enabled}}
        <div class="instruction">{{i18n "user.notification_schedule.tip"}}</div>

        <table class="notification-schedule-table">
          <tbody class="notification-schedule-tbody">
            {{#each this.days as |day|}}
              <UserNotificationScheduleDay
                @day={{day.day}}
                @endTimeOptions={{day.endTimeOptions}}
                @endTimeValue={{day.endTimeValue}}
                @onChangeEndTime={{day.onChangeEndTime}}
                @onChangeStartTime={{day.onChangeStartTime}}
                @startTimeOptions={{day.startTimeOptions}}
                @startTimeValue={{day.startTimeValue}}
              />
            {{/each}}
          </tbody>
        </table>
      {{/if}}
    </div>
  </template>
}
