export default class RenamePasskey extends Component {
  @service router;
  @service dialog;

  @tracked passkeyName;
  @tracked errorMessage;

  instructions = i18n("user.passkeys.rename_passkey_instructions");

  constructor() {
    super(...arguments);
    this.passkeyName = this.args.model.name;
  }

