              @label="user.mcp_authorizations.revoke"
            />
          {{/if}}
          {{#if this.isReauthorizationRequired}}
            <DButton
              class="btn-default btn-small"
              @action={{@onReauthorize}}
              @label="user.mcp_authorizations.reauthorize"
            />
          {{/if}}
        </div>
      </td>
    </tr>
  </template>
