export default class UserMcpAuthorizations extends Component {
  @service a11y;
  @service currentUser;
  @service dialog;
  @service toasts;

  @tracked authorizations = [];
  @tracked loading = true;

  constructor() {
    super(...arguments);
    if (!this.shouldRender) {
      this.loading = false;
      return;
    }
    this.#loadAuthorizations();
  }

  get shouldRender() {
    return (
      this.args.model?.id === this.currentUser?.id &&
      this.args.model?.show_mcp_authorizations
    );
  }

  get username() {
    return this.args.model?.username;
  }

  get endpoint() {
    return `/u/${encodeURIComponent(this.username)}/preferences/mcp-authorizations`;
  }

  get hasAuthorizations() {
    return this.authorizations.length > 0;
  }

  @action
  revoke(authorization) {
    this.dialog.confirm({
      message: i18n("user.mcp_authorizations.revoke_confirm", {
        name: authorization.client_name,
      }),
      didConfirm: async () => {
        try {
          await ajax(`${this.endpoint}/${authorization.id}.json`, {
            type: "DELETE",
          });
          this.authorizations = this.authorizations.map((item) =>
            item.id === authorization.id
              ? { ...item, status: "revoked", token_count: 0 }
              : item
          );
          this.a11y.announce(i18n("user.mcp_authorizations.revoked"));
          this.toasts.success({
            duration: "short",
            data: { message: i18n("user.mcp_authorizations.revoked") },
          });
        } catch (error) {
          popupAjaxError(error);
        }
      },
    });
  }

  @action
  reauthorize() {
    this.dialog.alert({
      message: i18n("user.mcp_authorizations.reauthorize_in_client"),
    });
  }

  async #loadAuthorizations() {
    if (!this.username) {
      this.loading = false;
      return;
    }

    try {
      const result = await ajax(`${this.endpoint}.json`);
      this.authorizations = result.authorizations || result;
    } catch (error) {
      popupAjaxError(error);
    } finally {
      this.loading = false;
    }
  }

  <template>
    {{#if this.shouldRender}}
      <div class="control-group user-mcp-authorizations">
        <label class="control-label">{{i18n
            "user.mcp_authorizations.title"
          }}</label>
        <p class="instructions">{{i18n
            "user.mcp_authorizations.description"
          }}</p>

        <DConditionalLoadingSpinner @condition={{this.loading}}>
          {{#if this.hasAuthorizations}}
            <table class="d-table user-mcp-authorizations__table">
              <colgroup>
                <col class="user-mcp-authorizations__application-column" />
                <col />
                <col class="user-mcp-authorizations__status-column" />
              </colgroup>
              <thead class="d-table__header">
                <tr class="d-table__row">
                  <th class="d-table__header-cell">{{i18n
                      "user.mcp_authorizations.application"
                    }}</th>
                  <th class="d-table__header-cell">{{i18n
                      "user.mcp_authorizations.details"
                    }}</th>
                  <th class="d-table__header-cell">{{i18n
                      "user.mcp_authorizations.status"
                    }}</th>
                </tr>
              </thead>
              <tbody class="d-table__body">
                {{#each this.authorizations as |authorization|}}
                  <UserMcpAuthorizationRow
                    @authorization={{authorization}}
                    @onReauthorize={{this.reauthorize}}
                    @onRevoke={{fn this.revoke authorization}}
                  />
                {{/each}}
              </tbody>
            </table>
          {{else}}
            <p class="user-mcp-authorizations__empty">{{i18n
                "user.mcp_authorizations.empty"
              }}</p>
          {{/if}}
        </DConditionalLoadingSpinner>
      </div>
    {{/if}}
  </template>
}
import Component from "@glimmer/component";
import { fn } from "@ember/helper";
import { action } from "@ember/object";
import { schedule } from "@ember/runloop";
import { service } from "@ember/service";
import { trustHTML } from "@ember/template";
import ConfirmSession from "discourse/components/dialog-messages/confirm-session";
import PasskeyOptionsDropdown from "discourse/components/user-preferences/passkey-options-dropdown";
import RenamePasskey from "discourse/components/user-preferences/rename-passkey";
import { popupAjaxError } from "discourse/lib/ajax-error";
import {
  bufferToBase64,
  stringToBuffer,
  WebauthnAbortHandler,
} from "discourse/lib/webauthn";
import DButton from "discourse/ui-kit/d-button";
import dFormatDate from "discourse/ui-kit/helpers/d-format-date";
import { i18n } from "discourse-i18n";

export default class UserPasskeys extends Component {
  @service dialog;
  @service currentUser;
  @service capabilities;
  @service router;

  get showActions() {
    return (
      this.currentUser.id === this.args.model.id &&
      !this.capabilities.isAppWebview
    );
  }

  async createPasskey() {
    try {
      const response = await this.args.model.createPasskey();

      const publicKeyCredentialCreationOptions = {
        challenge: Uint8Array.from(response.challenge, (c) => c.charCodeAt(0)),
        rp: {
          name: response.rp_name,
          id: response.rp_id,
        },
        user: {
          id: Uint8Array.from(response.user_secure_id, (c) => c.charCodeAt(0)),
          name: this.currentUser.username,
          displayName: this.currentUser.username,
        },
        pubKeyCredParams: response.supported_algorithms.map((alg) => {
          return { type: "public-key", alg };
        }),
        excludeCredentials: response.existing_passkey_credential_ids.map(
          (credentialId) => {
            return {
              type: "public-key",
              id: stringToBuffer(atob(credentialId)),
            };
          }
        ),
        authenticatorSelection: {
          // https://www.w3.org/TR/webauthn-2/#user-verification
          // for passkeys (first factor), user verification should be marked as required
          // it ensures browser prompts user for PIN/fingerprint/faceID before authenticating
          userVerification: "required",
          // See https://w3c.github.io/webauthn/#sctn-createCredential for context
          // This ensures that the authenticator stores a client-side private key
          // physical security keys (like Yubikey) need this
          requireResidentKey: true,
        },
      };

      const credential = await navigator.credentials.create({
        publicKey: publicKeyCredentialCreationOptions,
        signal: WebauthnAbortHandler.signal(),
      });

      let credentialParam = {
        id: credential.id,
        rawId: bufferToBase64(credential.rawId),
        type: credential.type,
        attestation: bufferToBase64(credential.response.attestationObject),
        clientData: bufferToBase64(credential.response.clientDataJSON),
        name: i18n("user.passkeys.name.default"),
      };

      const registrationResponse =
        await this.args.model.registerPasskey(credentialParam);

      if (registrationResponse.error) {
        this.dialog.alert(registrationResponse.error);
        return;
      }

      this.router.refresh();

      // Prompt to rename key after creating
      this.dialog.dialog({
        title: i18n("user.passkeys.passkey_successfully_created"),
        type: "notice",
        bodyComponent: RenamePasskey,
        bodyComponentModel: registrationResponse,
      });
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error(error);
      this.errorMessage =
        error.name === "InvalidStateError"
          ? i18n("user.passkeys.already_added_error")
          : i18n("user.passkeys.not_allowed_error");
      this.dialog.alert(this.errorMessage);
    }
  }

  confirmDelete(id) {
    schedule("afterRender", () => {
      this.dialog.deleteConfirm({
        title: i18n("user.passkeys.confirm_delete_passkey"),
        didConfirm: () => {
          this.args.model.deletePasskey(id).then((response) => {
            if (response.success) {
              this.router.refresh();
            } else {
              this.dialog.alert(response.message);
            }
          });
        },
      });
    });
  }

  @action
  async addPasskey() {
    try {
      const trustedSession = await this.args.model.trustedSession();

      if (!trustedSession.success) {
        this.dialog.dialog({
          title: i18n("user.confirm_access.title"),
          type: "notice",
          bodyComponent: ConfirmSession,
          didConfirm: () => this.createPasskey(),
        });
      } else {
