import { tracked } from "@glimmer/tracking";
import Controller from "@ember/controller";
import EmberObject, { action } from "@ember/object";
import { uniqueItemsFromArray } from "discourse/lib/array-tools";
import { autoTrackedArray } from "discourse/lib/tracked-tools";
import Badge from "discourse/models/badge";
import UserBadge from "discourse/models/user-badge";
import { i18n } from "discourse-i18n";

export default class ShowController extends Controller {
  @tracked model;

  /** @type {string | null} */
  @tracked username = null;
  @tracked loadingMore = false;
  @tracked noMoreBadges = false;
  @tracked showTitlePicker = false;
  @tracked userBadgesAll;
  @tracked userBadgesGrantCount;

  /** @type {import("discourse/models/user-badge").default[] | null} */
  @autoTrackedArray userBadges = null;

  queryParams = ["username"];

  get selectableUserBadges() {
    return [
      EmberObject.create({
        id: 0,
        badge: Badge.create({ name: i18n("badges.none") }),
      }),
      ...uniqueItemsFromArray(
        this.userBadgesAll.filter((ub) => ub.badge.allow_title),
        "badge.name"
      ),
    ];
  }

  get othersCount() {
    return this.model.grant_count - this.userBadgesGrantCount;
  }

  get currentUserHasBadge() {
    return !!this.userBadgesAll?.some((ub) => ub.badge?.id === this.model.id);
  }

  get isFilteredToOtherUser() {
    return (
      !!this.username && this.userBadges?.[0]?.user?.id !== this.currentUser?.id
    );
  }

  get hasBadge() {
    return this.username
      ? this.userBadgesGrantCount > 0
      : this.currentUserHasBadge;
  }

  get canSelectTitle() {
    return (
      this.siteSettings.enable_badges &&
      this.model.allow_title &&
      this.hasBadge &&
      !this.isFilteredToOtherUser
    );
  }

  get canLoadMore() {
    if (this.noMoreBadges) {
      return false;
    }
    const total = this.userBadgesGrantCount ?? this.model.grant_count;
    return total > (this.userBadges?.length || 0);
  }

  get canShowOthers() {
    return !!this.username && this.othersCount > 0;
  }

  @action
  async loadMore() {
    if (!this.canLoadMore || this.loadingMore) {
      return;
    }

    this.loadingMore = true;

    try {
      const userBadges = this.userBadges;
      const result = await UserBadge.findByBadgeId(this.model.id, {
        offset: userBadges.length,
        username: this.username,
      });

      userBadges.push(...result);
      if (userBadges.length === 0) {
        this.noMoreBadges = true;
      }
    } finally {
      this.loadingMore = false;
    }
  }

  @action
  toggleTitlePicker() {
    this.showTitlePicker = !this.showTitlePicker;
  }
}
import { hash } from "rsvp";
import PreloadStore from "discourse/lib/preload-store";
import Badge from "discourse/models/badge";
import UserBadge from "discourse/models/user-badge";
import DiscourseRoute from "discourse/routes/discourse";

export default class BadgesShow extends DiscourseRoute {
  queryParams = {
    username: {
      refreshModel: true,
    },
  };

  serialize(model) {
    return model.getProperties("id", "slug");
  }

  model(params) {
    if (PreloadStore.get("badge")) {
      return PreloadStore.getAndRemove("badge").then((json) =>
        Badge.createFromJson(json)
      );
    } else {
      return Badge.findById(params.id);
    }
  }

  afterModel(model, transition) {
    const usernameFromParams =
      transition.to.queryParams && transition.to.queryParams.username;

    const userBadgesGrant = UserBadge.findByBadgeId(model.get("id"), {
      username: usernameFromParams,
    }).then((userBadges) => {
      this.userBadgesGrant = userBadges;
    });

    const username = this.currentUser && this.currentUser.username_lower;
    const userBadgesAll = UserBadge.findByUsername(username).then(
      (userBadges) => {
        this.userBadgesAll = userBadges;
      }
    );

    const promises = {
      userBadgesGrant,
      userBadgesAll,
    };

    return hash(promises);
  }

  titleToken() {
    const model = this.modelFor("badges.show");
    if (model) {
      return model.get("name");
    }
  }

  setupController(controller) {
    super.setupController(...arguments);

    controller.set("userBadges", this.userBadgesGrant);
    controller.set("userBadgesGrantCount", this.userBadgesGrant.grant_count);
    controller.set("userBadgesAll", this.userBadgesAll);
  }

  resetController(controller) {
    controller.showTitlePicker = false;
  }
}
