import DConditionalLoadingSpinner from "discourse/ui-kit/d-conditional-loading-spinner";
import DHorizontalOverflowNav from "discourse/ui-kit/d-horizontal-overflow-nav";
import DLoadMore from "discourse/ui-kit/d-load-more";
import DUserLink from "discourse/ui-kit/d-user-link";
import dAvatar from "discourse/ui-kit/helpers/d-avatar";
import dCategoryLink from "discourse/ui-kit/helpers/d-category-link";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import dLoadingSpinner from "discourse/ui-kit/helpers/d-loading-spinner";
import { i18n } from "discourse-i18n";

export default <template>
  {{#if @controller.loading}}
    {{hideApplicationFooter}}
  {{/if}}

  {{bodyClass "search-page"}}

  <section class="search-container">
    <PluginOutlet
      @connectorTagName="div"
      @name="full-page-search-above-search-header"
      @outletArgs={{lazyHash searchTerm=@controller.searchTerm}}
    />
    <div class="search-header" role="search">
      {{! the page announces itself to a screen reader, but the types above the
          field are what say what this page is to everyone else }}
      <h1 class="search-page-heading sr-only">
        {{i18n "search.full_page_title"}}
      </h1>

      <DHorizontalOverflowNav
        class="search-types"
        @ariaLabel={{i18n "search.type.label"}}
      >
        {{#each @controller.searchTypes key="id" as |searchType|}}
          <li>
            {{! a plain button, not a DButton: the nav styles this element
                directly, and the button classes would fight them }}
            <button
              class={{dConcatClass
                "search-types__type"
                (if (eq @controller.activeSearchType searchType.id) "active")
              }}
              data-search-type={{searchType.id}}
              type="button"
              {{on "click" (fn @controller.setSearchType searchType.id)}}
            >{{searchType.name}}</button>
          </li>
        {{/each}}
      </DHorizontalOverflowNav>

      <div class="search-bar">
        <div class="search-bar__field">
          <SearchTextField
            class="full-page-search search no-blur search-query"
            type="search"
            @aria-label={{i18n "search.search_term_label"}}
            @enter={{fn @controller.search (hash collapseFilters=true)}}
            @hasAutofocus={{@controller.hasAutofocus}}
            @value={{@controller.searchTerm}}
          />

          {{#if @controller.searchTerm}}
            <ClearButton @clearSearch={{@controller.clearSearchTerm}} />
          {{/if}}
        </div>
        <DButton
          class="btn-primary search-cta"
          @action={{fn @controller.search (hash collapseFilters=true)}}
          @ariaLabel={{@controller.searchButtonLabel}}
          @disabled={{@controller.searchButtonDisabled}}
          @icon={{@controller.searchButtonIcon}}
          @label={{@controller.searchButtonLabel}}
        />
      </div>

      {{#if @controller.usingDefaultSearchType}}
        {{! context is only provided when searching from mobile view }}
        {{#if @controller.context}}
          <div class="search-context">
            <label>
              <Input
                name="searchContext"
                @checked={{@controller.searchContextEnabled}}
                @type="checkbox"
              />
              {{@controller.searchContextDescription}}
            </label>
          </div>
        {{/if}}

        <div class="search-filters">
          <PluginOutlet
            @name="full-page-search-filters"
            @outletArgs={{lazyHash
              searchTerm=(readonly @controller.searchTerm)
              onChangeSearchTerm=(fn (mut @controller.searchTerm))
              search=(fn @controller.search (hash collapseFilters=true))
              searchButtonDisabled=@controller.searchButtonDisabled
              expandFilters=@controller.expandFilters
              sortOrder=@controller.sortOrder
              sortOrderOptions=@controller.sortOrders
              setSortOrder=@controller.setSortOrder
              type=@controller.search_type
              addSearchResults=@controller.addSearchResults
              resultCount=@controller.resultCount
            }}
          >
            <SearchAdvancedOptions
              @addSearchResults={{@controller.addSearchResults}}
              @expandFilters={{@controller.expandFilters}}
              @model={{@controller.model}}
              @onChangeSearchTerm={{fn (mut @controller.searchTerm)}}
              @search={{fn @controller.search (hash collapseFilters=true)}}
              @searchButtonDisabled={{@controller.searchButtonDisabled}}
              @searchTerm={{readonly @controller.searchTerm}}
              @searchType={{@controller.search_type}}
              @sortOrder={{@controller.sortOrder}}
            />
          </PluginOutlet>
        </div>
      {{/if}}

      <div class="search-notice">
        {{#if @controller.invalidSearch}}
          <div class="fps-invalid">
            {{i18n "search.too_short"}}
          </div>
        {{/if}}
      </div>

    </div>

    <div class="search-advanced">
      <PluginOutlet
        @connectorTagName="div"
        @name="full-page-search-below-search-header"
        @outletArgs={{lazyHash
          search=@controller.searchTerm
          type=@controller.search_type
          model=@controller.model
          addSearchResults=@controller.addSearchResults
          sortOrder=@controller.sortOrder
        }}
      />

      {{#if @controller.hasResults}}
        {{#if @controller.usingDefaultSearchType}}
          <div
            ariaLabel={{i18n "search.sort_or_bulk_actions"}}
            class={{@controller.searchInfoClassNames}}
            role="region"
          >
            {{#if @controller.canBulkSelect}}
              <DButton
                class="btn-default bulk-select"
                @action={{@controller.toggleBulkSelect}}
                @icon="list"
                @title="topics.bulk.toggle"
              />
            {{/if}}
            {{#if @controller.bulkSelectEnabled}}
              {{#if @controller.hasUnselectedResults}}
                <DButton
                  class="btn-default bulk-select-all"
                  @action={{@controller.selectAll}}
                  @icon="square-check"
                  @label="search.select_all"
                />
              {{/if}}

              {{#if @controller.hasSelection}}
                <DButton
                  class="btn-default bulk-select-clear"
                  @action={{@controller.clearAll}}
                  @icon="far-square"
                  @label="search.clear_all"
                />
              {{/if}}
            {{/if}}
            {{#if @controller.canBulkSelect}}
              {{#if @controller.bulkSelectHelper.selected}}
                <SearchBulkSelectDropdown
                  @afterBulkActionComplete={{@controller.afterBulkActionComplete}}
                  @bulkSelectHelper={{@controller.bulkSelectHelper}}
                />
              {{/if}}
            {{/if}}

            <div class="sort-by inline-form">
              <label>
                {{i18n "search.sort_by"}}
              </label>
              <ComboBox
                @content={{@controller.sortOrders}}
                @id="search-sort-by"
                @onChange={{@controller.setSortOrder}}
                @options={{hash castInteger=true}}
                @value={{@controller.sortOrder}}
              />
            </div>
          </div>
        {{/if}}

        <h2 aria-live="polite" class="result-count" id="search-result-count">
          {{trustHTML @controller.resultCountLabel}}
        </h2>
      {{/if}}

      <PluginOutlet
        @connectorTagName="div"
        @name="full-page-search-below-search-info"
        @outletArgs={{lazyHash search=@controller.searchTerm}}
      />

      {{#if @controller.searching}}
        {{dLoadingSpinner size="medium"}}
      {{else}}
        <div
          aria-label={{if
            @controller.q
            (i18n "search.results_page" term=@controller.q)
            (i18n "search.results")
          }}
          class="search-results"
          role="region"
        >
          <DLoadMore @action={{@controller.loadMore}}>
            {{#if
              (or
                @controller.usingDefaultSearchType @controller.customSearchType
              )
            }}
              <PluginOutlet
                @connectorTagName="div"
                @name="full-page-search-before-results"
                @outletArgs={{lazyHash
                  model=@controller.model
                  searchTerm=@controller.searchTerm
                }}
              />
              <SearchResultEntries
                @bulkSelectEnabled={{@controller.bulkSelectEnabled}}
                @highlightQuery={{@controller.highlightQuery}}
                @isPMOnly={{@controller.isPMOnly}}
                @posts={{@controller.searchResultPosts}}
                @searchLogId={{@controller.model.grouped_search_result.search_log_id}}
                @selected={{@controller.bulkSelectHelper.selected}}
              />

              <DConditionalLoadingSpinner @condition={{@controller.loading}}>
                {{#if @controller.error}}
                  <div class="warning">
                    {{@controller.error}}
                  </div>
                {{/if}}

                {{#if @controller.showNoResults}}
                  <div class="no-results-container">
                    <h3>{{i18n "search.no_results"}}</h3>

                    {{#if @controller.showSuggestion}}
                      <div class="no-results-suggestion">
                        {{i18n "search.cant_find"}}
                        {{#if @controller.canCreateTopic}}
                          <a href {{on "click" @controller.createTopic}}>{{i18n
                              "search.start_new_topic"
                            }}</a>
                          {{#unless @controller.siteSettings.login_required}}
                            {{i18n "search.or_search_google"}}
                          {{/unless}}
                        {{else}}
                          {{i18n "search.search_google"}}
                        {{/if}}
                      </div>

                      <GoogleSearch @searchTerm={{@controller.searchTerm}} />
                    {{/if}}
                  </div>
                {{/if}}

                {{#if @controller.hasResults}}
                  <h3 class="search-footer">
                    {{#if
                      @controller.model.grouped_search_result.more_full_page_results
                    }}
                      {{#if @controller.isLastPage}}
                        {{i18n "search.more_results"}}
                      {{/if}}
                    {{else}}
                      {{i18n "search.no_more_results"}}
                    {{/if}}
                  </h3>
                {{/if}}
              </DConditionalLoadingSpinner>
            {{else}}
              <DConditionalLoadingSpinner @condition={{@controller.loading}}>
                {{#if @controller.hasResults}}
                  {{#if @controller.model.categories.length}}
                    <h4 class="category-heading">
                      {{i18n "search.categories"}}
                    </h4>
                    <div class="category-items">
                      {{#each @controller.model.categories as |category|}}
                        {{dCategoryLink
                          category
                          extraClasses="fps-category-item"
                        }}
                      {{/each}}
                    </div>
                  {{/if}}

                  {{#if @controller.model.tags.length}}
                    <h4 class="tag-heading">
                      {{i18n "search.tags"}}
                    </h4>

                    <div class="tag-items">
                      {{#each @controller.model.tags as |tag|}}
                        <div class="fps-tag-item">
                          <a href={{tag.url}}>
                            {{tag.name}}
                          </a>
                        </div>
                      {{/each}}
                    </div>
                  {{/if}}

                  {{#if @controller.model.users}}
                    <div class="user-items">
                      {{#each @controller.model.users as |user|}}
                        <DUserLink class="fps-user-item" @user={{user}}>
                          {{dAvatar user imageSize="large"}}

                          <div class="user-titles">
                            {{#if user.name}}
                              <span class="name">
                                {{user.name}}
                              </span>
                            {{/if}}

                            <span class="username">
                              {{user.username}}
                            </span>
                          </div>
                        </DUserLink>
                      {{/each}}
                    </div>
                  {{/if}}
                {{else}}
                  {{#if @controller.searchActive}}
                    <h3>{{i18n "search.no_results"}}</h3>
                  {{/if}}
                {{/if}}
              </DConditionalLoadingSpinner>
            {{/if}}
            <PluginOutlet
              @name="full-page-search-below-results"
              @outletArgs={{lazyHash canLoadMore=@controller.canLoadMore}}
            />
          </DLoadMore>
        </div>
      {{/if}}
    </div>
  </section>
</template>
import { action } from "@ember/object";
import { ajax } from "discourse/lib/ajax";
import { getTransient, setTransient } from "discourse/lib/page-tracker";
import PreloadStore from "discourse/lib/preload-store";
import {
  getSearchKey,
  isValidSearchTerm,
  translateResults,
} from "discourse/lib/search";
import { escapeExpression } from "discourse/lib/utilities";
import DiscourseRoute from "discourse/routes/discourse";
import { i18n } from "discourse-i18n";

export default class FullPageSearch extends DiscourseRoute {
  queryParams = {
    q: {},
    expanded: false,
    context_id: {},
    context: {},
    skip_context: {},
  };

  category = null;

  beforeModel(transition) {
    if (this.site.can_search) {
      return;
    }

    transition.send("showLogin");
  }

  titleToken() {
    return i18n("search.results_page", {
      term: escapeExpression(
        this.controllerFor("full-page-search").get("searchTerm")
      ),
    });
  }

  model(params) {
    const cached = getTransient("lastSearch");
    let args = { q: params.q };
    if (params.context_id && !args.skip_context) {
      args.search_context = {
        type: params.context,
        id: params.context_id,
      };
    }

    const searchKey = getSearchKey(args);
    if (cached && cached.data.searchKey === searchKey) {
      // extend expiry
      setTransient("lastSearch", { searchKey, model: cached.data.model }, 5);
      return cached.data.model;
    }

    return PreloadStore.getAndRemove("search", () => {
      if (isValidSearchTerm(params.q, this.siteSettings)) {
        return ajax("/search", { data: args });
      } else {
        return null;
      }
    }).then(async (results) => {
      const model = (results && (await translateResults(results))) || {};
      setTransient("lastSearch", { searchKey, model }, 5);
      return model;
    });
  }

  @action
  didTransition() {
    this.controllerFor("full-page-search")._afterTransition();
    return true;
  }
}
import { trustHTML } from "@ember/template";
import GroupInfo from "discourse/components/group-info";
import GroupMembershipButton from "discourse/components/group-membership-button";
import GroupNavigation from "discourse/components/group-navigation";
import PluginOutlet from "discourse/components/plugin-outlet";
import DTooltip from "discourse/float-kit/components/d-tooltip";
import lazyHash from "discourse/helpers/lazy-hash";
import routeAction from "discourse/helpers/route-action";
import DAvatarFlair from "discourse/ui-kit/d-avatar-flair";
import DButton from "discourse/ui-kit/d-button";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

export default <template>
  <span>
    <PluginOutlet
      @connectorTagName="div"
      @name="before-group-container"
      @outletArgs={{lazyHash group=@controller.model}}
    />
  </span>

  <div class="container group group-{{@controller.model.name}}">
    {{#if @controller.showTooltip}}
      <div class="group-delete-tooltip">
        <p>{{i18n "admin.groups.delete_automatic_group"}}</p>
      </div>
    {{/if}}

    <div class="group-details-container">
      <div class="group-info">
        {{#if
          (or
            @controller.model.flair_icon
            @controller.model.flair_url
            @controller.model.flair_bg_color
          )
        }}
          <div class="group-avatar-flair">
            <DAvatarFlair
              @flairBgColor={{@controller.model.flair_bg_color}}
              @flairColor={{@controller.model.flair_color}}
              @flairName={{@controller.model.name}}
              @flairUrl={{or
                @controller.model.flair_icon
                @controller.model.flair_url
              }}
            />
          </div>
        {{/if}}

        <div class="group-info-names">
          <GroupInfo @group={{@controller.model}} />

          {{#if (and @controller.canManageGroup @controller.model.automatic)}}
            <DTooltip class="group-automatic-tooltip">
              <:trigger>
                {{dIcon "gear"}}
                {{i18n "admin.groups.manage.membership.automatic"}}
              </:trigger>
              <:content>
                {{i18n "admin.groups.manage.membership.automatic_tooltip"}}
              </:content>
            </DTooltip>
          {{/if}}
        </div>

        <div class="group-details-button">
          <GroupMembershipButton
            @model={{@controller.model}}
            @showLogin={{routeAction "showLogin"}}
          />

          {{#if @controller.currentUser.admin}}
            {{#if @controller.model.automatic}}
              <DButton
                class="btn-default"
                @action={{@controller.toggleDeleteTooltip}}
                @icon="circle-question"
                @label="admin.groups.delete"
              />
            {{else}}
              <DButton
                class="btn-danger"
                data-test-selector="delete-group-button"
                @action={{@controller.destroyGroup}}
                @disabled={{@controller.destroying}}
                @icon="trash-can"
                @label="admin.groups.delete"
              />
            {{/if}}
          {{/if}}

          {{#if @controller.displayGroupMessageButton}}
            <DButton
              class="btn-primary group-message-button"
              @action={{@controller.messageGroup}}
              @icon="envelope"
              @label="groups.message"
            />
          {{/if}}
        </div>

        <PluginOutlet
          @connectorTagName="div"
          @name="group-details-after"
          @outletArgs={{lazyHash model=@controller.model}}
        />
      </div>

      {{#if @controller.model.bio_cooked}}
        <div class="group-bio">
          {{trustHTML @controller.model.bio_cooked}}
        </div>
      {{/if}}

    </div>

    <div class="user-content-wrapper">
      <section class="user-primary-navigation">
        <GroupNavigation
          @currentPath={{@controller.currentPath}}
          @group={{@controller.model}}
          @tabs={{@controller.tabs}}
        />
      </section>
      {{outlet}}
    </div>
  </div>
</template>
import Controller, { inject as controller } from "@ember/controller";
import EmberObject, { action, computed } from "@ember/object";
import { service } from "@ember/service";
import GroupDeleteDialog from "discourse/components/dialog-messages/group-delete";
import { i18n } from "discourse-i18n";

class Tab extends EmberObject {
  init() {
    super.init(...arguments);

    this.setProperties({
      route: this.route || `group.${this.name}`,
      message: i18n(`groups.${this.i18nKey || this.name}`),
    });
  }
}

export default class GroupController extends Controller {
  @service dialog;
  @service currentUser;
  @service router;
  @service composer;
  @controller application;

  counts = null;
  showing = "members";

  /** @type {boolean | null} */
  destroying = null;
  showTooltip = false;

  @computed(
    "showMessages",
    "model.user_count",
    "model.request_count",
    "canManageGroup",
    "model.allow_membership_requests"
  )
  get tabs() {
    const membersTab = Tab.create({
      name: "members",
      route: "group.index",
      icon: "users",
      i18nKey: "members.title",
      count: this.model?.user_count,
    });

    const defaultTabs = [
      membersTab,
      Tab.create({ name: "activity", icon: "bars-staggered" }),
    ];

    if (this.canManageGroup && this.model?.allow_membership_requests) {
      defaultTabs.push(
        Tab.create({
          name: "requests",
          i18nKey: "requests.title",
          icon: "user-plus",
          count: this.model?.request_count,
        })
      );
    }

    if (this.showMessages) {
      defaultTabs.push(
        Tab.create({
          name: "messages",
          i18nKey: "messages",
          icon: "envelope",
        })
      );
    }

    if (this.canManageGroup) {
      defaultTabs.push(
        Tab.create({
          name: "manage",
          i18nKey: "manage.title",
          icon: "wrench",
        })
      );
    }

    defaultTabs.push(
      Tab.create({
        name: "permissions",
        i18nKey: "permissions.title",
        icon: "id-card",
      })
    );

    return defaultTabs;
  }

  @computed(
    "model.has_messages",
    "model.is_group_user",
    "currentUser.can_send_private_messages"
  )
  get showMessages() {
    if (!this.currentUser?.can_send_private_messages) {
      return false;
    }

    if (!this.model?.has_messages) {
      return false;
    }

    return (
      this.model?.is_group_user || (this.currentUser && this.currentUser.admin)
    );
  }

  @computed("model.messageable")
  get displayGroupMessageButton() {
    return this.currentUser && this.model?.messageable;
  }

  @computed("model", "model.automatic")
  get canManageGroup() {
    return this.currentUser?.canManageGroup(this.model);
  }

  @action
  messageGroup() {
    this.composer.openNewMessage({
      recipients: this.get("model.name"),
      hasGroups: true,
    });
  }

  @action
  destroyGroup() {
    this.set("destroying", true);

    const model = this.model;

    this.dialog.deleteConfirm({
      title: i18n("admin.groups.delete_confirm", { group: model.name }),
      bodyComponent: GroupDeleteDialog,
      bodyComponentModel: model,
      didConfirm: () => {
        model
          .destroy()
          .catch((error) => {
            // eslint-disable-next-line no-console
            console.error(error);
            this.dialog.alert(i18n("admin.groups.delete_failed"));
          })
          .then(() => {
            this.router.transitionTo("groups.index");
          })
          .finally(() => {
            this.set("destroying", false);
          });
      },
      didCancel: () => this.set("destroying", false),
    });
  }

  @action
  toggleDeleteTooltip() {
    this.toggleProperty("showTooltip");
  }
}
import DiscourseRoute from "discourse/routes/discourse";

export default class Group extends DiscourseRoute {
  titleToken() {
    return [this.modelFor("group").get("name")];
  }

  model(params) {
    return this.store.find("group", params.name);
  }

  serialize(model) {
    return { name: model.get("name").toLowerCase() };
  }

  setupController(controller) {
    super.setupController(...arguments);

    controller.set("showTooltip", false);
  }
}
