import Controller from "@ember/controller";
import { service } from "@ember/service";

export default class GroupActivityController extends Controller {
  // eslint-disable-next-line discourse/no-unused-services
  @service siteSettings; // used in the route template

  queryParams = ["category_id"];
}
import Route from "@ember/routing/route";

export default class extends Route {}
import PostList from "discourse/components/post-list/index";
import { i18n } from "discourse-i18n";

export default <template>
  <PostList
    @emptyText={{i18n "groups.empty.posts"}}
    @fetchMorePosts={{@controller.fetchMorePosts}}
    @posts={{@controller.model}}
    @titlePath="topic_html_title"
  />
</template>
import Controller, { inject as controller } from "@ember/controller";
import { action } from "@ember/object";

export default class GroupActivityPostsController extends Controller {
  @controller group;
  @controller("group.activity") groupActivity;
  @controller application;

  @action
  async fetchMorePosts() {
    const posts = this.model;
    const before = posts.length > 0 ? posts.at(-1)?.created_at : undefined;
    const group = this.group.model;
    const categoryId = this.groupActivity.category_id;
    const opts = { before, type: this.type, categoryId };

    return await group.findPosts(opts);
  }
}
import { action } from "@ember/object";
import { trackedArray } from "@ember/reactive/collections";
import DiscourseRoute from "discourse/routes/discourse";
import { i18n } from "discourse-i18n";

/** @returns {any} */
export function buildGroupPage(type) {
  return class GroupActivityPosts extends DiscourseRoute {
    type = type;
    templateName = "group.activity.posts";
    controllerName = "group.activity.posts";

    titleToken() {
      return i18n(`groups.${type}`);
    }

    async model(params, transition) {
      const categoryId = transition.to.queryParams.category_id;
      const posts = await this.modelFor("group").findPosts({
        type,
        categoryId,
      });

      return trackedArray(posts);
    }

    setupController(controller, model) {
      let loadedAll = model.length < 20;
      controller.setProperties({
        model,
        type,
        canLoadMore: !loadedAll,
      });
    }

    @action
    didTransition() {
      return true;
    }
  };
}

