                        id="new-account-username"
                        maxlength={{@controller.maxUsernameLength}}
                        name="username"
                        type="text"
                        value={{@controller.accountUsername}}
                        {{on "focusin" @controller.scrollInputIntoView}}
                        {{on "input" @controller.setAccountUsername}}
