                          >
                            {{dIcon "triangle-exclamation"}}
                            {{i18n "login.caps_lock_warning"}}
                          </div>
                        </div>
                      </div>
                    </div>
                  {{/unless}}

                  {{#if
                    (and
                      @controller.showFullname
                      (not @controller.fullnameRequired)
