    {{#if @controller.model}}
      <AddCategoryTagClasses
        @category={{@controller.model.category}}
        @tags={{@controller.model.tags}}
      />
      <AddTopicStatusClasses @topic={{@controller.model}} />
      {{bodyClass (concat "archetype-" @controller.model.archetype)}}
      {{#if @controller.shouldRenderNestedView}}
        {{#let @controller.nestedController as |nested|}}
          <PostTextSelection
            @buildQuoteMarkdown={{nested.buildQuoteMarkdown}}
            @editPost={{nested.editPost}}
            @quoteState={{nested.quoteState}}
            @selectText={{nested.selectText}}
            @topic={{@controller.model}}
          />

          <div
            class="selected-posts nested-view__selected-posts
              {{unless nested.multiSelect 'hidden'}}"
          >
            <SelectedPosts
              @canChangeOwner={{nested.canChangeOwner}}
              @canDeleteSelected={{nested.canDeleteSelected}}
              @canDeselectAll={{nested.canDeselectAll}}
              @canMergePosts={{nested.canMergePosts}}
              @canMergeTopic={{nested.canMergeTopic}}
              @canSelectAll={{nested.canSelectAll}}
              @deleteSelected={{nested.deleteSelected}}
              @deselectAll={{nested.deselectAll}}
              @mergePosts={{nested.mergePosts}}
              @selectAll={{nested.selectAll}}
              @selectedPostsCount={{nested.selectedPostsCount}}
              @toggleMultiSelect={{nested.toggleMultiSelect}}
            />
          </div>

          <Nested
            @ancestorsTruncated={{nested.ancestorsTruncated}}
            @buffered={{nested.buffered}}
            @cancelEditingTopic={{nested.cancelEditingTopic}}
            @canEditTags={{nested.canEditTags}}
            @changeNotice={{nested.changeNotice}}
            @changePostOwner={{nested.changePostOwner}}
            @changeSort={{nested.changeSort}}
            @clearScrollAnchor={{nested.clearScrollAnchor}}
            @collapseReplies={{nested.collapseReplies}}
            @contextMode={{nested.contextMode}}
            @contextNoAncestors={{nested.contextNoAncestors}}
            @deletePost={{nested.deletePost}}
            @editingTopic={{nested.editingTopic}}
            @editPost={{nested.editPost}}
            @effectiveSort={{nested.effectiveSort}}
            @expansionState={{nested.expansionState}}
            @fetchedChildrenCache={{nested.fetchedChildrenCache}}
            @finishedEditingTopic={{nested.finishedEditingTopic}}
            @grantBadge={{nested.grantBadge}}
            @hasMoreRoots={{nested.hasMoreRoots}}
            @initialFocusedPath={{nested.initialFocusedPath}}
            @loadingMore={{nested.loadingMore}}
            @loadMoreRoots={{nested.loadMoreRoots}}
            @loadNewRoots={{nested.loadNewRoots}}
            @lockPost={{nested.lockPost}}
            @minimumRequiredTags={{nested.minimumRequiredTags}}
            @multiSelect={{nested.multiSelect}}
            @newRootPostCount={{nested.newRootPostCount}}
            @opPost={{nested.opPost}}
            @permanentlyDeletePost={{nested.permanentlyDeletePost}}
            @pinnedPostIds={{nested.pinnedPostIds}}
            @postNumber={{nested.postNumber}}
            @postSelected={{nested.postSelected}}
            @rebakePost={{nested.rebakePost}}
            @recoverPost={{nested.recoverPost}}
            @replyToPost={{nested.replyToPost}}
            @rootNodes={{nested.rootNodes}}
            @saveScrollPosition={{nested.saveScrollPosition}}
            @scrollAnchor={{nested.scrollAnchor}}
            @selectBelow={{nested.selectBelow}}
            @selectReplies={{nested.selectReplies}}
            @setFocusedPostNumber={{nested.setFocusedPostNumber}}
            @showActivityLog={{nested.showActivityLog}}
            @showCategoryChooser={{nested.showCategoryChooser}}
            @showFlags={{nested.showFlags}}
            @showHistory={{nested.showHistory}}
            @showPagePublish={{nested.showPagePublish}}
            @sort={{nested.sort}}
            @startEditingTopic={{nested.startEditingTopic}}
            @targetPostNumber={{nested.targetPostNumber}}
            @togglePostSelection={{nested.togglePostSelection}}
            @togglePostType={{nested.togglePostType}}
            @toggleWiki={{nested.toggleWiki}}
            @topic={{@controller.model}}
            @topicCategoryChanged={{nested.topicCategoryChanged}}
            @topicTagsChanged={{nested.topicTagsChanged}}
            @unhidePost={{nested.unhidePost}}
            @unlockPost={{nested.unlockPost}}
            @viewFullThread={{nested.viewFullThread}}
            @viewParentContext={{nested.viewParentContext}}
          />
        {{/let}}
      {{else}}

        {{#unless @controller.shouldHideScrollableContentAbove}}
          <div class="container">
            <DiscourseBanner
              @hide={{@controller.model.errorLoading}}
              @overlay={{@controller.hasScrolled}}
            />
          </div>
        {{/unless}}

        {{#unless @controller.shouldHideScrollableContentAbove}}
          {{#if @controller.showSharedDraftControls}}
            <SharedDraftControls @topic={{@controller.model}} />
          {{/if}}

          <span>
            <PluginOutlet
              @connectorTagName="div"
              @name="topic-above-post-stream"
              @outletArgs={{lazyHash
                model=@controller.model
                editFirstPost=@controller.editFirstPost
              }}
            />
          </span>
        {{/unless}}

        {{#if @controller.model.postStream.loaded}}
          {{#if @controller.model.postStream.firstPostPresent}}
            <TopicTitle
              @cancelled={{@controller.cancelEditingTopic}}
              @model={{@controller.model}}
              @save={{@controller.finishedEditingTopic}}
            >
              {{#if @controller.editingTopic}}
                <div class="edit-topic-title">
                  <PrivateMessageGlyph
                    @shouldShow={{@controller.model.isPrivateMessage}}
                  />

                  <TopicTitleEditor
                    @buffered={{@controller.buffered}}
                    @bufferedTitle={{@controller.buffered.title}}
                    @isEditingLocalization={{@controller.editingTopicLocalization}}
                    @model={{@controller.model}}
                    @translationLocale={{@controller.translationLocale}}
                    @translationTitle={{@controller.translationTitle}}
                  />

                  <TopicMetadata
                    @buffered={{@controller.buffered}}
                    @canEditTags={{@controller.canEditTags}}
                    @minimumRequiredTags={{@controller.minimumRequiredTags}}
                    @model={{@controller.model}}
                    @onCancel={{@controller.cancelEditingTopic}}
                    @onSave={{@controller.finishedEditingTopic}}
                    @showCategoryChooser={{@controller.showCategoryChooser}}
                    @topicCategoryChanged={{@controller.topicCategoryChanged}}
                    @topicTagsChanged={{@controller.topicTagsChanged}}
                  >
                    {{#if @controller.canRemoveTopicFeaturedLink}}
                      <a
                        class="remove-featured-link"
                        href
                        title={{i18n "composer.remove_featured_link"}}
                        {{on "click" @controller.removeFeaturedLink}}
                      >
                        {{dIcon "circle-xmark"}}
                        {{@controller.featuredLinkDomain}}
                      </a>
                    {{/if}}
                  </TopicMetadata>
                </div>

              {{else}}
                <h1
                  {{! Prevent duplicating the topic title heading on screen readers when the header is displaying the title
                in the header }}
                  aria-hidden={{booleanString
                    @controller.titleIsVisibleOnHeader
                  }}
                  data-topic-id={{@controller.model.id}}
                >
                  {{#unless @controller.model.is_warning}}
                    {{#if @controller.canSendPms}}
                      <PrivateMessageGlyph
                        @ariaLabel="user.messages.inbox"
                        @href={{@controller.pmPath}}
                        @shouldShow={{@controller.model.isPrivateMessage}}
                        @title="topic_statuses.personal_message.title"
                      />
                    {{else}}
                      <PrivateMessageGlyph
                        @shouldShow={{@controller.model.isPrivateMessage}}
                      />
                    {{/if}}
                  {{/unless}}

                  {{#if @controller.model.details.loaded}}
                    <TopicStatus @topic={{@controller.model}} />
                    <a
                      class="fancy-title"
                      href={{@controller.model.url}}
                      {{on "click" @controller.handleTitleClick}}
                    >
                      {{trustHTML @controller.model.fancyTitle~}}
                      {{~#if @controller.model.details.can_edit~}}
                        <span class="edit-topic__wrapper">
                          {{dIcon "pencil" class="edit-topic"}}
                        </span>
                      {{~/if}}
                    </a>
                  {{/if}}

                  <PluginOutlet
                    @name="topic-title-suffix"
                    @outletArgs={{lazyHash model=@controller.model}}
                  />
                </h1>

                <PluginOutlet
                  @name="topic-category-wrapper"
                  @outletArgs={{lazyHash topic=@controller.model}}
                >
                  <TopicCategory
                    class="topic-category"
                    @topic={{@controller.model}}
                  />
                </PluginOutlet>

              {{/if}}
            </TopicTitle>

            {{#if @controller.model.publishedPage}}
              <div class="published-page-notice">
                <div class="details">
                  {{#if @controller.model.publishedPage.public}}
                    <span class="is-public">{{i18n
                        "topic.publish_page.public"
                      }}</span>
                  {{/if}}
                  {{i18n "topic.publish_page.topic_published"}}
                  <div>
                    <a
                      href={{@controller.model.publishedPage.url}}
                      rel="noopener noreferrer"
                      target="_blank"
                    >{{@controller.model.publishedPage.url}}</a>
                  </div>
                </div>
                <div class="controls">
                  <DButton
                    @action={{routeAction "showPagePublish"}}
                    @icon="file"
                    @label="topic.publish_page.publishing_settings"
                  />
                </div>
              </div>
            {{/if}}

          {{/if}}

          <div class="container posts">
            <div
              class="selected-posts {{unless @controller.multiSelect 'hidden'}}"
            >
              <SelectedPosts
                @canChangeOwner={{@controller.canChangeOwner}}
                @canDeleteSelected={{@controller.canDeleteSelected}}
                @canDeselectAll={{@controller.canDeselectAll}}
                @canMergePosts={{@controller.canMergePosts}}
                @canMergeTopic={{@controller.canMergeTopic}}
                @canSelectAll={{@controller.canSelectAll}}
                @deleteSelected={{@controller.deleteSelected}}
                @deselectAll={{@controller.deselectAll}}
                @mergePosts={{@controller.mergePosts}}
                @selectAll={{@controller.selectAll}}
                @selectedPostsCount={{@controller.selectedPostsCount}}
                @toggleMultiSelect={{@controller.toggleMultiSelect}}
              />
            </div>

            {{#if
              (and @controller.showBottomTopicMap @controller.loadedAllPosts)
            }}
              <div class="topic-map --bottom">
                <TopicMap
                  @model={{@controller.model}}
                  @postStream={{@controller.model.postStream}}
                  @removeAllowedGroup={{@controller.removeAllowedGroup}}
                  @removeAllowedUser={{@controller.removeAllowedUser}}
                  @showInvite={{routeAction "showInvite"}}
                  @showPMMap={{eq
                    @controller.model.archetype
                    "private_message"
                  }}
                  @topicDetails={{@controller.model.details}}
                />
              </div>
            {{/if}}

            <PluginOutlet @connectorTagName="div" @name="above-timeline" />

            <TopicNavigation
              class="topic-navigation"
              @jumpToDate={{@controller.jumpToDate}}
              @jumpToIndex={{@controller.jumpToIndex}}
              @topic={{@controller.model}}
              as |info toggleProgressExpansion|
            >
              <PluginOutlet
                @connectorTagName="div"
                @name="topic-navigation"
                @outletArgs={{lazyHash
                  topic=@controller.model
                  renderTimeline=info.renderTimeline
                  topicProgressExpanded=info.topicProgressExpanded
                }}
              />

              {{#if info.renderTimeline}}
                <TopicTimeline
                  @convertToPrivateMessage={{@controller.convertToPrivateMessage}}
                  @convertToPublicTopic={{@controller.convertToPublicTopic}}
                  @deleteTopic={{@controller.deleteTopic}}
                  @enteredIndex={{@controller.enteredIndex}}
                  @fullscreen={{info.topicProgressExpanded}}
                  @info={{info}}
                  @jumpBottom={{@controller.jumpBottom}}
                  @jumpEnd={{@controller.jumpEnd}}
                  @jumpToIndex={{@controller.jumpToIndex}}
                  @jumpTop={{@controller.jumpTop}}
                  @jumpToPostPrompt={{@controller.jumpToPostPrompt}}
                  @model={{@controller.model}}
                  @prevEvent={{info.prevEvent}}
                  @recoverTopic={{@controller.recoverTopic}}
                  @replyToPost={{@controller.replyToPost}}
                  @resetBumpDate={{@controller.resetBumpDate}}
                  @showChangeTimestamp={{routeAction "showChangeTimestamp"}}
                  @showFeatureTopic={{routeAction "showFeatureTopic"}}
                  @showTopicSlowModeUpdate={{routeAction
                    "showTopicSlowModeUpdate"
                  }}
                  @showTopicTimerModal={{routeAction "showTopicTimerModal"}}
                  @showTopReplies={{@controller.showTopReplies}}
                  @toggleArchived={{@controller.toggleArchived}}
                  @toggleClosed={{@controller.toggleClosed}}
                  @toggleMultiSelect={{@controller.toggleMultiSelect}}
                  @toggleVisibility={{@controller.toggleVisibility}}
                />
              {{else}}
                <TopicProgress
                  @jumpToPost={{@controller.jumpToPost}}
                  @onExpandToggle={{toggleProgressExpansion}}
                  @prevEvent={{info.prevEvent}}
                  @topic={{@controller.model}}
                >
                  <PluginOutlet
                    @connectorTagName="div"
                    @name="before-topic-progress"
                    @outletArgs={{lazyHash
                      model=@controller.model
                      jumpToPost=@controller.jumpToPost
                    }}
                  />
                  <TopicAdminMenu
                    @convertToPrivateMessage={{@controller.convertToPrivateMessage}}
                    @convertToPublicTopic={{@controller.convertToPublicTopic}}
                    @deleteTopic={{@controller.deleteTopic}}
                    @recoverTopic={{@controller.recoverTopic}}
                    @resetBumpDate={{@controller.resetBumpDate}}
                    @showChangeTimestamp={{routeAction "showChangeTimestamp"}}
                    @showFeatureTopic={{routeAction "showFeatureTopic"}}
                    @showTopicSlowModeUpdate={{routeAction
                      "showTopicSlowModeUpdate"
                    }}
                    @showTopicTimerModal={{routeAction "showTopicTimerModal"}}
                    @toggleArchived={{@controller.toggleArchived}}
                    @toggleClosed={{@controller.toggleClosed}}
                    @toggleMultiSelect={{@controller.toggleMultiSelect}}
                    @toggleVisibility={{@controller.toggleVisibility}}
                    @topic={{@controller.model}}
                  />
                  {{#if @controller.model.has_localized_content}}
                    <TopicContentLanguagePreferences />
                  {{/if}}
                </TopicProgress>
              {{/if}}

              <PluginOutlet
                @connectorTagName="div"
                @name="topic-navigation-bottom"
                @outletArgs={{lazyHash model=@controller.model}}
              />
            </TopicNavigation>

            <div class="row">
              <section
                class="topic-area"
                data-topic-id={{@controller.model.id}}
                id="topic"
              >
                <div class="posts-wrapper">
                  <span>
                    <PluginOutlet
                      @connectorTagName="div"
                      @name="topic-above-posts"
                      @outletArgs={{lazyHash model=@controller.model}}
                    />
                  </span>

                  {{#if @controller.model.postStream.firstPostNotLoaded}}
                    {{hideScrollableContent "above"}}
                  {{/if}}

                  {{#unless @controller.model.postStream.loadingFilter}}
                    <PostStream
                      @bottomVisibleChanged={{@controller.bottomVisibleChanged}}
                      @cancelFilter={{@controller.cancelFilter}}
                      @canCreatePost={{@controller.model.details.can_create_post}}
                      @changeNotice={{@controller.changeNotice}}
                      @changePostOwner={{@controller.changePostOwner}}
                      @currentPostChanged={{@controller.currentPostChanged}}
                      @currentPostScrolled={{@controller.currentPostScrolled}}
                      @deletePost={{@controller.deletePost}}
                      @editPost={{@controller.editPost}}
                      @expandHidden={{@controller.expandHidden}}
                      @fillGapAfter={{@controller.fillGapAfter}}
                      @fillGapBefore={{@controller.fillGapBefore}}
                      @filteredPostsCount={{@controller.model.postStream.filteredPostsCount}}
                      @filteringRepliesToPostNumber={{@controller.replies_to_post_number}}
                      @gaps={{@controller.model.postStream.gaps}}
                      @grantBadge={{@controller.grantBadge}}
                      @highestPostNumber={{@controller.highestPostNumber}}
                      @lastReadPostNumber={{@controller.userLastReadPostNumber}}
                      @lockPost={{@controller.lockPost}}
                      @multiSelect={{@controller.multiSelect}}
                      @permanentlyDeletePost={{@controller.permanentlyDeletePost}}
                      @postSelected={{@controller.postSelected}}
                      @postStream={{@controller.model.postStream}}
                      @rebakePost={{@controller.rebakePost}}
                      @recoverPost={{@controller.recoverPost}}
                      @removeAllowedGroup={{@controller.removeAllowedGroup}}
                      @removeAllowedUser={{@controller.removeAllowedUser}}
                      @replyToPost={{@controller.replyToPost}}
                      @selectBelow={{@controller.selectBelow}}
                      @selectedPostsCount={{@controller.selectedPostsCount}}
                      @selectedQuery={{@controller.selectedQuery}}
                      @selectReplies={{@controller.selectReplies}}
                      @showFlags={{@controller.showPostFlags}}
                      @showHistory={{routeAction "showHistory"}}
                      @showInvite={{routeAction "showInvite"}}
                      @showLogin={{routeAction "showLogin"}}
                      @showPagePublish={{routeAction "showPagePublish"}}
                      @showRawEmail={{routeAction "showRawEmail"}}
                      @showReadIndicator={{@controller.model.show_read_indicator}}
                      @showTopReplies={{@controller.showTopReplies}}
                      @streamFilters={{@controller.model.postStream.streamFilters}}
                      @toggleBookmark={{@controller.toggleBookmark}}
                      @togglePostSelection={{@controller.togglePostSelection}}
                      @togglePostType={{@controller.togglePostType}}
                      @toggleWiki={{@controller.toggleWiki}}
                      @topic={{@controller.model}}
                      @topicPageQueryParams={{@controller.topicPageQueryParams}}
                      @topVisibleChanged={{@controller.topVisibleChanged}}
                      @unhidePost={{@controller.unhidePost}}
                      @unlockPost={{@controller.unlockPost}}
                      @updateTopicPageQueryParams={{@controller.updateTopicPageQueryParams}}
                    />
                  {{/unless}}

                  {{#if @controller.model.postStream.lastPostNotLoaded}}
                    {{hideScrollableContent "below"}}
                  {{/if}}
                </div>
                <div id="topic-bottom"></div>

                <DConditionalLoadingSpinner
                  @condition={{@controller.model.postStream.loadingFilter}}
                >
                  {{#if @controller.loadedAllPosts}}

                    {{#if @controller.model.pending_posts}}
                      <div class="pending-posts">
                        {{#each @controller.model.pending_posts as |pending|}}
                          <div
                            class="reviewable-item"
                            data-reviewable-id={{pending.id}}
                          >
                            <div class="reviewable-meta-data">
                              <span class="reviewable-type">
                                {{i18n "review.awaiting_approval"}}
                              </span>
                              <span class="created-at">
                                {{dAgeWithTooltip pending.created_at}}
                              </span>
                            </div>
                            <div class="post-contents-wrapper">
                              <ReviewableCreatedBy
                                @user={{@controller.currentUser}}
                              />
                              <div class="post-contents">
                                <ReviewableCreatedByName
                                  @user={{@controller.currentUser}}
                                />
                                <div class="post-body">
                                  <DCookText @rawText={{pending.raw}} />
                                </div>
                              </div>
                            </div>
                            <div class="reviewable-actions">
                              <PluginOutlet
                                @name="topic-additional-reviewable-actions"
                                @outletArgs={{lazyHash pending=pending}}
                              />
                              <DButton
                                class="btn-danger"
                                @action={{fn @controller.deletePending pending}}
                                @icon="trash-can"
                                @label="review.delete"
                              />
                            </div>
                          </div>
                        {{/each}}
                      </div>
                    {{/if}}

                    {{#if @controller.model.queued_posts_count}}
                      <div class="has-pending-posts">
                        <div>
                          {{trustHTML
                            (i18n
                              "review.topic_has_pending"
                              count=@controller.model.queued_posts_count
                            )
                          }}
                        </div>

                        <LinkTo
                          @query={{hash
                            topic_id=@controller.model.id
                            type="ReviewableQueuedPost"
                            status="pending"
                          }}
                          @route="review"
                        >
                          {{i18n "review.view_pending"}}
                        </LinkTo>
                      </div>
                    {{/if}}

                    <SlowModeInfo
                      @topic={{@controller.model}}
                      @user={{@controller.currentUser}}
                    />

                    <TopicTimerInfo
                      @basedOnLastPost={{@controller.model.topic_timer.based_on_last_post}}
                      @categoryId={{@controller.model.topic_timer.category_id}}
                      @durationMinutes={{@controller.model.topic_timer.duration_minutes}}
                      @executeAt={{@controller.model.topic_timer.execute_at}}
                      @removeTopicTimer={{fn
                        @controller.removeTopicTimer
                        @controller.model.topic_timer.status_type
                        "topic_timer"
                      }}
                      @showTopicTimerModal={{routeAction "showTopicTimerModal"}}
                      @statusType={{@controller.model.topic_timer.status_type}}
                      @statusUpdate={{@controller.model.topic_status_update}}
                      @topicClosed={{@controller.model.closed}}
                    />

                    {{#if @controller.showSelectedPostsAtBottom}}
                      <div
                        class="selected-posts
                          {{unless @controller.multiSelect 'hidden'}}
                          {{if @controller.showSelectedPostsAtBottom 'hidden'}}"
                      >
                        <SelectedPosts
                          @canChangeOwner={{@controller.canChangeOwner}}
                          @canDeleteSelected={{@controller.canDeleteSelected}}
                          @canDeselectAll={{@controller.canDeselectAll}}
                          @canMergePosts={{@controller.canMergePosts}}
                          @canMergeTopic={{@controller.canMergeTopic}}
                          @canSelectAll={{@controller.canSelectAll}}
                          @deleteSelected={{@controller.deleteSelected}}
                          @deselectAll={{@controller.deselectAll}}
                          @mergePosts={{@controller.mergePosts}}
                          @selectAll={{@controller.selectAll}}
                          @selectedPostsCount={{@controller.selectedPostsCount}}
                          @toggleMultiSelect={{@controller.toggleMultiSelect}}
                        />
                      </div>
                    {{/if}}

                  {{/if}}
                </DConditionalLoadingSpinner>

                <PluginOutlet
                  @connectorTagName="div"
                  @name="topic-area-bottom"
                  @outletArgs={{lazyHash model=@controller.model}}
                />
              </section>
            </div>

          </div>
          {{#if @controller.loadedAllPosts}}
            {{#if @controller.session.showSignupCta}}
              {{! replace "Log In to Reply" with the infobox }}
              <SignupCta />
            {{else}}
              {{#if @controller.currentUser}}
                <span>
                  <PluginOutlet
                    @connectorTagName="div"
                    @name="topic-above-footer-buttons"
                    @outletArgs={{lazyHash model=@controller.model}}
                  />
                </span>

                {{#if @controller.showTopicFooterButtons}}
                  <TopicFooterButtons
                    @convertToPrivateMessage={{@controller.convertToPrivateMessage}}
                    @convertToPublicTopic={{@controller.convertToPublicTopic}}
                    @deferTopic={{@controller.deferTopic}}
                    @deleteTopic={{@controller.deleteTopic}}
                    @editFirstPost={{@controller.editFirstPost}}
                    @recoverTopic={{@controller.recoverTopic}}
                    @replyToPost={{@controller.replyToPost}}
                    @resetBumpDate={{@controller.resetBumpDate}}
                    @showChangeTimestamp={{routeAction "showChangeTimestamp"}}
                    @showFeatureTopic={{routeAction "showFeatureTopic"}}
                    @showFlagTopic={{routeAction "showFlagTopic"}}
                    @showTopicSlowModeUpdate={{routeAction
                      "showTopicSlowModeUpdate"
                    }}
                    @showTopicTimerModal={{routeAction "showTopicTimerModal"}}
                    @toggleArchived={{@controller.toggleArchived}}
                    @toggleArchiveMessage={{@controller.toggleArchiveMessage}}
                    @toggleBookmark={{@controller.toggleBookmark}}
                    @toggleClosed={{@controller.toggleClosed}}
                    @toggleMultiSelect={{@controller.toggleMultiSelect}}
                    @toggleVisibility={{@controller.toggleVisibility}}
                    @topic={{@controller.model}}
                  />
                {{/if}}
              {{else}}
                <AnonymousTopicFooterButtons @topic={{@controller.model}} />
              {{/if}}
            {{/if}}

            <br />

            <span>
              <PluginOutlet
                @connectorTagName="div"
                @name="topic-above-suggested"
                @outletArgs={{lazyHash model=@controller.model}}
              />
            </span>

            <MoreTopics @topic={{@controller.model}} />
            <PluginOutlet
              @name="topic-below-suggested"
              @outletArgs={{lazyHash model=@controller.model}}
            />
          {{/if}}
          <EmbedTopicFooter @topic={{@controller.model}} />
          <EmbedModeComposer @topic={{@controller.model}} />
        {{else}}
          <div class="container">
            <DConditionalLoadingSpinner @condition={{@controller.noErrorYet}}>
              {{#if @controller.model.errorHtml}}
                <div class="not-found">{{trustHTML
                    @controller.model.errorHtml
                  }}</div>
              {{else}}
                <div class="topic-error">
                  <div>{{@controller.model.errorMessage}}</div>
                  {{#if @controller.model.noRetry}}
                    {{#unless @controller.currentUser}}
                      <DButton
                        class="btn-primary topic-retry"
                        @action={{routeAction "showLogin"}}
                        @icon="user"
                        @label="log_in"
                      />
                    {{/unless}}
                  {{else}}
                    <DButton
                      class="btn-primary topic-retry"
                      @action={{@controller.retryLoading}}
                      @icon="arrows-rotate"
                      @label="errors.buttons.again"
                    />
                  {{/if}}
                </div>
                <DConditionalLoadingSpinner
                  @condition={{@controller.retrying}}
                />
              {{/if}}
            </DConditionalLoadingSpinner>
          </div>
        {{/if}}

        {{#each (array @controller.model) as |topic|}}
          <PostTextSelection
            @buildQuoteMarkdown={{@controller.buildQuoteMarkdown}}
            @editPost={{@controller.editPost}}
            @quoteState={{@controller.quoteState}}
            @selectText={{@controller.selectText}}
            @topic={{topic}}
          />
        {{/each}}
      {{/if}}
    {{/if}}
  </DiscourseTopic>
</template>
import { action, get } from "@ember/object";
import { cancel, schedule } from "@ember/runloop";
import { service } from "@ember/service";
import { isEmpty } from "@ember/utils";
import AddPmParticipants from "discourse/components/modal/add-pm-participants";
import AnonymousFlagModal from "discourse/components/modal/anonymous-flag";
import ChangeOwnerModal from "discourse/components/modal/change-owner";
import ChangeTimestampModal from "discourse/components/modal/change-timestamp";
import EditSlowModeModal from "discourse/components/modal/edit-slow-mode";
import EditTopicTimerModal from "discourse/components/modal/edit-topic-timer";
import FeatureTopicModal from "discourse/components/modal/feature-topic";
import FlagModal from "discourse/components/modal/flag";
import GrantBadgeModal from "discourse/components/modal/grant-badge";
import HistoryModal from "discourse/components/modal/history";
import MoveToTopicModal from "discourse/components/modal/move-to-topic";
import PublishPageModal from "discourse/components/modal/publish-page";
import RawEmailModal from "discourse/components/modal/raw-email";
import ReportIllegalContentModal from "discourse/components/modal/report-illegal-content";
import PostFlag from "discourse/lib/flag-targets/post-flag";
import TopicFlag from "discourse/lib/flag-targets/topic-flag";
import { getAbsoluteURL } from "discourse/lib/get-url";
import discourseLater from "discourse/lib/later";
import { setTopicId } from "discourse/lib/topic-list-tracker";
import topicTitleToken from "discourse/lib/topic-title-token";
import DiscourseURL from "discourse/lib/url";
import { ID_CONSTRAINT } from "discourse/models/topic";
import DiscourseRoute from "discourse/routes/discourse";
import { i18n } from "discourse-i18n";

const SCROLL_DELAY = 500;

export default class TopicRoute extends DiscourseRoute {
  @service a11y;
  @service composer;
  @service currentUser;
  @service screenTrack;
  @service modal;
  @service router;

  /** @type {ReturnType<typeof import("discourse/lib/later").default> | null} */
  scheduledReplace = null;

  /** @type {number | null} */
  lastScrollPos = null;
  isTransitioning = false;
  queryParams = {
    filter: { replace: true },
    username_filters: { replace: true },
    sort: { replace: true, refreshModel: true },
    context: { refreshModel: true },
    collapseReplies: { replace: true },
  };
  #announcedUnreadForTopicId = null;

  buildRouteInfoMetadata() {
    return {
      scrollOnTransition: false,
    };
  }

  titleToken() {
    return topicTitleToken(this.modelFor("topic"), this.siteSettings);
  }

  @action
  showInvite() {
    let modalTitle;

    if (this.isPM) {
      modalTitle = "topic.invite_private.title";
    } else if (this.invitingToTopic) {
      modalTitle = "topic.invite_reply.title";
    } else {
      modalTitle = "user.invited.create";
    }

    this.modal.show(AddPmParticipants, {
      model: {
        title: modalTitle,
        inviteModel: this.modelFor("topic"),
      },
    });
  }

  @action
  showFlags(model) {
    if (!this.currentUser && this.siteSettings.dsa_reporting_enabled) {
      this.modal.show(ReportIllegalContentModal, {
        model: { contentUrl: getAbsoluteURL(model.urlWithNumber) },
      });
      return;
    }

    this.modal.show(this.currentUser ? FlagModal : AnonymousFlagModal, {
      model: {
        allowIllegalContentReport: true,
        flagTarget: new PostFlag(),
        flagModel: model,
        setHidden: () => model.set("hidden", true),
      },
    });
  }

  @action
  showFlagTopic() {
    const model = this.modelFor("topic");
    this.modal.show(FlagModal, {
      model: {
        allowIllegalContentReport: true,
        flagTarget: new TopicFlag(),
        flagModel: model,
        setHidden: () => model.set("hidden", true),
      },
    });
  }

  @action
  showPagePublish() {
    const model = this.modelFor("topic");
    this.modal.show(PublishPageModal, {
      model,
    });
  }

  @action
  showTopicTimerModal() {
    const model = this.modelFor("topic");
    this.modal.show(EditTopicTimerModal, {
      model: {
        topic: model,
        setTopicTimer: (v) => model.set("topic_timer", v),
        updateTopicTimerProperty: this.updateTopicTimerProperty,
      },
    });
  }

  @action
  updateTopicTimerProperty(property, value) {
    this.modelFor("topic").set(`topic_timer.${property}`, value);
  }

  @action
  showTopicSlowModeUpdate() {
    this.modal.show(EditSlowModeModal, {
      model: { topic: this.modelFor("topic") },
    });
  }

  @action
  showChangeTimestamp() {
    this.modal.show(ChangeTimestampModal, {
      model: { topic: this.modelFor("topic") },
    });
  }

  @action
  showFeatureTopic() {
    const topicController = this.controllerFor("topic");
    const model = this.modelFor("topic");
    model.setProperties({
      pinnedInCategoryUntil: null,
      pinnedGloballyUntil: null,
    });

    this.modal.show(FeatureTopicModal, {
      model: {
        topic: model,
        pinGlobally: () => topicController.send("pinGlobally"),
        togglePinned: () => topicController.send("togglePinned"),
        makeBanner: () => topicController.send("makeBanner"),
        removeBanner: () => topicController.send("removeBanner"),
      },
    });
  }

  @action
  showHistory(model, revision) {
    this.modal.show(HistoryModal, {
      model: {
        postId: model.id,
        postVersion: revision || "latest",
        post: model,
        editPost: (post) => this.controllerFor("topic").send("editPost", post),
      },
    });
  }

  @action
  showGrantBadgeModal(post = null) {
    const topicController = this.controllerFor("topic");
    this.modal.show(GrantBadgeModal, {
      model: {
        selectedPost: post ?? topicController.selectedPosts[0],
      },
    });
  }

  @action
  showRawEmail(model) {
    this.modal.show(RawEmailModal, { model });
  }

  @action
  moveToTopic() {
    const topicController = this.controllerFor("topic");
    this.modal.show(MoveToTopicModal, {
      model: {
        topic: this.modelFor("topic"),
        selectedPostsCount: topicController.selectedPostsCount,
        selectedAllPosts: topicController.selectedAllPosts,
        selectedPosts: topicController.selectedPosts,
        selectedPostIds: topicController.selectedPostIds,
        toggleMultiSelect: topicController.toggleMultiSelect,
      },
    });
  }

  @action
  changeOwner(post = null) {
    const topicController = this.controllerFor("topic");
    this.modal.show(ChangeOwnerModal, {
      model: {
        deselectAll: topicController.deselectAll,
        multiSelect: topicController.multiSelect,
        selectedPostsCount: post ? 1 : topicController.selectedPostsCount,
        selectedPostIds: post ? [post.id] : topicController.selectedPostIds,
        selectedPostsUsername:
          post?.username ?? topicController.selectedPostsUsername,
        toggleMultiSelect: topicController.toggleMultiSelect,
        topic: post?.topic ?? this.modelFor("topic"),
      },
    });
  }

  // Use replaceState to update the URL once it changes
  @action
  postChangedRoute(currentPost) {
    if (TopicRoute.disableReplaceState) {
      return;
    }

    const topic = this.modelFor("topic");
    if (topic && currentPost) {
      let postUrl;
      if (currentPost > 1) {
        postUrl = topic.urlForPostNumber(currentPost);
      } else {
        postUrl = topic.url;
      }

      if (this._router.currentRoute.queryParams) {
        let searchParams;

        Object.entries(this._router.currentRoute.queryParams).map(
          ([key, value]) => {
            if (!searchParams) {
              searchParams = new URLSearchParams();
            }

            searchParams.append(key, value);
          }
        );

        if (searchParams) {
          postUrl += `?${searchParams.toString()}`;
        }
      }

      cancel(this.scheduledReplace);

      this.setProperties({
        lastScrollPos: document.scrollingElement.scrollTop,
        scheduledReplace: discourseLater(
          this,
          "_replaceUnlessScrolling",
          postUrl,
          topic.id,
          SCROLL_DELAY
        ),
      });
    }
  }

  @action
  didTransition() {
    const controller = this.controllerFor("topic");
    const topicId = controller.get("model.id");
    setTopicId(topicId);
    return true;
  }

  @action
  willTransition() {
    super.willTransition(...arguments);
    cancel(this.scheduledReplace);
    return true;
  }

  setupParams(topic, params) {
    const postStream = topic.get("postStream");
    postStream.filter = get(params, "filter");

    const usernames = get(params, "username_filters");

    if (!isEmpty(usernames) && usernames !== "undefined") {
      postStream.userFilters = [...new Set(usernames.split(","))];
    } else {
      postStream.userFilters = [];
    }

    return topic;
  }

  model(params, transition) {
    if (params.slug.match(ID_CONSTRAINT)) {
      // URL with no slug - redirect to a URL with placeholder slug
      this.router.transitionTo(`/t/-/${params.slug}/${params.id}`);
      return;
    }

    const queryParams = transition.to.queryParams;

    let topic = this.modelFor("topic");
    if (topic && topic.get("id") === parseInt(params.id, 10)) {
      this.setupParams(topic, queryParams);
      return topic;
    } else {
      let props = { ...params };
      delete props.username_filters;
      delete props.filter;
      topic = this.store.createRecord("topic", props);
      return this.setupParams(topic, queryParams);
    }
  }

  announceUnreadPosts(topic) {
    if (this.#announcedUnreadForTopicId === topic.id) {
      return;
    }
    this.#announcedUnreadForTopicId = topic.id;

    const lastRead = topic.last_read_post_number;
    const unread = topic.highest_post_number - lastRead;
    if (lastRead && unread > 0) {
      this.a11y.announce(i18n("topic.unread_posts", { count: unread }));
    }
  }

  deactivate() {
    super.deactivate(...arguments);

    this.#announcedUnreadForTopicId = null;

    this.searchService.searchContext = null;

    const topicController = this.controllerFor("topic");
    const postStream = topicController.get("model.postStream");

    postStream.cancelFilter();

    topicController.set("multiSelect", false);
    this.composer.set("topic", null);
    this.screenTrack.stop();

    this.appEvents.trigger("header:hide-topic");

    this.controllerFor("topic").set("model", null);
  }

  setupController(controller, model) {
    controller.setProperties({
      model,
      editingTopic: false,
      firstPostExpanded: false,
    });

    this.searchService.searchContext = model.get("searchContext");

    // close the multi select when switching topics
    controller.set("multiSelect", false);
    controller.get("quoteState").clear();

    this.composer.set("topic", model);
    this.topicTrackingState.trackIncoming("all");

    // We reset screen tracking every time a topic is entered
    this.screenTrack.start(model.get("id"), controller);

    schedule("afterRender", () =>
      this.appEvents.trigger("header:update-topic", model)
    );
  }

  // replaceState can be very slow on Android Chrome. This function debounces replaceState
  // within a topic until scrolling stops
  _replaceUnlessScrolling(url, topicId) {
    const { currentRouteName } = this.router;

    const stillOnTopicRoute = currentRouteName?.split(".")[0] === "topic";
    if (!stillOnTopicRoute) {
      return;
    }

    const stillOnSameTopic = this.modelFor("topic").id === topicId;
    if (!stillOnSameTopic) {
      return;
    }

    const currentPos = document.scrollingElement.scrollTop;
    if (currentPos === this.lastScrollPos) {
      DiscourseURL.replaceState(`${url}${window.location.hash}`);
      return;
    }

    this.setProperties({
      lastScrollPos: currentPos,
      scheduledReplace: discourseLater(
        this,
        "_replaceUnlessScrolling",
        url,
        topicId,
        SCROLL_DELAY
      ),
    });
  }
}
import { action } from "@ember/object";
import { getOwner } from "@ember/owner";
import { schedule } from "@ember/runloop";
import { service } from "@ember/service";
import { isEmpty } from "@ember/utils";
import { ajax } from "discourse/lib/ajax";
import EmbedMode from "discourse/lib/embed-mode";
import { isTesting } from "discourse/lib/environment";
import {
  processNestedContextResponse,
  processNestedRootResponse,
} from "discourse/lib/nested-topic-model";
import {
  hydrateExpansionState,
  hydrateFetchedChildrenCache,
  hydrateNestedModelData,
  isValidNestedViewCacheSnapshot,
  NESTED_VIEW_CACHE_FORMAT_VERSION,
} from "discourse/lib/nested-view-cache-snapshot";
import resolvePermalink from "discourse/lib/permalink-check";
import PreloadStore from "discourse/lib/preload-store";
import { registerPostInTopicPostStream } from "discourse/lib/process-node";
import DiscourseURL from "discourse/lib/url";
import Draft from "discourse/models/draft";
import DiscourseRoute from "discourse/routes/discourse";

export function nestedQueryString(params) {
  const query = new URLSearchParams();

  for (const [key, value] of Object.entries(params)) {
    if (value !== undefined && value !== null) {
      query.set(key, value);
    }
  }

  return query.toString();
}

function originalTopicPath(topic, params) {
  let path = `/t/${topic.slug}/${topic.id}`;
  const nearPost = params.nearPost;
  if (nearPost && nearPost !== "last" && nearPost !== 999999999) {
    path += `/${nearPost}`;
  }
  return path;
}

// This route is used for retrieving a topic based on params
export default class TopicFromParams extends DiscourseRoute {
  @service appEvents;
  @service composer;
  @service header;
  @service historyStore;
  @service nestedViewCache;
  @service router;
  @service screenTrack;
  @service site;
  @service siteSettings;
  @service store;

  buildRouteInfoMetadata() {
    return {
      scrollOnTransition: false,
    };
  }

  // Avoid default model hook
  model(params, transition) {
    params = params || {};
    params.track_visit = true;

    const topic = this.modelFor("topic");

    const queryParams = transition?.to?.queryParams || {};
    if (topic.is_nested_view) {
      return this.#loadNestedModel(topic, params, queryParams).catch((e) => {
        if (!isTesting()) {
          // eslint-disable-next-line no-console
          console.log("Could not view nested topic", e);
        }
        params._loading_error = true;
        return params;
      });
    }

    const postStream = topic.postStream;

    // I sincerely hope no topic gets this many posts
    if (params.nearPost === "last") {
      params.nearPost = 999999999;
    }
    params.forceLoad = true;

    return postStream
      .refresh(params)
      .then(() => {
        if (topic.is_nested_view) {
          return this.#loadNestedModel(topic, params, queryParams);
        }
        return params;
      })
      .catch(async (e) => {
        if (!isTesting()) {
          // eslint-disable-next-line no-console
          console.log("Could not view topic", e);
        }

        // The id-only topic JSON drops the slug, so the server can't match a
        // permalink for the original URL; resolve it here instead.
        if (topic.errorHtml) {
          const result = await resolvePermalink(
            originalTopicPath(topic, params),
            transition,
            this.router
          ).catch(() => null);
          if (result?.type === "redirect") {
            return params;
          }
        }

        params._loading_error = true;
        return params;
      });
  }

  afterModel(model) {
    const topic = this.modelFor("topic");

    if (model._nested) {
      this.header.enterTopic(model._nested.topic, !model._nested.contextMode);
      return;
    }

    const isLoadingFirstPost =
      topic.postStream.firstPostPresent &&
      !(model.nearPost && model.nearPost > 1);
    this.header.enterTopic(topic, isLoadingFirstPost);
  }

  deactivate() {
    super.deactivate(...arguments);

    const topicController = this.controllerFor("topic");
    const nestedController = this.controllerFor("nested");
    this.#saveNestedToCache(nestedController);

    topicController.unsubscribe();
    this.#resetTopicControllerBulkSelection(topicController);
    nestedController.unsubscribe();
    nestedController.topic = null;
  }

  setupController(controller, params, { _discourse_anchor }) {
    // Don't do anything else if we couldn't load
    // TODO: Tests require this but it seems bad
    if (params._loading_error) {
      return;
    }

    if (params._nested) {
      this.#setupNestedController(params._nested);
      return;
    }

    const topicController = this.controllerFor("topic");
    const nestedController = this.controllerFor("nested");
    const wasNestedView = Boolean(nestedController.topic);
    if (wasNestedView) {
      this.#saveNestedToCache(nestedController);
    }
    nestedController.unsubscribe();
    if (wasNestedView) {
      this.#resetTopicControllerBulkSelection(topicController);
      nestedController.topic = null;
    }
    const topic = this.modelFor("topic");
    const postStream = topic.postStream;

    // there are no closestPost for hidden topics
    if (topic.view_hidden) {
      return;
    }

    // The post we requested might not exist. Let's find the closest post —
    // a topic with no posts at all has none, so everything keyed off a post
    // is skipped below while the route itself still sets up.
    const closestPost = postStream.closestPostForPostNumber(
      params.nearPost || 1
    );
    const closest = closestPost?.post_number;

    topicController.setProperties({
      "model.currentPost": closest,
      enteredIndex: closestPost
        ? topic.postStream.progressIndexOfPost(closestPost)
        : undefined,
      enteredAt: Date.now().toString(),
      userLastReadPostNumber: topic.last_read_post_number,
      highestPostNumber: topic.highest_post_number,
    });

    this.appEvents.trigger("page:topic-loaded", topic);
    this.#announceUnreadPosts(topic);
    topicController.subscribe();
    if (wasNestedView) {
      this.screenTrack.start(topic.id, topicController);
    }

    if (closestPost) {
      // Highlight our post after the next render
      schedule("afterRender", () =>
        this.appEvents.trigger("post:highlight", closest)
      );

      const opts = {};
      if (document.location.hash) {
        opts.anchor = document.location.hash.slice(1);
      } else if (_discourse_anchor) {
        opts.anchor = _discourse_anchor;
      }
      DiscourseURL.jumpToPost(closest, opts);

      // completely clear out all the bookmark related attributes
      // because they are not in the response if bookmarked == false
      if (!closestPost.bookmarked) {
        closestPost.clearBookmark();
      }
    }

    if (!isEmpty(topic.draft) && !EmbedMode.enabled) {
      this.composer.open({
        draft: Draft.getLocal(topic.draft_key, topic.draft),
        draftKey: topic.draft_key,
        draftSequence: topic.draft_sequence,
        ignoreIfChanged: true,
        topic,
      });
    }
  }

  @action
  willTransition(transition) {
    this.controllerFor("topic").set("previousURL", document.location.pathname);

    transition.followRedirects().finally(() => {
      const routeName = this.router.currentRouteName;

      if (!routeName?.startsWith("topic.")) {
        this.header.clearTopic();
      }
    });

    // NOTE: omitting this return can break the back button when transitioning quickly between
    // topics and the latest page.
    return true;
  }

  async #loadNestedModel(topic, params, queryParams) {
    const sort =
      queryParams.sort ||
      this.siteSettings.nested_replies_default_sort ||
      "top";
    const postNumber = Number(params.nearPost);
    const targetsPost = Number.isInteger(postNumber) && postNumber > 1;
    const slug = topic.slug || params.slug || "topic";
    const nestedParams = {
      ...params,
      post_number: targetsPost ? postNumber : null,
      context: queryParams.context,
    };

    const cacheKey = this.nestedViewCache.buildKey(topic.id, {
      ...nestedParams,
      sort,
    });
    const cached = this.#restoreNestedFromCache(cacheKey);

    if (cached) {
      params._nested = cached;
      params._nested.collapseReplies = this.#truthyQueryParam(
        queryParams.collapse_replies || queryParams.collapseReplies
      );
      return params;
    }

    if (targetsPost) {
      const query = nestedQueryString({
        sort,
        track_visit: true,
        context: queryParams.context,
      });

      const data = await PreloadStore.getAndRemove(
        `nested_topic_${topic.id}`,
        () => ajax(`/n/${slug}/${topic.id}/context/${postNumber}.json?${query}`)
      );

      params._nested = processNestedContextResponse({
        data,
        params: nestedParams,
        site: this.site,
        sort,
        store: this.store,
      });
    } else {
      const query = nestedQueryString({ sort, track_visit: true });
      const data = await PreloadStore.getAndRemove(
        `nested_topic_${topic.id}`,
        () => ajax(`/n/${slug}/${topic.id}.json?${query}`)
      );

      params._nested = processNestedRootResponse({
        data,
        params: nestedParams,
        site: this.site,
        siteSettings: this.siteSettings,
        store: this.store,
      });
    }

    const scrollAnchor = this.#loadScrollAnchor(cacheKey);
    if (scrollAnchor) {
      this._restoringFromCache = {
        expansionState: new Map(),
        fetchedChildrenCache: new Map(),
        scrollAnchor,
      };
    }

    params._nested.collapseReplies = this.#truthyQueryParam(
      queryParams.collapse_replies || queryParams.collapseReplies
    );

    return params;
  }

  #restoreNestedFromCache(cacheKey) {
    const cached = this.nestedViewCache.get(cacheKey);
    if (!cached) {
      this._restoringFromCache = null;
      return null;
    }

    const shouldRestore = this.nestedViewCache.consumeTraversal({
      allowLocalSignal: true,
      isPoppedState: this.historyStore.isPoppedState,
    });

    if (!shouldRestore) {
      this._restoringFromCache = null;
      return null;
    }

    const restored = this.#hydrateCachedEntry(cached);
    if (!restored) {
      this.nestedViewCache.remove(cacheKey);
      this._restoringFromCache = null;
      return null;
    }

    this._restoringFromCache = restored;
    return restored.modelData;
  }

  #scrollAnchorKey(cacheKey) {
    return `nested-view-scroll:${cacheKey}`;
  }

  #announceUnreadPosts(topic) {
    getOwner(this).lookup("route:topic").announceUnreadPosts(topic);
  }

  #loadScrollAnchor(cacheKey) {
    try {
      const value = sessionStorage.getItem(this.#scrollAnchorKey(cacheKey));
      return value ? JSON.parse(value) : null;
    } catch {
      return null;
    }
  }

  #hydrateCachedEntry(cached) {
    if (
      cached.formatVersion !== NESTED_VIEW_CACHE_FORMAT_VERSION ||
      !isValidNestedViewCacheSnapshot(cached.modelData)
    ) {
      return null;
    }

    const modelData = hydrateNestedModelData(this.store, cached.modelData);

    return {
      modelData,
      expansionState: hydrateExpansionState(cached.expansionState),
      fetchedChildrenCache: hydrateFetchedChildrenCache(
        this.store,
        modelData.topic,
        cached.fetchedChildrenCache
      ),
      scrollAnchor: cached.scrollAnchor,
    };
  }

  #setupNestedController(model) {
    const topicController = this.controllerFor("topic");
    const nestedController = this.controllerFor("nested");

    const restoringFromCache = this._restoringFromCache;

    if (!this.#teardownCurrentNestedTopic(nestedController, model.topic.id)) {
      nestedController.unsubscribe();
    }

    topicController.set("model", model.topic);
    this.#resetTopicControllerBulkSelection(topicController);
    topicController.setProperties({
      enteredAt: Date.now().toString(),
      userLastReadPostNumber: model.topic.last_read_post_number,
      highestPostNumber: model.topic.highest_post_number,
      sort: model.sort,
      context: model.context ?? (model.contextNoAncestors ? 0 : null),
      collapseReplies: model.collapseReplies,
    });

    if (restoringFromCache) {
      nestedController.expansionState = restoringFromCache.expansionState;
      nestedController.fetchedChildrenCache =
        restoringFromCache.fetchedChildrenCache;
      nestedController.scrollAnchor = restoringFromCache.scrollAnchor;
      this._restoringFromCache = null;
    } else {
      nestedController.expansionState = new Map();
      nestedController.fetchedChildrenCache = new Map();
      nestedController.scrollAnchor = null;
    }

    nestedController.setProperties(model);

    // Set the topic route's currentModel so route actions that call
    // this.modelFor("topic") (e.g. showFeatureTopic, showTopicTimerModal)
    // find the hydrated topic.
    getOwner(this).lookup("route:topic").currentModel = model.topic;

    // The Topic details setter replaces _details without preserving the
    // back-reference to the parent topic. Restore it so that
    // topic.details.updateNotifications() can construct the correct URL.
    model.topic.details.set("topic", model.topic);

    // Store the OP in the postStream so core components that read loaded posts
    // (e.g. share modal's "reply as new topic", bulk selection) find it.
    if (model.opPost && model.topic.postStream) {
      registerPostInTopicPostStream(model.topic, model.opPost);
    }

    this.appEvents.trigger("page:topic-loaded", model.topic);
    this.#announceUnreadPosts(model.topic);
    topicController.subscribe();
    nestedController.subscribe();
    this.screenTrack.start(model.topic.id, nestedController);

    if (!isEmpty(model.topic.draft) && !EmbedMode.enabled) {
      this.composer.open({
        draft: Draft.getLocal(model.topic.draft_key, model.topic.draft),
        draftKey: model.topic.draft_key,
        draftSequence: model.topic.draft_sequence,
        ignoreIfChanged: true,
        topic: model.topic,
      });
    }

    if (restoringFromCache?.scrollAnchor) {
      schedule("afterRender", () =>
        this.#restoreScrollAnchor(restoringFromCache.scrollAnchor)
      );
    } else if (!model.contextMode) {
      schedule("afterRender", () => window.scrollTo(0, 0));
    }
  }

  #restoreScrollAnchor(anchor) {
    if (Number.isFinite(anchor.scrollY)) {
      window.scrollTo(0, anchor.scrollY);
      return;
    }

    const article = document.querySelector(
      `.nested-post [data-post-number="${anchor.postNumber}"]`
    );
    const element = article?.closest(".nested-post") || article;
    if (element) {
      const rect = element.getBoundingClientRect();
      window.scrollTo(0, window.scrollY + rect.top - anchor.offsetFromTop);
    }
  }

  #teardownCurrentNestedTopic(controller, nextTopicId) {
    const currentTopicId = controller.topic?.id;

    if (!currentTopicId || String(currentTopicId) === String(nextTopicId)) {
      return false;
    }

    this.#saveNestedToCache(controller);
    controller.unsubscribe();
    this.screenTrack.stop();
    return true;
  }

  #saveNestedToCache(controller) {
    if (!controller.topic) {
      return;
    }

    const anchor = this.#findScrollAnchor();
    controller.saveToCache(anchor);
  }

  #findScrollAnchor() {
    const articles = document.querySelectorAll(
      ".nested-post [data-post-number]"
    );
    let best = null;
    let bestDistance = Infinity;

    for (const el of articles) {
      const rect = el.getBoundingClientRect();
      const distance = Math.abs(rect.top);
      if (distance < bestDistance) {
        bestDistance = distance;
        best = {
          postNumber: Number(el.dataset.postNumber),
          offsetFromTop: rect.top,
          scrollY: window.scrollY,
        };
      }
    }

    return best;
  }

  #resetTopicControllerBulkSelection(topicController) {
    topicController.set("multiSelect", false);
    topicController.selectedPostIds = [];
  }

  #truthyQueryParam(value) {
    return value === true || value === "true" || value === "1" || value === 1;
  }
}
