  asc = null;
  name = "";

  /** @type {string | null | undefined} */
  group = null;

  /** @type {string | null | undefined} */
  nameInput = null;

  /** @type {string | null} */
  exclude_usernames = null;

  /** @type {string | null} */
  exclude_groups = null;
  isLoading = false;

  /** @type {{ id: number, name: string, type: string, position: number, icon: string | null, user_field_id: number | null }[] | null} */
  columns = null;

  /** @type {{ name: string, id: string }[] | null} */
  groupOptions = null;

  /** @type {DirectoryParams | null} */
  params = null;

  @computed("currentUser", "groupOptions")
  get showGroupFilter() {
    return this.currentUser && this.groupOptions;
  }

  @dependentKeyCompat
  get showTimeRead() {
    return this.period === "all";
  }

  loadUsers(params = null) {
    if (params) {
      this.set("params", params);
    }

    this.setProperties({
      isLoading: true,
      nameInput: this.params.name,
      order: this.params.order,
    });

    const userFieldIds = this.columns
      .filter((c) => c.type === "user_field")
      .map((c) => c.user_field_id)
      .join("|");
    const pluginColumnIds = this.columns
      .filter((c) => c.type === "plugin")
      .map((c) => c.id)
      .join("|");

    return this.store
      .find(
        "directoryItem",
        Object.assign(this.params, {
          user_field_ids: userFieldIds,
          plugin_column_ids: pluginColumnIds,
        })
      )
      .then((model) => {
        const lastUpdatedAt = model.get("resultSetMeta.last_updated_at");
        this.setProperties({
          model,
          lastUpdatedAt: lastUpdatedAt ? longDate(lastUpdatedAt) : null,
          period: this.params.period,
        });
      })
      .finally(() => {
        this.set("isLoading", false);
      });
  }

  loadGroups() {
    if (this.currentUser) {
      return Group.findAll({ ignore_automatic: true }).then((groups) => {
        const groupOptions = groups
          .filter((group) => group.can_see_members)
          .map((group) => {
            return {
              name: group.full_name || group.name,
              id: group.name,
            };
          });
        this.set("groupOptions", groupOptions);
      });
    }
  }

  @action
  groupChanged(_, groupAttrs) {
    // First param is the group name, which include none or 'all groups'. Ignore this and look at second param.
    this.set("group", groupAttrs?.id);
  }

  @action
  showEditColumnsModal() {
    // TODO (ui-kit-reorderable-list-cleanup) drop the branch and the legacy
    // component once the change ships.
    const Modal = this.siteSettings.enable_new_reordering_controls
      ? EditUserDirectoryColumnsModalReorderable
      : EditUserDirectoryColumnsModal;

    this.modal.show(Modal);
  }

  @action
  onUsernameFilterChanged(filter) {
    discourseDebounce(this, this._setUsernameFilter, filter, 500);
  }

  @action
  updateOrderAndAsc(order, asc) {
    this.setProperties({ order, asc });
  }

  @action
  loadMore() {
    this.model.loadMore();
  }

  _setUsernameFilter(username) {
    this.setProperties({
      name: username,
      "params.name": username,
    });
    this.loadUsers();
  }
}
import { service } from "@ember/service";
import { Promise } from "rsvp";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import DiscourseRoute from "discourse/routes/discourse";
import { i18n } from "discourse-i18n";

export default class Users extends DiscourseRoute {
  @service router;
  @service siteSettings;
  @service currentUser;

  queryParams = {
    period: { refreshModel: true },
    order: { refreshModel: true },
    asc: { refreshModel: true },
    name: { refreshModel: false, replace: true },
    group: { refreshModel: true },
    exclude_groups: { refreshModel: true },
    exclude_usernames: { refreshModel: true },
  };

  titleToken() {
    return i18n("directory.title");
  }

  resetController(controller, isExiting) {
    if (isExiting) {
      controller.setProperties({
        period: "weekly",
        order: "likes_received",
        asc: null,
        name: "",
        group: null,
        exclude_usernames: null,
        exclude_groups: null,
        lastUpdatedAt: null,
        groupOptions: null,
      });
    }
  }

  beforeModel() {
    if (this.siteSettings.hide_user_profiles_from_public && !this.currentUser) {
      this.router.replaceWith("discovery");
    }
  }

  async model(params) {
    if (!this.columns) {
      try {
        const response = await ajax("/directory-columns.json");
        this.columns = response.directory_columns;
      } catch (error) {
        popupAjaxError(error);
        throw error;
      }
    }

    params.order ||= this.columns[0]?.name || "likes_received";
    return { params, columns: this.columns };
  }

  setupController(controller, { columns, params }) {
    controller.set("columns", columns);
    const promises = [controller.loadUsers(params)];

    // Only load groups on first load, not on every refresh
    if (!controller.groupOptions) {
      promises.push(controller.loadGroups());
    }

    return Promise.all(promises);
  }
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { action } from "@ember/object";
import { service } from "@ember/service";
import SignupProgressBar from "discourse/components/signup-progress-bar";
import WelcomeHeader from "discourse/components/welcome-header";
import bodyClass from "discourse/helpers/body-class";
import hideApplicationHeaderButtons from "discourse/helpers/hide-application-header-buttons";
import hideApplicationSidebar from "discourse/helpers/hide-application-sidebar";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import getURL from "discourse/lib/get-url";
import DButton from "discourse/ui-kit/d-button";
import { i18n } from "discourse-i18n";

export default class extends Component {
  @service siteSettings;
  @service currentUser;

  @tracked accountActivated = false;
  @tracked isLoading = false;
  @tracked needsApproval = false;
  @tracked
  errorMessage = this.currentUser
    ? i18n("user.activate_account.already_done")
    : null;

  get signupStep() {
    if (this.needsApproval) {
      return "approve";
    } else if (this.accountActivated) {
      return "login";
    } else {
      return "activate";
    }
  }

  @action
  async activate() {
    this.isLoading = true;

    let hp;
    try {
      hp = await ajax("/session/hp");
    } catch (error) {
      this.isLoading = false;
      popupAjaxError(error);
      return;
    }

    try {
      const response = await ajax(
        `/u/activate-account/${this.args.model.token}.json`,
        {
          type: "PUT",
          data: {
            password_confirmation: hp.value,
            challenge: hp.challenge.split("").reverse().join(""),
          },
        }
      );

      if (!response.success) {
        this.errorMessage = i18n("user.activate_account.already_done");
        return;
      }

      this.accountActivated = true;

      if (response.redirect_to) {
        window.location.href = response.redirect_to;
      } else if (response.needs_approval) {
        this.needsApproval = true;
      } else {
        setTimeout(this.loadHomepage, 3000);
      }
    } catch {
      this.errorMessage = i18n("user.activate_account.already_done");
    }
  }

  @action
  loadHomepage() {
    window.location.href = getURL("/");
  }

  <template>
    {{bodyClass "activate-account-page"}}
    {{hideApplicationHeaderButtons "search" "login" "signup" "menu"}}
    {{hideApplicationSidebar}}
    {{#if this.errorMessage}}
      <div class="alert alert-error">
        {{this.errorMessage}}
      </div>
    {{else}}
      <div class="activate-account">
        <SignupProgressBar @step={{this.signupStep}} />
        <WelcomeHeader
          @header={{i18n
            "user.activate_account.welcome_to"
            site_name=this.siteSettings.title
          }}
        />
        <br />
        {{#if this.accountActivated}}
          <div class="account-activated">
            <div class="tada-image">
              <img alt="tada emoji" src={{getURL "/images/wizard/tada.svg"}} />
            </div>
            {{#if this.needsApproval}}
              <p>{{i18n "user.activate_account.approval_required"}}</p>
            {{else}}
              <p>{{i18n "user.activate_account.please_continue"}}</p>
              <DButton
                class="btn-primary continue-button"
                @action={{this.loadHomepage}}
                @translatedLabel={{i18n
                  "user.activate_account.continue_button"
                }}
              />
            {{/if}}
          </div>
        {{else}}
          <DButton
            class="activate-account-button btn-primary"
            @action={{this.activate}}
            @disabled={{this.isLoading}}
            @label="user.activate_account.action"
          />
        {{/if}}
      </div>
    {{/if}}
  </template>
}
